/**
 * Sync current gold price from Script Properties to the Aset sheet.
 * The current sheet note says: update Harga Emas Sekarang in F12.
 */
function syncGoldPriceToAssetSheet() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  const sheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.aset);

  if (!sheet) {
    return { ok: false, reason: 'asset_sheet_missing' };
  }

  const price = getGoldMarketPrice24kPerGram_();

  if (!price || price <= 0) {
    return { ok: false, reason: 'gold_price_missing_or_zero' };
  }

  sheet.getRange('F12').setValue(price);
  sheet.getRange('F12').setNumberFormat('"Rp" #,##0');

  return {
    ok: true,
    sheet: sheet.getName(),
    cell: 'F12',
    price_24k_per_gram_idr: price
  };
}

/**
 * Daily wrapper:
 * 1. Fetch ANTAM price
 * 2. Store Script Property
 * 3. Write price to Aset!F12
 */
function updateAntamGoldPriceDailyAndSyncSheet() {
  const update = updateAntamGoldPriceDaily();
  const sync = syncGoldPriceToAssetSheet();

  return {
    ok: Boolean(update && update.ok && sync && sync.ok),
    update,
    sync
  };
}

/**
 * Replace old daily gold trigger with synced daily trigger.
 */
function setupDailyAntamGoldPriceTriggerSynced() {
  ScriptApp.getProjectTriggers().forEach(trigger => {
    const fn = trigger.getHandlerFunction && trigger.getHandlerFunction();

    if (
      fn === 'updateAntamGoldPriceDaily' ||
      fn === 'updateAntamGoldPriceDailyAndSyncSheet'
    ) {
      ScriptApp.deleteTrigger(trigger);
    }
  });

  ScriptApp
    .newTrigger('updateAntamGoldPriceDailyAndSyncSheet')
    .timeBased()
    .everyDays(1)
    .atHour(10)
    .nearMinute(15)
    .inTimezone('Asia/Jakarta')
    .create();

  return {
    ok: true,
    trigger: 'updateAntamGoldPriceDailyAndSyncSheet',
    schedule: 'daily around 10:15 Asia/Jakarta',
    writes_to: '🥇 Aset!F12'
  };
}

/**
 * Read latest 24K gold price per gram from Script Properties.
 * Main property is updated by updateAntamGoldPriceDaily().
 */
function getGoldMarketPrice24kPerGram_() {
  const props = PropertiesService.getScriptProperties();

  const price = Number(props.getProperty('GOLD_24K_PRICE_PER_GRAM_IDR') || 0);

  if (price && price > 0) {
    return Math.round(price);
  }

  return 0;
}

/**
 * Manual fallback setter.
 * Use from code wrapper if official fetch ever fails.
 */
function setGoldMarketPrice24kPerGram(value) {
  const n = Number(value);

  if (!n || n <= 0) {
    throw new Error('Invalid GOLD_24K_PRICE_PER_GRAM_IDR value');
  }

  PropertiesService
    .getScriptProperties()
    .setProperty('GOLD_24K_PRICE_PER_GRAM_IDR', String(Math.round(n)));

  PropertiesService
    .getScriptProperties()
    .setProperty('GOLD_24K_PRICE_UPDATE_STATUS', 'manual_ok');

  syncGoldPriceToAssetSheet();

  return {
    ok: true,
    GOLD_24K_PRICE_PER_GRAM_IDR: Math.round(n)
  };
}

/**
 * Temporary manual setter for current known ANTAM price.
 * Change the number here only if needed.
 */
function setGoldPriceManualToday() {
  return setGoldMarketPrice24kPerGram(2839000);
}

function appendGoldAssetRow_(sheet, parsed, rawText, common) {
  const headerRow = findGoldLedgerHeaderRow_(sheet);
  if (!headerRow) {
    return {
      status: 'fallback',
      writtenTab: sheet.getName(),
      reason: 'gold_ledger_header_not_found'
    };
  }

  const price24k = Number(parsed.goldMarketPrice24k || getGoldMarketPrice24kPerGram_() || 0);
  const physicalGram = Number(parsed.goldWeightGram || 0);
  const karat = Number(parsed.goldKarat || 24);
  const pureGram = physicalGram && karat ? physicalGram * karat / 24 : physicalGram;
  const purchasePrice = Number(parsed.goldPurchasePrice || 0);
  const action = parsed.goldAction || parseGoldAction_(rawText);

  if (!physicalGram || physicalGram <= 0) {
    return {
      status: 'fallback',
      writtenTab: sheet.getName(),
      reason: 'gold_weight_missing'
    };
  }

  const pureGramRounded = roundGoldGram_(pureGram);
  const isSell = action === 'sell';

  const gramsIn = isSell ? '' : pureGramRounded;
  const gramsOut = isSell ? pureGramRounded : '';

  const pricePerGram = purchasePrice && physicalGram
    ? Math.round(purchasePrice / physicalGram)
    : price24k;

  const totalAmount = purchasePrice || (price24k && pureGramRounded ? Math.round(price24k * pureGramRounded) : '');

  // AIRO_TASK7_ASET_CLARITY_DISTINCTION_V1
  // Calculate acquisition cost (actual cash outflow) from parsed.amount or purchasePrice.
  const acquisitionCost = Number(parsed.amount || purchasePrice || 0);
  const showDistinction = acquisitionCost > 0 && totalAmount > 0 && acquisitionCost !== totalAmount;

  const notes = [
    parsed.goldNotes ? 'catatan: ' + parsed.goldNotes : '',
    'berat_fisik: ' + physicalGram + ' gr',
    'karat: ' + karat + 'K',
    'gram_setara_24k: ' + pureGramRounded + ' gr',
    showDistinction ? 'biaya_beli: ' + airoSprint7FFormatRupiah_(acquisitionCost) : '',
    showDistinction ? 'estimasi_nilai: ' + airoSprint7FFormatRupiah_(totalAmount) : '',
    isSell ? 'gold_outflow: true' : ''
  ].filter(Boolean).join(' | ');

  const targetRow = findNextGoldLedgerRow_(sheet, headerRow);

  // Gold Ledger fixed columns:
  // A gold_event_id
  // B date
  // C action
  // D grams_in
  // E grams_out
  // F price_per_gram
  // G fee
  // H total_amount
  // I source_account
  // J source
  // K raw_text
  // L notes, if column exists
  const row = [
    common.linked_txn_id || makeTxnId_({}, rawText),
    parsed.goldPurchaseDate || parsed.date || parseDate_(rawText),
    isSell ? 'sell' : 'buy',
    gramsIn,
    gramsOut,
    pricePerGram || '',
    '',
    totalAmount || '',
    parsed.account && parsed.account !== 'Unknown' ? parsed.account : '',
    'telegram',
    rawText,
    notes
  ];

  const width = Math.min(row.length, Math.max(sheet.getLastColumn(), 11));
  sheet.getRange(targetRow, 1, 1, width).setValues([row.slice(0, width)]);

  return {
    status: 'written',
    writtenTab: sheet.getName(),
    row: targetRow,
    rowId: sheet.getName() + ':' + targetRow,
    tabUrl: getSheetTabUrl_(SpreadsheetApp.openById(getProp_('SPREADSHEET_ID')), sheet),
    section: 'gold',
    acquisitionCost: acquisitionCost,
    marketValue: totalAmount
  };
}

function findGoldLedgerHeader_(sheet) {
  const maxRows = Math.min(sheet.getLastRow(), 80);
  const maxCols = Math.min(sheet.getLastColumn(), 20);
  const values = sheet.getRange(1, 1, maxRows, maxCols).getValues();

  for (let r = 0; r < values.length; r++) {
    const normalized = values[r].map(v => canonicalKey_(v));

    const hasGoldEvent = normalized.includes('gold_event_id');
    const hasGramsIn = normalized.includes('grams_in');
    const hasRawText = normalized.includes('raw_text');

    if (hasGoldEvent && hasGramsIn && hasRawText) {
      const lastNonEmpty = values[r].reduce((last, v, idx) => {
        return String(v || '').trim() ? idx + 1 : last;
      }, 0);

      return {
        row: r + 1,
        headers: values[r].slice(0, lastNonEmpty).map(v => String(v || '').trim())
      };
    }
  }

  return null;
}

function goldFieldForHeader_(header) {
  const h = canonicalKey_(header);

  const aliases = {
    gold_event_id: ['gold_event_id', 'event_id', 'id'],
    date: ['date', 'tanggal', 'tanggal_beli', 'purchase_date'],
    action: ['action', 'aksi', 'type', 'jenis'],
    grams_in: ['grams_in', 'gram_in', 'gram_masuk', 'berat', 'berat_gram'],
    grams_out: ['grams_out', 'gram_out', 'gram_keluar'],
    price_per_gram: ['price_per_gram', 'harga_per_gram', 'harga_gram'],
    fee: ['fee', 'biaya'],
    total_amount: ['total_amount', 'total', 'harga_beli', 'modal', 'nilai_beli'],
    source_account: ['source_account', 'akun_sumber', 'account'],
    source: ['source', 'sumber'],
    raw_text: ['raw_text', 'pesan', 'message'],
    notes: ['notes', 'catatan', 'note']
  };

  for (const field in aliases) {
    if (aliases[field].map(canonicalKey_).includes(h)) {
      return field;
    }
  }

  return '';
}

function parseGoldAsset_(rawText) {
  const text = String(rawText || '').toLowerCase();
  const isGoldAsset = /\b(aset\s+emas|emas|gold|antam|logam mulia)\b/i.test(text);

  if (!isGoldAsset) {
    return {
      isGoldAsset: false,
      action: '',
      karat: '',
      weightGram: '',
      pureGram: '',
      purchasePrice: '',
      purchaseDate: '',
      notes: '',
      marketPrice24k: '',
      estimatedValue: ''
    };
  }

  const action = parseGoldAction_(text);
  const karat = parseGoldKarat_(text);
  const weightGram = parseGoldWeightGram_(text);
  const pureGram = weightGram && karat ? weightGram * karat / 24 : '';
  const purchasePrice = parseGoldPurchasePrice_(text);
  const purchaseDate = parseIndonesianDate_(text) || parseDate_(text);
  const notes = parseGoldNotes_(rawText);
  const marketPrice24k = getGoldMarketPrice24kPerGram_();
  const estimatedValue = pureGram && marketPrice24k ? Math.round(pureGram * marketPrice24k) : '';

  return {
    isGoldAsset,
    action,
    karat,
    weightGram,
    pureGram,
    purchasePrice,
    purchaseDate,
    notes,
    marketPrice24k,
    estimatedValue
  };
}

function parseGoldKarat_(text) {
  const m = String(text || '').match(/\b(24|23|22|21|20|19|18|17|16|15|14|10|9)\s*k\b/i);
  if (m) return Number(m[1]);

  const jenis = String(text || '').match(/\bjenis\s+emas\s+(24|23|22|21|20|19|18|17|16|15|14|10|9)\s*k\b/i);
  if (jenis) return Number(jenis[1]);

  return 24;
}

function parseGoldWeightGram_(text) {
  const m = String(text || '').match(/\bberat\s+(\d+(?:[.,]\d+)?)\s*(gram|gr|g)\b/i);
  if (m) return Number(m[1].replace(',', '.'));

  const m2 = String(text || '').match(/\b(\d+(?:[.,]\d+)?)\s*(gram|gr|g)\b/i);
  if (m2) return Number(m2[1].replace(',', '.'));

  return '';
}

function parseGoldPurchasePrice_(text) {
  const buy = String(text || '').match(/\b(beli|harga|modal)\s+(\d+(?:[.,]\d+)?)\s*(jt|juta|rb|ribu)?\b/i);
  if (!buy) return '';

  const n = Number(buy[2].replace(',', '.'));
  const unit = String(buy[3] || '').toLowerCase();

  if (unit === 'jt' || unit === 'juta') return Math.round(n * 1000000);
  if (unit === 'rb' || unit === 'ribu') return Math.round(n * 1000);

  return cleanAmount_(buy[2]);
}

function parseGoldNotes_(rawText) {
  const m = String(rawText || '').match(/\bcatatan\s+(.+)$/i);
  return m ? m[1].trim() : '';
}

function parseIndonesianDate_(text) {
  const monthMap = {
    januari: '01', jan: '01',
    februari: '02', feb: '02',
    maret: '03', mar: '03',
    april: '04', apr: '04',
    mei: '05',
    juni: '06', jun: '06',
    juli: '07', jul: '07',
    agustus: '08', agu: '08', aug: '08',
    september: '09', sep: '09',
    oktober: '10', okt: '10', oct: '10',
    november: '11', nov: '11',
    desember: '12', des: '12', dec: '12'
  };

  const m = String(text || '').toLowerCase().match(/\btanggal\s+(\d{1,2})\s+([a-z]+)\s+(\d{4})\b/i);
  if (!m) return '';

  const day = String(m[1]).padStart(2, '0');
  const month = monthMap[m[2]];
  const year = m[3];

  if (!month) return '';

  return `${year}-${month}-${day}`;
}

function cleanupInvalidGoldLedgerRows() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  const sheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.aset);

  if (!sheet) return { ok: false, reason: 'asset_sheet_missing' };

  const headerRow = findGoldLedgerHeaderRow_(sheet);
  if (!headerRow) return { ok: false, reason: 'gold_header_missing' };

  let deleted = 0;

  for (let r = sheet.getLastRow(); r > headerRow; r--) {
    const row = sheet.getRange(r, 1, 1, 11).getValues()[0];

    const eventId = String(row[0] || '');
    const action = String(row[2] || '');
    const gramsIn = row[3];
    const rawText = String(row[10] || '').toLowerCase();

    const isGoldRow = eventId.startsWith('tg:') || rawText.includes('aset emas') || rawText.includes('emas');
    const gramsNum = Number(gramsIn);

    const invalid =
      isGoldRow &&
      (
        !action ||
        !gramsIn ||
        Number.isNaN(gramsNum) ||
        gramsNum <= 0 ||
        gramsNum > 1000
      );

    if (invalid) {
      sheet.deleteRow(r);
      deleted++;
    }
  }

  return {
    ok: true,
    deleted
  };
}

function findGoldLedgerHeaderRow_(sheet) {
  const maxRows = Math.min(sheet.getLastRow(), 100);
  const values = sheet.getRange(1, 1, maxRows, Math.min(sheet.getLastColumn(), 15)).getValues();

  for (let r = 0; r < values.length; r++) {
    const normalized = values[r].map(v => canonicalKey_(v));
    if (
      normalized.includes('gold_event_id') &&
      normalized.includes('date') &&
      normalized.includes('grams_in') &&
      normalized.includes('raw_text')
    ) {
      return r + 1;
    }
  }

  return 0;
}

function findNextGoldLedgerRow_(sheet, headerRow) {
  const lastRow = Math.max(sheet.getLastRow(), headerRow + 1);
  const values = sheet.getRange(headerRow + 1, 1, Math.max(1, lastRow - headerRow), 11).getValues();

  for (let i = values.length - 1; i >= 0; i--) {
    if (values[i].some(v => String(v || '').trim() !== '')) {
      return headerRow + 1 + i + 1;
    }
  }

  return headerRow + 1;
}

function roundGoldGram_(value) {
  const n = Number(value || 0);
  return Math.round(n * 10000) / 10000;
}

function parseGoldAction_(text) {
  const t = String(text || '').toLowerCase();

  if (/\b(jual|sell|sold|lepas)\b/i.test(t)) {
    return 'sell';
  }

  if (/\b(beli|buy|purchase|tambah|masuk)\b/i.test(t)) {
    return 'buy';
  }

  return '';
}

function cleanupWrongGoldSellRows() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  const sheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.aset);

  if (!sheet) return { ok: false, reason: 'asset_sheet_missing' };

  const headerRow = findGoldLedgerHeaderRow_(sheet);
  if (!headerRow) return { ok: false, reason: 'gold_header_missing' };

  let deleted = 0;

  for (let r = sheet.getLastRow(); r > headerRow; r--) {
    const row = sheet.getRange(r, 1, 1, 11).getValues()[0];

    const action = String(row[2] || '').toLowerCase();
    const gramsIn = row[3];
    const gramsOut = row[4];
    const rawText = String(row[10] || '').toLowerCase();

    const isWrongSell =
      rawText.includes('jual') &&
      action === 'buy' &&
      gramsIn &&
      !gramsOut;

    if (isWrongSell) {
      sheet.deleteRow(r);
      deleted++;
    }
  }

  return {
    ok: true,
    deleted
  };
}

function getSheetTabUrl_(ss, sheet) {
  if (!ss || !sheet) return '';
  return ss.getUrl() + '#gid=' + sheet.getSheetId();
}

function getSheetTabUrlByName_(ss, tabName) {
  const sheet = getSheetLoose_(ss, tabName);
  return sheet ? getSheetTabUrl_(ss, sheet) : ss.getUrl();
}

function parseHumanMoney_(value) {
  const raw = String(value || '').toLowerCase().trim();

  const juta = raw.match(/(\d+(?:[.,]\d+)?)\s*(jt|juta)\b/i);
  if (juta) return Math.round(Number(juta[1].replace(',', '.')) * 1000000);

  const milyar = raw.match(/(\d+(?:[.,]\d+)?)\s*(m|miliar|milyar)\b/i);
  if (milyar) return Math.round(Number(milyar[1].replace(',', '.')) * 1000000000);

  const ribu = raw.match(/(\d+(?:[.,]\d+)?)\s*(rb|ribu)\b/i);
  if (ribu) return Math.round(Number(ribu[1].replace(',', '.')) * 1000);

  return cleanAmount_(raw);
}

/**
 * Remove old duplicate Net Worth/Home Equity panels from earlier layout attempts.
 * Keeps only the final safe panel in:
 * - AA:AB = Home Equity
 * - AD:AE = Net Worth Final
 */

function ensureSheetSize_(sheet, minRows, minCols) {
  const currentRows = sheet.getMaxRows();
  const currentCols = sheet.getMaxColumns();

  if (currentRows < minRows) {
    sheet.insertRowsAfter(currentRows, minRows - currentRows);
  }

  if (currentCols < minCols) {
    sheet.insertColumnsAfter(currentCols, minCols - currentCols);
  }

  return {
    ok: true,
    rows: sheet.getMaxRows(),
    cols: sheet.getMaxColumns()
  };
}

function breakMergedRangesSafely_(sheet, a1Notation) {
  const range = sheet.getRange(a1Notation);

  try {
    const mergedRanges = range.getMergedRanges();
    mergedRanges.forEach(mr => {
      try {
        mr.breakApart();
      } catch (err) {}
    });
  } catch (err) {}

  return true;
}

function safeClearRange_(sheet, a1Notation) {
  breakMergedRangesSafely_(sheet, a1Notation);

  const range = sheet.getRange(a1Notation);
  range.clearContent();
  range.clearFormat();
  range.clearDataValidations();

  return true;
}

function setupNetWorthMetrics() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));

  const asset =
    getSheetLoose_(ss, AIRO_CONFIG.tabs.aset) ||
    getSheetLoose_(ss, 'Aset');

  const dashboard =
    getSheetLoose_(ss, '🏠 Dashboard') ||
    getSheetLoose_(ss, 'Dashboard');

  if (!asset) {
    return { ok: false, reason: 'asset_sheet_missing' };
  }

  if (!dashboard) {
    return { ok: false, reason: 'dashboard_sheet_missing' };
  }

  const helper = setupAsetNetWorthHelpers_(asset);
  const panel = setupDashboardNetWorthPanel();

  return {
    ok: true,
    helper,
    panel
  };
}

function setupAsetNetWorthHelpers_(asset) {
  ensureSheetSize_(asset, 24, 31);

  // Helper cells only. They may be hidden; dashboard is the visible panel.
  const oldHome = asset.getRange('AB17').getValue();
  const oldHaircut = asset.getRange('AB18').getValue();
  const oldPrincipal = asset.getRange('AB20').getValue();

  const homeValue = oldHome || 166000000;
  const haircut = oldHaircut || 0.05;
  const principal = oldPrincipal || 145000000;

  breakMergedRangesSafely_(asset, 'AA16:AE22');
  asset.getRange('AA16:AE22').clearFormat().clearDataValidations();

  asset.getRange('AA16').setValue('NET_WORTH_HELPER_DO_NOT_EDIT_RANDOMLY');
  asset.getRange('AA17').setValue('Nilai Rumah Pasar');
  asset.getRange('AB17').setValue(homeValue);

  asset.getRange('AA18').setValue('Haircut Konservatif');
  asset.getRange('AB18').setValue(haircut);

  asset.getRange('AA19').setValue('Nilai Rumah Konservatif');
  asset.getRange('AB19').setFormula('=IFERROR(AB17*(1-AB18);0)');

  asset.getRange('AA20').setValue('Sisa Pokok Rumah');
  asset.getRange('AB20').setValue(principal);

  asset.getRange('AA21').setValue('Ekuitas Rumah');
  asset.getRange('AB21').setFormula('=IFERROR(AB19-AB20;0)');

  asset.getRange('AB17:AB21').setNumberFormat('"Rp" #,##0');
  asset.getRange('AB18').setNumberFormat('0.00%');

  // Hide helper columns if possible so Aset stays clean.
  try {
    asset.hideColumns(27, 5); // AA:AE
  } catch (err) {}

  return {
    ok: true,
    helper_range: 'AA16:AB21',
    values: {
      home_value: homeValue,
      haircut,
      principal
    }
  };
}

function ccDueDateForCycle_(cycle) {
  const end = cycle && cycle.end instanceof Date ? cycle.end : todayDate_();
  return new Date(end.getFullYear(), end.getMonth(), 30);
}

function formatDateYmd_(dateObj) {
  if (dateObj instanceof Date) {
    return Utilities.formatDate(dateObj, Session.getScriptTimeZone(), 'yyyy-MM-dd');
  }
  return String(dateObj || '');
}

function setupCreditCardTabCycleHeader_() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  const cc =
    getSheetLoose_(ss, AIRO_CONFIG.tabs.creditCard) ||
    getSheetLoose_(ss, 'Credit Card');

  if (!cc) return { ok: false, reason: 'credit_card_sheet_missing' };

  let header = findCcHeaderRow_(cc);
  if (!header) return { ok: false, reason: 'cc_header_missing' };

  // Stacked layout needs the real transaction table header to start at row 8.
  // If the header is still in the old row 3 layout, move it down once.
  if (header.row < 8) {
    cc.insertRowsBefore(header.row, 8 - header.row);
    header = findCcHeaderRow_(cc);
  }

  const map = ccColMap_(header.headers);
  const required = ['amount', 'status_pocket_blu', 'billing_cycle_id'];
  for (let i = 0; i < required.length; i++) {
    if (!map[required[i]]) return { ok: false, reason: 'cc_column_missing_' + required[i] };
  }

  ensureSheetSize_(cc, Math.max(cc.getMaxRows(), 20), 14);
  safeClearRange_(cc, 'A1:N6');

  const currentCycle = ccBillingCycle_(todayDate_());
  const payableDate = new Date(currentCycle.start);
  payableDate.setDate(payableDate.getDate() - 1);
  const payableCycle = ccBillingCycle_(payableDate);
  const payableDueDate = ccDueDateForCycle_(payableCycle);

  const amountFromDisplay_ = function(value) {
    let s = String(value || '').replace(/\s+/g, '').replace(/[^0-9,.-]/g, '');
    if (!s) return 0;
    if (s.indexOf(',') >= 0 && s.indexOf('.') >= 0) {
      s = s.replace(/\./g, '').replace(',', '.');
    } else {
      s = s.replace(/[.,]/g, '');
    }
    return Number(s) || 0;
  };

  const stats = {
    payable_total: 0,
    payable_belum_blu: 0,
    payable_sudah_blu: 0,
    payable_rows: 0,
    unbilled_total: 0,
    unbilled_belum_blu: 0,
    unbilled_sudah_blu: 0,
    unbilled_rows: 0
  };

  const lastRow = cc.getLastRow();
  const lastCol = cc.getLastColumn();

  if (lastRow > header.row) {
    const rows = cc.getRange(header.row + 1, 1, lastRow - header.row, lastCol).getDisplayValues();

    rows.forEach(function(row) {
      const amount = amountFromDisplay_(row[map.amount - 1]);
      const status = String(row[map.status_pocket_blu - 1] || '').toLowerCase();
      const cycleId = String(row[map.billing_cycle_id - 1] || '').trim();

      if (!amount || !cycleId) return;

      const isSudahBlu =
        status.indexOf('sudah') >= 0 ||
        status.indexOf('paid') >= 0 ||
        status.indexOf('posted') >= 0 ||
        status.indexOf('transferred') >= 0;

      if (cycleId === payableCycle.id) {
        stats.payable_total += amount;
        stats.payable_rows++;
        if (isSudahBlu) stats.payable_sudah_blu += amount;
        else stats.payable_belum_blu += amount;
      }

      if (cycleId === currentCycle.id) {
        stats.unbilled_total += amount;
        stats.unbilled_rows++;
        if (isSudahBlu) stats.unbilled_sudah_blu += amount;
        else stats.unbilled_belum_blu += amount;
      }
    });
  }

  const overdue = todayDate_() > payableDueDate && stats.payable_belum_blu > 0;
  const payableStatus = overdue ? 'OVERDUE / CEK BLU' : (stats.payable_belum_blu > 0 ? 'PERLU SIAPKAN BLU' : 'AMAN');

  // Section 1: Tagihan Jatuh Tempo
  cc.getRange('A1:H1').merge();
  cc.getRange('A1').setValue(
    'TAGIHAN JATUH TEMPO | ' +
    payableCycle.id + ' | ' +
    formatDateYmd_(payableCycle.start) + ' - ' + formatDateYmd_(payableCycle.end) +
    ' | Due ' + formatDateYmd_(payableDueDate)
  );

  cc.getRange('A2').setValue('Total Tagihan');
  cc.getRange('B2').setValue(stats.payable_total);
  cc.getRange('C2').setValue('Sudah Blu');
  cc.getRange('D2').setValue(stats.payable_sudah_blu);
  cc.getRange('E2').setValue('Belum Blu');
  cc.getRange('F2').setValue(stats.payable_belum_blu);
  cc.getRange('G2').setValue('Status');
  cc.getRange('H2').setValue(payableStatus);

  cc.getRange('A3:H3').merge();
  cc.getRange('A3').setValue('Tagihan jatuh tempo tetap tampil sampai dana pembayaran disiapkan di Pocket Blu khusus CC / paid / closed.');

  // Section 2: Periode Berjalan / Unbilled
  cc.getRange('A4:H4').merge();
  cc.getRange('A4').setValue(
    'PERIODE BERJALAN / UNBILLED | ' +
    currentCycle.id + ' | ' +
    formatDateYmd_(currentCycle.start) + ' - ' + formatDateYmd_(currentCycle.end) +
    ' | Belum closing'
  );

  cc.getRange('A5').setValue('Total Sementara');
  cc.getRange('B5').setValue(stats.unbilled_total);
  cc.getRange('C5').setValue('Transaksi');
  cc.getRange('D5').setValue(stats.unbilled_rows);
  cc.getRange('E5').setValue('Belum Blu');
  cc.getRange('F5').setValue(stats.unbilled_belum_blu);
  cc.getRange('G5').setValue('Status');
  cc.getRange('H5').setValue('Tracking');

  cc.getRange('A6:H6').merge();
  cc.getRange('A6').setValue('Periode berjalan tidak dicampur ke tagihan jatuh tempo sebelumnya.');

  // Number formats
  cc.getRange('B2:D2').setNumberFormat('"Rp" #,##0');
  cc.getRange('F2').setNumberFormat('"Rp" #,##0');
  cc.getRange('B5').setNumberFormat('"Rp" #,##0');
  cc.getRange('F5').setNumberFormat('"Rp" #,##0');

  // Styles
  cc.getRange('A1:H1')
    .setBackground(overdue ? '#cc0000' : '#7030a0')
    .setFontColor('#ffffff')
    .setFontWeight('bold')
    .setHorizontalAlignment('center');

  cc.getRange('A2:H3')
    .setBackground(overdue ? '#f4cccc' : '#eadcf8')
    .setFontWeight('bold')
    .setBorder(true, true, true, true, true, true);

  cc.getRange('A4:H4')
    .setBackground('#1f4e79')
    .setFontColor('#ffffff')
    .setFontWeight('bold')
    .setHorizontalAlignment('center');

  cc.getRange('A5:H6')
    .setBackground('#eaf2f8')
    .setFontWeight('bold')
    .setBorder(true, true, true, true, true, true);

  cc.getRange('A3:H3').setFontStyle('italic');
  cc.getRange('A6:H6').setFontStyle('italic');
  cc.getRange('A1:H6').setVerticalAlignment('middle');

  cc.setFrozenRows(Math.max(8, cc.getFrozenRows()));

  // Color transaction rows by cycle.
  header = findCcHeaderRow_(cc);
  const refreshedMap = ccColMap_(header.headers);
  const refreshedLastRow = cc.getLastRow();
  const refreshedLastCol = cc.getLastColumn();

  if (refreshedLastRow > header.row && refreshedMap.billing_cycle_id) {
    const dataRange = cc.getRange(header.row + 1, 1, refreshedLastRow - header.row, refreshedLastCol);
    const values = dataRange.getDisplayValues();

    values.forEach(function(row, idx) {
      const cycleId = String(row[refreshedMap.billing_cycle_id - 1] || '').trim();
      const target = cc.getRange(header.row + 1 + idx, 1, 1, refreshedLastCol);

      if (cycleId === payableCycle.id) {
        target.setBackground('#fff2cc');
      } else if (cycleId === currentCycle.id) {
        target.setBackground('#eaf2f8');
      }
    });
  }

  return {
    ok: true,
    sheet: cc.getName(),
    gid: cc.getSheetId(),
    header_row: header.row,
    table_header_row: header.row,
    payable_cycle: payableCycle.id,
    payable_start: formatDateYmd_(payableCycle.start),
    payable_end: formatDateYmd_(payableCycle.end),
    payable_due_date: formatDateYmd_(payableDueDate),
    current_cycle: currentCycle.id,
    current_start: formatDateYmd_(currentCycle.start),
    current_end: formatDateYmd_(currentCycle.end),
    layout: 'A1:H3 payable, A4:H6 unbilled, table starts at row ' + header.row,
    stats: stats,
    tab_url: getSheetTabUrl_(ss, cc)
  };
}

