function cleanupDuplicateNetWorthPanels() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));

  const asset =
    getSheetLoose_(ss, AIRO_CONFIG.tabs.aset) ||
    getSheetLoose_(ss, 'Aset');

  if (!asset) {
    return { ok: false, reason: 'asset_sheet_missing' };
  }

  ensureSheetSize_(asset, 24, 31);

  // Remove visible duplicate panels from Aset only.
  // Do not touch Gold Summary, Gold Ledger, or original Estimasi Net Worth.
  const maxRows = Math.min(asset.getMaxRows(), 120);
  const maxCols = Math.min(asset.getMaxColumns(), 31);
  const values = asset.getRange(1, 1, maxRows, maxCols).getDisplayValues();

  const cleared = [];

  for (let r = 0; r < values.length; r++) {
    for (let c = 0; c < values[r].length; c++) {
      const text = String(values[r][c] || '').toLowerCase();

      const isDuplicatePanel =
        (text.includes('rumah') && text.includes('home equity')) ||
        text.includes('net worth final');

      if (!isDuplicatePanel) continue;

      const row = r + 1;
      const col = c + 1;

      // Ignore hidden helper marker around AA:AE.
      if (col >= 27 && col <= 31) continue;

      const height = Math.min(7, asset.getMaxRows() - row + 1);
      const width = Math.min(6, asset.getMaxColumns() - col + 1);
      const a1 = asset.getRange(row, col, height, width).getA1Notation();

      safeClearRange_(asset, a1);
      cleared.push(a1);
    }
  }

  const setup = setupNetWorthMetrics();

  return {
    ok: true,
    cleared_duplicate_asset_ranges: cleared,
    setup
  };
}

function polishNetWorthLayout() {
  return setupNetWorthMetrics();
}

function dashboardLayoutReadOnlyAudit_(ss) {
  const dashboard =
    getSheetLoose_(ss, AIRO_CONFIG.tabs.dashboard) ||
    getSheetLoose_(ss, 'Dashboard');

  if (!dashboard) {
    return {
      ok: false,
      reason: 'dashboard_sheet_missing'
    };
  }

  const maxRows = Math.min(dashboard.getMaxRows(), 80);
  const maxCols = Math.min(dashboard.getMaxColumns(), 16);
  const values = dashboard.getRange(1, 1, maxRows, maxCols).getDisplayValues();

  const labels = [];
  for (let r = 0; r < values.length; r++) {
    for (let c = 0; c < values[r].length; c++) {
      const text = String(values[r][c] || '').trim();
      if (!text) continue;
      labels.push({
        row: r + 1,
        col: c + 1,
        text: text.slice(0, 120)
      });
    }
  }

  const requiredHints = [
    'Net Worth',
    'Assets',
    'Cashflow',
    'Credit Card',
    'Cash',
    'Hutang',
    'Cicilan',
    'Review Queue',
    'Sync'
  ];

  const foundHints = {};
  requiredHints.forEach(function(hint) {
    const re = new RegExp(hint, 'i');
    foundHints[hint] = labels.some(function(item) {
      return re.test(item.text);
    });
  });

  return {
    ok: true,
    command: 'dashboard_layout_read_only_audit',
    sheet_name: dashboard.getName(),
    scanned_rows: maxRows,
    scanned_cols: maxCols,
    non_empty_count: labels.length,
    labels_sample: labels.slice(0, 60),
    found_hints: foundHints,
    google_write_performed: false
  };
}

