function airoSprint6BMaskChatId_(chatId) {
  const raw = String(chatId || '').trim();
  if (!raw) return '';
  if (raw.length <= 4) return '***' + raw;
  return raw.slice(0, 2) + '***' + raw.slice(-3);
}

function airoSprint6BGetAdminChatStatus_() {
  const raw = String(getProp_('ADMIN_CHAT_ID') || '').trim();
  return {
    ok: true,
    configured: Boolean(raw),
    property_name: 'ADMIN_CHAT_ID',
    masked_chat_id: airoSprint6BMaskChatId_(raw)
  };
}

function airoSprint6BSetAdminChatId_(chatId) {
  const normalized = String(chatId || '').trim();
  if (!normalized) {
    return {
      ok: false,
      configured: false,
      property_name: 'ADMIN_CHAT_ID',
      reason: 'missing_chat_id'
    };
  }

  PropertiesService.getScriptProperties().setProperty('ADMIN_CHAT_ID', normalized);

  return {
    ok: true,
    configured: true,
    property_name: 'ADMIN_CHAT_ID',
    masked_chat_id: airoSprint6BMaskChatId_(normalized)
  };
}


function airoSprint6BIsLiveEnabled_() {
  try {
    const val = PropertiesService.getScriptProperties().getProperty('AIRO_ALERT_ENGINE_LIVE_ENABLED');
    return String(val).trim().toLowerCase() === 'true';
  } catch (err) {
    return false;
  }
}

function airoSprint6BSetLiveEnabled_(enabled) {
  const props = PropertiesService.getScriptProperties();
  if (enabled) {
    props.setProperty('AIRO_ALERT_ENGINE_LIVE_ENABLED', 'true');
  } else {
    props.setProperty('AIRO_ALERT_ENGINE_LIVE_ENABLED', 'false');
  }
}

function airoSprint6BGetLiveStatus_(ss) {
  ss = ss || SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  const isLiveEnabled = airoSprint6BIsLiveEnabled_();
  const triggers = ScriptApp.getProjectTriggers();
  let safeCount = 0;
  let liveCount = 0;

  const safeHandler = airoSprint6BTriggerHandlerName_();
  const liveHandler = 'airoSprint6BTriggerHandlerLive_';

  for (let i = 0; i < triggers.length; i++) {
    const fnName = String(triggers[i].getHandlerFunction ? triggers[i].getHandlerFunction() : '');
    if (fnName === safeHandler) {
      safeCount++;
    } else if (fnName === liveHandler) {
      liveCount++;
    }
  }

  let lastSafeSummary = 'no_recent_safe_heartbeat_found';
  let lastLiveSummary = 'no_recent_live_heartbeat_found';
  const audit = ss.getSheetByName('_AIRO_Audit_Log');
  if (audit) {
    const lastRow = audit.getLastRow();
    if (lastRow >= 2) {
      const readRows = Math.min(lastRow - 1, 100);
      const startRow = lastRow - readRows + 1;
      const vals = audit.getRange(startRow, 1, readRows, audit.getLastColumn()).getDisplayValues();

      let foundSafe = false;
      let foundLive = false;
      for (let j = vals.length - 1; j >= 0; j--) {
        if (foundSafe && foundLive) {
          break;
        }
        const row = vals[j];
        const action = String(row[2] || '');
        const desc = String(row[5] || '');
        const meta = String(row[7] || '');

        if (!foundSafe && (action === 'sprint6b_trigger_safe_heartbeat' || action === 'sprint6b_alert_runner_safe_mode')) {
          try {
            const parsedMeta = JSON.parse(meta);
            lastSafeSummary = 'Action: ' + action + ', Evaluated: ' + (parsedMeta.evaluated_count || 0) + ', Would Send: ' + (parsedMeta.would_send_count || parsedMeta.eligible_count || 0) + ', Sent: ' + (parsedMeta.sent_count || 0) + ' (' + desc + ')';
          } catch (e) {
            lastSafeSummary = 'Action: ' + action + ' (' + desc + ')';
          }
          foundSafe = true;
        }

        if (!foundLive && (action === 'sprint6b_trigger_live_heartbeat' || action === 'sprint6b_trigger_live_disabled_heartbeat' || action === 'sprint6b_trigger_live_enabled_heartbeat')) {
          try {
            const parsedMeta = JSON.parse(meta);
            const liveVal = parsedMeta.live_enabled !== undefined ? String(parsedMeta.live_enabled).toUpperCase() : 'UNKNOWN';
            const sentVal = parsedMeta.sent_count !== undefined ? parsedMeta.sent_count : 0;
            const proactiveVal = parsedMeta.proactive_send_performed !== undefined ? String(parsedMeta.proactive_send_performed).toUpperCase() : 'FALSE';
            lastLiveSummary = 'Action: ' + action + ', Evaluated: ' + (parsedMeta.evaluated_count || parsedMeta.would_send_count || 0) + ', Would Send: ' + (parsedMeta.would_send_count || parsedMeta.eligible_count || 0) + ', Sent: ' + sentVal + ', Live Enabled: ' + liveVal + ', Proactive Send: ' + proactiveVal + ' (' + desc + ')';
          } catch (e) {
            lastLiveSummary = 'Action: ' + action + ' (' + desc + ')';
          }
          foundLive = true;
        }
      }
    }
  }

  let warning = '';
  if (isLiveEnabled && liveCount === 0) {
    warning = '⚠️ WARNING: Alert engine is LIVE enabled, but no live trigger is installed in the project.';
  } else if (!isLiveEnabled && liveCount > 0) {
    warning = '⚠️ WARNING: Live trigger is installed, but alert engine is soft-disabled (LIVE enabled is false).';
  }

  return {
    live_enabled: isLiveEnabled,
    safe_trigger_count: safeCount,
    live_trigger_count: liveCount,
    live_handler_name: liveHandler,
    last_summary: lastLiveSummary !== 'no_recent_live_heartbeat_found' ? lastLiveSummary : lastSafeSummary,
    last_safe_summary: lastSafeSummary,
    last_live_summary: lastLiveSummary,
    warning: warning
  };
}

