function airoSprint6BDuplicateSuppressionRunner_(ss) {
  ss = ss || SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));

  const readback = airoSprint6BCooldownSuppressionReadback_(ss);
  const evaluated = readback.evaluated_alerts || [];
  const suppressed = readback.suppressed_alerts || [];
  const eligible = readback.eligible_alerts || [];

  let wouldSendCount = 0;
  let blockedDuplicateCount = 0;

  const decisions = [];

  for (let i = 0; i < evaluated.length; i++) {
    const item = evaluated[i] || {};
    const isSuppressed = Boolean(item.suppressed_by_cooldown);
    const decision = isSuppressed ? 'BLOCK_DUPLICATE' : 'WOULD_SEND_IF_TRIGGER_ENABLED';

    if (isSuppressed) {
      blockedDuplicateCount += 1;
    } else {
      wouldSendCount += 1;
    }

    decisions.push({
      alert_key: String(item.alert_key || ''),
      severity: String(item.severity || 'INFO'),
      title: String(item.title || ''),
      suppressed_by_cooldown: isSuppressed,
      decision: decision,
      sent: false
    });
  }

  const hasSuppressed = (suppressed.length > 0);
  const targetKey = hasSuppressed ? suppressed[0].alert_key : '';
  let targetDecision = 'NOT_FOUND';
  if (!hasSuppressed) {
    targetDecision = 'NO_SUPPRESSED_CANDIDATE';
  } else {
    for (let j = 0; j < decisions.length; j++) {
      if (decisions[j].alert_key === targetKey) {
        targetDecision = decisions[j].decision;
        break;
      }
    }
  }

  return {
    ok: true,
    sprint: '6B',
    command: 'sprint6b_duplicate_suppression_runner',
    mode: 'read-only',
    write_performed: false,
    google_write_performed: false,
    proactive_send_performed: false,
    trigger_created: false,
    evaluated_count: evaluated.length,
    blocked_duplicate_count: blockedDuplicateCount,
    would_send_count: wouldSendCount,
    sent_count: 0,
    target_key: targetKey || null,
    target_suppressed: Boolean(hasSuppressed && readback.target_key_suppressed),
    target_decision: targetDecision,
    audit_exists: Boolean(readback.audit_exists),
    cooldown_record_count: Number(readback.cooldown_record_count || 0),
    decisions: decisions,
    suppressed_alerts: suppressed,
    eligible_alerts: eligible,
    next_step: 'record duplicate suppression pass, then prepare guarded trigger installer'
  };
}

function airoBuildSprint6BDuplicateSuppressionRunnerReply_(result) {
  result = result || {};

  let msg = '🛡️ Sprint 6B duplicate suppression runner selesai.\n';
  msg += 'Mode: read-only\n';
  msg += 'Write performed: false\n';
  msg += 'Proactive send performed: false\n';
  msg += 'Trigger created: false\n\n';

  msg += 'Decision Summary\n';
  msg += '- Evaluated: ' + String(result.evaluated_count || 0) + '\n';
  msg += '- Blocked duplicate: ' + String(result.blocked_duplicate_count || 0) + '\n';
  msg += '- Would send if trigger enabled: ' + String(result.would_send_count || 0) + '\n';
  msg += '- Sent: ' + String(result.sent_count || 0) + '\n\n';

  msg += 'Target\n';
  msg += '- Key: ' + String(result.target_key || '-') + '\n';
  msg += '- Suppressed: ' + String(Boolean(result.target_suppressed)) + '\n';
  msg += '- Decision: ' + String(result.target_decision || '-') + '\n\n';

  msg += 'Suppressed Alerts\n';
  const suppressed = result.suppressed_alerts || [];
  if (!suppressed.length) {
    msg += '- none\n';
  } else {
    for (let i = 0; i < Math.min(suppressed.length, 6); i++) {
      const item = suppressed[i] || {};
      msg += '- [' + String(item.severity || 'INFO') + '] ' + String(item.title || '-') + '\n';
      msg += '  key: ' + String(item.alert_key || '-') + '\n';
    }
  }

  msg += '\nNext: kalau target decision BLOCK_DUPLICATE, duplicate suppression pass.';

  return msg.slice(0, 3900);
}

function airoSprint6BCooldownSuppressionReadback_(ss) {
  ss = ss || SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));

  const plan = airoSprint6BAlertEnginePlan_(ss, { mode: 'cooldown-readback' });
  const candidates = plan.alert_candidates || [];
  const recent = airoSprint6BCooldownReadRecentKeys_(ss);

  const evaluated = [];
  const suppressed = [];
  const eligible = [];

  for (let i = 0; i < candidates.length; i++) {
    const alert = candidates[i] || {};
    const alertKey = airoSprint6BAlertKeyForToday_(alert);
    const matched = Boolean(recent.keys && recent.keys[alertKey]);

    const row = {
      key: String(alert.key || ''),
      alert_key: alertKey,
      severity: String(alert.severity || 'INFO'),
      title: String(alert.title || ''),
      message: String(alert.message || ''),
      source: String(alert.source || ''),
      suppressed_by_cooldown: matched,
      cooldown_record: matched ? recent.keys[alertKey] : null
    };

    evaluated.push(row);

    if (matched) {
      suppressed.push(row);
    } else {
      eligible.push(row);
    }
  }

  const hasSuppressed = (suppressed.length > 0);
  const targetKey = hasSuppressed ? suppressed[0].alert_key : '';
  const targetSuppressed = hasSuppressed ? Boolean(recent.keys && recent.keys[targetKey]) : false;

  return {
    ok: true,
    sprint: '6B',
    command: 'sprint6b_cooldown_suppression_readback',
    mode: 'read-only',
    write_performed: false,
    google_write_performed: false,
    proactive_send_performed: false,
    trigger_created: false,
    audit_exists: recent.audit_exists,
    audit_rows: recent.audit_rows,
    cooldown_record_count: recent.rows.length,
    evaluated_count: evaluated.length,
    suppressed_count: suppressed.length,
    eligible_count: eligible.length,
    evaluated_alerts: evaluated,
    suppressed_alerts: suppressed.slice(0, 8),
    eligible_alerts: eligible.slice(0, 8),
    target_key_checked: targetKey || null,
    target_key_suppressed: targetSuppressed,
    status: hasSuppressed ? 'OK' : 'NO_SUPPRESSED_CANDIDATE',
    next_step: 'record cooldown suppression readback live pass, then implement duplicate suppression runner mode'
  };
}

