function airoSprint6BIsQuietHours_(dateObj) {
  dateObj = dateObj || new Date();
  const hourString = Utilities.formatDate(dateObj, 'Asia/Jakarta', 'HH');
  const hour = Number(hourString);
  return (hour >= 22 || hour < 7);
}

function airoSprint6BParseDate_(val) {
  if (val instanceof Date) return val;
  if (!val) return null;
  const str = String(val).trim();
  if (!str) return null;
  let match = str.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
  if (match) return new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
  match = str.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})/);
  if (match) return new Date(Number(match[3]), Number(match[2]) - 1, Number(match[1]));
  const parsed = new Date(str);
  return isNaN(parsed.getTime()) ? null : parsed;
}

function airoSprint6BIsRowActive_(dateVal) {
  const d = airoSprint6BParseDate_(dateVal);
  if (!d) return false;
  return d.getTime() >= new Date('2026-05-15').getTime();
}

function airoSprint6BAlertRunnerSafeMode_(ss, options) {
  ss = ss || SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  options = options || {};

  const mode = String(options.mode || 'safe');
  const shouldSend = Boolean(options.send === true);
  const shouldWriteAudit = Boolean(options.writeAudit === true);
  // Hard max-send cap: only applied when mode=live and shouldSend=true.
  const MAX_LIVE_SENDS_PER_RUN = 1;
  const isLiveSendMode = shouldSend && mode === 'live';

  const plan = airoSprint6BAlertEnginePlan_(ss, { mode: 'runner-safe' });
  const candidates = plan.alert_candidates || [];
  const recentKeys = airoSprint6BReadRecentAlertKeys_(ss);

  const isQuietHours = airoSprint6BIsQuietHours_(new Date());

  const evaluated = [];
  const eligible = [];
  const suppressed = [];

  let cooldownSuppressedCount = 0;
  let quietHoursSuppressedCount = 0;

  for (let i = 0; i < candidates.length; i++) {
    const alert = candidates[i] || {};
    const alertKey = airoSprint6BAlertKeyForToday_(alert);
    const isCooldownSuppressed = Boolean(recentKeys[alertKey]);
    const isQuietHoursSuppressed = isQuietHours && (alert.severity !== 'CRITICAL');
    const isSuppressed = isCooldownSuppressed || isQuietHoursSuppressed;

    if (isCooldownSuppressed) cooldownSuppressedCount++;
    if (isQuietHoursSuppressed) quietHoursSuppressedCount++;

    const row = {
      key: String(alert.key || ''),
      alert_key: alertKey,
      severity: String(alert.severity || 'INFO'),
      title: String(alert.title || ''),
      message: String(alert.message || ''),
      source: String(alert.source || ''),
      cooldown_minutes: Number(alert.default_cooldown_minutes || 360),
      ack_supported: Boolean(alert.ack_supported),
      suppressed_by_cooldown: isCooldownSuppressed,
      suppressed_by_quiet_hours: isQuietHoursSuppressed,
      quiet_hours_active: isQuietHours,
      would_send: !isSuppressed,
      sent: false
    };

    evaluated.push(row);

    if (isSuppressed) {
      suppressed.push(row);
    } else {
      eligible.push(row);
    }
  }

  let sentCount = 0;
  const eligibleBeforeCap = eligible.length;
  let sendCapApplied = false;
  const targetChatId = String((options && options.targetChatId) || getProp_('ADMIN_CHAT_ID') || '').trim();

  if (shouldSend) {
    // Apply hard cap when in live send mode to limit blast radius.
    const sendLimit = isLiveSendMode ? MAX_LIVE_SENDS_PER_RUN : eligible.length;
    if (isLiveSendMode && eligible.length > sendLimit) {
      sendCapApplied = true;
    }
    for (let j = 0; j < eligible.length && sentCount < sendLimit; j++) {
      const item = eligible[j];
      sendTelegram_(
        targetChatId,
        '🚨 AIRO Alert\n' +
        '[' + item.severity + '] ' + item.title + '\n\n' +
        item.message + '\n\n' +
        'Source: ' + item.source + '\n' +
        'ACK: admin alert ack ' + item.alert_key
      );
      item.sent = true;
      sentCount += 1;
    }
  }

  if (shouldWriteAudit) {
    const audit = ss.getSheetByName('_AIRO_Audit_Log');
    if (audit) {
      audit.appendRow([
        new Date(),
        'AIRO',
        'sprint6b_alert_runner_safe_mode',
        shouldSend ? 'INFO' : 'DRY_RUN',
        'Sprint 6B Alert Engine',
        'Alert runner evaluated candidates',
        'sprint6b_alert_runner',
        JSON.stringify({
          mode: mode,
          send: shouldSend,
          evaluated_count: evaluated.length,
          eligible_count: eligible.length,
          suppressed_count: suppressed.length,
          cooldown_suppressed_count: cooldownSuppressedCount,
          quiet_hours_suppressed_count: quietHoursSuppressedCount,
          quiet_hours_active: isQuietHours,
          sent_count: sentCount,
          send_cap_applied: sendCapApplied,
          max_live_sends_per_run: isLiveSendMode ? MAX_LIVE_SENDS_PER_RUN : null,
          first_alert_key: eligible.length ? eligible[0].alert_key : ''
        })
      ]);
    }
  }

  return {
    ok: true,
    sprint: '6B',
    command: 'sprint6b_alert_runner_safe_mode',
    mode: mode,
    write_performed: shouldWriteAudit,
    google_write_performed: shouldWriteAudit,
    proactive_send_performed: sentCount > 0,
    trigger_created: false,
    evaluated_count: evaluated.length,
    eligible_count: eligible.length,
    eligible_before_cap: eligibleBeforeCap,
    suppressed_count: suppressed.length,
    cooldown_suppressed_count: cooldownSuppressedCount,
    quiet_hours_suppressed_count: quietHoursSuppressedCount,
    quiet_hours_active: isQuietHours,
    sent_count: sentCount,
    send_cap_applied: sendCapApplied,
    max_live_sends_per_run: isLiveSendMode ? MAX_LIVE_SENDS_PER_RUN : null,
    target_chat_id_configured: Boolean(targetChatId),
    target_chat_id_source: options && options.targetChatId ? 'request_chat_id' : 'ADMIN_CHAT_ID',
    cooldown_storage: '_AIRO_Audit_Log',
    ack_supported: true,
    evaluated_alerts: evaluated,
    top_eligible: eligible.slice(0, 6),
    top_suppressed: suppressed.slice(0, 6),
    next_step: shouldSend ? 'validate received proactive alert and cooldown behavior' : 'run send=false safe mode accepted, then implement ACK route or controlled send test'
  };
}

