function airoSprint6BAlertEnginePlan_(ss, options) {
  ss = ss || SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  options = options || {};

  const mode = String(options.mode || 'dry-run');
  const now = new Date();

  const recon = airoSprint5ReconciliationReadOnly_(ss, { sampleLimit: 6 });
  const analytics = recon.dashboard_analytics || {};

  const ccTab = airoSprint6BGetTabSummary_(ss, '💳 Credit Card');
  const reviewTab = airoSprint6BGetTabSummary_(ss, '🧾 Review Queue');
  const accountTab = airoSprint6BGetTabSummary_(ss, '📒 Account Ledger');
  const financeEventsTab = airoSprint6BGetTabSummary_(ss, '🧭 Finance Events');
  const auditTab = airoSprint6BGetTabSummary_(ss, '_AIRO_Audit_Log');
  const dashboardTab = airoSprint6BGetTabSummary_(ss, 'Dashboard');

  const alertCandidates = [];

  const parseCleanNumber_ = function(v) {
    return Number(String(v || '').replace(/[^0-9-]/g, '')) || 0;
  };

  // A. Data Status Dirty / Warning (Dashboard)
  let dataStatus = 'Unknown';
  let dashStatusMsg = '';
  let dashStatusFound = false;

  const dashSheet = getSheetLoose_(ss, 'Dashboard');
  if (!dashSheet) {
    dataStatus = 'source_missing';
    dashStatusMsg = 'Dashboard tab is missing';
  } else {
    const lastRow = Math.min(dashSheet.getLastRow(), 30);
    const lastCol = Math.min(dashSheet.getLastColumn(), 15);
    if (lastRow < 1 || lastCol < 1) {
      dataStatus = 'source_missing';
      dashStatusMsg = 'Dashboard sheet is empty';
    } else {
      const values = dashSheet.getRange(1, 1, lastRow, lastCol).getDisplayValues();
      let foundLabel = false;
      for (let r = 0; r < values.length; r++) {
        for (let c = 0; c < values[r].length; c++) {
          const text = String(values[r][c] || '').trim();
          if (/data\s+status/i.test(text)) {
            foundLabel = true;
            if (c + 1 < values[r].length) {
              const val = String(values[r][c+1] || '').trim();
              if (val) {
                dataStatus = val;
                dashStatusFound = true;
                break;
              }
            }
          }
        }
        if (dashStatusFound) break;
      }
      if (!foundLabel) {
        dataStatus = 'not_configured';
        dashStatusMsg = 'Dashboard Data Status label not found';
      } else if (!dashStatusFound) {
        dataStatus = 'not_configured';
        dashStatusMsg = 'Dashboard Data Status value is empty';
      }
    }
  }

  if (dataStatus === 'Dirty') {
    alertCandidates.push({
      key: 'data_status_dirty',
      severity: 'CRITICAL',
      title: 'Data Status Dirty',
      message: 'Dashboard Data Status is Dirty.',
      source: 'Dashboard',
      cooldown_key: 'data_status_dirty',
      default_cooldown_minutes: 360,
      send_now_in_dry_run: false,
      ack_supported: true
    });
  } else if (dataStatus === 'Warning') {
    alertCandidates.push({
      key: 'data_status_warning',
      severity: 'WARNING',
      title: 'Data Status Warning',
      message: 'Dashboard Data Status is Warning; review Action Required before trusting clean insights.',
      source: 'Dashboard',
      cooldown_key: 'data_status_warning',
      default_cooldown_minutes: 720,
      send_now_in_dry_run: false,
      ack_supported: true
    });
  } else if (dataStatus === 'source_missing' || dataStatus === 'not_configured') {
    alertCandidates.push({
      key: 'data_status_dirty',
      severity: 'WARNING',
      title: 'Data Status Monitor Error',
      message: 'Dashboard status check failed: ' + dataStatus + ' (' + dashStatusMsg + ')',
      source: 'Dashboard',
      cooldown_key: 'data_status_dirty',
      default_cooldown_minutes: 360,
      send_now_in_dry_run: false,
      ack_supported: true
    });
  }

  // B. Credit Card Due
  let ccDueAlertItem = null;
  if (!ccTab.exists) {
    ccDueAlertItem = {
      key: 'cc_due_monitor',
      severity: 'WARNING',
      title: 'Credit Card Due Monitor Error',
      message: 'Credit Card source tab is missing; cc_due_monitor source_missing',
      source: 'Credit Card',
      cooldown_key: 'cc_due_monitor',
      default_cooldown_minutes: 1440,
      send_now_in_dry_run: false,
      ack_supported: true
    };
  } else {
    const ccSheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.creditCard);
    if (!ccSheet) {
      ccDueAlertItem = {
        key: 'cc_due_monitor',
        severity: 'WARNING',
        title: 'Credit Card Due Monitor Error',
        message: 'Credit Card source tab is missing; cc_due_monitor source_missing',
        source: 'Credit Card',
        cooldown_key: 'cc_due_monitor',
        default_cooldown_minutes: 1440,
        send_now_in_dry_run: false,
        ack_supported: true
      };
    } else {
      const ccHeader = findCcHeaderRow_(ccSheet);
      if (!ccHeader) {
        ccDueAlertItem = {
          key: 'cc_due_monitor',
          severity: 'WARNING',
          title: 'Credit Card Due Monitor Error',
          message: 'Credit Card due monitor not_configured: header row not found',
          source: 'Credit Card',
          cooldown_key: 'cc_due_monitor',
          default_cooldown_minutes: 1440,
          send_now_in_dry_run: false,
          ack_supported: true
        };
      } else {
        const colMap = ccColMap_(ccHeader.headers);
        const idxStatus = (colMap[canonicalKey_('status_pocket_blu')] || 0) - 1;
        const idxDate = (colMap[canonicalKey_('date')] || 0) - 1;
        const idxAmount = (colMap[canonicalKey_('amount')] || 0) - 1;

        if (idxStatus < 0 || idxDate < 0) {
          ccDueAlertItem = {
            key: 'cc_due_monitor',
            severity: 'WARNING',
            title: 'Credit Card Due Monitor Error',
            message: 'Credit Card due monitor not_configured: status or date mapping missing',
            source: 'Credit Card',
            cooldown_key: 'cc_due_monitor',
            default_cooldown_minutes: 1440,
            send_now_in_dry_run: false,
            ack_supported: true
          };
        } else {
          const lastRow = ccSheet.getLastRow();
          let unpaidCount = 0;
          let unpaidTotal = 0;
          let minDiffDays = Infinity;
          let targetDue = null;

          if (lastRow > ccHeader.row) {
            const values = ccSheet.getRange(ccHeader.row + 1, 1, lastRow - ccHeader.row, ccHeader.headers.length).getDisplayValues();
            for (let r = 0; r < values.length; r++) {
              const row = values[r];
              const statusVal = String(row[idxStatus] || '').trim();
              const dateVal = String(row[idxDate] || '').trim();
              const amountVal = idxAmount >= 0 ? parseCleanNumber_(row[idxAmount]) : 0;
              const isUnpaid = (!statusVal || statusVal === '⏳ Belum');

              if (isUnpaid && dateVal) {
                const parsedDate = airoSprint6BParseDate_(dateVal);
                if (parsedDate) {
                  const cycle = ccBillingCycle_(parsedDate);
                  const dueDate = ccDueDateForCycle_(cycle);
                  const diffTime = dueDate.getTime() - now.getTime();
                  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                  unpaidCount++;
                  unpaidTotal += amountVal;
                  if (diffDays < minDiffDays) {
                    minDiffDays = diffDays;
                    targetDue = dueDate;
                  }
                }
              }
            }
          }

          if (unpaidCount > 0 && minDiffDays <= 3) {
            ccDueAlertItem = {
              key: 'cc_due_monitor',
              severity: minDiffDays < 0 ? 'CRITICAL' : 'WARNING',
              title: 'Credit Card Payment Due Soon',
              message: 'Credit Card has ' + unpaidCount + ' unpaid transaction(s) total Rp' + unpaidTotal.toLocaleString('id-ID') + '. Closest due is in ' + minDiffDays + ' days on ' + (targetDue ? formatDateYmd_(targetDue) : '-') + '.',
              source: 'Credit Card',
              cooldown_key: 'cc_due_monitor',
              default_cooldown_minutes: 1440,
              send_now_in_dry_run: false,
              ack_supported: true
            };
          } else {
            ccDueAlertItem = {
              key: 'cc_due_monitor',
              severity: 'INFO',
              title: 'Credit Card Due Monitor',
              message: 'Credit Card billing is active; no payments due soon (<= 3 days).',
              source: 'Credit Card',
              cooldown_key: 'cc_due_monitor',
              default_cooldown_minutes: 1440,
              send_now_in_dry_run: false,
              ack_supported: true
            };
          }
        }
      }
    }
  }
  if (ccDueAlertItem) {
    alertCandidates.push(ccDueAlertItem);
  }

  // C. Cash Wallet Threshold
  let cashThresholdAlertItem = null;
  let threshold = 1000000;

  const settingsSheet = getSheetLoose_(ss, 'Settings');
  if (settingsSheet) {
    const sLastRow = settingsSheet.getLastRow();
    if (sLastRow > 0) {
      const sVals = settingsSheet.getRange(1, 1, sLastRow, Math.min(settingsSheet.getLastColumn(), 5)).getValues();
      for (let i = 0; i < sVals.length; i++) {
        const key = String(sVals[i][0] || '').toLowerCase().trim();
        if (key.includes('cash_threshold') || key.includes('cash threshold')) {
          const val = Number(sVals[i][1]);
          if (!isNaN(val) && val > 0) {
            threshold = val;
            break;
          }
        }
      }
    }
  }

  if (!accountTab.exists) {
    cashThresholdAlertItem = {
      key: 'cash_threshold',
      severity: 'WARNING',
      title: 'Cash Wallet Threshold Error',
      message: 'Account Ledger source tab is missing; cash_threshold source_missing',
      source: 'Account Ledger',
      cooldown_key: 'cash_threshold',
      default_cooldown_minutes: 1440,
      send_now_in_dry_run: false,
      ack_supported: true
    };
  } else {
    const accountSheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.accountLedger);
    if (!accountSheet) {
      cashThresholdAlertItem = {
        key: 'cash_threshold',
        severity: 'WARNING',
        title: 'Cash Wallet Threshold Error',
        message: 'Account Ledger source tab is missing; cash_threshold source_missing',
        source: 'Account Ledger',
        cooldown_key: 'cash_threshold',
        default_cooldown_minutes: 1440,
        send_now_in_dry_run: false,
        ack_supported: true
      };
    } else {
      const headerObj = findHeader_(accountSheet);
      if (!headerObj) {
        cashThresholdAlertItem = {
          key: 'cash_threshold',
          severity: 'WARNING',
          title: 'Cash Wallet Threshold Error',
          message: 'Account Ledger cash threshold not_configured: header row not found',
          source: 'Account Ledger',
          cooldown_key: 'cash_threshold',
          default_cooldown_minutes: 1440,
          send_now_in_dry_run: false,
          ack_supported: true
        };
      } else {
        const headers = headerObj.headers;
        const colMap = {};
        headers.forEach((h, idx) => {
          colMap[canonicalKey_(h)] = idx;
        });
        const idxAccount = colMap['account'];
        const idxInflow = colMap['amount_in'];
        const idxOutflow = colMap['amount_out'];

        if (idxAccount < 0 || idxInflow < 0 || idxOutflow < 0) {
          cashThresholdAlertItem = {
            key: 'cash_threshold',
            severity: 'WARNING',
            title: 'Cash Wallet Threshold Error',
            message: 'Account Ledger cash threshold not_configured: status or amount columns missing',
            source: 'Account Ledger',
            cooldown_key: 'cash_threshold',
            default_cooldown_minutes: 1440,
            send_now_in_dry_run: false,
            ack_supported: true
          };
        } else {
          let cashUmumTotal = 0;
          let cashBensinTotal = 0;
          let cashLegacyTotal = 0;
          const lastRow = accountSheet.getLastRow();
          const startRow = headerObj.row + 1;

          if (lastRow >= startRow) {
            const data = accountSheet.getRange(startRow, 1, lastRow - startRow + 1, headers.length).getValues();
            for (let i = 0; i < data.length; i++) {
              const rowVals = data[i];
              const accVal = String(rowVals[idxAccount] || '').trim();
              const inflowVal = Number(rowVals[idxInflow]) || 0;
              const outflowVal = Number(rowVals[idxOutflow]) || 0;

              if (accVal === 'Cash Umum') {
                cashUmumTotal += (inflowVal - outflowVal);
              } else if (accVal === 'Cash Bensin') {
                cashBensinTotal += (inflowVal - outflowVal);
              } else if (accVal === 'Cash') {
                cashLegacyTotal += (inflowVal - outflowVal);
              }
            }
          }

          const totalCash = cashUmumTotal + cashBensinTotal + cashLegacyTotal;
          if (totalCash < threshold) {
            cashThresholdAlertItem = {
              key: 'cash_threshold',
              severity: 'WARNING',
              title: 'Cash Wallet Low Balance',
              message: 'Total Cash balance Rp' + totalCash.toLocaleString('id-ID') + ' is below threshold Rp' + threshold.toLocaleString('id-ID') + ' (Cash Umum: Rp' + cashUmumTotal.toLocaleString('id-ID') + ', Cash Bensin: Rp' + cashBensinTotal.toLocaleString('id-ID') + ').',
              source: 'Account Ledger',
              cooldown_key: 'cash_threshold',
              default_cooldown_minutes: 1440,
              send_now_in_dry_run: false,
              ack_supported: true
            };
          }
        }
      }
    }
  }
  if (cashThresholdAlertItem) {
    alertCandidates.push(cashThresholdAlertItem);
  }

  // D. Partial Write Failure & Missing Category (Finance Events)
  let partialWriteAlertItem = null;
  let missingCategoryAlertItem = null;

  if (!financeEventsTab.exists) {
    partialWriteAlertItem = {
      key: 'partial_write_failure',
      severity: 'WARNING',
      title: 'Partial Write Monitor Error',
      message: 'Finance Events tab is missing; partial_write_failure source_missing',
      source: 'Finance Events',
      cooldown_key: 'partial_write_failure',
      default_cooldown_minutes: 60,
      send_now_in_dry_run: false,
      ack_supported: true
    };
    missingCategoryAlertItem = {
      key: 'partial_write_failure',
      severity: 'WARNING',
      title: 'Missing Category Monitor Error',
      message: 'Finance Events tab is missing; missing_category source_missing',
      source: 'Finance Events',
      cooldown_key: 'partial_write_failure',
      default_cooldown_minutes: 60,
      send_now_in_dry_run: false,
      ack_supported: true
    };
  } else {
    const eventsSheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.financeEvents);
    if (!eventsSheet) {
      partialWriteAlertItem = {
        key: 'partial_write_failure',
        severity: 'WARNING',
        title: 'Partial Write Monitor Error',
        message: 'Finance Events tab is missing; partial_write_failure source_missing',
        source: 'Finance Events',
        cooldown_key: 'partial_write_failure',
        default_cooldown_minutes: 60,
        send_now_in_dry_run: false,
        ack_supported: true
      };
      missingCategoryAlertItem = {
        key: 'partial_write_failure',
        severity: 'WARNING',
        title: 'Missing Category Monitor Error',
        message: 'Finance Events tab is missing; missing_category source_missing',
        source: 'Finance Events',
        cooldown_key: 'partial_write_failure',
        default_cooldown_minutes: 60,
        send_now_in_dry_run: false,
        ack_supported: true
      };
    } else {
      const lastRow = eventsSheet.getLastRow();
      const lastCol = eventsSheet.getLastColumn();
      if (lastRow < 2) {
        // empty sheet
      } else {
        const headers = eventsSheet.getRange(1, 1, 1, lastCol).getDisplayValues()[0].map(h => String(h || '').trim().toLowerCase());
        const colMap = {};
        headers.forEach((h, idx) => {
          colMap[canonicalKey_(h)] = idx;
        });

        const idxStatus = colMap['status'] !== undefined ? colMap['status'] : -1;
        const idxWriteStatus = colMap['write_status'] !== undefined ? colMap['write_status'] : -1;
        const idxReconStatus = colMap['reconciliation_status'] !== undefined ? colMap['reconciliation_status'] : -1;

        const idxQualityStatus = colMap['quality_status'] !== undefined ? colMap['quality_status'] : -1;
        const idxCategory = colMap['category'] !== undefined ? colMap['category'] : -1;

        const idxEventTs = colMap['event_ts'] !== undefined ? colMap['event_ts'] : (colMap['date'] !== undefined ? colMap['date'] : -1);
        const idxEventType = colMap['event_type'] !== undefined ? colMap['event_type'] : -1;

        if ((idxStatus < 0 && idxWriteStatus < 0 && idxReconStatus < 0) || idxEventTs < 0) {
          partialWriteAlertItem = {
            key: 'partial_write_failure',
            severity: 'WARNING',
            title: 'Partial Write Monitor Error',
            message: 'Finance Events columns missing; partial_write_failure not_configured',
            source: 'Finance Events',
            cooldown_key: 'partial_write_failure',
            default_cooldown_minutes: 60,
            send_now_in_dry_run: false,
            ack_supported: true
          };
        }
        if (idxCategory < 0 && idxQualityStatus < 0) {
          missingCategoryAlertItem = {
            key: 'partial_write_failure',
            severity: 'WARNING',
            title: 'Missing Category Monitor Error',
            message: 'Finance Events columns missing; missing_category not_configured',
            source: 'Finance Events',
            cooldown_key: 'partial_write_failure',
            default_cooldown_minutes: 60,
            send_now_in_dry_run: false,
            ack_supported: true
          };
        }

        if (!partialWriteAlertItem || !missingCategoryAlertItem) {
          const values = eventsSheet.getRange(2, 1, lastRow - 1, lastCol).getDisplayValues();
          let failedCount = 0;
          let firstFailedType = '';
          let firstFailedRow = -1;

          let missingCategoryCount = 0;
          let firstMissingCatType = '';
          let firstMissingCatRow = -1;

          for (let r = 0; r < values.length; r++) {
            const row = values[r];
            const rowNum = r + 2;
            const dateVal = String(row[idxEventTs] || '').trim();
            const isActive = airoSprint6BIsRowActive_(dateVal);

            if (isActive) {
              let hasWriteFailure = false;
              if (idxStatus >= 0) {
                const s = String(row[idxStatus] || '').trim().toLowerCase();
                if (/failed|error|partial/i.test(s)) hasWriteFailure = true;
              }
              if (idxWriteStatus >= 0) {
                const s = String(row[idxWriteStatus] || '').trim().toLowerCase();
                if (/failed|error|partial/i.test(s)) hasWriteFailure = true;
              }
              if (idxReconStatus >= 0) {
                const s = String(row[idxReconStatus] || '').trim().toLowerCase();
                if (/failed|error|partial/i.test(s)) hasWriteFailure = true;
              }

              if (hasWriteFailure) {
                failedCount++;
                if (firstFailedRow < 0) {
                  firstFailedRow = rowNum;
                  firstFailedType = idxEventType >= 0 ? String(row[idxEventType] || '') : 'Unknown';
                }
              }

              let isMissingCategory = false;
              if (idxQualityStatus >= 0) {
                const s = String(row[idxQualityStatus] || '').trim().toLowerCase();
                if (s.includes('missing_category') || s.includes('uncategorized')) isMissingCategory = true;
              }
              if (idxCategory >= 0) {
                const c = String(row[idxCategory] || '').trim().toLowerCase();
                if (!c || /^(lainnya|lain|uncategorized|unknown)$/i.test(c)) isMissingCategory = true;
              }

              if (isMissingCategory) {
                missingCategoryCount++;
                if (firstMissingCatRow < 0) {
                  firstMissingCatRow = rowNum;
                  firstMissingCatType = idxEventType >= 0 ? String(row[idxEventType] || '') : 'Unknown';
                }
              }
            }
          }

          if (failedCount > 0 && !partialWriteAlertItem) {
            partialWriteAlertItem = {
              key: 'partial_write_failure',
              severity: 'CRITICAL',
              title: 'Finance Event Write Failure',
              message: 'Finance Events has ' + failedCount + ' active failed/partial write row(s) (e.g. Row ' + firstFailedRow + ', event_type: ' + firstFailedType + ').',
              source: 'Finance Events',
              cooldown_key: 'partial_write_failure',
              default_cooldown_minutes: 60,
              send_now_in_dry_run: false,
              ack_supported: true
            };
          }
          if (missingCategoryCount > 0 && !missingCategoryAlertItem) {
            missingCategoryAlertItem = {
              key: 'missing_category',
              severity: 'WARNING',
              title: 'Missing Transaction Category',
              message: 'Finance Events has ' + missingCategoryCount + ' active transaction(s) with missing or unclassified categories (e.g. Row ' + firstMissingCatRow + ', event_type: ' + firstMissingCatType + ').',
              source: 'Finance Events',
              cooldown_key: 'missing_category',
              default_cooldown_minutes: 360,
              send_now_in_dry_run: false,
              ack_supported: true
            };
          }
        }
      }
    }
  }

  if (partialWriteAlertItem) alertCandidates.push(partialWriteAlertItem);
  if (missingCategoryAlertItem) alertCandidates.push(missingCategoryAlertItem);

  // E. Pending Clarification Timeout
  let pendingClarificationAlertItem = null;
  try {
    const props = PropertiesService.getScriptProperties().getProperties();
    const keys = Object.keys(props);
    const pendingTimeouts = [];
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      if (k.indexOf('AIRO_PENDING_CLARIFICATION_') === 0) {
        const chatId = k.replace('AIRO_PENDING_CLARIFICATION_', '');
        try {
          const item = JSON.parse(props[k]);
          if (item && item.updated_at) {
            const updatedDate = new Date(item.updated_at);
            const diffMs = now.getTime() - updatedDate.getTime();
            const diffHours = diffMs / (1000 * 60 * 60);
            if (diffHours > 24) {
              pendingTimeouts.push({
                chatId: chatId,
                type: item.type || 'unknown',
                hours: Math.floor(diffHours),
                updated_at: item.updated_at
              });
            }
          }
        } catch (e) {}
      }
    }

    if (pendingTimeouts.length > 0) {
      pendingClarificationAlertItem = {
        key: 'pending_clarification_timeout',
        severity: 'WARNING',
        title: 'Pending Clarification Timeout',
        message: 'There are ' + pendingTimeouts.length + ' pending clarification(s) older than 24 hours (e.g. Chat ID ' + pendingTimeouts[0].chatId + ', type: ' + pendingTimeouts[0].type + ', pending ' + pendingTimeouts[0].hours + 'h).',
        source: 'PropertiesService',
        cooldown_key: 'pending_clarification_timeout',
        default_cooldown_minutes: 360,
        send_now_in_dry_run: false,
        ack_supported: true
      };
    }
  } catch (err) {
    pendingClarificationAlertItem = {
      key: 'pending_clarification_timeout',
      severity: 'WARNING',
      title: 'Pending Clarification Monitor Error',
      message: 'Pending clarification read failed; pending_clarification_timeout not_configured',
      source: 'PropertiesService',
      cooldown_key: 'pending_clarification_timeout',
      default_cooldown_minutes: 360,
      send_now_in_dry_run: false,
      ack_supported: true
    };
  }
  if (pendingClarificationAlertItem) {
    alertCandidates.push(pendingClarificationAlertItem);
  }

  // F. Critical Reconciliation Issue
  if (recon && recon.reconciliation && Number(recon.reconciliation.critical_count || 0) > 0) {
    alertCandidates.push({
      key: 'critical_reconciliation_issue',
      severity: 'CRITICAL',
      title: 'Critical Reconciliation Issue',
      message: 'Reconciliation verifier found ' + recon.reconciliation.critical_count + ' active critical issue(s).',
      source: 'Sprint 5 reconciliation analytics',
      cooldown_key: 'critical_reconciliation_issue',
      default_cooldown_minutes: 360,
      send_now_in_dry_run: false,
      ack_supported: true
    });
  }

  alertCandidates.sort(function(a, b) {
    return airoSprint6BSeverityRank_(a.severity) - airoSprint6BSeverityRank_(b.severity);
  });

  const alertTypes = [
    {
      key: 'cc_due',
      status: ccTab.exists ? 'planned' : 'blocked_missing_source',
      source: ccTab.actual_name || '💳 Credit Card',
      trigger: 'scheduled daily',
      cooldown_minutes: 1440,
      ack_supported: true
    },
    {
      key: 'data_status_dirty',
      status: 'planned',
      source: 'Sprint 5 reconciliation analytics',
      trigger: 'scheduled and after reconciliation',
      cooldown_minutes: 360,
      ack_supported: true
    },
    {
      key: 'partial_write_failure',
      status: 'planned',
      source: 'Finance Events + Audit Log',
      trigger: 'after write failure detection',
      cooldown_minutes: 60,
      ack_supported: true
    },
    {
      key: 'pending_clarification_timeout',
      status: reviewTab.exists ? 'planned' : 'blocked_missing_source',
      source: reviewTab.actual_name || '🧾 Review Queue',
      trigger: 'scheduled hourly',
      cooldown_minutes: 360,
      ack_supported: true
    },
    {
      key: 'cash_threshold',
      status: accountTab.exists ? 'planned' : 'blocked_missing_source',
      source: accountTab.actual_name || '📒 Account Ledger',
      trigger: 'scheduled daily',
      cooldown_minutes: 1440,
      ack_supported: true
    }
  ];

  return {
    ok: true,
    sprint: '6B',
    command: 'sprint6b_alert_engine_plan',
    mode: mode,
    write_performed: false,
    google_write_performed: false,
    proactive_send_performed: false,
    trigger_created: false,
    generated_at: now,
    data_status: dataStatus,
    critical_count: Number(recon.reconciliation.critical_count || 0),
    quiet_hours_active: airoSprint6BIsQuietHours_(now),
    source_status: {
      dashboard: dashboardTab,
      account_ledger: accountTab,
      finance_events: financeEventsTab,
      credit_card: ccTab,
      review_queue: reviewTab,
      audit_log: auditTab
    },
    alert_types: alertTypes,
    alert_candidates: alertCandidates,
    alert_candidate_count: alertCandidates.length,
    cooldown_policy: {
      enabled: true,
      storage: '_AIRO_Audit_Log',
      key_format: 'alert_type + yyyyMMdd + severity',
      default_cooldown_minutes: 360,
      ack_command_planned: 'admin alert ack <alert_key>'
    },
    next_step: 'implement scheduled alert runner after dry-run plan is accepted'
  };
}

function airoBuildSprint6BAlertEnginePlanReply_(plan) {
  plan = plan || {};
  const source = plan.source_status || {};
  const types = plan.alert_types || [];
  const candidates = plan.alert_candidates || [];

  let msg = '🚨 Sprint 6B Alert Engine plan siap.\n';
  msg += 'Mode: ' + String(plan.mode || 'dry-run') + '\n';
  msg += 'Quiet hours active (Asia/Jakarta): ' + String(plan.quiet_hours_active || false) + '\n';
  msg += 'Write performed: false\n';
  msg += 'Proactive send performed: false\n';
  msg += 'Trigger created: false\n\n';

  msg += 'Current Trust\n';
  msg += '- Data Status: ' + String(plan.data_status || '-') + '\n';
  msg += '- Critical: ' + String(plan.critical_count || 0) + '\n';
  msg += '- Alert candidates: ' + String(plan.alert_candidate_count || 0) + '\n\n';

  msg += 'Sources\n';
  const sourceKeys = Object.keys(source);
  for (let i = 0; i < sourceKeys.length; i++) {
    const key = sourceKeys[i];
    const item = source[key] || {};
    msg += '- ' + key + ': ' + (item.exists ? 'OK' : 'MISSING') + ' (' + String(item.actual_name || item.requested_name || '-') + ')\n';
  }

  msg += '\nAlert Types\n';
  for (let j = 0; j < Math.min(types.length, 8); j++) {
    const item = types[j] || {};
    msg += '- ' + String(item.key || '-') + ': ' + String(item.status || '-') + ', cooldown ' + String(item.cooldown_minutes || 0) + 'm\n';
  }

  msg += '\nTop Candidates\n';
  for (let k = 0; k < Math.min(candidates.length, 6); k++) {
    const item = candidates[k] || {};
    msg += '- [' + String(item.severity || 'INFO') + '] ' + String(item.title || '-') + ': ' + String(item.message || '-') + '\n';
  }

  msg += '\nCooldown\n';
  msg += '- Enabled: true\n';
  msg += '- Storage: _AIRO_Audit_Log\n';
  msg += '- ACK planned: admin alert ack <alert_key>\n\n';

  msg += 'Next: kalau plan ini benar, lanjut implement scheduled alert runner.';

  return msg.slice(0, 3900);
}

function airoSprint6DashboardFinalReadback_(ss) {
  ss = ss || SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));

  const found = airoSprint6FindSheetLoose_(ss, 'Dashboard');
  if (!found || !found.sheet) {
    return {
      ok: false,
      command: 'sprint6_dashboard_final_readback',
      write_performed: false,
      google_write_performed: false,
      dashboard_found: false,
      error: 'Dashboard tab not found'
    };
  }

  const sh = found.sheet;
  const lastRow = sh.getLastRow();
  const lastCol = sh.getLastColumn();
  const readRows = Math.max(1, Math.min(lastRow || 1, 80));
  const readCols = Math.max(1, Math.min(lastCol || 1, 16));

  const values = sh.getRange(1, 1, readRows, readCols).getDisplayValues();
  const flat = values.map(function(row) {
    return row.join(' | ');
  }).join('\n');

  const lower = flat.toLowerCase();

  const markers = [
    'AIRO Finance Command Center',
    'Sprint 6 Dashboard Final',
    'Data Status',
    'Cash Ledger dependency',
    'FORBIDDEN',
    'Action Required',
    'Executive Command Center',
    'Wallet & Cashflow',
    'Domain Health',
    'Data Quality Center',
    'Smart Insight Panel',
    'Email Ingestion',
    'HIDDEN'
  ];

  const markerStatus = {};
  for (let i = 0; i < markers.length; i++) {
    const marker = markers[i];
    markerStatus[marker] = lower.indexOf(marker.toLowerCase()) >= 0;
  }

  const preview = [];
  for (let r = 0; r < Math.min(values.length, 14); r++) {
    const row = values[r] || [];
    const line = row.slice(0, Math.min(row.length, 7)).join(' | ');
    if (String(line).replace(/\s+/g, '').length) {
      preview.push(String(r + 1) + ': ' + line);
    }
  }

  const backupTabs = ss.getSheets()
    .map(function(sheet) {
      return sheet.getName();
    })
    .filter(function(name) {
      return String(name || '').indexOf('_AIRO_Dashboard_Backup_') === 0;
    })
    .sort();

  const audit = ss.getSheetByName('_AIRO_Audit_Log');
  let auditRows = 0;
  let auditPreview = '';
  let auditHasBuildEvent = false;

  if (audit) {
    auditRows = audit.getLastRow();
    const auditCols = Math.max(1, Math.min(audit.getLastColumn() || 1, 8));
    const startRow = Math.max(1, auditRows - 4);
    const numRows = Math.max(1, auditRows - startRow + 1);
    const auditValues = audit.getRange(startRow, 1, numRows, auditCols).getDisplayValues();
    auditPreview = auditValues.map(function(row) {
      return row.join(' | ');
    }).join('\n');
    auditHasBuildEvent = auditPreview.toLowerCase().indexOf('sprint6_dashboard_final_controlled_build') >= 0;
  }

  const requiredMarkers = [
    'AIRO Finance Command Center',
    'Data Status',
    'Cash Ledger dependency',
    'FORBIDDEN',
    'Action Required',
    'Data Quality Center'
  ];

  let passCount = 0;
  for (let j = 0; j < requiredMarkers.length; j++) {
    if (markerStatus[requiredMarkers[j]]) {
      passCount += 1;
    }
  }

  // AIRO_SPRINT6_DASHBOARD_PANEL_GUARD_INTEGRITY_V1
  const getValueSafe = function(r, c) {
    if (r - 1 < values.length && c - 1 < values[r - 1].length) {
      return String(values[r - 1][c - 1] || '').trim();
    }
    return '';
  };

  const findValToRightOfLabel = function(pat) {
    for (let r = 0; r < values.length; r++) {
      for (let c = 0; c < values[r].length; c++) {
        const text = String(values[r][c] || '').trim();
        if (pat.test(text)) {
          if (c + 1 < values[r].length) {
            return String(values[r][c + 1] || '').trim();
          }
        }
      }
    }
    return '';
  };

  let netWorthPanelSafe = false;
  for (let r = 16; r <= 24; r++) {
    for (let c = 9; c <= 14; c++) {
      if (/NET WORTH/i.test(getValueSafe(r, c))) {
        netWorthPanelSafe = true;
        break;
      }
    }
    if (netWorthPanelSafe) break;
  }

  let ccPanelSafe = false;
  for (let r = 25; r <= 34; r++) {
    for (let c = 9; c <= 14; c++) {
      if (/CREDIT CARD/i.test(getValueSafe(r, c))) {
        ccPanelSafe = true;
        break;
      }
    }
    if (ccPanelSafe) break;
  }

  let oldNetWorthCollisionClean = true;
  for (let c = 2; c <= 7; c++) {
    if (/NET WORTH & HOME EQUITY/i.test(getValueSafe(16, c))) {
      oldNetWorthCollisionClean = false;
      break;
    }
  }

  let oldCcCollisionClean = true;
  for (let c = 2; c <= 7; c++) {
    if (/CREDIT CARD [—–-] TOKOPEDIA CC/i.test(getValueSafe(25, c))) {
      oldCcCollisionClean = false;
      break;
    }
  }

  let actionRequiredCount = 0;
  let actionRequiredHeaderRow = -1;
  for (let r = 0; r < values.length; r++) {
    for (let c = 0; c < values[r].length; c++) {
      const text = String(values[r][c] || '').trim();
      if (/^action required:?$/i.test(text)) {
        actionRequiredHeaderRow = r;
        break;
      }
    }
    if (actionRequiredHeaderRow >= 0) break;
  }

  if (actionRequiredHeaderRow >= 0) {
    for (let r = actionRequiredHeaderRow + 2; r < values.length; r++) {
      const col1 = String(values[r][0] || '').trim();
      const col2 = String(values[r][1] || '').trim();
      if (/domain health|data quality center|smart insight panel/i.test(col1)) {
        break;
      }
      if (col1 && col2 && !/no active action required/i.test(col2)) {
        actionRequiredCount++;
      }
    }
  }

  const displayedDataStatus = findValToRightOfLabel(/^data status:?$/i);
  const displayedActiveIssues = Number(findValToRightOfLabel(/^active issues:?$/i).replace(/[^0-9]/g, '')) || 0;
  const displayedCriticalIssues = Number(findValToRightOfLabel(/^critical( issues)?:?$/i).replace(/[^0-9]/g, '')) || 0;

  let falseCleanDetected = false;
  let falseCleanReason = '';
  if (/trusted/i.test(displayedDataStatus)) {
    if (displayedActiveIssues > 0 || displayedCriticalIssues > 0 || actionRequiredCount > 0) {
      falseCleanDetected = true;
      falseCleanReason = 'Status is Trusted but issues (Active: ' + displayedActiveIssues + ', Critical: ' + displayedCriticalIssues + ', Actions: ' + actionRequiredCount + ') exist';
    }
  }

  const panelGuardPass = (
    netWorthPanelSafe &&
    ccPanelSafe &&
    oldNetWorthCollisionClean &&
    oldCcCollisionClean &&
    !falseCleanDetected
  );

  return {
    ok: true,
    command: 'sprint6_dashboard_final_readback',
    write_performed: false,
    google_write_performed: false,
    dashboard_found: true,
    dashboard_requested_name: found.requested_name,
    dashboard_actual_name: found.actual_name,
    dashboard_match_type: found.match_type,
    dashboard_rows: lastRow,
    dashboard_cols: lastCol,
    marker_status: markerStatus,
    required_marker_pass_count: passCount,
    required_marker_total: requiredMarkers.length,
    required_marker_pass: passCount === requiredMarkers.length,
    backup_tab_count: backupTabs.length,
    latest_backup_tab: backupTabs.length ? backupTabs[backupTabs.length - 1] : '',
    audit_log_exists: Boolean(audit),
    audit_log_rows: auditRows,
    audit_has_build_event_in_last_rows: auditHasBuildEvent,
    preview: preview,
    audit_preview: auditPreview,
    net_worth_panel_safe: netWorthPanelSafe,
    cc_panel_safe: ccPanelSafe,
    old_net_worth_collision_clean: oldNetWorthCollisionClean,
    old_cc_collision_clean: oldCcCollisionClean,
    false_clean_detected: falseCleanDetected,
    false_clean_reason: falseCleanReason,
    panel_guard_pass: panelGuardPass
  };
}

function airoBuildSprint6DashboardFinalReadbackReply_(result) {
  result = result || {};
  let msg = '🔎 Sprint 6 Dashboard Final readback selesai.\n';
  msg += 'Mode: read-only\n';
  msg += 'Write performed: false\n\n';

  msg += 'Dashboard\n';
  msg += '- Found: ' + String(Boolean(result.dashboard_found)) + '\n';
  msg += '- Actual tab: ' + String(result.dashboard_actual_name || '-') + '\n';
  msg += '- Rows: ' + String(result.dashboard_rows || 0) + '\n';
  msg += '- Cols: ' + String(result.dashboard_cols || 0) + '\n\n';

  msg += 'Markers\n';
  msg += '- Required marker pass: ' + String(result.required_marker_pass_count || 0) + '/' + String(result.required_marker_total || 0) + '\n';
  const markers = result.marker_status || {};
  const markerNames = Object.keys(markers);
  const requiredSet = {
    'AIRO Finance Command Center': true,
    'Data Status': true,
    'Cash Ledger dependency': true,
    'FORBIDDEN': true,
    'Action Required': true,
    'Data Quality Center': true
  };
  for (let i = 0; i < markerNames.length; i++) {
    const name = markerNames[i];
    const isOptional = !requiredSet[name];
    const optionalLabel = isOptional ? ' (Optional)' : '';
    msg += '- ' + name + optionalLabel + ': ' + (markers[name] ? 'OK' : 'MISSING') + '\n';
  }

  msg += '\nBackup\n';
  msg += '- Backup tab count: ' + String(result.backup_tab_count || 0) + '\n';
  msg += '- Latest backup: ' + String(result.latest_backup_tab || '-') + '\n\n';

  msg += 'Audit Log\n';
  msg += '- Exists: ' + String(Boolean(result.audit_log_exists)) + '\n';
  msg += '- Rows: ' + String(result.audit_log_rows || 0) + '\n';
  msg += '- Build event in last rows: ' + String(Boolean(result.audit_has_build_event_in_last_rows)) + '\n\n';

  msg += 'Panel Guard & Integrity\n';
  msg += '- Panel Guard Pass: ' + String(Boolean(result.panel_guard_pass)) + '\n';
  msg += '- Net Worth safe (I16:N24): ' + (result.net_worth_panel_safe ? 'OK' : 'MISSING') + '\n';
  msg += '- Credit Card safe (I25:N34): ' + (result.cc_panel_safe ? 'OK' : 'MISSING') + '\n';
  msg += '- Old NW collision clean (B16:G24): ' + (result.old_net_worth_collision_clean ? 'CLEAN' : 'WARNING/COLLISION') + '\n';
  msg += '- Old CC collision clean (B25:G34): ' + (result.old_cc_collision_clean ? 'CLEAN' : 'WARNING/COLLISION') + '\n';
  msg += '- False-Clean Status: ' + (result.false_clean_detected ? 'WARNING (' + result.false_clean_reason + ')' : 'OK') + '\n\n';

  msg += 'Preview\n';
  const preview = result.preview || [];
  for (let j = 0; j < Math.min(preview.length, 10); j++) {
    msg += preview[j] + '\n';
  }

  msg += '\nNext: kalau required marker pass 6/6, record Sprint 6 Dashboard Final live pass.';

  return msg.slice(0, 3900);
}

function airoSprint6DashboardFinalBuild_(ss, options) {
  ss = ss || SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  options = options || {};

  const plan = airoSprint6DashboardFinalPlan_(ss, { mode: 'build' });
  const dashboardFound = airoSprint6FindSheetLoose_(ss, 'Dashboard');

  if (!dashboardFound || !dashboardFound.sheet) {
    throw new Error('Existing Dashboard tab not found. Run admin dashboard sprint6 plan first.');
  }

  const dashboard = dashboardFound.sheet;
  const timezone = Session.getScriptTimeZone ? Session.getScriptTimeZone() : 'Asia/Jakarta';
  const stamp = Utilities.formatDate(new Date(), timezone, 'yyyyMMdd_HHmmss');
  const backupName = '_AIRO_Dashboard_Backup_' + stamp;

  const backup = dashboard.copyTo(ss);
  backup.setName(backupName);

  const recon = airoSprint5ReconciliationReadOnly_(ss, { sampleLimit: 6 });
  const analytics = recon.dashboard_analytics || {};

  dashboard.clear({ contentsOnly: false });

  // Break apart and clear old legacy panel ranges to ensure no merged cells or stale content remnants persist
  safeClearRange_(dashboard, 'B16:G24');
  safeClearRange_(dashboard, 'B25:G34');

  const topRows = [
    ['AIRO Finance Command Center', '', '', '', '', '', ''],
    ['Last synced', new Date(), 'Mode', 'Sprint 6 Dashboard Final', 'Data Status', analytics.data_status || 'Warning', ''],
    ['Trust reason', analytics.data_status_reason || '-', '', '', 'Critical', airoSprint6SafeNumber_(analytics.critical_count), ''],
    ['Policy', 'Cash Ledger dependency: FORBIDDEN', '', '', 'Email Ingestion', 'HIDDEN', ''],
  ];

  airoSprint6WriteRows_(dashboard, 1, 1, topRows);

  const kpiRows = [
    ['Executive Command Center', '', '', '', '', '', ''],
    ['Metric', 'Value', 'Source', 'Status', 'Action', '', ''],
    ['Data Status', analytics.data_status || 'Warning', 'Sprint 5 reconciliation analytics', analytics.critical_count > 0 ? 'Dirty' : 'Warning', 'Review', '', ''],
    ['Active Issues', airoSprint6SafeNumber_(analytics.issue_count_active), 'Sprint 5 reconciliation analytics', 'Monitor', 'Review Action Required', '', ''],
    ['Legacy Issues', airoSprint6SafeNumber_(analytics.issue_count_legacy), 'Sprint 5 reconciliation analytics', 'Monitor', 'Classify if active period affected', '', ''],
    ['Critical Issues', airoSprint6SafeNumber_(analytics.critical_count), 'Sprint 5 reconciliation analytics', airoSprint6SafeNumber_(analytics.critical_count) > 0 ? 'Critical' : 'Clean', 'Fix if > 0', '', ''],
    ['Wallet & Cashflow Source', 'Account Ledger', '📒 Account Ledger', 'Source OK', 'Do not read Cash Ledger', '', ''],
    ['Spending Source', 'Account Ledger category', '📒 Account Ledger', 'Source OK', 'Exclude missing category from clean breakdown', '', ''],
  ];

  airoSprint6WriteRows_(dashboard, 6, 1, kpiRows);

  const actionRows = [
    ['Action Required', '', '', '', '', '', ''],
    ['Severity', 'Message', 'Action', 'Source', '', '', ''],
  ];

  const actions = analytics.action_required || [];
  if (actions.length) {
    for (let i = 0; i < Math.min(actions.length, 6); i++) {
      const item = actions[i] || {};
      actionRows.push([
        String(item.severity || 'INFO'),
        String(item.message || '-'),
        String(item.action || 'Review'),
        String(item.key || 'Sprint 5'),
        '',
        '',
        ''
      ]);
    }
  } else {
    actionRows.push(['INFO', 'No active action required from reconciliation.', 'Monitor', 'Sprint 5', '', '', '']);
  }

  airoSprint6WriteRows_(dashboard, 16, 1, actionRows);

  const domainRows = [
    ['Domain Health', '', '', '', '', '', ''],
    ['Domain', 'Source', 'Detected', 'Rows', 'Status', 'Rule', ''],
  ];

  const sources = plan.required_source_tabs || {};
  const sourceNames = Object.keys(sources);
  for (let j = 0; j < sourceNames.length; j++) {
    const name = sourceNames[j];
    const src = sources[name] || {};
    domainRows.push([
      name,
      src.actual_name || name,
      src.exists ? 'YES' : 'NO',
      src.rows || 0,
      src.exists ? 'OK' : 'MISSING',
      name.indexOf('Cash Ledger') >= 0 ? 'FORBIDDEN' : 'Source contract',
      ''
    ]);
  }

  airoSprint6WriteRows_(dashboard, 26, 1, domainRows);

  const alertStatus = airoSprint6BGetLiveStatus_(ss);
  const adminChatId = getProp_('ADMIN_CHAT_ID') || '';
  const maskedChat = adminChatId ? airoSprint6BMaskChatId_(adminChatId) : '';

  const qualityRows = [
    ['Data Quality Center', '', '', '', '', '', ''],
    ['Check', 'Value', 'Source', 'Status', 'Action', '', ''],
    ['Write performed', 'true', 'Dashboard builder', 'OK', 'Backup created first', '', ''],
    ['Backup tab', backupName, 'Dashboard copy', 'OK', 'Restore if needed', '', ''],
    ['Cash Ledger dependency', 'FORBIDDEN', 'Policy', 'OK', 'Keep excluded', '', ''],
    ['Email Ingestion Status', 'HIDDEN', 'email_ingestion_enabled=false', 'OK', 'Show only in Sprint 7+', '', ''],
    ['Audit Log', '_AIRO_Audit_Log', 'Data Quality Center', (sources['_AIRO_Audit_Log'] && sources['_AIRO_Audit_Log'].exists) ? 'OK' : 'MISSING', 'Ensure tab if missing', '', ''],
    ['Alert Engine State', alertStatus.live_enabled ? 'LIVE' : 'SAFE', 'PropertiesService', alertStatus.live_enabled ? 'Enabled' : 'Disabled', 'Monitor', '', ''],
    ['ADMIN_CHAT_ID', adminChatId ? 'Registered (' + maskedChat + ')' : 'Missing', 'PropertiesService', adminChatId ? 'OK' : 'CRITICAL', adminChatId ? 'Monitor' : 'Register Chat', '', ''],
    ['Live Trigger Count', String(alertStatus.live_trigger_count), 'ScriptApp.getProjectTriggers', alertStatus.live_trigger_count > 0 ? 'OK' : 'WARNING', 'Observability', '', ''],
    ['Safe Trigger Count', String(alertStatus.safe_trigger_count), 'ScriptApp.getProjectTriggers', alertStatus.safe_trigger_count > 0 ? 'OK' : 'WARNING', 'Observability', '', ''],
    ['Last Live Heartbeat', alertStatus.last_live_summary ? alertStatus.last_live_summary.slice(0, 80) : '-', '_AIRO_Audit_Log', 'Readback OK', 'Monitor', '', ''],
    ['Last Safe Heartbeat', alertStatus.last_safe_summary ? alertStatus.last_safe_summary.slice(0, 80) : '-', '_AIRO_Audit_Log', 'Readback OK', 'Monitor', '', '']
  ];

  airoSprint6WriteRows_(dashboard, 40, 1, qualityRows);

  const insightRows = [
    ['Smart Insight Panel', '', '', '', '', '', ''],
    ['Insight', 'Interpretation', 'Recommended action', '', '', '', ''],
    ['Dashboard trust', 'Data Status is ' + String(analytics.data_status || 'Warning'), 'Use warning banner until issues are resolved.', '', '', '', ''],
    ['Category quality', 'Kategori Lainnya remains an Action Required item.', 'Review categories from Action Required.', '', '', '', ''],
    ['Source discipline', 'Cash Ledger exists but is excluded.', 'Keep Account Ledger as wallet/cashflow source.', '', '', '', ''],
  ];

  airoSprint6WriteRows_(dashboard, 55, 1, insightRows);

  // 1. Paint general container background before building right-side panels
  const maxRow = Math.min(dashboard.getLastRow() || 65, 65);
  const maxCol = Math.min(dashboard.getLastColumn() || 14, 14);
  if (maxRow > 0 && maxCol > 0) {
    dashboard.getRange(1, 1, maxRow, maxCol)
      .setFontFamily('Roboto')
      .setFontColor('#e0e0e0')
      .setBackground('#121212');
  }

  // 2. Setup Net Worth and Credit Card panels on the right side
  setupDashboardNetWorthPanel();
  setupDashboardCreditCardCyclePanel();

  // 3. Apply left-side visual styling and auto-severity coloring
  airoApplyDashboardStyling_(dashboard);
  airoApplyDashboardSeverityColors_(dashboard);

  dashboard.getRange('A1:G1').merge();
  dashboard.getRange('A1').setFontSize(18).setFontWeight('bold');
  dashboard.getRange('A2:G4').setFontWeight('bold');
  dashboard.getRange('A6:G6').setFontWeight('bold');
  dashboard.getRange('A16:G16').setFontWeight('bold');
  dashboard.getRange('A26:G26').setFontWeight('bold');
  dashboard.getRange('A40:G40').setFontWeight('bold');
  dashboard.getRange('A55:G55').setFontWeight('bold');
  dashboard.setFrozenRows(4);
  dashboard.autoResizeColumns(1, 7);

  const audit = ss.getSheetByName('_AIRO_Audit_Log');
  if (audit) {
    audit.appendRow([
      new Date(),
      'AIRO',
      'sprint6_dashboard_final_controlled_build',
      'INFO',
      'Sprint 6 Dashboard Final',
      'Dashboard Final controlled build completed with backup',
      dashboard.getName(),
      JSON.stringify({
        backup_tab: backupName,
        write_performed: true,
        google_write_performed: true,
        data_status: analytics.data_status || '',
        critical_count: analytics.critical_count || 0
      })
    ]);
  }

  return {
    ok: true,
    command: 'sprint6_dashboard_final_controlled_build',
    write_performed: true,
    google_write_performed: true,
    dashboard_tab: dashboard.getName(),
    dashboard_gid: dashboard.getSheetId(),
    backup_tab: backupName,
    backup_gid: backup.getSheetId(),
    data_status: analytics.data_status || 'Warning',
    critical_count: airoSprint6SafeNumber_(analytics.critical_count),
    action_required_count: (analytics.action_required || []).length,
    cash_ledger_dependency: 'forbidden',
    email_ingestion_status: 'hidden',
    sections_written: [
      'Topbar',
      'Action Required',
      'Executive Command Center',
      'Wallet & Cashflow',
      'Domain Health',
      'Spending Intelligence',
      'Data Quality Center',
      'Smart Insight Panel'
    ]
  };
}

