    const accountRows = findRows_(accountSheet);

    const formatRows_ = function(rows) {
      if (!rows.length) return '-';
      const maxRows = 3;
      const shown = rows.slice(Math.max(rows.length - maxRows, 0));
      const prefix = rows.length > maxRows ? '(showing last ' + maxRows + ' of ' + rows.length + ')\n' : '';
      return prefix + shown.map(function(item) {
        return '#' + item.row + ': ' + item.values;
      }).join('\n');
    };

