    const cashAmountStartCol = findColumn_(cashInfo, ['amount_start', 'start_amount'], 3);
    const cashTypeCol = findColumn_(cashInfo, ['type', 'jenis'], 16);
    const cashStatusCol = findColumn_(cashInfo, ['status'], 10);

    const cashInAmountFromRow_ = function(row) {
      const primary = toNumber_(row[cashInCol - 1]);
      if (primary > 0) return primary;
      const amountStart = toNumber_(row[cashAmountStartCol - 1]);
      const typeVal = String(row[cashTypeCol - 1] || '').trim().toLowerCase();
      const statusVal = String(row[cashStatusCol - 1] || '').trim().toLowerCase();
      if (
        amountStart > 0 &&
        (typeVal === 'income' || typeVal === 'transfer_in' || typeVal === 'cash_in' || statusVal === 'aktif')
      ) {
        return amountStart;
      }
      return 0;
    };

    const accountDateCol = findColumn_(accountInfo, ['date', 'tanggal', 'tgl'], 2);
    const accountCol = findColumn_(accountInfo, ['account', 'akun', 'wallet', 'rekening'], 3);
    const accountInCol = findColumn_(accountInfo, ['amount_in', 'cash_in', 'nominal_masuk', 'masuk'], 4);
    const accountDescCol = findColumn_(accountInfo, ['description', 'deskripsi'], 9);
    const accountSourceCol = findColumn_(accountInfo, ['source_tab', 'source'], 11);

