function reserveTelegramUpdateOnce_(update, message, rawText) {
  const key = makeTelegramDedupeKey_(update, message, rawText);

  if (!key) {
    return { ok: true, key: '' };
  }

  const lock = LockService.getScriptLock();
  lock.waitLock(7000);

  try {
    const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
    const sheet = getOrCreateDedupeSheet_(ss);

    const found = sheet
      .createTextFinder(key)
      .matchEntireCell(true)
      .findNext();

    if (found) {
      return {
        ok: true,
        duplicate: true,
        key
      };
    }

    sheet.appendRow([
      key,
      new Date(),
      update && update.update_id ? update.update_id : '',
      message && message.chat && message.chat.id ? message.chat.id : '',
      message && message.message_id ? message.message_id : '',
      String(rawText || '').slice(0, 500)
    ]);

    return {
      ok: true,
      duplicate: false,
      key
    };
  } finally {
    try {
      lock.releaseLock();
    } catch (err) {}
  }
}

function makeTelegramDedupeKey_(update, message, rawText) {
  const updateId = update && update.update_id ? String(update.update_id) : '';
  const chatId = message && message.chat && message.chat.id ? String(message.chat.id) : '';
  const messageId = message && message.message_id ? String(message.message_id) : '';
  const text = String(rawText || '');

  if (!updateId && !chatId && !messageId && !text) {
    return '';
  }

  const hash = Utilities.base64EncodeWebSafe(
    Utilities.computeDigest(
      Utilities.DigestAlgorithm.SHA_256,
      [updateId, chatId, messageId, text].join('|')
    )
  ).slice(0, 24);

  return ['tg', chatId || 'unknown_chat', messageId || 'unknown_msg', updateId || 'unknown_update', hash].join(':');
}

function getOrCreateDedupeSheet_(ss) {
  const name = '_AIRO_Dedupe_Log';
  let sheet = ss.getSheetByName(name);

  if (!sheet) {
    sheet = ss.insertSheet(name);
    sheet.getRange(1, 1, 1, 6).setValues([[
      'dedupe_key',
      'created_at',
      'update_id',
      'chat_id',
      'message_id',
      'raw_text'
    ]]);
    sheet.setFrozenRows(1);
    try {
      sheet.hideSheet();
    } catch (err) {}
  }

  return sheet;
}

function showAiroDedupeLog() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  const sheet = getOrCreateDedupeSheet_(ss);
  sheet.showSheet();

  return {
    ok: true,
    sheet: sheet.getName()
  };
}

function hideAiroDedupeLog() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  const sheet = getOrCreateDedupeSheet_(ss);
  sheet.hideSheet();

  return {
    ok: true,
    sheet: sheet.getName()
  };
}

function isCreditCardPaymentText_(text) {
  const t = String(text || '').toLowerCase().trim();

  return (
    /^bayar\s+cc\b/i.test(t) ||
    /^bayar\s+tagihan\b.*\b(cc|credit card|kartu kredit|tokopedia cc|tokopedia card)\b/i.test(t)
  );
}

function isBorrowInText_(text) {
  const t = String(text || '').toLowerCase();

  return (
    /\b(pinjam|dipinjamkan|minjem|hutang ke saya|utang ke saya|dipinjami)\b/i.test(t) ||
    /\b(dapat|terima)\s+(pinjaman|hutang|utang)\b/i.test(t)
  ) && !isDebtPaymentText_(t);
}

function isClearDebtBorrowIntentForDirectHutang_(rawText, parsed) {
  const text = String(rawText || '');
  if (!isBorrowInText_(text)) return false;
  if (isDebtPaymentText_(text)) return false;

  const amount = Number(parsed && parsed.amount ? parsed.amount : 0);
  if (!amount || amount <= 0) return false;

  const person = parseDebtPerson_(rawText) || (parsed && parsed.creditor) || parseCreditor_(text);
  return Boolean(String(person || '').trim());
}

function isDebtPaymentText_(text) {
  const t = String(text || '').toLowerCase();

  return /\b(bayar|lunasi|nyicil|cicil)\b.*\b(hutang|utang|pinjaman)\b/i.test(t);
}

function ensureDropdownAcceptsCurrentValues_(sheet, targetRow, startCol, headers, data) {
  if (!sheet || !headers || !data) return;

  headers.forEach((h, idx) => {
    const field = fieldForHeader_(h);

    // Only extend controlled semantic fields.
    // This prevents category/type like Gaji, CC Payment, debt_in from being blanked.
    if (!['category', 'type'].includes(field)) return;

    const value = data[field];
    if (value === '' || value === null || typeof value === 'undefined') return;

    const cell = sheet.getRange(targetRow, startCol + idx);
    const validation = cell.getDataValidation();

    if (!validation) return;

    const criteriaType = validation.getCriteriaType();
    const criteriaValues = validation.getCriteriaValues();
    const current = String(value);

    if (criteriaType === SpreadsheetApp.DataValidationCriteria.VALUE_IN_LIST) {
      const allowed = (criteriaValues[0] || [])
        .map(v => String(v))
        .filter(Boolean);

      const allowedLower = allowed.map(v => v.toLowerCase());

      if (!allowedLower.includes(current.toLowerCase())) {
        allowed.push(current);

        const rule = SpreadsheetApp
          .newDataValidation()
          .requireValueInList(allowed, true)
          .setAllowInvalid(false)
          .build();

        cell.setDataValidation(rule);
      }

      return;
    }

    if (criteriaType === SpreadsheetApp.DataValidationCriteria.VALUE_IN_RANGE) {
      try {
        const allowedRange = criteriaValues[0];
        const allowedValues = allowedRange
          .getValues()
          .flat()
          .map(v => String(v))
          .filter(Boolean);

        const allowedLower = allowedValues.map(v => v.toLowerCase());

        if (allowedLower.includes(current.toLowerCase())) {
          return;
        }

        const values = allowedRange.getValues();

        for (let r = 0; r < values.length; r++) {
          for (let c = 0; c < values[r].length; c++) {
            if (!String(values[r][c] || '').trim()) {
              allowedRange.getCell(r + 1, c + 1).setValue(current);
              return;
            }
          }
        }
      } catch (err) {
        // Do not block write if dropdown source range cannot be updated.
      }
    }
  });
}

function isCreditCardPurchaseText_(text) {
  const t = String(text || '').toLowerCase().trim();

  if (isCreditCardPaymentText_(t)) return false;
  if (isCreditCardRefundText_(t)) return false;

  return (
    /^cc\s+(beli|bayar)\b/i.test(t) ||
    /\b(tokopedia\s*cc|tokopedia\s*card|credit\s*card|kartu\s*kredit)\b.*\b(beli|bayar)\b/i.test(t) ||
    /\bcc\b.*\b(beli|bayar)\b/i.test(t)
  );
}

function isCreditCardRefundText_(text) {
  return /\b(refund|pengembalian|dikembalikan|retur)\b.*\b(cc|credit card|kartu kredit|tokopedia cc|tokopedia card)\b/i
    .test(String(text || '').toLowerCase());
}

function isDirtyCcLogText_(rawText) {
  const text = String(rawText || '').trim();

  // 1. admin command
  if (/^admin\s+(find|cari|cleanup|void|clear|reset|fix|rapikan|audit|check|cek)\b/i.test(text)) {
    return true;
  }

  // 2. baris transcript WhatsApp/Telegram
  if (/^\[\d{2}\/\d{2}\/\d{4},?\s+\d{2}:\d{2}(?::\d{2})?\]/m.test(text)) {
    return true;
  }
  if (/^\[\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}(?::\d{2})?\]/m.test(text)) {
    return true;
  }

  // 3. specific names/prefixes often found in logs
  if (/Airo Finance:/i.test(text)) {
    return true;
  }
  if (/Egit Aristo Randas:/i.test(text)) {
    return true;
  }

  // 4. multiline transcript with multiple timestamps/dates
  const lines = text.split('\n');
  let dateTimestampCount = 0;
  for (let i = 0; i < lines.length; i++) {
    if (/\b\d{2}\/\d{2}\/\d{4}\b/.test(lines[i]) || /\b\d{2}:\d{2}\b/.test(lines[i])) {
      dateTimestampCount++;
    }
  }
  if (lines.length > 2 && dateTimestampCount >= 2) {
    return true;
  }

  return false;
}

function writeCreditCardSafely_(ss, parsed, rawText, common) {
  const tabName = AIRO_CONFIG.tabs.creditCard;
  const sheet = getSheetLoose_(ss, tabName);

  if (!sheet) {
    return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      ...common,
      status: 'review',
      issue_reason: 'credit_card_tab_missing'
    }, { createIfMissing: false });
  }

  const text = String(rawText || '').toLowerCase();

  // Guard against admin commands/transcripts/logs leaking into CC
  if (isDirtyCcLogText_(rawText)) {
    return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      ...common,
      status: 'pending',
      issue_reason: 'cc_blocked_dirty_log_transcript'
    }, { createIfMissing: false });
  }

  // Refund CC is intentionally not auto-written yet to avoid corrupting CC totals.
  if (isCreditCardRefundText_(text)) {
    return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      ...common,
      category: 'CC Refund',
      status: 'pending',
      issue_reason: 'cc_refund_needs_manual_review'
    }, { createIfMissing: false });
  }

  if (isCreditCardPaymentText_(text)) {
    return markCreditCardPocketBluTransfer_(ss, sheet, parsed, rawText, common);
  }

  const purchaseResult = appendCreditCardPurchase_(ss, sheet, parsed, rawText, common);

  if (purchaseResult && purchaseResult.status === 'written') {
    // AIRO_CC_PURCHASE_FINANCE_EVENT_EMISSION_V1
    // Credit Card purchase is a domain event, not an Account Ledger wallet outflow.
    // It still must be indexed in Finance Events after the domain row is written.
    recordFinanceEventForWriteResult_(ss, purchaseResult, common, parsed, rawText, {
      event_type: 'cc_purchase',
      event_source: 'telegram',
      source_tab: AIRO_CONFIG.tabs.creditCard,
      source_row: purchaseResult.row || '',
      linked_txn_id: common.linked_txn_id || common.rowId || purchaseResult.rowId || ''
    });
  }

  return purchaseResult;
}


function writeHutangSafely_(ss, parsed, rawText, common) {
  const tabName = AIRO_CONFIG.tabs.hutang;
  const sheet = getSheetLoose_(ss, tabName);

  if (!sheet) {
    return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      ...common,
      status: 'pending',
      issue_reason: 'hutang_tab_missing'
    }, { createIfMissing: false });
  }

  const text = String(rawText || '').toLowerCase();
  const type = String(parsed && parsed.type ? parsed.type : '').toLowerCase();
  const category = String(
    parsed && parsed.category ? parsed.category : ''
  ).toLowerCase();
  const subcategory = String(
    parsed && parsed.subcategory ? parsed.subcategory : ''
  ).toLowerCase();

  if (/\bbayar\b.*\b(hutang|utang)\b.*\bke saya\b/i.test(text)) {
    return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      ...common,
      category: 'Piutang',
      status: 'pending',
      issue_reason: 'orang_bayar_hutang_ke_saya_needs_piutang_flow'
    }, { createIfMissing: false });
  }

  const selectedDebtPayment =
    type === 'debt_payment' ||
    /^bayar\s+(hutang|utang)\b/i.test(subcategory) ||
    (
      category === 'debt & obligations' &&
      /\b(hutang|utang)\b/i.test(subcategory)
    );

  if (isDebtPaymentText_(text) || selectedDebtPayment) {
    return appendDebtPaymentAndUpdateMaster_(
      ss,
      sheet,
      parsed,
      rawText,
      common
    );
  }

  if (isBorrowInText_(text)) {
    return appendDebtIncreaseAndUpdateMaster_(
      ss,
      sheet,
      parsed,
      rawText,
      common
    );
  }

  return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
    ...common,
    status: 'pending',
    issue_reason: 'hutang_intent_unclear'
  }, { createIfMissing: false });
}
function stripQaTag_(text) {
  return String(text || '')
    .replace(/\bQA_[A-Z0-9_]+\b/gi, '')
    .trim();
}

function extractHumanAmountFromText_(text) {
  const t = sanitizeAmountExtractionText_(text).toLowerCase();
  const re = /(\d+(?:[.,]\d+)?)\s*(jt|juta|rb|ribu|k)?\b/gi;
  let m;
  let best = 0;

  while ((m = re.exec(t)) !== null) {
    const n = Number(String(m[1]).replace(',', '.'));
    const unit = String(m[2] || '').toLowerCase();

    if (!n) continue;

    let value = n;
    if (unit === 'jt' || unit === 'juta') value = n * 1000000;
    else if (unit === 'rb' || unit === 'ribu' || unit === 'k') value = n * 1000;

    value = Math.round(value);

    // Skip obvious years unless unit is present.
    if (!unit && value >= 1900 && value <= 2200) continue;

    if (value > best) best = value;
  }

  return best;
}

function amountForIntent_(parsed, rawText) {
  const parsedAmount = Number(parsed && parsed.amount ? parsed.amount : 0);
  if (parsedAmount > 0) return parsedAmount;

  const human = extractHumanAmountFromText_(rawText);
  if (human > 0) return human;

  return 0;
}

function todayDate_() {
  return new Date();
}

function ccBillingCycle_(dateObj) {
  const d = dateObj instanceof Date ? dateObj : new Date();
  const y = d.getFullYear();
  const m = d.getMonth();
  const day = d.getDate();

  let start;
  let end;
  let cycleYear;
  let cycleMonth;

  if (day >= 16) {
    start = new Date(y, m, 16);
    end = new Date(y, m + 1, 15);
    cycleYear = end.getFullYear();
    cycleMonth = end.getMonth() + 1;
  } else {
    start = new Date(y, m - 1, 16);
    end = new Date(y, m, 15);
    cycleYear = end.getFullYear();
    cycleMonth = end.getMonth() + 1;
  }

  const cycleId = 'TOKPED_CC_' + cycleYear + '-' + String(cycleMonth).padStart(2, '0');

  return {
    id: cycleId,
    start,
    end,
    statementMonth: new Date(cycleYear, cycleMonth - 1, 1)
  };
}

function parseCcMerchant_(text) {
  let t = stripQaTag_(text).toLowerCase();

  if (/\bpdam\b/i.test(t)) return 'PDAM';
  if (/\bpln|listrik\b/i.test(t)) return 'PLN';
  if (/\bshopee\b/i.test(t)) return 'Shopee';
  if (/\btiktok\s*shop|tiktokshop\b/i.test(t)) return 'TikTok Shop';
  if (/\bgrabcar|grab\b/i.test(t)) return 'Grab';
  if (/\bgojek|gocar|goride\b/i.test(t)) return 'Gojek';
  if (/\btokopedia\b/i.test(t)) return 'Tokopedia';

  t = t
    .replace(/^cc\s+(beli|bayar|pesan)\s+/i, '')
    .replace(/\btokopedia\s+cc\b/gi, '')
    .replace(/\bcc\b/gi, '')
    .replace(/\bharga\b/gi, '')
    .replace(/\bhari ini\b/gi, '')
    .replace(/\bkemarin\b/gi, '')
    .replace(/\bbesok\b/gi, '')
    .replace(/\btgl\s+\d{1,2}\s+[a-z]+(?:\s+\d{4})?\b/gi, '')
    .replace(/\btanggal\s+\d{1,2}\s+[a-z]+(?:\s+\d{4})?\b/gi, '')
    .replace(/\d+(?:[.,]\d+)?\s*(jt|juta|rb|ribu|k)?/gi, '')
    .replace(/\s+/g, ' ')
    .trim();

  if (!t) return 'CC';

  const words = t.split(/\s+/).filter(Boolean).slice(0, 3);
  return titleCaseSimple_(words.join(' '));
}

function parseCcItemKeyword_(text) {
  let t = stripQaTag_(text).toLowerCase();

  t = t
    .replace(/^bayar\s+tagihan\s+/i, '')
    .replace(/^bayar\s+cc\s+/i, '')
    .replace(/^cc\s+(beli|bayar)\s+/i, '')
    .replace(/\btokopedia\s+cc\b/gi, '')
    .replace(/\bcc\b/gi, '')
    .replace(/\bhari ini\b/gi, '')
    .replace(/\bkemarin\b/gi, '')
    .replace(/\bbesok\b/gi, '')
    .replace(/\bdari\s+(blu|blu bca|bca|cash)\b/gi, '')
    .replace(/\bharga\b/gi, '')
    .replace(/\d+(?:[.,]\d+)?\s*(jt|juta|rb|ribu|k)?/gi, '')
    .replace(/\s+/g, ' ')
    .trim();

  return t || 'cc_payment';
}

function findCcHeaderRow_(sheet) {
  const maxRows = Math.min(sheet.getLastRow(), 20);
  const maxCols = Math.min(sheet.getLastColumn(), 15);
  const values = sheet.getRange(1, 1, maxRows, maxCols).getValues();

  for (let r = 0; r < values.length; r++) {
    const normalized = values[r].map(v => canonicalKey_(v));
    if (
      normalized.includes('cc_entry_id') &&
      normalized.includes('amount') &&
      normalized.includes('status_pocket_blu')
    ) {
      return {
        row: r + 1,
        headers: values[r].map(v => String(v || '').trim())
      };
    }
  }

  return null;
}

function ccColMap_(headers) {
  const map = {};
  headers.forEach((h, i) => {
    map[canonicalKey_(h)] = i + 1;
  });
  return map;
}

function appendCreditCardPurchase_(ss, sheet, parsed, rawText, common) {
  const header = findCcHeaderRow_(sheet);

  if (!header) {
    return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      ...common,
      status: 'pending',
      issue_reason: 'cc_header_not_found'
    }, { createIfMissing: false });
  }

  const amount = Number(parsed && parsed.amount ? parsed.amount : 0) || amountForIntent_(parsed, rawText);
  const date = parseCcDateFromText_(rawText, todayDate_());
  const cycle = ccBillingCycle_(date);
  const targetRow = findNextSectionRow_(sheet, header.row, 1, header.headers.length);

  const data = {
    cc_entry_id: common.linked_txn_id || makeTxnId_({}, rawText),
    date,
    merchant_app: parseCcMerchant_(rawText),
    amount,
    status_pocket_blu: '⏳ Belum',
    description: stripQaTag_(rawText),
    transferred_at: '',
    linked_txn_id: common.linked_txn_id || makeTxnId_({}, rawText),
    notes: 'cc_purchase',
    billing_cycle_id: cycle.id,
    billing_start: cycle.start,
    billing_end: cycle.end,
    statement_month: cycle.statementMonth
  };

  const row = header.headers.map(h => {
    const k = canonicalKey_(h);
    return data[k] !== undefined ? data[k] : '';
  });

  sheet.getRange(targetRow, 1, 1, row.length).setValues([row]);

  // AIRO_CC_PURCHASE_WRITE_VERIFY_V1
  // Direct Credit Card writes must expose writeVerified so Finance Events payload can reflect actual write verification.
  const writeTruth = verifyAppendWrite_(ss, sheet, targetRow, 1, row);

  return {
    status: 'written',
    writtenTab: sheet.getName(),
    row: targetRow,
    rowId: sheet.getName() + ':' + targetRow,
    writeVerified: writeTruth.writeVerified === true,
    readbackRawText: writeTruth.readbackRawText || '',
    tabUrl: getSheetTabUrl_(ss, sheet)
  };
}

function markCreditCardPocketBluTransfer_(ss, sheet, parsed, rawText, common) {
  const header = findCcHeaderRow_(sheet);

  if (!header) {
    return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      ...common,
      status: 'pending',
      issue_reason: 'cc_header_not_found'
    }, { createIfMissing: false });
  }

  const map = ccColMap_(header.headers);
  const amountCol = map.amount;
  const statusCol = map.status_pocket_blu;
  const transferredCol = map.transferred_at;
  const descCol = map.description;
  const notesCol = map.notes;

  const amount = Number(parsed && parsed.amount ? parsed.amount : 0) || amountForIntent_(parsed, rawText);
  const keyword = parseCcItemKeyword_(rawText);

  if (!amount || !amountCol || !statusCol || !descCol) {
    return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      ...common,
      status: 'pending',
      issue_reason: 'cc_payment_amount_or_columns_missing'
    }, { createIfMissing: false });
  }

  const lastRow = sheet.getLastRow();
  const width = Math.max(...[amountCol, statusCol, transferredCol || 1, descCol, notesCol || 1]);
  const rows = sheet.getRange(header.row + 1, 1, Math.max(1, lastRow - header.row), width).getValues();

  let bestRow = 0;
  let alreadyPaidRow = 0;

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const rowAmount = Number(row[amountCol - 1] || 0);
    const rowStatus = String(row[statusCol - 1] || '').toLowerCase();
    const rowDesc = String(row[descCol - 1] || '').toLowerCase();

    if (rowAmount !== amount) continue;

    const words = keyword.split(/\s+/).filter(w => w.length >= 3);

    if (
      rowStatus === 'posted' ||
      rowStatus === 'paid' ||
      rowStatus === 'transferred' ||
      rowStatus.includes('sudah')
    ) {
      const paidKeywordMatch = !words.length || words.some(w => rowDesc.includes(w));
      if (paidKeywordMatch) {
        alreadyPaidRow = header.row + 1 + i;
      }
      continue;
    }

    const keywordMatch = !words.length || words.some(w => rowDesc.includes(w));

    if (keywordMatch) {
      bestRow = header.row + 1 + i;
      break;
    }
  }

  // AIRO_TASK9_CC_PAYMENT_IDEMPOTENCY_GUARD_V1
  // Retry safety: if a matching CC row is already paid/transferred, do not write another Account Ledger outflow.
  if (alreadyPaidRow) {
    return {
      status: 'skipped',
      skipped: true,
      duplicate: true,
      reason: 'cc_payment_already_marked_paid',
      writtenTab: sheet.getName(),
      row: alreadyPaidRow,
      rowId: sheet.getName() + ':' + alreadyPaidRow,
      amount: amount,
      account: parsed.account || 'Blu',
      category: parsed.category || 'Credit Card Payment'
    };
  }

  if (!bestRow) {
    // AIRO_TASK6A_CC_PAYMENT_NO_MATCH_ACCOUNT_LEDGER_V1
    // When no matching open CC purchase row is found, the payment is still real.
    // Write the Blu outflow to Account Ledger + emit Finance Events.
    // Also write a Review Queue pending row so the owner can manually match it later.
    // raw_text (including smoke tags) is preserved in both writes.
    const noMatchParsed = Object.assign({}, parsed, {
      type: 'cc_payment',
      category: 'CC Payment',
      account: parsed.account || 'Blu',
      amount: amount
    });
    const noMatchCommon = Object.assign({}, common, {
      linked_txn_id: common.linked_txn_id || common.rowId || makeTxnId_({}, rawText)
    });
    const noMatchLedgerResult = writeAccountLedgerMirror_(ss, noMatchParsed, rawText, noMatchCommon, AIRO_CONFIG.tabs.creditCard);

    recordFinanceEventForWriteResult_(ss, noMatchLedgerResult || { status: 'skipped' }, noMatchCommon, noMatchParsed, rawText, {
      event_type: 'cc_payment',
      event_source: 'telegram',
      source_tab: AIRO_CONFIG.tabs.accountLedger,
      source_row: (noMatchLedgerResult && noMatchLedgerResult.row) || '',
      linked_txn_id: noMatchCommon.linked_txn_id
    });

    const reviewResult = appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      ...common,
      raw_text: rawText,
      category: 'CC Payment',
      status: 'pending',
      issue_reason: 'cc_payment_no_matching_pending_purchase'
    }, { createIfMissing: false });

    // AIRO_TASK9_CC_NO_MATCH_LEDGER_PRIMARY_RETURN_V1
    // No-match CC payment still represents a real Blu outflow.
    // Keep Review Queue for manual matching, but expose Account Ledger as the
    // primary write result when the ledger write is verified.
    if (
      noMatchLedgerResult &&
      noMatchLedgerResult.status === 'written' &&
      noMatchLedgerResult.writeVerified === true
    ) {
      return Object.assign({}, noMatchLedgerResult, {
        writtenTab: AIRO_CONFIG.tabs.accountLedger,
        account_ledger_result: noMatchLedgerResult,
        review_queue_result: reviewResult || null,
        cc_payment_no_match: true,
        cc_payment_no_match_review_status:
          reviewResult && reviewResult.status ? reviewResult.status : '',
        cc_payment_no_match_review_row:
          reviewResult && reviewResult.row ? reviewResult.row : ''
      });
    }

    return Object.assign({}, reviewResult, {
      account_ledger_result: noMatchLedgerResult || null,
      cc_payment_no_match: true,
      cc_payment_account_ledger_status:
        noMatchLedgerResult && noMatchLedgerResult.status
          ? noMatchLedgerResult.status
          : 'missing_or_unverified'
    });
  }

  const accountParsed = Object.assign({}, parsed, {
    type: 'cc_payment',
    category: parsed.category || 'Credit Card Payment',
    account: parsed.account || 'Blu',
    amount: amount
  });
  const accountCommon = Object.assign({}, common, {
    linked_txn_id: common.linked_txn_id || makeTxnId_({}, rawText)
  });
  const accountLedgerResult = writeAccountLedgerMirror_(ss, accountParsed, rawText, accountCommon, AIRO_CONFIG.tabs.creditCard);

  // AIRO_TASK9_CC_LEDGER_FIRST_GUARD_V1
  // Matched CC payment must not mark the Credit Card row as paid unless Account Ledger write is verified.
  if (!accountLedgerResult || accountLedgerResult.status !== 'written' || accountLedgerResult.writeVerified !== true) {
    return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      queue_id: accountCommon.linked_txn_id || makeTxnId_({}, rawText),
      created_at: todayDate_(),
      source: 'telegram',
      raw_text: rawText,
      parsed_json: JSON.stringify(accountParsed),
      amount: amount,
      account: accountParsed.account || 'Blu',
      category: accountParsed.category || 'Credit Card Payment',
      status: 'pending',
      issue_reason: 'cc_payment_account_ledger_write_not_verified',
      target_tab: sheet.getName(),
      target_row: bestRow,
      account_ledger_result: accountLedgerResult || null,
      cc_payment_ledger_first_guard: true
    }, { createIfMissing: false });
  }

  sheet.getRange(bestRow, statusCol).setValue('✅ Sudah');

  if (transferredCol) {
    sheet.getRange(bestRow, transferredCol).setValue(todayDate_());
  }

  if (notesCol) {
    const oldNotes = String(sheet.getRange(bestRow, notesCol).getValue() || '');
    const newNotes = [
      oldNotes,
      'pocket_blu_transfer: ' + stripQaTag_(rawText)
    ].filter(Boolean).join(' | ');

    sheet.getRange(bestRow, notesCol).setValue(newNotes);
  }

  return {
    status: 'written',
    writtenTab: sheet.getName(),
    row: bestRow,
    rowId: sheet.getName() + ':' + bestRow,
    account_ledger_result: accountLedgerResult || null,
    tabUrl: getSheetTabUrl_(ss, sheet)
  };
}

function findHutangMasterHeader_(sheet) {
  const maxRows = Math.min(sheet.getLastRow(), 15);
  const maxCols = Math.min(sheet.getLastColumn(), 10);
  const values = sheet.getRange(1, 1, maxRows, maxCols).getValues();

  for (let r = 0; r < values.length; r++) {
    const normalized = values[r].map(v => canonicalKey_(v));
    if (
      normalized.includes('hutang_id') &&
      normalized.includes('nama') &&
      normalized.includes('jumlah_pokok') &&
      normalized.includes('total_dibayar')
    ) {
      return {
        row: r + 1,
        headers: values[r].map(v => String(v || '').trim())
      };
    }
  }

  return null;
}

function findHutangPaymentHeader_(sheet) {
  const maxRows = Math.min(sheet.getLastRow(), 20);
  const maxCols = Math.min(sheet.getLastColumn(), 10);
  const values = sheet.getRange(1, 1, maxRows, maxCols).getValues();

  for (let r = 0; r < values.length; r++) {
    const normalized = values[r].map(v => canonicalKey_(v));
    if (
      normalized.includes('pay_id') &&
      normalized.includes('hutang_id') &&
      normalized.includes('nama') &&
      normalized.includes('amount')
    ) {
      return {
        row: r + 1,
        headers: values[r].map(v => String(v || '').trim())
      };
    }
  }

  return null;
}

function hutangColMap_(headers) {
  const map = {};
  headers.forEach((h, i) => {
    map[canonicalKey_(h)] = i + 1;
  });
  return map;
}

function normalizePersonName_(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/\bQA_[A-Z0-9_]+\b/gi, '')
    .replace(/\b(hari ini|kemarin|besok)\b/gi, '')
    .replace(/\d+(?:[.,]\d+)?\s*(jt|juta|rb|ribu|k)?/gi, '')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function cleanDebtPersonName_(value) {
  // AIRO_HUTANG_CLEAN_DEBT_PERSON_ALIAS_V1
  // Compatibility alias for parseCreditor_ after Hutang direct routing patch.
  return normalizePersonName_(value);
}

function parseDebtPerson_(rawText) {
  const text = stripQaTag_(rawText).toLowerCase();

  // Pattern 1 (original): bayar hutang ke <person> <digit>
  let m = text.match(/\bbayar\s+(?:hutang|utang)\s+ke\s+(.+?)\s+\d/i);
  if (m) return normalizePersonName_(m[1]);

  // AIRO_TASK6B_HUTANG_AMOUNT_BEFORE_KE_V1
  // Pattern 2 (new): bayar hutang <amount> ke <person> [dari|ke|pakai|smk|qa|live|...]
  // Handles: "bayar hutang 100000 ke budi dari bca"
  m = text.match(/\bbayar\s+(?:hutang|utang)\s+[\d.,]+\s*(?:rb|ribu|k|jt|juta)?\s+ke\s+([a-z][a-z0-9 ._-]{0,39}?)(?:\s+(?:dari|ke|pakai|smk|qa|live)\b)/i);
  if (m) return normalizePersonName_(m[1]);

  // Pattern 3: pinjam dari <person> <digit>
  m = text.match(/\bpinjam\s+(?:uang\s+)?dari\s+(.+?)\s+\d/i);
  if (m) return normalizePersonName_(m[1]);

  return '';
}

function findDebtMasterRowByName_(sheet, masterHeader, person) {
  const map = hutangColMap_(masterHeader.headers);
  const namaCol = map.nama;
  if (!namaCol) return null;

  const lastRow = Math.min(sheet.getLastRow(), 9);
  const values = sheet.getRange(masterHeader.row + 1, 1, Math.max(1, lastRow - masterHeader.row), masterHeader.headers.length).getValues();
  const wanted = normalizePersonName_(person);

  for (let i = 0; i < values.length; i++) {
    const rowName = normalizePersonName_(values[i][namaCol - 1]);

    if (!rowName) continue;

    if (rowName === wanted || rowName.includes(wanted) || wanted.includes(rowName)) {
      return {
        row: masterHeader.row + 1 + i,
        values: values[i],
        map
      };
    }
  }

  return null;
}

function titleDebtPersonName_(value) {
  const cleaned = normalizePersonName_(value);
  if (!cleaned) return '';

  return cleaned
    .split(/\s+/)
    .filter(Boolean)
    .map(function(part) {
      return part.charAt(0).toUpperCase() + part.slice(1);
    })
    .join(' ');
}

function findNextHutangMasterBlankRow_(sheet, masterHeader, paymentHeader) {
  // AIRO_HUTANG_AUTO_CREATE_MASTER_V1
  // Keep master writes inside the master section, above the payment/log header.
  const startRow = masterHeader.row + 1;
  const endRow = paymentHeader && paymentHeader.row
    ? Math.max(startRow, paymentHeader.row - 1)
    : Math.max(startRow, sheet.getLastRow() + 1);

  const width = Math.max(1, masterHeader.headers.length);
  const height = Math.max(1, endRow - startRow + 1);
  const values = sheet.getRange(startRow, 1, height, width).getValues();

  for (let i = 0; i < values.length; i++) {
    const hasAnyValue = values[i].some(function(v) {
      return String(v || '').trim() !== '';
    });

    if (!hasAnyValue) return startRow + i;
  }

  return 0;
}

function appendDebtMasterRow_(sheet, masterHeader, paymentHeader, person, amount, rawText, common) {
  // AIRO_HUTANG_AUTO_CREATE_MASTER_V1
  // Borrow/debt increase from a new person should create a Hutang master row,
  // not fall back to Review Queue.
  const targetRow = findNextHutangMasterBlankRow_(sheet, masterHeader, paymentHeader);
  if (!targetRow) {
    return {
      status: 'fallback',
      reason: 'hutang_master_no_blank_row'
    };
  }

  const normalizedPerson = normalizePersonName_(person);
  const displayName = titleDebtPersonName_(normalizedPerson) || String(person || '').trim();
  const hutangId = 'debt_' + String(common && common.linked_txn_id ? common.linked_txn_id : makeTxnId_({}, rawText));
  const notes = 'debt_auto_created: ' + stripQaTag_(rawText);

  const data = {
    hutang_id: hutangId,
    nama: displayName,
    creditor: displayName,
    jumlah_pokok: amount,
    total_dibayar: 0,
    sisa_hutang: amount,
    status: 'aktif',
    date: todayDate_(),
    tanggal: todayDate_(),
    created_at: new Date(),
    description: stripQaTag_(rawText),
    raw_text: rawText,
    notes: notes,
    catatan: notes,
    amount: amount,
    nominal: amount
  };

  let row = masterHeader.headers.map(function(h) {
    const key = canonicalKey_(h);
    return data[key] !== undefined ? data[key] : '';
  });

  row = sanitizeValuesForValidation_(sheet, targetRow, 1, row, data);
  sheet.getRange(targetRow, 1, 1, row.length).setValues([row]);

  return {
    status: 'written',
    row: targetRow,
    hutangId: hutangId,
    nama: displayName
  };
}


function appendDebtPaymentAndUpdateMaster_(ss, sheet, parsed, rawText, common) {
  return withAccountLedgerPrimaryLock_(function() {
    const masterHeader = findHutangMasterHeader_(sheet);
    const paymentHeader = findHutangPaymentHeader_(sheet);

    if (!masterHeader || !paymentHeader) {
      return {
        status: 'fallback',
        reason: 'hutang_header_missing'
      };
    }

    const paymentKeys = paymentHeader.headers.map(
      h => canonicalKey_(h)
    );

    if (
      paymentKeys.indexOf('pay_id') < 0 ||
      paymentKeys.indexOf('sisa_setelah') < 0
    ) {
      return {
        status: 'fallback',
        reason: 'hutang_payment_identity_or_repair_column_missing'
      };
    }

    const person = debtPersonFromParsedOrText_(parsed, rawText);
    const amount =
      Number(parsed && parsed.amount ? parsed.amount : 0) ||
      amountForIntent_(parsed, rawText);

    if (!person || !amount) {
      return {
        status: 'fallback',
        reason: 'hutang_payment_person_or_amount_missing'
      };
    }

    const master = findDebtMasterRowByName_(
      sheet,
      masterHeader,
      person
    );

    if (!master) {
      return {
        status: 'fallback',
        reason: 'hutang_person_not_found_in_master'
      };
    }

    const stableId =
      (common && (common.rowId || common.linked_txn_id)) ||
      makeTxnId_({}, rawText);

    const displayPerson =
      titleDebtPersonName_(person) ||
      String(person || '').trim();

    const accountParsed = Object.assign({}, parsed, {
      type: 'debt_payment',
      category: 'Debt & Obligations',
      subcategory:
        parsed.subcategory ||
        ('Bayar Hutang ' + displayPerson),
      account: parsed.account || 'Unknown',
      amount: amount
    });

    const accountCommon = Object.assign({}, common || {}, {
      rowId: stableId,
      linked_txn_id: stableId
    });

    const ledgerResult = writeAccountLedgerPrimary_(
      ss,
      accountParsed,
      rawText,
      accountCommon,
      AIRO_CONFIG.tabs.hutang
    );

    if (!ledgerResult || !ledgerResult.ok) {
      return {
        status: 'failed',
        reason:
          ledgerResult && ledgerResult.reason
            ? ledgerResult.reason
            : 'hutang_account_ledger_primary_failed',
        account_ledger_result: ledgerResult || null,
        account_ledger_write_performed: Boolean(
          ledgerResult &&
          ledgerResult.account_ledger_write_performed
        )
      };
    }

    const map = master.map;
    const hutangId = map.hutang_id
      ? sheet.getRange(master.row, map.hutang_id).getValue()
      : '';

    const nama = map.nama
      ? sheet.getRange(master.row, map.nama).getValue()
      : displayPerson;

    const pokok = map.jumlah_pokok
      ? Number(
          sheet
            .getRange(master.row, map.jumlah_pokok)
            .getValue() || 0
        )
      : 0;

    try {
      const existingLog = findDebtPaymentLogByPayId_(
        sheet,
        paymentHeader,
        ledgerResult.entry_id
      );

      if (existingLog) {
        const loggedSisa = Number(existingLog.sisa_setelah);

        if (!Number.isFinite(loggedSisa)) {
          return {
            status: 'partial',
            reason:
              'hutang_projection_repair_value_invalid|' +
              'account_ledger_entry_id=' +
              ledgerResult.entry_id,
            account_ledger_entry_id: ledgerResult.entry_id,
            account_ledger_result: ledgerResult,
            domain_projection_status: 'failed'
          };
        }

        const repairedPaid = Math.max(0, pokok - loggedSisa);

        if (map.total_dibayar) {
          sheet
            .getRange(master.row, map.total_dibayar)
            .setValue(repairedPaid);
        }

        if (map.sisa_hutang) {
          sheet
            .getRange(master.row, map.sisa_hutang)
            .setValue(loggedSisa);
        }

        if (map.status) {
          sheet
            .getRange(master.row, map.status)
            .setValue(loggedSisa <= 0 ? 'lunas' : 'aktif');
        }

        return {
          status: 'written',
          writtenTab: sheet.getName(),
          row: master.row,
          rowId: ledgerResult.entry_id,
          tabUrl: getSheetTabUrl_(ss, sheet),
          account_ledger_entry_id: ledgerResult.entry_id,
          account_ledger_result: ledgerResult,
          domain_projection_status: 'existing_repaired',
          domain_projection_row: existingLog.row
        };
      }

      const oldPaid = map.total_dibayar
        ? Number(
            sheet
              .getRange(master.row, map.total_dibayar)
              .getValue() || 0
          )
        : 0;

      const newPaid = oldPaid + amount;
      const sisa = Math.max(0, pokok - newPaid);

      const paymentRow = appendDebtPaymentLog_(
        sheet,
        paymentHeader,
        {
          pay_id: ledgerResult.entry_id,
          hutang_id: hutangId,
          nama: nama,
          date: todayDate_(),
          amount: amount,
          sisa_setelah: sisa,
          source:
            parsed.account &&
            parsed.account !== 'Unknown'
              ? parsed.account
              : '',
          notes:
            'account_ledger_primary:' +
            ledgerResult.entry_id +
            '; ' +
            stripQaTag_(rawText)
        }
      );

      const logReadback = findDebtPaymentLogByPayId_(
        sheet,
        paymentHeader,
        ledgerResult.entry_id
      );

      if (!logReadback) {
        return {
          status: 'partial',
          reason:
            'hutang_payment_log_readback_failed|' +
            'account_ledger_entry_id=' +
            ledgerResult.entry_id,
          account_ledger_entry_id: ledgerResult.entry_id,
          account_ledger_result: ledgerResult,
          domain_projection_status: 'failed'
        };
      }

      if (map.total_dibayar) {
        sheet
          .getRange(master.row, map.total_dibayar)
          .setValue(newPaid);
      }

      if (map.sisa_hutang) {
        sheet
          .getRange(master.row, map.sisa_hutang)
          .setValue(sisa);
      }

      if (map.status) {
        sheet
          .getRange(master.row, map.status)
          .setValue(sisa <= 0 ? 'lunas' : 'aktif');
      }

      return {
        status: 'written',
        writtenTab: sheet.getName(),
        row: master.row,
        rowId: ledgerResult.entry_id,
        tabUrl: getSheetTabUrl_(ss, sheet),
        account_ledger_entry_id: ledgerResult.entry_id,
        account_ledger_result: ledgerResult,
        domain_projection_status: 'written',
        domain_projection_row: paymentRow
      };
    } catch (error) {
      return {
        status: 'partial',
        reason:
          'hutang_domain_projection_failed|' +
          'account_ledger_entry_id=' +
          ledgerResult.entry_id +
          '|' +
          String(
            error && error.message
              ? error.message
              : error
          ),
        account_ledger_entry_id: ledgerResult.entry_id,
        account_ledger_result: ledgerResult,
        domain_projection_status: 'failed'
      };
    }
  });
}
function appendDebtIncreaseAndUpdateMaster_(ss, sheet, parsed, rawText, common) {
  const masterHeader = findHutangMasterHeader_(sheet);
  const paymentHeader = findHutangPaymentHeader_(sheet);

  if (!masterHeader || !paymentHeader) {
    return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      ...common,
      status: 'pending',
      issue_reason: 'hutang_header_missing'
    }, { createIfMissing: false });
  }

  const person = parseDebtPerson_(rawText);
  const amount = Number(parsed && parsed.amount ? parsed.amount : 0) || amountForIntent_(parsed, rawText);

  if (!person || !amount) {
    return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
      ...common,
      status: 'pending',
      issue_reason: 'hutang_increase_person_or_amount_missing'
    }, { createIfMissing: false });
  }

  const master = findDebtMasterRowByName_(sheet, masterHeader, person);

  if (!master) {
    const created = appendDebtMasterRow_(sheet, masterHeader, paymentHeader, person, amount, rawText, common);

    if (!created || created.status !== 'written') {
      return appendByHeader_(ss, AIRO_CONFIG.tabs.review, {
        ...common,
        status: 'pending',
        issue_reason: created && created.reason ? created.reason : 'hutang_person_not_found_in_master'
      }, { createIfMissing: false });
    }

    appendDebtPaymentLog_(sheet, paymentHeader, {
      pay_id: common.linked_txn_id || makeTxnId_({}, rawText),
      hutang_id: created.hutangId,
      nama: created.nama || person,
      date: todayDate_(),
      amount,
      sisa_setelah: amount,
      source: parsed.account && parsed.account !== 'Unknown' ? parsed.account : '',
      notes: 'debt_increase: ' + stripQaTag_(rawText)
    });

    return {
      status: 'written',
      writtenTab: sheet.getName(),
      row: created.row,
      rowId: sheet.getName() + ':' + created.row,
      tabUrl: getSheetTabUrl_(ss, sheet)
    };
  }

  const map = master.map;
  const oldPokok = map.jumlah_pokok ? Number(sheet.getRange(master.row, map.jumlah_pokok).getValue() || 0) : 0;
  const paid = map.total_dibayar ? Number(sheet.getRange(master.row, map.total_dibayar).getValue() || 0) : 0;
  const newPokok = oldPokok + amount;
  const sisa = Math.max(0, newPokok - paid);

  if (map.jumlah_pokok) sheet.getRange(master.row, map.jumlah_pokok).setValue(newPokok);
  if (map.sisa_hutang) sheet.getRange(master.row, map.sisa_hutang).setValue(sisa);
  if (map.status) sheet.getRange(master.row, map.status).setValue(sisa <= 0 ? 'lunas' : 'aktif');

  appendDebtPaymentLog_(sheet, paymentHeader, {
    pay_id: common.linked_txn_id || makeTxnId_({}, rawText),
    hutang_id: map.hutang_id ? sheet.getRange(master.row, map.hutang_id).getValue() : '',
    nama: map.nama ? sheet.getRange(master.row, map.nama).getValue() : person,
    date: todayDate_(),
    amount,
    sisa_setelah: sisa,
    source: '',
    notes: 'debt_increase: ' + stripQaTag_(rawText)
  });

  return {
    status: 'written',
    writtenTab: sheet.getName(),
    row: master.row,
    rowId: sheet.getName() + ':' + master.row,
    tabUrl: getSheetTabUrl_(ss, sheet)
  };
}

function appendDebtPaymentLog_(sheet, paymentHeader, data) {
  const map = hutangColMap_(paymentHeader.headers);
  const targetRow = findNextSectionRow_(sheet, paymentHeader.row, 1, paymentHeader.headers.length);

  const row = paymentHeader.headers.map(h => {
    const k = canonicalKey_(h);
    return data[k] !== undefined ? data[k] : '';
  });

  sheet.getRange(targetRow, 1, 1, row.length).setValues([row]);

  return targetRow;
}

function fixCreditCardStatusDropdownValues() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  const sheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.creditCard);

  if (!sheet) {
    return { ok: false, reason: 'credit_card_sheet_missing' };
  }

  const header = findCcHeaderRow_(sheet);
  if (!header) {
    return { ok: false, reason: 'cc_header_missing' };
  }

  const map = ccColMap_(header.headers);
  const statusCol = map.status_pocket_blu;

  if (!statusCol) {
    return { ok: false, reason: 'status_pocket_blu_col_missing' };
  }

  const lastRow = sheet.getLastRow();
  if (lastRow <= header.row) {
    return { ok: true, changed: 0 };
  }

  const range = sheet.getRange(header.row + 1, statusCol, lastRow - header.row, 1);
  const values = range.getValues();

  let changed = 0;

  const fixed = values.map(row => {
    const raw = String(row[0] || '').trim();
    const low = raw.toLowerCase();

    if (!raw) return [''];

    if (
      low === 'posted' ||
      low === 'paid' ||
      low === 'transferred' ||
      low.includes('sudah')
    ) {
      if (raw !== '✅ Sudah') changed++;
      return ['✅ Sudah'];
    }

    if (
      low === 'pending_transfer' ||
      low === 'pending' ||
      low === 'unpaid' ||
      low.includes('belum')
    ) {
      if (raw !== '⏳ Belum') changed++;
      return ['⏳ Belum'];
    }

    if (
      low === 'partial' ||
      low === 'partially_paid' ||
      low.includes('sebagian')
    ) {
      if (raw !== '⚠️ Sebagian') changed++;
      return ['⚠️ Sebagian'];
    }

    return [raw];
  });

  range.setValues(fixed);

  return {
    ok: true,
    sheet: sheet.getName(),
    changed
  };
}

function moveCreditCardStatusAfterAmount() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  const sheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.creditCard);

  if (!sheet) {
    return { ok: false, reason: 'credit_card_sheet_missing' };
  }

  const header = findCcHeaderRow_(sheet);
  if (!header) {
    return { ok: false, reason: 'cc_header_missing' };
  }

  const map = ccColMap_(header.headers);
  const amountCol = map.amount;
  const statusCol = map.status_pocket_blu;
  const descCol = map.description;

  if (!amountCol || !statusCol || !descCol) {
    return {
      ok: false,
      reason: 'required_columns_missing',
      amountCol,
      statusCol,
      descCol
    };
  }

  const targetStatusCol = amountCol + 1;

  if (statusCol === targetStatusCol) {
    fixCreditCardStatusDropdownValues();
    return {
      ok: true,
      changed: false,
      reason: 'status_already_after_amount',
      statusCol
    };
  }

  // Safe table-only reorder.
  // Expected current layout:
  // amount | description | status_pocket_blu
  // Target:
  // amount | status_pocket_blu | description
  if (descCol !== targetStatusCol) {
    return {
      ok: false,
      reason: 'unexpected_cc_column_layout',
      amountCol,
      statusCol,
      descCol,
      expectedDescriptionCol: targetStatusCol
    };
  }

  const startRow = header.row;
  const numRows = sheet.getMaxRows() - startRow + 1;

  const statusRange = sheet.getRange(startRow, statusCol, numRows, 1);
  const descRange = sheet.getRange(startRow, descCol, numRows, 1);

  const statusValues = statusRange.getValues();
  const descValues = descRange.getValues();
  const statusValidations = statusRange.getDataValidations();

  // Put status into column after amount.
  descRange.setValues(statusValues);
  descRange.setDataValidations(statusValidations);

  // Put description into old status column and remove dropdown validation there.
  statusRange.setValues(descValues);
  statusRange.clearDataValidations();

  // Make headers explicit.
  sheet.getRange(startRow, targetStatusCol).setValue('status_pocket_blu');
  sheet.getRange(startRow, statusCol).setValue('description');

  // Normalize old values like posted/pending_transfer to dropdown labels.
  fixCreditCardStatusDropdownValues();

  return {
    ok: true,
    changed: true,
    moved: 'status_pocket_blu after amount',
    new_status_col: targetStatusCol,
    description_col: statusCol
  };
}

function titleCaseSimple_(value) {
  return String(value || '')
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

function parseCcDateFromText_(rawText, fallbackDate) {
  const text = String(rawText || '').toLowerCase();
  const fallback = fallbackDate instanceof Date ? fallbackDate : todayDate_();
  const year = fallback.getFullYear();

  const months = {
    januari: 0, jan: 0,
    februari: 1, feb: 1,
    maret: 2, mar: 2,
    april: 3, apr: 3,
    mei: 4,
    juni: 5, jun: 5,
    juli: 6, jul: 6,
    agustus: 7, agu: 7, aug: 7,
    september: 8, sep: 8,
    oktober: 9, okt: 9, oct: 9,
    november: 10, nov: 10,
    desember: 11, des: 11, dec: 11
  };

  let m = text.match(/\b(?:tgl|tanggal)\s+(\d{1,2})\s+([a-z]+)(?:\s+(\d{4}))?\b/i);
  if (!m) {
    m = text.match(/\b(\d{1,2})\s+([a-z]+)(?:\s+(\d{4}))?\b/i);
  }

  if (m) {
    const day = Number(m[1]);
    const mon = months[String(m[2]).toLowerCase()];
    const y = m[3] ? Number(m[3]) : year;

    if (!Number.isNaN(mon) && day >= 1 && day <= 31) {
      return new Date(y, mon, day);
    }
  }

  if (/\bkemarin\b/i.test(text)) {
    const d = new Date(fallback);
    d.setDate(d.getDate() - 1);
    return d;
  }

  if (/\bbesok\b/i.test(text)) {
    const d = new Date(fallback);
    d.setDate(d.getDate() + 1);
    return d;
  }

  if (/\bhari ini\b/i.test(text)) {
    return fallback;
  }

  return fallback;
}

function fixCreditCardDateMerchantFromRawText() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  const sheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.creditCard);

  if (!sheet) {
    return { ok: false, reason: 'credit_card_sheet_missing' };
  }

  const header = findCcHeaderRow_(sheet);
  if (!header) {
    return { ok: false, reason: 'cc_header_missing' };
  }

  const map = ccColMap_(header.headers);

  const dateCol = map.date;
  const merchantCol = map.merchant_app;
  const descCol = map.description;
  const cycleCol = map.billing_cycle_id;
  const startCol = map.billing_start;
  const endCol = map.billing_end;
  const statementCol = map.statement_month;

  if (!dateCol || !merchantCol || !descCol) {
    return {
      ok: false,
      reason: 'required_columns_missing',
      dateCol,
      merchantCol,
      descCol
    };
  }

  const lastRow = sheet.getLastRow();
  if (lastRow <= header.row) {
    return { ok: true, changed: 0 };
  }

  let changed = 0;

  for (let r = header.row + 1; r <= lastRow; r++) {
    const desc = String(sheet.getRange(r, descCol).getValue() || '').trim();
    if (!desc) continue;

    const oldDate = sheet.getRange(r, dateCol).getValue();
    const fallbackDate = oldDate instanceof Date ? oldDate : todayDate_();

    const parsedDate = parseCcDateFromText_(desc, fallbackDate);
    const merchant = parseCcMerchant_(desc);
    const cycle = ccBillingCycle_(parsedDate);

    sheet.getRange(r, dateCol).setValue(parsedDate);
    sheet.getRange(r, merchantCol).setValue(merchant);

    if (cycleCol) sheet.getRange(r, cycleCol).setValue(cycle.id);
    if (startCol) sheet.getRange(r, startCol).setValue(cycle.start);
    if (endCol) sheet.getRange(r, endCol).setValue(cycle.end);
    if (statementCol) sheet.getRange(r, statementCol).setValue(cycle.statementMonth);

    changed++;
  }

  return {
    ok: true,
    sheet: sheet.getName(),
    changed
  };
}

/**
 * Manual backfill function to migrate historical data from 💵 Cash Ledger to 📒 Account Ledger.
 * Safe to run multiple times: it is append-only, performs strict deduplication based on entry_id
 * and key properties, and populates balance formulas dynamically without overwriting existing data.
 */
function AIRO_BACKFILL_ACCOUNT_LEDGER_FROM_CASH_LEDGER() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  var tz = ss.getSpreadsheetTimeZone() || Session.getScriptTimeZone();

  var cashSheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.cash);
  if (!cashSheet) {
    throw new Error('Cash Ledger sheet not found');
  }

  var accountSheet = ensureAccountLedgerSheet_(ss);
  if (!accountSheet) {
    throw new Error('Failed to ensure Account Ledger sheet exists');
  }

  var cashHeaderObj = findHeader_(cashSheet);
  if (!cashHeaderObj) {
    throw new Error('Header not found in Cash Ledger');
  }

  var accountHeaderObj = findHeader_(accountSheet);
  if (!accountHeaderObj) {
    throw new Error('Header not found in Account Ledger');
  }

  var cashHeaders = cashHeaderObj.headers;
  var accountHeaders = accountHeaderObj.headers;

  // Validate required fields in Cash Ledger
  var hasDate = cashHeaders.some(function(h) {
    var f = fieldForHeader_(h);
    return f === 'date' || canonicalKey_(h) === 'date_start' || canonicalKey_(h) === 'date';
  });
  var hasAccount = cashHeaders.some(function(h) {
    var f = fieldForHeader_(h);
    return f === 'account' || f === 'source' || canonicalKey_(h) === 'account' || canonicalKey_(h) === 'source';
  });
  var hasAmount = cashHeaders.some(function(h) {
    var f = fieldForHeader_(h);
    return f === 'amount' || f === 'amount_in' || f === 'amount_out' || canonicalKey_(h) === 'amount';
  });
  var hasDesc = cashHeaders.some(function(h) {
    var f = fieldForHeader_(h);
    return f === 'description' || f === 'raw_text' || f === 'notes' || canonicalKey_(h) === 'description';
  });

  if (!hasDate || !hasAccount || !hasAmount || !hasDesc) {
    throw new Error('Cash Ledger is missing required columns (Date, Account, Amount, or Description)');
  }

  // Validate required fields in Account Ledger
  var hasAccDate = accountHeaders.some(function(h) {
    return canonicalKey_(h) === 'date';
  });
  var hasAccAccount = accountHeaders.some(function(h) {
    return canonicalKey_(h) === 'account';
  });
  var hasAccAmountIn = accountHeaders.some(function(h) {
    return canonicalKey_(h) === 'amount_in';
  });
  var hasAccAmountOut = accountHeaders.some(function(h) {
    return canonicalKey_(h) === 'amount_out';
  });
  var hasAccDesc = accountHeaders.some(function(h) {
    return canonicalKey_(h) === 'description';
  });

  if (!hasAccDate || !hasAccAccount || !hasAccAmountIn || !hasAccAmountOut || !hasAccDesc) {
    throw new Error('Account Ledger is missing required target columns (date, account, amount_in, amount_out, or description)');
  }

  // Read Cash Ledger rows
  var cashHeaderRow = cashHeaderObj.row;
  var cashLastRow = cashSheet.getLastRow();
  var parsedCashRows = [];

  if (cashLastRow > cashHeaderRow) {
    var maxCols = cashSheet.getLastColumn();
    var cashData = cashSheet.getRange(cashHeaderRow + 1, 1, cashLastRow - cashHeaderRow, maxCols).getValues();

    for (var r = 0; r < cashData.length; r++) {
      var rowVals = cashData[r];
      var rowObj = {};
      for (var c = 0; c < cashHeaders.length; c++) {
        var header = cashHeaders[c];
        if (header) {
          rowObj[canonicalKey_(header)] = rowVals[c];
        }
      }

      // Filter empty rows
      var entryId = getFieldValue_(rowObj, 'entry_id', cashHeaders) || getFieldValue_(rowObj, 'linked_txn_id', cashHeaders);
      var desc = getFieldValue_(rowObj, 'description', cashHeaders) || getFieldValue_(rowObj, 'raw_text', cashHeaders);
      var amt = getFieldValue_(rowObj, 'amount', cashHeaders) || getFieldValue_(rowObj, 'amount_in', cashHeaders) || getFieldValue_(rowObj, 'amount_out', cashHeaders);

      if (!entryId && !desc && !amt) {
        continue;
      }
      parsedCashRows.push(rowObj);
    }
  }

  var registerEntryIdVariants_ = function(map, value) {
    var entryStr = String(value || '').trim().toLowerCase();
    if (!entryStr) {
      return;
    }
    map[entryStr] = true;
    if (entryStr.slice(-3) === ':in') {
      map[entryStr.slice(0, -3)] = true;
    } else if (entryStr.slice(-4) === ':out') {
      map[entryStr.slice(0, -4)] = true;
    }
  };

  // Read Account Ledger rows for dedup
  var accountHeaderRow = accountHeaderObj.row;
  var accountLastRow = accountSheet.getLastRow();
  var existingAccountKeys = {};
  var existingEntryIds = {};
  var existingAccountRowsCount = 0;

  if (accountLastRow > accountHeaderRow) {
    var accountData = accountSheet.getRange(accountHeaderRow + 1, 1, accountLastRow - accountHeaderRow, accountHeaders.length).getValues();
    existingAccountRowsCount = accountData.length;

    for (var r = 0; r < accountData.length; r++) {
      var rowVals = accountData[r];
      var rowObj = {};
      for (var c = 0; c < accountHeaders.length; c++) {
        var header = accountHeaders[c];
        if (header) {
          rowObj[canonicalKey_(header)] = rowVals[c];
        }
      }

      var key = buildDedupKey_(rowObj, accountHeaders, tz);
      if (key) {
        existingAccountKeys[key] = true;
      }

      var entryId = getFieldValue_(rowObj, 'entry_id', accountHeaders) || getFieldValue_(rowObj, 'linked_txn_id', accountHeaders);
      registerEntryIdVariants_(existingEntryIds, entryId);
    }
  }

  // Backfill loop
  var appendedCount = 0;
  var skippedCount = 0;

  for (var i = 0; i < parsedCashRows.length; i++) {
    var cashRow = parsedCashRows[i];

    var cashEntryId = getFieldValue_(cashRow, 'entry_id', cashHeaders) || getFieldValue_(cashRow, 'linked_txn_id', cashHeaders);
    var cashEntryStr = String(cashEntryId || '').trim().toLowerCase();
    var isDuplicate = false;
    var cashKey = '';

    if (cashEntryStr && existingEntryIds[cashEntryStr]) {
      isDuplicate = true;
    } else {
      cashKey = buildDedupKey_(cashRow, cashHeaders, tz);
      if (cashKey && existingAccountKeys[cashKey]) {
        isDuplicate = true;
      }
    }

    if (isDuplicate) {
      skippedCount++;
      continue;
    }

    // Construct new row object for Account Ledger
    var entryId = cashEntryId || makeTxnId_({}, getFieldValue_(cashRow, 'description', cashHeaders) || getFieldValue_(cashRow, 'raw_text', cashHeaders) || 'backfill');
    var dateVal = getFieldValue_(cashRow, 'date', cashHeaders) || getFieldValue_(cashRow, 'date_start', cashHeaders);
    if (dateVal instanceof Date) {
      dateVal = Utilities.formatDate(dateVal, tz, 'yyyy-MM-dd');
    }

    var amountIn = getFieldValue_(cashRow, 'amount_in', cashHeaders);
    var amountOut = getFieldValue_(cashRow, 'amount_out', cashHeaders);

    // If amount_in / amount_out is not explicitly present, calculate based on amount & type
    if (amountIn === '' && amountOut === '') {
      var amountVal = getFieldValue_(cashRow, 'amount', cashHeaders);
      var typeVal = String(getFieldValue_(cashRow, 'type', cashHeaders) || '').toLowerCase();
      var rawTextVal = getFieldValue_(cashRow, 'raw_text', cashHeaders) || getFieldValue_(cashRow, 'description', cashHeaders) || '';
      var isInflow = ['income', 'transfer_in', 'cash_in'].indexOf(typeVal) >= 0 || isCashInflowText_(rawTextVal);

      if (isInflow) {
        amountIn = amountVal;
        amountOut = '';
      } else {
        amountIn = '';
        amountOut = amountVal;
      }
    }

    var cashRowTextForAccount = getFieldValue_(cashRow, 'raw_text', cashHeaders) || getFieldValue_(cashRow, 'description', cashHeaders) || '';
    var accountValForLedger = getFieldValue_(cashRow, 'account', cashHeaders) || getFieldValue_(cashRow, 'source', cashHeaders) || 'Cash';
    if (String(accountValForLedger || '').trim().toLowerCase() === 'cash') {
      accountValForLedger = cashAccountNameForLedger_(cashRowTextForAccount);
    }

    var row = {
      entry_id: entryId,
      date: dateVal,
      account: accountValForLedger,
      amount_in: amountIn,
      amount_out: amountOut,
      balance: '',
      type: getFieldValue_(cashRow, 'type', cashHeaders) || 'expense',
      category: getFieldValue_(cashRow, 'category', cashHeaders) || 'Lainnya',
      description: getFieldValue_(cashRow, 'description', cashHeaders) || getFieldValue_(cashRow, 'raw_text', cashHeaders) || '',
      raw_text: getFieldValue_(cashRow, 'raw_text', cashHeaders) || getFieldValue_(cashRow, 'description', cashHeaders) || '',
      source_tab: AIRO_CONFIG.tabs.cash,
      linked_txn_id: getFieldValue_(cashRow, 'linked_txn_id', cashHeaders) || '',
      notes: getFieldValue_(cashRow, 'notes', cashHeaders) || ''
    };

    var result = appendByHeader_(ss, AIRO_CONFIG.tabs.accountLedger, row, { createIfMissing: false });
    if (result && result.status === 'written' && result.row) {
      appendedCount++;
      // Set formula balance
      try {
        var r = result.row;
        var formula = '=IF(C' + r + '="";"";SUMIFS($D$2:D' + r + ';$C$2:C' + r + ';C' + r + ')-SUMIFS($E$2:E' + r + ';$C$2:C' + r + ';C' + r + '))';
        accountSheet.getRange(r, 6).setFormula(formula);
        applyAccountLedgerRowStyle_(accountSheet, r);
      } catch (e) {}

      // Update local dedup maps to avoid duplicates in the same batch
      if (cashEntryStr) {
        registerEntryIdVariants_(existingEntryIds, cashEntryStr);
      }
      if (!cashKey) {
        cashKey = buildDedupKey_(cashRow, cashHeaders, tz);
      }
      if (cashKey) {
        existingAccountKeys[cashKey] = true;
      }
    } else {
      skippedCount++;
    }
  }

  var resultSummary = {
    cashRows: parsedCashRows.length,
    existingAccountRows: existingAccountRowsCount,
    appendedRows: appendedCount,
    skippedRows: skippedCount,
    accountLedgerTab: accountSheet.getName()
  };
  Logger.log(JSON.stringify(resultSummary));
  return resultSummary;
}

function getFieldValue_(rowObj, fieldName, headers) {
  var canonicalField = canonicalKey_(fieldName);
  if (rowObj[canonicalField] !== undefined && rowObj[canonicalField] !== null && rowObj[canonicalField] !== '') {
    return rowObj[canonicalField];
  }
  for (var i = 0; i < headers.length; i++) {
    var h = headers[i];
    if (fieldForHeader_(h) === fieldName) {
      var key = canonicalKey_(h);
      if (rowObj[key] !== undefined && rowObj[key] !== null && rowObj[key] !== '') {
        return rowObj[key];
      }
    }
  }
  return '';
}

function buildDedupKey_(rowObj, headers, tz) {
  var dateVal = getFieldValue_(rowObj, 'date', headers) || getFieldValue_(rowObj, 'date_start', headers);
  if (dateVal instanceof Date) {
    dateVal = Utilities.formatDate(dateVal, tz || Session.getScriptTimeZone(), 'yyyy-MM-dd');
  }

  var accountVal = getFieldValue_(rowObj, 'account', headers) || getFieldValue_(rowObj, 'source', headers) || 'Cash';

  var amountVal = getFieldValue_(rowObj, 'amount', headers);
  if (amountVal === undefined || amountVal === null || amountVal === '') {
    var amountIn = getFieldValue_(rowObj, 'amount_in', headers);
    var amountOut = getFieldValue_(rowObj, 'amount_out', headers);
    amountVal = (Number(amountIn) || 0) + (Number(amountOut) || 0);
  }

  var typeVal = getFieldValue_(rowObj, 'type', headers) || 'expense';
  var descVal = getFieldValue_(rowObj, 'description', headers) || getFieldValue_(rowObj, 'raw_text', headers) || getFieldValue_(rowObj, 'notes', headers);

  var d = String(dateVal || '').trim().toLowerCase();
  var acc = String(accountVal || '').trim().toLowerCase();
  var amt = Number(amountVal) || 0;
  var t = String(typeVal || '').trim().toLowerCase();
  var desc = String(descVal || '').trim().toLowerCase();

  if (!d && !amt) {
    return '';
  }

  return d + '|' + acc + '|' + t + '|' + amt + '|' + desc;
}

/**
 * Audit function for Account Ledger to identify missing source_tab, cash backfill rows, and duplicate candidates.
 * Completely read-only.
 */
function AIRO_AUDIT_ACCOUNT_LEDGER_BACKFILL_CLEANUP() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  var tz = ss.getSpreadsheetTimeZone() || Session.getScriptTimeZone();

  var sheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.accountLedger);
  if (!sheet) {
    throw new Error('Account Ledger sheet not found');
  }

  var headerObj = findHeader_(sheet);
  if (!headerObj) {
    throw new Error('Header not found in Account Ledger');
  }

  var headers = headerObj.headers;
  var startRow = headerObj.row + 1;
  var lastRow = sheet.getLastRow();

  var emptySourceTabRows = [];
  var cashBackfillLikeRows = [];
  var suspectedDuplicateRows = [];
  var duplicateCandidatesMap = {};
  var totalRows = 0;

  if (lastRow >= startRow) {
    var data = sheet.getRange(startRow, 1, lastRow - startRow + 1, headers.length).getValues();
    totalRows = data.length;

    for (var i = 0; i < data.length; i++) {
      var rowVals = data[i];
      var rowNum = startRow + i;

      var rowObj = {};
      for (var c = 0; c < headers.length; c++) {
        var h = headers[c];
        if (h) {
          rowObj[canonicalKey_(h)] = rowVals[c];
        }
      }

      var sourceTabVal = String(rowObj['source_tab'] || '').trim();
      var entryIdVal = String(rowObj['entry_id'] || '').trim().toLowerCase();
      var notesVal = String(rowObj['notes'] || '').trim().toLowerCase();

      // Check empty source_tab
      if (sourceTabVal === '' && emptySourceTabRows.length < 30) {
        emptySourceTabRows.push(rowNum);
      }

      // Check cash backfill like
      var isCashBackfill = sourceTabVal.toLowerCase().indexOf('cash') >= 0 ||
                           entryIdVal.indexOf('backfill') >= 0 ||
                           notesVal.indexOf('backfill') >= 0;
      if (isCashBackfill && cashBackfillLikeRows.length < 30) {
        cashBackfillLikeRows.push(rowNum);
      }

      // Build a unique key for duplicate identification:
      // date + account + amount_in + amount_out + normalized description/raw_text
      var dateVal = rowObj['date'];
      if (dateVal instanceof Date) {
        dateVal = Utilities.formatDate(dateVal, tz, 'yyyy-MM-dd');
      }
      var d = String(dateVal || '').trim().toLowerCase();

      var acc = String(rowObj['account'] || '').trim().toLowerCase();
      var amtIn = Number(rowObj['amount_in']) || 0;
      var amtOut = Number(rowObj['amount_out']) || 0;

      var descVal = rowObj['description'] || rowObj['raw_text'] || '';
      var desc = String(descVal || '').trim().toLowerCase();

      var dupKey = d + '|' + acc + '|' + amtIn + '|' + amtOut + '|' + desc;

      if (dupKey) {
        if (!duplicateCandidatesMap[dupKey]) {
          duplicateCandidatesMap[dupKey] = [];
        }
        duplicateCandidatesMap[dupKey].push(rowNum);
      }
    }

    // Process duplicates
    var duplicateCandidates = [];
    var keys = Object.keys(duplicateCandidatesMap);
    for (var k = 0; k < keys.length; k++) {
      var key = keys[k];
      var rows = duplicateCandidatesMap[key];
      if (rows.length > 1) {
        if (duplicateCandidates.length < 30) {
          duplicateCandidates.push({
            key: key,
            rows: rows
          });
        }
        for (var r = 1; r < rows.length; r++) {
          if (suspectedDuplicateRows.length < 30) {
            suspectedDuplicateRows.push(rows[r]);
          }
        }
      }
    }
  }

  var resultSummary = {
    totalRows: totalRows,
    emptySourceTabRows: emptySourceTabRows,
    cashBackfillLikeRows: cashBackfillLikeRows,
    duplicateCandidates: duplicateCandidates,
    suspectedDuplicateRows: suspectedDuplicateRows
  };

  Logger.log(JSON.stringify(resultSummary));
  return resultSummary;
}

/**
 * Safe, specific manual cleanup function for duplicate rows and blank source_tab in Account Ledger.
 */
function AIRO_CLEANUP_ACCOUNT_LEDGER_BACKFILL_DUPES_20260517() {
  const ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
  var tz = ss.getSpreadsheetTimeZone() || Session.getScriptTimeZone();

  var sheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.accountLedger);
  if (!sheet) {
    throw new Error('Account Ledger sheet not found');
  }

  var headerObj = findHeader_(sheet);
  if (!headerObj) {
    throw new Error('Header not found in Account Ledger');
  }

  var headers = headerObj.headers;
  var startRow = headerObj.row + 1;
  var lastRow = sheet.getLastRow();

  if (lastRow < 15) {
    throw new Error('Sheet row count is less than 15. Minimal 15 rows required before cleanup.');
  }

  // Inner helper to construct unique comparison key for a row
  function getRowKey(rowNum) {
    var vals = sheet.getRange(rowNum, 1, 1, headers.length).getValues()[0];
    var rowObj = {};
    for (var c = 0; c < headers.length; c++) {
      var h = headers[c];
      if (h) {
        rowObj[canonicalKey_(h)] = vals[c];
      }
    }
    var dateVal = rowObj['date'];
    if (dateVal instanceof Date) {
      dateVal = Utilities.formatDate(dateVal, tz, 'yyyy-MM-dd');
    }
    var d = String(dateVal || '').trim().toLowerCase();
    var acc = String(rowObj['account'] || '').trim().toLowerCase();
    var amtIn = Number(rowObj['amount_in']) || 0;
    var amtOut = Number(rowObj['amount_out']) || 0;
    var descVal = rowObj['description'] || rowObj['raw_text'] || '';
    var desc = String(descVal || '').trim().toLowerCase();
    return d + '|' + acc + '|' + amtIn + '|' + amtOut + '|' + desc;
  }

  // Safety validations: Row keys must match exactly
  var key2 = getRowKey(2);
  var key12 = getRowKey(12);
  if (key2 !== key12) {
    throw new Error('Safety validation failed: Row 2 key does not match Row 12 key.');
  }

  var key3 = getRowKey(3);
  var key13 = getRowKey(13);
  if (key3 !== key13) {
    throw new Error('Safety validation failed: Row 3 key does not match Row 13 key.');
  }

  var key4 = getRowKey(4);
  var key14 = getRowKey(14);
  if (key4 !== key14) {
    throw new Error('Safety validation failed: Row 4 key does not match Row 14 key.');
  }

  var key5 = getRowKey(5);
  var key15 = getRowKey(15);
  if (key5 !== key15) {
    throw new Error('Safety validation failed: Row 5 key does not match Row 15 key.');
  }

  // Perform deletion of exact row indices in descending order
  sheet.deleteRow(15);
  sheet.deleteRow(14);
  sheet.deleteRow(13);
  sheet.deleteRow(12);

  // Find column index of source_tab
  var sourceTabColIdx = -1;
  for (var c = 0; c < headers.length; c++) {
    if (canonicalKey_(headers[c]) === 'source_tab') {
      sourceTabColIdx = c + 1;
      break;
    }
  }

  if (sourceTabColIdx === -1) {
    throw new Error('Could not find column index of source_tab');
  }

  // Repair missing source_tab values for remaining rows
  var repairedSourceTabRows = [];
  var updatedLastRow = sheet.getLastRow();
  for (var r = startRow; r <= updatedLastRow; r++) {
    var val = sheet.getRange(r, sourceTabColIdx).getValue();
    if (String(val || '').trim() === '') {
      sheet.getRange(r, sourceTabColIdx).setValue(AIRO_CONFIG.tabs.cash);
      repairedSourceTabRows.push(r);
    }
  }

  var resultSummary = {
    deletedRows: [15, 14, 13, 12],
    repairedSourceTabRows: repairedSourceTabRows,
    accountLedgerTab: sheet.getName()
  };

  Logger.log(JSON.stringify(resultSummary));
  return resultSummary;
}

/**
 * Normalizes input value to supported accounts (Cash, Blu, BCA).
 */
function normalizeSupportedAccount_(value) {
  var v = String(value || '').toLowerCase().replace(/[\s_]+/g, ' ').trim();

  if (v === 'pocket blu' || v === 'blu pocket') return 'Blu Pocket';
  if (v === 'pocket blu cc' || v === 'blu pocket cc') return 'Blu Pocket CC';
  if (v === 'pocket bca' || v === 'bca pocket') return 'BCA Pocket';
  if (v === 'cc' || v === 'credit card') return 'Credit Card';
  if (v === 'blu' || v === 'blu bca' || v === 'blubca') return 'Blu';
  if (v === 'bca') return 'BCA';
  if (v === 'cash umum') return 'Cash Umum';
  if (v === 'cash bensin') return 'Cash Bensin';

  if (v === 'cash' || v === 'tunai') {
    var registry = airoSprint7AccountContractGetRegistry_();
    var activeCash = [];
    for (var i = 0; i < registry.length; i++) {
      var acc = registry[i];
      if (acc.account_name === 'Cash Umum' || acc.account_name === 'Cash Bensin') {
        activeCash.push(acc.account_name);
      }
    }
    // cash ambiguity marker: both Cash Umum and Cash Bensin active
    if (activeCash.length === 2) {
      return '';
    }
    if (activeCash.length === 1) {
      return activeCash[0];
    }
    return 'Cash Umum';
  }

  var registry = airoSprint7AccountContractGetRegistry_();
  for (var i = 0; i < registry.length; i++) {
    var acc = registry[i];
    var name = acc.account_name;
    var nameLower = name.toLowerCase().replace(/[\s_]+/g, ' ').trim();
    if (v === nameLower) {
      return name;
    }
  }

  return '';
}

/**
 * Detects whether the transaction represents an internal transfer between Cash, Blu, and BCA.
 */
function detectInternalTransfer_(parsed, rawText) {
  var t = String(rawText || '').toLowerCase().trim();

  // Support source marker: dr, dari, from
  // Support destination marker: ke, to
  // Support amount suffix: rb, ribu, k
  var aliasPattern = '\\b(pocket\\s+blu|blu\\s+pocket|pocket\\s+bca|bca\\s+pocket|cash\\s+umum|cash\\s+bensin|credit\\s+card|cc|blu|bca|cash|tunai)\\b';

  var fromRegex = new RegExp('(?:dari|from|dr)\\s+' + aliasPattern, 'i');
  var toRegex = new RegExp('(?:ke|to)\\s+' + aliasPattern, 'i');

  var sourceAccount = '';
  var targetAccount = '';

  var fromMatch = t.match(fromRegex);
  if (fromMatch) {
    sourceAccount = normalizeSupportedAccount_(fromMatch[1]);
  }

  var toMatch = t.match(toRegex);
  if (toMatch) {
    targetAccount = normalizeSupportedAccount_(toMatch[1]);
  }

  if (!sourceAccount && parsed && parsed.account) {
    sourceAccount = normalizeSupportedAccount_(parsed.account);
  }

  if (!sourceAccount || !targetAccount || sourceAccount === targetAccount) {
    return null;
  }

  return {
    sourceAccount: sourceAccount,
    targetAccount: targetAccount
  };
}

/**
 * Writes an internal transfer to the Account Ledger as two separate entries (outflow and inflow)
 * and synchronizes with the Cash Ledger compatibility layer if one of the accounts is Cash.
 */
// AIRO_TASK8_DEBT_CICILAN_LEDGER_FIRST_SELFTEST_V1
function task8DebtCicilanLedgerFirstContract_(
  ledgerState,
  projectionState
) {
  const ledger = ledgerState || {};

  if (!ledger.ok) {
    return {
      status: 'failed',
      write_order: ['account_ledger'],
      retry_projection_only: false,
      duplicate_ledger_append: false
    };
  }

  if (projectionState !== 'written') {
    return {
      status: 'partial',
      write_order: ['account_ledger', 'domain_projection'],
      retry_projection_only: true,
      duplicate_ledger_append: false,
      account_ledger_existing: Boolean(ledger.existing)
    };
  }

  return {
    status: 'written',
    write_order: ['account_ledger', 'domain_projection'],
    retry_projection_only: false,
    duplicate_ledger_append: false,
    account_ledger_existing: Boolean(ledger.existing)
  };
}

function runTask8DebtCicilanLedgerFirstSelfTestFromEditor() {
  const results = [];

  const debtSuccess =
    task8DebtCicilanLedgerFirstContract_(
      { ok: true, existing: false },
      'written'
    );

  results.push({
    test: 'debt_payment_ledger_before_domain',
    passed:
      debtSuccess.status === 'written' &&
      debtSuccess.write_order.join('>') ===
        'account_ledger>domain_projection'
  });

  const cicilanSuccess =
    task8DebtCicilanLedgerFirstContract_(
      { ok: true, existing: false },
      'written'
    );

  results.push({
    test: 'cicilan_ledger_before_domain',
    passed:
      cicilanSuccess.status === 'written' &&
      cicilanSuccess.write_order[0] ===
        'account_ledger'
  });

  const retry =
    task8DebtCicilanLedgerFirstContract_(
      { ok: true, existing: true },
      'missing'
    );

  results.push({
    test: 'existing_ledger_projection_only_retry',
    passed:
      retry.status === 'partial' &&
      retry.retry_projection_only === true &&
      retry.duplicate_ledger_append === false
  });

  const projectionFailure =
    task8DebtCicilanLedgerFirstContract_(
      { ok: true, existing: false },
      'failed'
    );

  results.push({
    test: 'projection_failure_is_partial',
    passed: projectionFailure.status === 'partial'
  });

  const repeated =
    task8DebtCicilanLedgerFirstContract_(
      { ok: true, existing: true },
      'written'
    );

  results.push({
    test: 'repeated_request_no_duplicate_ledger',
    passed:
      repeated.status === 'written' &&
      repeated.duplicate_ledger_append === false
  });

  const ledgerFailure =
    task8DebtCicilanLedgerFirstContract_(
      { ok: false, existing: false },
      'written'
    );

  results.push({
    test: 'domain_not_called_when_ledger_fails',
    passed:
      ledgerFailure.status === 'failed' &&
      ledgerFailure.write_order.length === 1
  });

  const ok = results.every(item => item.passed);

  return {
    ok: ok,
    status: ok ? 'PASS' : 'FAIL',
    mode: 'task8_debt_cicilan_ledger_first_selftest',
    results: results,
    finance_events_write_performed: false,
    workbook_write_performed: false,
    telegram_send_performed: false,
    gmail_modified: false,
    deploy_performed: false
  };
}

function writeInternalTransferToAccountLedger_(ss, parsed, rawText, common, transfer) {
  var sharedTxnId = (common && (common.linked_txn_id || common.rowId)) || makeTxnId_({}, rawText);

  // Write Source Outflow Row
  var parsedOut = {
    ...parsed,
    account: transfer.sourceAccount,
    type: 'transfer_out',
    amount: parsed.amount
  };
  var commonOut = {
    ...common,
    rowId: sharedTxnId + ':out',
    linked_txn_id: sharedTxnId + ':in'
  };
  var outResult = writeAccountLedgerMirror_(ss, parsedOut, rawText, commonOut, transfer.sourceAccount);

  // Write Target Inflow Row
  var parsedIn = {
    ...parsed,
    account: transfer.targetAccount,
    type: 'transfer_in',
    amount: parsed.amount
  };
  var commonIn = {
    ...common,
    rowId: sharedTxnId + ':in',
    linked_txn_id: sharedTxnId + ':out'
  };
  var inResult = writeAccountLedgerMirror_(ss, parsedIn, rawText, commonIn, transfer.targetAccount);

  // Cash Ledger compatibility layer synchronization
  var cashResult = null;
  if (transfer.targetAccount === 'Cash') {
    var parsedCashIn = {
      ...parsed,
      account: 'Cash',
      type: 'transfer_in',
      amount: parsed.amount
    };
    cashResult = writeCashLedgerCompatibility_(ss, parsedCashIn, rawText, common);
  } else if (transfer.sourceAccount === 'Cash') {
    var parsedCashOut = {
      ...parsed,
      account: 'Cash',
      type: 'transfer_out',
      amount: parsed.amount
    };
    cashResult = writeCashLedgerCompatibility_(ss, parsedCashOut, rawText, common);
  }

  var transferResult = {
    status: 'written',
    writtenTab: AIRO_CONFIG.tabs.accountLedger,
    rowId: sharedTxnId,
    row: (outResult && outResult.row) ? outResult.row : '',
    writeVerified: Boolean(outResult && outResult.row && inResult && inResult.row),
    transferInternal: true,
    sourceAccount: transfer.sourceAccount,
    targetAccount: transfer.targetAccount,
    accountLedgerRows: [
      (outResult && outResult.row) ? outResult.row : null,
      (inResult && inResult.row) ? inResult.row : null
    ],
    cashLedgerRow: (cashResult && cashResult.row) ? cashResult.row : null
  };

  if (transferResult.writeVerified) {
    // AIRO_INTERNAL_TRANSFER_FINANCE_EVENT_EMISSION_V1
    // Internal transfer writes two Account Ledger rows and one Finance Events index row.
    recordFinanceEventForWriteResult_(ss, transferResult, common, parsed, rawText, {
      event_type: 'internal_transfer',
      event_source: 'telegram',
      source_tab: AIRO_CONFIG.tabs.accountLedger,
      source_row: String(transferResult.accountLedgerRows[0] || '') + ',' + String(transferResult.accountLedgerRows[1] || ''),
      linked_txn_id: sharedTxnId,
      account: String(transfer.sourceAccount || '') + ' -> ' + String(transfer.targetAccount || ''),
      category: parsed.category || 'Lainnya',
      amount: parsed.amount || '',
      direction: 'transfer',
      notes: 'internal_transfer'
    });
  }

  return transferResult;
}

function airoLiveSchemaVerifyOnly() {
  const spreadsheetId =
    PropertiesService.getScriptProperties().getProperty('SPREADSHEET_ID') ||
    '1CKARXGurxZ0Rby3-_iisVS0_r65JM6ZaT6tbAJUF7sU';

  const ss = SpreadsheetApp.openById(spreadsheetId);
  const beforeTabs = ss.getSheets().map(function(sheet) { return sheet.getName(); });

  let financeEventsTab = '';
  let financeEventsStatus = 'skipped_missing_ensureFinanceEventsSheet_';
  if (typeof ensureFinanceEventsSheet_ === 'function') {
    const eventsSheet = ensureFinanceEventsSheet_(ss);
    financeEventsTab = eventsSheet ? eventsSheet.getName() : '';
    financeEventsStatus = financeEventsTab ? 'ok' : 'missing_after_ensure';
  }

  let cashReportingStatus = 'skipped_missing_refreshCashReportingFormulas';
  try {
    if (typeof refreshCashReportingFormulas === 'function') {
      const cashReportingResult = refreshCashReportingFormulas();
      cashReportingStatus = JSON.stringify(cashReportingResult || {});
    }
  } catch (err) {
    cashReportingStatus = 'error:' + err.message;
  }

  let reviewQueueSchemaStatus = 'skipped_missing_runTask3AReviewQueueSchemaVerifierFromEditor';
  try {
    if (typeof runTask3AReviewQueueSchemaVerifierFromEditor === 'function') {
      const verifierRes = runTask3AReviewQueueSchemaVerifierFromEditor();
      reviewQueueSchemaStatus = verifierRes.ok ? 'ok' : 'missing_columns';
    }
  } catch (err) {
    reviewQueueSchemaStatus = 'error:' + err.message;
  }

  const afterTabs = ss.getSheets().map(function(sheet) { return sheet.getName(); });

  Logger.log('AIRO_LIVE_SCHEMA_VERIFY_SPREADSHEET=' + ss.getName());
  Logger.log('AIRO_LIVE_SCHEMA_VERIFY_SPREADSHEET_ID=' + spreadsheetId);
  Logger.log('AIRO_LIVE_SCHEMA_VERIFY_BEFORE_TAB_COUNT=' + beforeTabs.length);
  Logger.log('AIRO_LIVE_SCHEMA_VERIFY_AFTER_TAB_COUNT=' + afterTabs.length);
  Logger.log('AIRO_LIVE_SCHEMA_VERIFY_FINANCE_EVENTS_STATUS=' + financeEventsStatus);
  Logger.log('AIRO_LIVE_SCHEMA_VERIFY_FINANCE_EVENTS_TAB=' + financeEventsTab);
  Logger.log('AIRO_LIVE_SCHEMA_VERIFY_CASH_REPORTING_STATUS=' + cashReportingStatus);
  Logger.log('AIRO_LIVE_SCHEMA_VERIFY_REVIEW_QUEUE_STATUS=' + reviewQueueSchemaStatus);
  Logger.log('AIRO_LIVE_SCHEMA_VERIFY_AFTER_TABS=' + afterTabs.join(' | '));

  return {
    spreadsheetName: ss.getName(),
    spreadsheetId: spreadsheetId,
    beforeTabCount: beforeTabs.length,
    afterTabCount: afterTabs.length,
    financeEventsStatus: financeEventsStatus,
    financeEventsTab: financeEventsTab,
    cashReportingStatus: cashReportingStatus,
    reviewQueueSchemaStatus: reviewQueueSchemaStatus,
    tabs: afterTabs
  };
}

