function airoSprint7ParserPlanExtractCommand_(e) {
  var out = {
    text: "",
    chat_id: null
  };

  try {
    if (!e || !e.postData || !e.postData.contents) {
      return out;
    }

    var update = JSON.parse(e.postData.contents);
    var msg = null;

    if (update.message) {
      msg = update.message;
    } else if (update.edited_message) {
      msg = update.edited_message;
    } else if (update.callback_query && update.callback_query.message) {
      msg = update.callback_query.message;
      out.text = update.callback_query.data || "";
    }

    if (!msg) {
      return out;
    }

    if (!out.text) {
      out.text = msg.text || msg.caption || "";
    }

    if (msg.chat && msg.chat.id) {
      out.chat_id = msg.chat.id;
    }

    return out;
  } catch (err) {
    return out;
  }
}

function airoSprint7ParserPlanGetBotToken_() {
  var props = PropertiesService.getScriptProperties();

  var names = [
    "TELEGRAM_BOT_TOKEN",
    "AIRO_TELEGRAM_BOT_TOKEN",
    "BOT_TOKEN",
    "TELEGRAM_TOKEN",
    "TG_BOT_TOKEN"
  ];

  for (var i = 0; i < names.length; i++) {
    var value = props.getProperty(names[i]);
    if (value) {
      return value;
    }
  }

  try {
    if (typeof TELEGRAM_BOT_TOKEN !== "undefined" && TELEGRAM_BOT_TOKEN) {
      return TELEGRAM_BOT_TOKEN;
    }
  } catch (err1) {}

  try {
    if (typeof BOT_TOKEN !== "undefined" && BOT_TOKEN) {
      return BOT_TOKEN;
    }
  } catch (err2) {}

  try {
    if (typeof TELEGRAM_TOKEN !== "undefined" && TELEGRAM_TOKEN) {
      return TELEGRAM_TOKEN;
    }
  } catch (err3) {}

  return "";
}

function airoSprint7ParserPlanReply_(chatId, messageText) {
  var token = airoSprint7ParserPlanGetBotToken_();

  if (!token) {
    throw new Error("Missing Telegram bot token property for parser plan route reply.");
  }

  var url = "https://api.telegram.org/bot" + token + "/sendMessage";
  var payload = {
    chat_id: chatId,
    text: messageText,
    parse_mode: "HTML",
    disable_web_page_preview: true
  };

  UrlFetchApp.fetch(url, {
    method: "post",
    contentType: "application/json",
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  });
}

function airoSprint7ParserPlanJsonOutput_(obj) {
  return ContentService
    .createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
}

function airoSprint7ParserPlanMaybeHandleRoute_(e) {
  var extracted = airoSprint7ParserPlanExtractCommand_(e);
  var text = String(extracted.text || "").trim().toLowerCase();

  if (text !== "admin email sprint7 parser plan") {
    return null;
  }

  var reply = airoAdminEmailSprint7ParserPlan_();

  if (extracted.chat_id) {
    airoSprint7ParserPlanReply_(extracted.chat_id, reply);
  }

  return airoSprint7ParserPlanJsonOutput_({
    ok: true,
    handled: true,
    command: "admin email sprint7 parser plan",
    mode: "dry-run",
    write_performed: false,
    email_ingestion_enabled: false
  });
}

function airoOriginalDoPostForSprint7SamplePreview_(e) {
  var sprint7ParserPlanResult = airoSprint7ParserPlanMaybeHandleRoute_(e);

  if (sprint7ParserPlanResult) {
    return sprint7ParserPlanResult;
  }

  return airoOriginalDoPostForSprint7ParserPlan_(e);
}
