/* AIRO_SPRINT7_MANUAL_SAMPLE_PREVIEW_START */
function airoSprint7SamplePreviewNormalize_(value) {
  return String(value || "").replace(/\s+/g, " ").trim();
}

function airoSprint7SamplePreviewHash_(value) {
  var normalized = airoSprint7SamplePreviewNormalize_(value).toLowerCase();

  if (!normalized) {
    return "";
  }

  try {
    var digest = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, normalized);
    var out = [];

    for (var i = 0; i < digest.length; i++) {
      var b = digest[i];

      if (b < 0) {
        b += 256;
      }

      out.push(("0" + b.toString(16)).slice(-2));
    }

    return out.join("").slice(0, 24);
  } catch (err) {
    return "hash_unavailable";
  }
}

function airoSprint7SamplePreviewHasSensitiveKeyword_(sampleText) {
  var text = String(sampleText || "").toLowerCase();

  var keywords = [
    "otp",
    "kode",
    "verifikasi",
    "verification",
    "login",
    "security",
    "password",
    "reset",
    "perangkat",
    "device",
    "one time password",
    "2fa",
    "authentication",
    "auth code",
    "kode keamanan"
  ];

  for (var i = 0; i < keywords.length; i++) {
    if (text.indexOf(keywords[i]) >= 0) {
      return keywords[i];
    }
  }

  return "";
}

function airoSprint7SamplePreviewExtractAmount_(sampleText) {
  var text = String(sampleText || "");
  var patterns = [
    /(?:rp|idr)\s*([0-9][0-9\.\,]*)/i,
    /(?:amount|nominal|sebesar|transaksi)\s*[:\-]?\s*(?:rp|idr)?\s*([0-9][0-9\.\,]*)/i,
    /\b([0-9]{1,3}(?:[\.][0-9]{3})+|[0-9]{4,})\b/
  ];

  for (var i = 0; i < patterns.length; i++) {
    var match = text.match(patterns[i]);

    if (match && match[1]) {
      var token = String(match[1]).trim();
      if (/,\d{2}$/.test(token)) {
        token = token.replace(/,\d{2}$/, "");
      }
      var raw = token.replace(/[^\d]/g, "");
      var amount = Number(raw);

      if (amount > 0) {
        return amount;
      }
    }
  }

  return 0;
}

function airoSprint7SamplePreviewCleanMerchant_(value) {
  var text = airoSprint7SamplePreviewNormalize_(value);

  text = text.replace(/\b(?:rp|idr)\s*[0-9][0-9\.\,]*/ig, " ");
  text = text.replace(/\b[0-9]{1,3}(?:[\.][0-9]{3})+\b/g, " ");
  text = text.replace(/\b[0-9]{4,}\b/g, " ");
  text = text.replace(/\bkartu\s+kredit\b/ig, " ");
  text = text.replace(/\bcredit\s+card\b/ig, " ");
  text = text.replace(/^[\s\-:=]+/g, " ");

  var blocked = {
    "di": true,
    "at": true,
    "amount": true,
    "nominal": true,
    "sebesar": true,
    "transaksi": true,
    "transaction": true,
    "notification": true,
    "sample": true,
    "debit": true,
    "credit": true,
    "card": true,
    "cc": true,
    "payment": true,
    "purchase": true,
    "pembayaran": true,
    "merchant": true,
    "toko": true,
    "store": true,
    "kartu": true,
    "kredit": true
  };

  var tokens = text.split(/\s+/);
  var kept = [];

  for (var i = 0; i < tokens.length; i++) {
    var token = String(tokens[i] || "").replace(/^[:=\-]+|[:=\-]+$/g, "");
    var lower = token.toLowerCase();

    if (!token) {
      continue;
    }

    if (blocked[lower]) {
      continue;
    }

    kept.push(token);
  }

  return kept.join(" ").replace(/\s+/g, " ").trim().slice(0, 60);
}

function airoSprint7SamplePreviewTokenKey_(token) {
  return String(token || "").toLowerCase().replace(/^[:=\-]+|[:=\-]+$/g, "");
}

function airoSprint7SamplePreviewExtractMerchant_(sampleText) {
  var text = airoSprint7SamplePreviewNormalize_(sampleText);
  var tokens = text.split(/\s+/);

  var labelKeys = {
    "merchant": true,
    "toko": true,
    "store": true
  };

  for (var i = 0; i < tokens.length; i++) {
    var raw = String(tokens[i] || "");
    var key = airoSprint7SamplePreviewTokenKey_(raw);

    if (labelKeys[key]) {
      return airoSprint7SamplePreviewCleanMerchant_(tokens.slice(i + 1).join(" "));
    }

    var inlineLabel = raw.match(/^(merchant|toko|store)[:=\-](.+)$/i);
    if (inlineLabel && inlineLabel[2]) {
      return airoSprint7SamplePreviewCleanMerchant_(inlineLabel[2] + " " + tokens.slice(i + 1).join(" "));
    }
  }

  for (var j = 0; j < tokens.length; j++) {
    var placeKey = airoSprint7SamplePreviewTokenKey_(tokens[j]);

    if (placeKey === "di" || placeKey === "at") {
      return airoSprint7SamplePreviewCleanMerchant_(tokens.slice(j + 1).join(" "));
    }
  }

  return "";
}

function airoSprint7SamplePreviewExtractPaymentMethod_(sampleText) {
  var text = String(sampleText || "").toLowerCase();

  if (text.indexOf("blu") >= 0) {
    return "Blu";
  }

  if (text.indexOf("bca") >= 0) {
    return "BCA";
  }

  if (text.indexOf("credit card") >= 0 || text.indexOf("kartu kredit") >= 0 || text.indexOf("cc") >= 0) {
    return "Credit Card";
  }

  if (text.indexOf("debit") >= 0) {
    return "Debit";
  }

  return "";
}

function airoSprint7SamplePreviewGuessCategory_(sampleText) {
  var text = String(sampleText || "").toLowerCase();

  if (text.indexOf("refund") >= 0 || text.indexOf("reversal") >= 0 || text.indexOf("pengembalian") >= 0) {
    return "Refund";
  }

  if (
    text.indexOf("kopi") >= 0 ||
    text.indexOf("coffee") >= 0 ||
    text.indexOf("cafe") >= 0 ||
    text.indexOf("café") >= 0 ||
    text.indexOf("starbucks") >= 0 ||
    text.indexOf("makan") >= 0 ||
    text.indexOf("minum") >= 0 ||
    text.indexOf("resto") >= 0 ||
    text.indexOf("restaurant") >= 0 ||
    text.indexOf("food") >= 0 ||
    text.indexOf("warung") >= 0
  ) {
    return "Makan";
  }

  if (text.indexOf("transport") >= 0 || text.indexOf("gojek") >= 0 || text.indexOf("grab") >= 0 || text.indexOf("bensin") >= 0) {
    return "Transport";
  }

  if (text.indexOf("transfer") >= 0) {
    return "Transfer";
  }

  return "";
}

function airoSprint7ManualSampleEmailPreview_(sampleText) {
  sampleText = airoSprint7SamplePreviewNormalize_(sampleText);

  var sensitiveKeyword = airoSprint7SamplePreviewHasSensitiveKeyword_(sampleText);
  var subjectHash = airoSprint7SamplePreviewHash_(sampleText);

  if (sensitiveKeyword) {
    var sensitiveDuplicateKey = airoSprint7SamplePreviewHash_([
      "email_sample_sensitive",
      sensitiveKeyword,
      subjectHash
    ].join("|"));

    return {
      ok: true,
      sprint: "Sprint 7",
      command: "admin email sprint7 sample preview",
      mode: "dry-run",
      write_performed: false,
      email_ingestion_enabled: false,
      email_default_off: true,
      dry_run_only: true,
      input_mode: "manual sample text or mock payload only",
      output_mode: "preview object only",
      live_email_scan_allowed: false,
      auto_write_allowed: false,

      safety: {
        gmail_read_performed: false,
        mailbox_read_performed: false,
        mail_trigger_created: false,
        finance_write_performed: false,
        account_ledger_write_performed: false,
        finance_events_write_performed: false,
        review_queue_write_performed: false,
        full_email_body_storage_allowed: false,
        sample_text_stored: false,
        otp_security_hard_block_before_finance_parse: true,
        finance_parser_skipped_due_to_sensitive: true,
        duplicate_detection_required_before_write: true
      },

      preview: {
        source_message_id: "manual_sample_" + subjectHash,
        sender: "manual_sample",
        subject: subjectHash ? "sample_subject_hash_" + subjectHash : "",
        received_at: "manual_sample_not_mailbox",
        merchant: "",
        amount: 0,
        currency: "",
        transaction_date: "",
        payment_method: "",
        category_guess: "",
        confidence: 0,
        duplicate_key: sensitiveDuplicateKey,
        needs_review_reason: "skipped_sensitive_keyword_" + sensitiveKeyword.replace(/\s+/g, "_"),
        parse_status: "skipped_sensitive",
        sensitive_skip_reason: "blocked_keyword_" + sensitiveKeyword
      },

      status: "skipped_sensitive",
      next: "sensitive sample hard-blocked before finance parsing; still no Gmail live read and no finance write"
    };
  }

  var amount = airoSprint7SamplePreviewExtractAmount_(sampleText);
  var merchant = airoSprint7SamplePreviewExtractMerchant_(sampleText);
  var paymentMethod = airoSprint7SamplePreviewExtractPaymentMethod_(sampleText);
  var categoryGuess = airoSprint7SamplePreviewGuessCategory_(sampleText);
  var duplicateKey = airoSprint7SamplePreviewHash_([
    "email_sample_preview",
    amount,
    merchant,
    paymentMethod,
    categoryGuess,
    subjectHash
  ].join("|"));

  var needsReview = [];

  if (!sampleText) {
    needsReview.push("sample_text_empty");
  }

  if (!amount) {
    needsReview.push("missing_amount");
  }

  if (!merchant) {
    needsReview.push("missing_merchant");
  }

  if (!paymentMethod) {
    needsReview.push("missing_payment_method");
  }

  if (!categoryGuess) {
    needsReview.push("missing_category_guess");
  }

  var confidence = 0;

  if (amount) {
    confidence += 30;
  }

  if (merchant) {
    confidence += 20;
  }

  if (paymentMethod) {
    confidence += 20;
  }

  if (categoryGuess) {
    confidence += 15;
  }

  if (sampleText) {
    confidence += 15;
  }

  var parseStatus = "candidate_ready_preview_only";

  if (!sampleText) {
    parseStatus = "candidate_low_confidence";
  } else if (needsReview.length > 0) {
    parseStatus = "candidate_needs_clarification";
  }

  return {
    ok: true,
    sprint: "Sprint 7",
    command: "admin email sprint7 sample preview",
    mode: "dry-run",
    write_performed: false,
    email_ingestion_enabled: false,
    email_default_off: true,
    dry_run_only: true,
    input_mode: "manual sample text or mock payload only",
    output_mode: "preview object only",
    live_email_scan_allowed: false,
    auto_write_allowed: false,

    safety: {
      gmail_read_performed: false,
      mailbox_read_performed: false,
      mail_trigger_created: false,
      finance_write_performed: false,
      account_ledger_write_performed: false,
      finance_events_write_performed: false,
      review_queue_write_performed: false,
      full_email_body_storage_allowed: false,
      sample_text_stored: false,
      otp_security_hard_block_before_finance_parse: true,
      finance_parser_skipped_due_to_sensitive: false,
      duplicate_detection_required_before_write: true
    },

    preview: {
      source_message_id: "manual_sample_" + subjectHash,
      sender: "manual_sample",
      subject: subjectHash ? "sample_subject_hash_" + subjectHash : "",
      received_at: "manual_sample_not_mailbox",
      merchant: merchant,
      amount: amount,
      currency: amount ? "IDR" : "",
      transaction_date: "",
      payment_method: paymentMethod,
      category_guess: categoryGuess,
      confidence: confidence,
      duplicate_key: duplicateKey,
      needs_review_reason: needsReview.join(", ") || "preview_only_no_write",
      parse_status: parseStatus,
      sensitive_skip_reason: ""
    },

    status: parseStatus,
    next: "review preview result; still no Gmail live read and no finance write"
  };
}

