// TASK_6_11_SMOKE_SCAN_ADMIN_COMMAND_ROUTE
// Routes "admin scan smoke dryrun" Telegram command to the dry-run scanner.
// READ-ONLY: no operational rows are modified or deleted.
function airoTask611SmokeAdminCommandMaybeHandleRoute_(e) {
  // TASK_6_11_PATCH_V2
  try {
    var body = JSON.parse(e && e.postData && e.postData.contents ? e.postData.contents : '{}');
    var msg = body.message || body.edited_message || {};
    var chatId = (msg.chat || {}).id;
    var rawText = ((msg.text || '').replace(/\s+/g, ' ')).trim();

    var isDryRun = /^admin\s+scan\s+smoke\s+(dryrun|dry[\s-]run)\s*$/i.test(rawText);
    var isCleanup = /^admin\s+cleanup\s+smoke\s+confirm\s*$/i.test(rawText);
    if (!isDryRun && !isCleanup) return null;

    if (isDryRun) {
      sendTelegram_(chatId, 'Task 6.11 — Dry-run scan v2 started...\nScanning 8 tabs for SMK_, QA_, TEST_ rows. Please wait.');
      var scanResult = airoTask611SmokeTestDryRunScan_();

      function tabDisplayLabel_(label) {
        var stripped = label.replace(/^[^ -\x7E]+/, '').trim();
        return stripped || label;
      }

      var statusLine = scanResult.allTabsNotFound
        ? 'Status: FAIL — all tabs not found (scan invalid)'
        : (scanResult.ok ? 'Status: DRY_RUN_READY' : 'Status: FAIL — errors occurred');

      var lines = [
        'Task 6.11 — Smoke/Test DRY RUN Scan v2',
        '',
        statusLine,
        'Phase: ' + (scanResult.phase || 'UNKNOWN'),
        'Timestamp: ' + scanResult.scanTimestamp,
        'TOTAL SMOKE ROWS: ' + scanResult.totalFound,
        ''
      ];

      var byTab = scanResult.byTab || {};
      for (var tabKey in byTab) {
        var tabInfo = byTab[tabKey];
        var displayLabel = tabDisplayLabel_(tabKey);
        if (!tabInfo.exists || tabInfo.skipped) {
          lines.push(displayLabel + ' [configured: ' + tabInfo.configured + ']: NOT FOUND');
        } else if (tabInfo.found > 0) {
          lines.push(displayLabel + ' [' + tabInfo.resolved + ']: ' +
            tabInfo.found + ' smoke row(s) — rows ' + (tabInfo.rows || []).join(', '));
        } else {
          lines.push(displayLabel + ' [' + tabInfo.resolved + ']: CLEAN');
        }
      }

      if (scanResult.errors && scanResult.errors.length > 0) {
        lines.push('');
        lines.push('ERRORS:');
        scanResult.errors.forEach(function(err) { lines.push('  ' + err); });
      }

      lines.push('');
      if (scanResult.ok && !scanResult.allTabsNotFound) {
        lines.push('Archive sheet "Smoke Archive DRY RUN" updated in workbook.');
        lines.push('Owner must review and approve before any deletion.');
        lines.push('Deletion is BLOCKED until owner approval.');
      } else {
        lines.push('Scan result is INVALID — do not proceed to deletion.');
        lines.push('Check spreadsheet tab names and re-run.');
      }

      sendTelegram_(chatId, lines.join('\n'));

      return json_({
        ok: scanResult.ok,
        handled: true,
        command: 'task_611_smoke_dryrun_scan_v2',
        write_performed: false,
        gmail_read_performed: false,
        any_row_deleted: false,
        any_row_modified: false,
        result: scanResult
      });
    } else if (isCleanup) {
      sendTelegram_(chatId, 'Task 6.11 — Destructive smoke/test cleanup started...\nDeleting approved rows bottom-up per tab. Please wait.');
      var cleanupResult = airoTask611SmokeCleanupExecute_();

      var lines = [
        'Task 6.11 — Smoke/Test Data Cleanup Complete',
        '',
        'Result: ' + (cleanupResult.ok ? 'PASS' : 'BLOCKED/FAIL'),
        'TOTAL DELETED ROWS: ' + cleanupResult.totalDeleted,
        '',
        'Deleted per tab:'
      ];
      for (var tab in cleanupResult.deleted) {
        lines.push('- ' + tab + ': ' + cleanupResult.deleted[tab] + ' row(s)');
      }

      var hasSkipped = false;
      for (var tab in cleanupResult.skipped) {
        if (cleanupResult.skipped[tab] > 0) {
          hasSkipped = true;
          break;
        }
      }
      if (hasSkipped) {
        lines.push('');
        lines.push('Skipped per tab:');
        for (var tab in cleanupResult.skipped) {
          if (cleanupResult.skipped[tab] > 0) {
            lines.push('- ' + tab + ': ' + cleanupResult.skipped[tab] + ' row(s)');
          }
        }
      }

      if (cleanupResult.suspicious && cleanupResult.suspicious.length > 0) {
        lines.push('');
        lines.push('⚠️ SUSPICIOUS ROWS:');
        cleanupResult.suspicious.forEach(function(row) {
          lines.push('  - ' + row);
        });
      }

      lines.push('');
      lines.push('Balance verification: ' + (cleanupResult.balanceVerification || 'OK'));
      lines.push('Smoke verification after cleanup: ' + cleanupResult.smokeVerification);
      lines.push('Archive sheet created/updated: ' + cleanupResult.archiveSheetName);

      sendTelegram_(chatId, lines.join('\n'));

      return json_({
        ok: cleanupResult.ok,
        handled: true,
        command: 'task_611_smoke_cleanup_execute',
        write_performed: true,
        gmail_read_performed: false,
        any_row_deleted: cleanupResult.totalDeleted > 0,
        any_row_modified: false,
        result: cleanupResult
      });
    }
  } catch (handlerErr) {
    var handlerErrMsg = String(handlerErr && handlerErr.message ? handlerErr.message : handlerErr);
    try {
      sendTelegram_(chatId, 'Task 6.11 scan/cleanup error:\n' + handlerErrMsg);
    } catch (e) {}
    return json_({ ok: false, handled: true, command: 'task_611_smoke_scan_cleanup_route', error: handlerErrMsg });
  }
}



