function airoTask9CleanupPreview_() {
  var target = airoTask9OpenConfiguredSpreadsheet_();
  var ss = target.spreadsheet;
  var spec = airoTask9CleanupSpec_();

  if (String(target.spreadsheetId) !== String(spec.spreadsheetId)) {
    throw new Error('task9_cleanup_workbook_mismatch');
  }

  var items = spec.candidates.map(function(item) {
    var sheet = getSheetLoose_(ss, item[0]);
    if (!sheet) {
      return {
        sheet: item[0],
        row: item[1],
        marker: item[2],
        valid: false,
        reason: 'sheet_missing'
      };
    }

    if (item[1] > sheet.getLastRow()) {
      return {
        sheet: sheet.getName(),
        row: item[1],
        marker: item[2],
        valid: false,
        reason: 'row_missing'
      };
    }

    var row = sheet
      .getRange(item[1], 1, 1, sheet.getLastColumn())
      .getDisplayValues()[0];

    var text = row.join(' | ');

    return {
      sheet: sheet.getName(),
      row: item[1],
      marker: item[2],
      valid: text.indexOf(item[2]) !== -1,
      preview: text.slice(0, 260)
    };
  });

  return {
    ok: items.length === 10 && items.every(function(item) {
      return item.valid === true;
    }),
    write_performed: false,
    workbook_write_performed: false,
    candidate_count: items.length,
    items: items
  };
}

