function doGet(e) {
  var probe = e && e.parameter && e.parameter.airo_probe;
  if (probe === 'task9_access_gate') {
    var response = {
      ok: true,
      handled: true,
      probe: "task9_access_gate",
      readonly: true,
      service: "airo-finance",
      source: "apps-script-webapp",
      task: "task9_cc_live_access_gate",
      timestamp: new Date().toISOString(),
      writes_performed: false,
      gmail_read_performed: false,
      telegram_send_performed: false
    };
    return ContentService.createTextOutput(JSON.stringify(response))
                         .setMimeType(ContentService.MimeType.JSON);
  }

  var errResponse = {
    ok: false,
    message: "Forbidden or unknown GET request"
  };
  return ContentService.createTextOutput(JSON.stringify(errResponse))
                       .setMimeType(ContentService.MimeType.JSON);
}

function airoTask9GetConfiguredSpreadsheetId_() {
  var id = String(PropertiesService.getScriptProperties().getProperty('SPREADSHEET_ID') || '').trim();
  if (!id) {
    throw new Error('AIRO Task 9 target spreadsheet id missing: ScriptProperties.SPREADSHEET_ID is empty');
  }
  return id;
}

function airoTask9OpenConfiguredSpreadsheet_() {
  var spreadsheetId = airoTask9GetConfiguredSpreadsheetId_();
  var ss = SpreadsheetApp.openById(spreadsheetId);

  if (ss && typeof ss.getId === 'function') {
    var actualId = String(ss.getId() || '').trim();
    if (actualId && actualId !== spreadsheetId) {
      throw new Error('AIRO Task 9 target spreadsheet mismatch: expected=' + spreadsheetId + ' actual=' + actualId);
    }
  }

  return {
    spreadsheet: ss,
    spreadsheetId: spreadsheetId
  };
}

function airoTask9CcPendingPocketCommandMaybeHandleRoute_(e) {
  try {
    var parsed = airoSprint7FParseTelegramText_(e);
    if (parsed.text !== "cek tagihan pending cc") {
      return null;
    }

    var target = airoTask9OpenConfiguredSpreadsheet_();
    var ss = target.spreadsheet;
    var targetSpreadsheetId = target.spreadsheetId;

    var sheet = getSheetLoose_(ss, 'Credit Card');
    if (!sheet) {
      if (parsed.chat_id) {
        sendTelegram_(parsed.chat_id, "Error: Tab Credit Card tidak ditemukan.");
      }
      return json_({ ok: false, handled: true, error: "credit_card_tab_not_found" });
    }

    var headerInfo = findCcHeaderRow_(sheet);
    if (!headerInfo) {
      if (parsed.chat_id) {
        sendTelegram_(parsed.chat_id, "Error: Header Credit Card tidak ditemukan.");
      }
      return json_({ ok: false, handled: true, error: "cc_header_not_found" });
    }

    var map = ccColMap_(headerInfo.headers);
    var statusColIdx = map.status_pocket_blu;
    var amountColIdx = map.amount;
    var descColIdx = map.description || map.merchant_app;
    var entryIdColIdx = map.cc_entry_id;

    if (!statusColIdx || !amountColIdx || !entryIdColIdx) {
      if (parsed.chat_id) {
        sendTelegram_(parsed.chat_id, "Error: Kolom status_pocket_blu, amount, atau cc_entry_id tidak ditemukan.");
      }
      return json_({ ok: false, handled: true, error: "cc_required_columns_missing" });
    }

    var startRow = headerInfo.row + 1;
    var lastRow = sheet.getLastRow();
    var pendingItems = [];
    var totalPending = 0;

    if (lastRow >= startRow) {
      var range = sheet.getRange(startRow, 1, lastRow - startRow + 1, headerInfo.headers.length);
      var values = range.getValues();

      for (var i = 0; i < values.length; i++) {
        var row = values[i];
        var statusVal = String(row[statusColIdx - 1] || '').trim().toLowerCase();

        var isPending = true;
        var excludes = ['sudah', 'paid', 'posted', 'transferred'];
        for (var j = 0; j < excludes.length; j++) {
          if (statusVal.indexOf(excludes[j]) !== -1) {
            isPending = false;
            break;
          }
        }

        if (isPending) {
          var amountVal = Number(row[amountColIdx - 1]) || 0;
          var descVal = String(descColIdx ? row[descColIdx - 1] : '').trim();
          var merchantColIdx = map.merchant_app;
          var merchantVal = String(merchantColIdx ? row[merchantColIdx - 1] : '').trim();
          var displayDesc = descVal || merchantVal;
          var entryIdVal = String(row[entryIdColIdx - 1] || '').trim();
          var billingCycleColIdx = map.billing_cycle_id;
          var billingCycleVal = billingCycleColIdx ? String(row[billingCycleColIdx - 1] || '').trim() : '';

          if (amountVal > 0 && displayDesc !== '') {
            pendingItems.push({
              description: displayDesc,
              amount: amountVal,
              cc_entry_id: entryIdVal,
              billing_cycle_id: billingCycleVal
            });
            totalPending += amountVal;
          }
        }
      }
    }

    if (parsed.chat_id && pendingItems.length > 0) {
      try {
        var cache = CacheService.getScriptCache();
        var cacheKey = "cc_pending_snapshot_" + parsed.chat_id;
        var snapshot = {
          target_spreadsheet_id: targetSpreadsheetId,
          generated_at: new Date().toISOString(),
          items: pendingItems.map(function(item) {
            return {
              cc_entry_id: item.cc_entry_id,
              amount: item.amount,
              description: item.description,
              billing_cycle_id: item.billing_cycle_id || ''
            };
          })
        };
        cache.put(cacheKey, JSON.stringify(snapshot), 900);
      } catch (cacheErr) {
        Logger.log("Failed to write CacheService: " + cacheErr.toString());
      }
    }

    var replyText = "";
    if (pendingItems.length === 0) {
      replyText = "Tidak ada pending CC.";
    } else {
      var lines = [];
      lines.push("💳 Pending Dana CC");
      lines.push("");
      for (var k = 0; k < pendingItems.length; k++) {
        lines.push((k + 1) + ". " + pendingItems[k].description + " — " + formatBalanceRupiah_(pendingItems[k].amount));
      }
      lines.push("");
      lines.push("Total belum disisihkan ke Blu Pocket CC: " + formatBalanceRupiah_(totalPending));
      lines.push("");
      lines.push("Balas:");
      lines.push("cc sudah <nomor>");
      replyText = lines.join("\n");
    }

    if (parsed.chat_id) {
      sendTelegram_(parsed.chat_id, replyText);
    }

    return json_({
      ok: true,
      handled: true,
      command: "cek tagihan pending cc",
      write_performed: false,
      gmail_read_performed: false,
      item_count: pendingItems.length,
      total_amount: totalPending
    });

  } catch (err) {
    var errMsg = String(err && err.message ? err.message : err);
    var chatId = null;
    try {
      var parsed = airoSprint7FParseTelegramText_(e);
      chatId = parsed.chat_id;
    } catch (e2) {}

    if (chatId) {
      try {
        sendTelegram_(chatId, "Error executing pending CC command: " + errMsg);
      } catch (e3) {}
    }

    return json_({
      ok: false,
      handled: true,
      command: "cek tagihan pending cc",
      error: errMsg
    });
  }
}

function airoTask9CcSudahNumberMaybeHandleRoute_(e) {
  try {
    var parsed = airoSprint7FParseTelegramText_(e);
    var rawText = String(parsed.text || "").trim();
    var match = rawText.match(/^cc\s+sudah\s+(\d+)$/i);
    if (!match) {
      return null;
    }

    var index = Number(match[1]);

    if (!parsed.chat_id) {
      return json_({ ok: false, handled: true, error: "chat_id_missing" });
    }

    var cache = CacheService.getScriptCache();
    var cacheKey = "cc_pending_snapshot_" + parsed.chat_id;
    var cachedStr = cache.get(cacheKey);
    var chatId = parsed.chat_id;

    var snapshot = null;
    try {
      if (cachedStr) {
        snapshot = JSON.parse(cachedStr);
      }
    } catch (e) {}

    if (!snapshot || !snapshot.items || !snapshot.items.length) {
      sendTelegram_(chatId, "Nomor pending CC belum terdaftar atau sudah kedaluwarsa.\n\nJalankan `cek tagihan pending cc` terlebih dahulu.");
      return json_({ ok: false, handled: true, error: "cc_pending_mapping_expired" });
    }

    var target = airoTask9OpenConfiguredSpreadsheet_();
    var ss = target.spreadsheet;
    var targetSpreadsheetId = target.spreadsheetId;

    if (String(snapshot.target_spreadsheet_id || '') !== String(targetSpreadsheetId || '')) {
      sendTelegram_(chatId, '⚠️ Mapping CC sudah tidak valid karena target workbook berubah. Jalankan ulang: cek tagihan pending cc');
      return json_({
        ok: false,
        handled: true,
        command: 'cc sudah',
        reason: 'target_spreadsheet_mismatch',
        write_performed: false
      });
    }

    var entryIds = snapshot.items.map(function(item) { return item.cc_entry_id; });

    if (index < 1 || index > entryIds.length) {
      sendTelegram_(chatId, "Nomor " + index + " tidak valid. Harap pilih nomor antara 1 dan " + entryIds.length + ".");
      return json_({ ok: false, handled: true, error: "cc_pending_index_out_of_range" });
    }

    var targetEntryId = entryIds[index - 1];
    if (!targetEntryId) {
      sendTelegram_(chatId, "Error: CC Entry ID tidak ditemukan.");
      return json_({ ok: false, handled: true, error: "cc_entry_id_not_found" });
    }

    if (targetSpreadsheetId !== '1CKARXGurxZ0Rby3-_iisVS0_r65JM6ZaT6tbAJUF7sU') {
      sendTelegram_(chatId, '⚠️ Target workbook mismatch. Settlement dibatalkan sebelum write.');
      return json_({
        ok: false,
        handled: true,
        command: 'cc sudah',
        reason: 'unexpected_target_spreadsheet_id',
        target_spreadsheet_id: targetSpreadsheetId,
        write_performed: false
      });
    }

    var sheet = getSheetLoose_(ss, 'Credit Card');
    if (!sheet) {
      sendTelegram_(chatId, "Error: Tab Credit Card tidak ditemukan.");
      return json_({ ok: false, handled: true, error: "credit_card_tab_not_found" });
    }

    var headerInfo = findCcHeaderRow_(sheet);
    if (!headerInfo) {
      sendTelegram_(parsed.chat_id, "Error: Header Credit Card tidak ditemukan.");
      return json_({ ok: false, handled: true, error: "cc_header_not_found" });
    }

    var map = ccColMap_(headerInfo.headers);
    var entryIdColIdx = map.cc_entry_id;
    var statusColIdx = map.status_pocket_blu;
    var amountColIdx = map.amount;
    var descColIdx = map.description || map.merchant_app;
    var transferredColIdx = map.transferred_at;
    var linkedTxnIdColIdx = map.linked_txn_id;
    var notesColIdx = map.notes;

    if (!statusColIdx || !amountColIdx || !entryIdColIdx) {
      sendTelegram_(parsed.chat_id, "Error: Kolom status_pocket_blu, amount, atau cc_entry_id tidak ditemukan.");
      return json_({ ok: false, handled: true, error: "cc_required_columns_missing" });
    }

    var startRow = headerInfo.row + 1;
    var lastRow = sheet.getLastRow();
    var targetRow = 0;
    var rowValues = null;

    if (lastRow >= startRow) {
      var range = sheet.getRange(startRow, 1, lastRow - startRow + 1, headerInfo.headers.length);
      var values = range.getValues();
      for (var i = 0; i < values.length; i++) {
        var rowValuesCandidate = values[i];
        var entryIdVal = String(rowValuesCandidate[entryIdColIdx - 1] || '').trim();
        if (entryIdVal === targetEntryId) {
          targetRow = startRow + i;
          rowValues = rowValuesCandidate;
          break;
        }
      }
    }

    if (!targetRow) {
      sendTelegram_(parsed.chat_id, "Error: Transaksi CC dengan ID " + targetEntryId + " tidak ditemukan di sheet.");
      return json_({ ok: false, handled: true, error: "cc_row_not_found" });
    }

    var statusVal = String(rowValues[statusColIdx - 1] || '').trim().toLowerCase();
    var amountVal = Number(rowValues[amountColIdx - 1]) || 0;
    var descVal = String(descColIdx ? rowValues[descColIdx - 1] : '').trim();
    var merchantVal = String(map.merchant_app ? rowValues[map.merchant_app - 1] : '').trim();
    var displayDesc = descVal || merchantVal;
    var linkedTxnIdVal = linkedTxnIdColIdx ? String(rowValues[linkedTxnIdColIdx - 1] || '').trim() : '';

    var excludes = ['sudah', 'paid', 'posted', 'transferred'];
    var isPending = true;
    for (var j = 0; j < excludes.length; j++) {
      if (statusVal.indexOf(excludes[j]) !== -1) {
        isPending = false;
        break;
      }
    }

    if (!isPending) {
      if (linkedTxnIdVal) {
        sendTelegram_(parsed.chat_id, "Transaksi sudah disiapkan ke Blu (Already Settled).\nLedger Ref: " + linkedTxnIdVal);
        return json_({ ok: true, handled: true, error: "cc_already_settled", ledger_ref: linkedTxnIdVal });
      } else {
        sendTelegram_(parsed.chat_id, "⚠️ Audit Warning: Status transaksi CC '" + statusVal + "' sudah Sudah tetapi linked_txn_id kosong. Tidak ada auto-write.");
        return json_({ ok: false, handled: true, error: "CC_STATUS_SUDAH_WITHOUT_LEDGER_LINK" });
      }
    }

    if (amountVal <= 0) {
      sendTelegram_(parsed.chat_id, "Error: Jumlah transaksi CC <= 0.");
      return json_({ ok: false, handled: true, error: "cc_amount_invalid" });
    }

    // Check duplicate in Account Ledger
    var ledgerSheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.accountLedger);
    if (ledgerSheet) {
      var ledgerHeader = findHeader_(ledgerSheet);
      if (ledgerHeader) {
        var ledgerMap = {};
        ledgerHeader.headers.forEach(function(h, idx) { ledgerMap[canonicalKey_(h)] = idx + 1; });
        var entryIdIdx = ledgerMap.entry_id;
        var linkedTxnIdIdx = ledgerMap.linked_txn_id;
        var ledgerLastRow = ledgerSheet.getLastRow();
        if (ledgerLastRow > ledgerHeader.row) {
          var ledgerRange = ledgerSheet.getRange(ledgerHeader.row + 1, 1, ledgerLastRow - ledgerHeader.row, ledgerHeader.headers.length);
          var ledgerValues = ledgerRange.getValues();
          for (var l = 0; l < ledgerValues.length; l++) {
            var lRow = ledgerValues[l];
            var lEntryId = entryIdIdx ? String(lRow[entryIdIdx - 1]).trim() : '';
            var lLinkedTxnId = linkedTxnIdIdx ? String(lRow[linkedTxnIdIdx - 1]).trim() : '';
            if (lEntryId === targetEntryId || lLinkedTxnId === targetEntryId) {
              sendTelegram_(parsed.chat_id, "⚠️ Transaksi sudah tercatat di Account Ledger dengan ID " + targetEntryId + " tetapi belum ditautkan di Credit Card. Silakan tautkan manual.");
              return json_({ ok: false, handled: true, error: "cc_ledger_duplicate_found", entry_id: targetEntryId });
            }
          }
        }
      }
    }

    // Write to Account Ledger as internal transfer: Blu Pocket -> Blu Pocket CC
    var ledgerCommon = {
      linked_txn_id: targetEntryId,
      rowId: targetEntryId
    };
    var ledgerParsed = {
      amount: amountVal,
      category: 'Transfer',
      description: "Dana CC reserved for: " + displayDesc,
      date: todayDate_()
    };
    var ledgerRawText = "transfer " + amountVal + " dr blu pocket ke blu pocket cc";
    var transferInfo = { sourceAccount: "Blu Pocket", targetAccount: "Blu Pocket CC" };
    var ledgerResult = writeInternalTransferToAccountLedger_(ss, ledgerParsed, ledgerRawText, ledgerCommon, transferInfo);

    if (!ledgerResult || ledgerResult.status !== 'written' || ledgerResult.writeVerified !== true) {
      sendTelegram_(parsed.chat_id, "Gagal memverifikasi penulisan ke Account Ledger. Settle dibatalkan.");
      return json_({ ok: false, handled: true, error: "cc_ledger_write_verification_failed" });
    }

    // Task 9 Step 4 Source verification guard of BOTH rows
    var ledgerSourceRow = ledgerResult.accountLedgerRows ? ledgerResult.accountLedgerRows[0] : null;
    var ledgerTargetRow = ledgerResult.accountLedgerRows ? ledgerResult.accountLedgerRows[1] : null;
    var sourceDetails = getAccountLedgerRowDetails_(ss, ledgerSourceRow);
    var targetDetails = getAccountLedgerRowDetails_(ss, ledgerTargetRow);

    if (!sourceDetails || !targetDetails) {
      sendTelegram_(parsed.chat_id, "⚠️ Verification Warning: Gagal membaca detail baris ledger untuk transfer.");
      return json_({ ok: false, handled: true, error: "cc_ledger_verification_failed_read_details" });
    }

    var vOutAcc = String(sourceDetails.account || '').trim();
    var vOutAmt = Number(sourceDetails.amountOut) || 0;
    var vInAcc = String(targetDetails.account || '').trim();
    var vInAmt = Number(targetDetails.amountIn) || 0;

    var verificationPassed = true;
    var verifError = "";

    if (vOutAcc !== "Blu Pocket") {
      verificationPassed = false;
      verifError = "source_account_mismatch";
    } else if (vOutAmt !== amountVal) {
      verificationPassed = false;
      verifError = "source_amount_mismatch";
    } else if (!vInAcc || vInAcc === "") {
      verificationPassed = false;
      verifError = "destination_account_blank";
    } else if (vInAcc !== "Blu Pocket CC") {
      verificationPassed = false;
      verifError = "destination_account_mismatch";
    } else if (vInAmt !== amountVal) {
      verificationPassed = false;
      verifError = "destination_amount_mismatch";
    }

    if (!verificationPassed) {
      sendTelegram_(parsed.chat_id, "⚠️ WARNING: Ledger verification failed (" + verifError + "). Credit Card status NOT updated.");
      return json_({
        ok: false,
        handled: true,
        error: "cc_ledger_verification_failed",
        reason: verifError,
        source_account: vOutAcc,
        source_amount: vOutAmt,
        destination_account: vInAcc,
        destination_amount: vInAmt
      });
    }

    // Update Credit Card row (only after both ledger rows verified!)
    sheet.getRange(targetRow, statusColIdx).setValue('✅ Sudah');
    if (transferredColIdx) {
      sheet.getRange(targetRow, transferredColIdx).setValue(todayDate_());
    }
    if (linkedTxnIdColIdx) {
      sheet.getRange(targetRow, linkedTxnIdColIdx).setValue(ledgerResult.rowId || targetEntryId);
    }
    if (notesColIdx) {
      var oldNotes = String(sheet.getRange(targetRow, notesColIdx).getValue() || '');
      var newNotes = [oldNotes, 'pocket_blu_settlement: ' + ledgerResult.rowId].filter(Boolean).join(' | ');
      sheet.getRange(targetRow, notesColIdx).setValue(newNotes);
    }

    var successLines = [];
    successLines.push("✅ Dana CC Disisihkan");
    successLines.push("Item: " + displayDesc);
    successLines.push("Amount: " + formatBalanceRupiah_(amountVal));
    successLines.push("Transfer: Blu Pocket → Blu Pocket CC");
    successLines.push("Ledger Row: 📒 Account Ledger:" + ledgerResult.row);

    if (sourceDetails && targetDetails &&
        sourceDetails.balance !== '' && sourceDetails.balance !== null && sourceDetails.balance !== undefined &&
        targetDetails.balance !== '' && targetDetails.balance !== null && targetDetails.balance !== undefined) {
      successLines.push("Saldo Blu Pocket sekarang: " + formatBalanceRupiah_(sourceDetails.balance));
      successLines.push("Saldo Blu Pocket CC sekarang: " + formatBalanceRupiah_(targetDetails.balance));
    }

    sendTelegram_(parsed.chat_id, successLines.join("\n"));

    return json_({
      ok: true,
      handled: true,
      command: "cc sudah " + index,
      write_performed: true,
      account_ledger_write_performed: true,
      cc_status_update_performed: true,
      item: displayDesc,
      amount: amountVal,
      ledger_row: ledgerResult.row
    });

  } catch (err) {
    var errMsg = String(err && err.message ? err.message : err);
    var chatId = null;
    try {
      var parsed = airoSprint7FParseTelegramText_(e);
      chatId = parsed.chat_id;
    } catch (e2) {}

    if (chatId) {
      try {
        sendTelegram_(chatId, "Error executing CC sudah command: " + errMsg);
      } catch (e3) {}
    }

    return json_({
      ok: false,
      handled: true,
      command: "cc sudah command",
      error: errMsg
    });
  }
}

function airoTask9ReadAndRepairMaybeHandleRoute_(e) {
  try {
    var body = JSON.parse(e && e.postData && e.postData.contents ? e.postData.contents : '{}');
    var msg = body.message || {};
    var rawText = String(msg.text || '').trim();
    if (rawText !== "admin task9 read" && rawText !== "admin task9 repair") {
      return null;
    }

    var target = airoTask9OpenConfiguredSpreadsheet_();
    var ss = target.spreadsheet;

    if (rawText === "admin task9 read") {
      var ledgerSheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.accountLedger);
      var ledgerLastRow = ledgerSheet ? ledgerSheet.getLastRow() : 0;
      var row72 = ledgerLastRow >= 72 ? ledgerSheet.getRange(72, 1, 1, 14).getValues()[0] : null;
      var row73 = ledgerLastRow >= 73 ? ledgerSheet.getRange(73, 1, 1, 14).getValues()[0] : null;
      // Also dump last 5 rows for debugging
      var lastFiveStart = Math.max(2, ledgerLastRow - 4);
      var lastFiveRows = ledgerLastRow >= 2 ? ledgerSheet.getRange(lastFiveStart, 1, ledgerLastRow - lastFiveStart + 1, 14).getValues() : [];

      var ccSheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.creditCard || 'Credit Card');
      if (!ccSheet) ccSheet = getSheetLoose_(ss, 'Credit Card');
      var ccHeaders = ccSheet ? findCcHeaderRow_(ccSheet).headers : [];
      var ccMap = ccSheet && ccHeaders.length ? ccColMap_(ccHeaders) : {};
      var ccRows = ccSheet && ccHeaders.length ? ccSheet.getRange(9, 1, Math.max(1, ccSheet.getLastRow() - 8), ccHeaders.length).getValues() : [];
      var ccMatched = null;
      var ccMatchedRowIdx = -1;
      for (var i = 0; i < ccRows.length; i++) {
        var row = ccRows[i];
        var descVal = ccMap.description ? String(row[ccMap.description - 1] || '').trim() : '';
        var amountVal2 = ccMap.amount ? Number(row[ccMap.amount - 1]) || 0 : 0;
        if (descVal === "cc beli 24000") {
          ccMatched = row;
          ccMatchedRowIdx = 9 + i;
          break;
        }
      }

      return json_({
        ok: true,
        ledgerLastRow: ledgerLastRow,
        row72: row72,
        row73: row73,
        lastFiveRows: lastFiveRows,
        lastFiveStart: lastFiveStart,
        ccMatched: ccMatched,
        ccMatchedRowIdx: ccMatchedRowIdx
      });
    }

    if (rawText === "admin task9 repair") {
      var regSheet = ss.getSheetByName("🏦 Account Registry");
      var registryRepaired = false;
      if (regSheet) {
        var regValues = regSheet.getDataRange().getValues();
        var hasCc = false;
        for (var rIdx = 0; rIdx < regValues.length; rIdx++) {
          if (String(regValues[rIdx][2]).trim() === "Blu Pocket CC") {
            hasCc = true;
            break;
          }
        }
        if (!hasCc) {
          regSheet.appendRow(['TRUE', 'blu_pocket_cc', 'Blu Pocket CC', 'Blu', 'bank', 'Blu', 'pocket cc', 'Blu', '#4CD2FF', 'FALSE', 'TRUE', 'FALSE', 'Blu BCA Pocket CC account']);
          registryRepaired = true;
        }
      }

      var ledgerSheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.accountLedger);
      var ledgerLastRow = ledgerSheet ? ledgerSheet.getLastRow() : 0;
      if (!ledgerSheet || ledgerLastRow < 73) {
        return json_({
          ok: true,
          repaired: false,
          registry_repaired: registryRepaired,
          reason: "row73_does_not_exist",
          ledgerLastRow: ledgerLastRow
        });
      }
      var row73Account = String(ledgerSheet.getRange(73, 3).getValue() || '').trim();
      var row73In = Number(ledgerSheet.getRange(73, 4).getValue()) || 0;
      var row73Type = String(ledgerSheet.getRange(73, 7).getValue() || '').trim();
      var row73Desc = String(ledgerSheet.getRange(73, 9).getValue() || '').trim();

      if ((row73Account === "" || row73Account === "null" || row73Account === "undefined") && row73In === 24000 && row73Type === "transfer_in" && row73Desc.indexOf("transfer 24000 dr blu pocket ke blu pocket cc") !== -1) {
        var prevBalance = 0;
        var values = ledgerSheet.getRange(2, 1, 71, 14).getValues();
        for (var idx = values.length - 1; idx >= 0; idx--) {
          var acc = String(values[idx][2] || '').trim();
          var bal = values[idx][5];
          if (acc === "Blu Pocket CC" && bal !== "" && bal !== null && bal !== undefined) {
            prevBalance = Number(bal) || 0;
            break;
          }
        }
        var newBalance = prevBalance + 24000;

        ledgerSheet.getRange(73, 3).setValue("Blu Pocket CC");
        ledgerSheet.getRange(73, 6).setValue(newBalance);

        return json_({
          ok: true,
          repaired: true,
          prevBalance: prevBalance,
          newBalance: newBalance
        });
      } else {
        return json_({
          ok: false,
          repaired: false,
          reason: "guard_mismatch",
          row73Account: row73Account,
          row73In: row73In,
          row73Type: row73Type,
          row73Desc: row73Desc,
          ledgerLastRow: ledgerLastRow
        });
      }
    }
  } catch (err) {
    return json_({ ok: false, error: err.toString() });
  }
}

