function airoSprint7EmailIngestionLogMaybeHandleRoute_(e) {
  var payload = {};
  try {
    payload = JSON.parse(e && e.postData && e.postData.contents ? e.postData.contents : "{}");
  } catch (err) {
    payload = {};
  }

  var message = payload.message || payload.edited_message || payload.channel_post || {};
  var rawText = String(message.text || message.caption || "").trim();
  var text = rawText.toLowerCase();

  if (text !== "admin email sprint7 ingestion log") {
    return null;
  }

  var chatId = message.chat && message.chat.id;
  var contract = airoSprint7EmailIngestionLogContract_();
  var replyText = airoSprint7EmailIngestionLogReplyText_(contract);

  var telegramReplyAttempted = false;
  var telegramReplyDelivered = false;
  var telegramReplyError = "";

  if (chatId && typeof sendTelegram_ === "function") {
    telegramReplyAttempted = true;
    try {
      sendTelegram_(chatId, replyText);
      telegramReplyDelivered = true;
    } catch (sendErr) {
      telegramReplyError = String(sendErr && sendErr.message ? sendErr.message : sendErr);
    }
  }

  if (!telegramReplyDelivered && chatId && typeof airoSprint7GmailLabelFilterSendTelegramReply_ === "function") {
    telegramReplyAttempted = true;
    try {
      airoSprint7GmailLabelFilterSendTelegramReply_(chatId, replyText);
      telegramReplyDelivered = true;
    } catch (fallbackErr) {
      telegramReplyError = telegramReplyError || String(fallbackErr && fallbackErr.message ? fallbackErr.message : fallbackErr);
    }
  }

  return ContentService
    .createTextOutput(JSON.stringify({
      ok: true,
      command: contract.command,
      status: contract.status,
      mode: contract.mode,
      design_only: contract.design_only,
      write_performed: contract.write_performed,
      email_ingestion_enabled: contract.email_ingestion_enabled,
      gmail_read_performed: contract.gmail_read_performed,
      mailbox_read_performed: contract.mailbox_read_performed,
      finance_write_performed: contract.finance_write_performed,
      telegram_reply_attempted: telegramReplyAttempted,
      telegram_reply_delivered: telegramReplyDelivered,
      telegram_reply_error: telegramReplyError
    }))
    .setMimeType(ContentService.MimeType.JSON);
}
