function airoSprint7EExtractSenderEmail_(fromValue) {
  var raw = String(fromValue || "").trim();
  var match = raw.match(/<([^>]+)>/);
  return String(match ? match[1] : raw).trim().toLowerCase();
}

function airoSprint7EProviderForSender_(sender) {
  var s = String(sender || "").toLowerCase();
  if (s === "receipts@blubybcadigital.id") {
    return "Blu";
  }
  if (s === "noreply@tokopedia.com") {
    return "Tokopedia Card";
  }
  return "Unknown";
}

function airoSprint7EIsAllowedSender_(sender, allowedSenders) {
  var s = String(sender || "").toLowerCase();
  for (var i = 0; i < allowedSenders.length; i++) {
    if (s === String(allowedSenders[i]).toLowerCase()) {
      return true;
    }
  }
  return false;
}

function airoSprint7EHasRequiredLabel_(thread, requiredLabel) {
  var labels = thread.getLabels();
  for (var i = 0; i < labels.length; i++) {
    if (String(labels[i].getName()) === String(requiredLabel)) {
      return true;
    }
  }
  return false;
}

function airoSprint7EIsSensitiveSubject_(subject) {
  var text = String(subject || "").toLowerCase();
  var terms = [
    "otp",
    "kode verifikasi",
    "verification code",
    "auth code",
    "password",
    "reset password",
    "login",
    "perangkat baru",
    "security",
    "keamanan",
    "suspicious",
    "kode keamanan",
    "authentication",
    "2fa"
  ];
  for (var i = 0; i < terms.length; i++) {
    if (text.indexOf(String(terms[i]).toLowerCase()) >= 0) {
      return true;
    }
  }
  return false;
}

function airoSprint7EClassifySubjectCandidate_(subject, provider) {
  var s = String(subject || "").toLowerCase();
  var p = String(provider || "");
  var classification = {
    candidate_status: "metadata_candidate",
    parse_status: "metadata_only_candidate",
    candidate_type: "unknown",
    clarification_needed: true,
    block_reason: ""
  };

  if (p === "Blu") {
    if (s.indexOf("masuk") >= 0) {
      classification.candidate_type = "transfer_masuk";
      classification.clarification_needed = false;
    } else if (s.indexOf("bayar otomatis") >= 0 || s.indexOf("transaksimu") >= 0 || s.indexOf("berhasil") >= 0) {
      classification.candidate_type = "blu_transaction";
      classification.clarification_needed = true;
    }
  }

  if (p === "Tokopedia Card") {
    if (s.indexOf("pembayaran tagihan") >= 0 && s.indexOf("berhasil") >= 0) {
      classification.candidate_type = "pembayaran_kartu_kredit";
      classification.clarification_needed = false;
    } else if (s.indexOf("refund") >= 0) {
      classification.candidate_type = "refund";
      classification.clarification_needed = true;
    } else {
      classification.candidate_type = "tokopedia_card_candidate";
      classification.clarification_needed = true;
    }
  }

  return classification;
}

function airoSprint7ERunOneShotReadOnlyPilot_() {
  var mailboxGuard = airoSprint7EAssertTargetMailbox_();
  if (!mailboxGuard.ok) {
    return airoSprint7EBlockedMailboxIdentityResult_(mailboxGuard);
  }


  var contract = airoSprint7EOneShotReadOnlyPilotContract_();
  var runId = "airo-7e-ro-" + Utilities.getUuid();
  var query = 'label:"' + contract.gmail_label_required + '" (from:receipts@blubybcadigital.id OR from:noreply@tokopedia.com)';
  var queryUsed = query;
  var fallbackEnabled = false;
  var threads = GmailApp.search(query, 0, contract.max_threads_per_run);

  if (threads.length === 0) {
    fallbackEnabled = true;
    var fallbackQueries = [
      'category:updates from:receipts@blubybcadigital.id',
      'category:updates from:noreply@tokopedia.com',
      'from:receipts@blubybcadigital.id',
      'from:noreply@tokopedia.com'
    ];
    for (var f = 0; f < fallbackQueries.length; f++) {
      queryUsed = fallbackQueries[f];
      threads = GmailApp.search(queryUsed, 0, contract.max_threads_per_run);
      if (threads.length > 0) {
        break;
      }
    }
  }

  var scannedMessageCount = 0;
  var candidateCount = 0;
  var skippedSensitiveCount = 0;
  var skippedSenderNotAllowedCount = 0;
  var skippedMissingLabelCount = 0;
  var clarificationNeededCount = 0;
  var dryRunRouteCount = 0;
  var candidates = [];

  for (var t = 0; t < threads.length; t++) {
    var thread = threads[t];
    var hasLabel = fallbackEnabled || airoSprint7EHasRequiredLabel_(thread, contract.gmail_label_required);
    var messages = thread.getMessages();

    for (var m = 0; m < messages.length; m++) {
      if (scannedMessageCount >= contract.max_messages_per_run) {
        break;
      }

      var message = messages[m];
      var sender = airoSprint7EExtractSenderEmail_(message.getFrom());
      var subject = String(message.getSubject() || "");
      var provider = airoSprint7EProviderForSender_(sender);

      if (!hasLabel) {
        skippedMissingLabelCount++;
        continue;
      }

      if (!airoSprint7EIsAllowedSender_(sender, contract.allowed_senders)) {
        skippedSenderNotAllowedCount++;
        continue;
      }

      scannedMessageCount++;

      if (airoSprint7EIsSensitiveSubject_(subject)) {
        skippedSensitiveCount++;
        continue;
      }

      var classification = airoSprint7EClassifySubjectCandidate_(subject, provider);
      if (classification.clarification_needed) {
        clarificationNeededCount++;
      }
      dryRunRouteCount++;
      candidateCount++;

      candidates.push({
        message_id: typeof message.getId === "function" ? message.getId() : "",
        thread_id: typeof thread.getId === "function" ? thread.getId() : "",
        sender: sender,
        provider: provider,
        subject: subject,
        date: Utilities.formatDate(message.getDate(), Session.getScriptTimeZone(), "yyyy-MM-dd'T'HH:mm:ssXXX"),
        candidate_status: classification.candidate_status,
        parse_status: classification.parse_status,
        candidate_type: classification.candidate_type,
        clarification_needed: classification.clarification_needed,
        dry_run_only: true,
        write_allowed: false,
        write_performed: false
      });
    }

    if (scannedMessageCount >= contract.max_messages_per_run) {
      break;
    }
  }

  return {
    ok: true,
    run_id: runId,
    command: contract.command,
    mode: contract.mode,
    status: "one_shot_read_only_pilot_completed",
    gmail_label: contract.gmail_label_required,
    source_query_used: queryUsed,
    source_query_fallback_enabled: fallbackEnabled,
    max_messages: contract.max_messages_per_run,
    max_threads: contract.max_threads_per_run,
    allowed_sender_count: contract.allowed_sender_count,
    source_count: contract.source_count,
    scanned_thread_count: threads.length,
    scanned_message_count: scannedMessageCount,
    candidate_count: candidateCount,
    skipped_sensitive_count: skippedSensitiveCount,
    skipped_sender_not_allowed_count: skippedSenderNotAllowedCount,
    skipped_missing_label_count: skippedMissingLabelCount,
    clarification_needed_count: clarificationNeededCount,
    dry_run_route_count: dryRunRouteCount,
    candidates: candidates,
    gmail_pilot_enabled: true,
    gmail_live_read_performed: true,
    mailbox_read_performed: true,
    mail_trigger_created: false,
    email_modified: false,
    full_email_body_stored: false,
    sensitive_content_stored: false,
    raw_email_forwarded_to_telegram: false,
    finance_write_performed: false,
    account_ledger_write_performed: false,
    finance_events_write_performed: false,
    review_queue_write_performed: false,
    domain_tab_write_performed: false
  };
}

function airoSprint7EOneShotPilotReplyText_(result) {
  result = result || {};
  var candidates = Array.isArray(result.candidates) ? result.candidates : [];

  var lines = [];
  lines.push("✅ Sprint 7E One-Shot Read-Only Gmail Pilot");
  lines.push("");
  lines.push("Command: " + String(result.command || "admin email sprint7e one shot read only pilot"));
  lines.push("Mode: " + String(result.mode || "read_only_dry_run"));
  lines.push("Status: " + String(result.status || "unknown"));
  lines.push("Run ID: " + String(result.run_id || "-"));
  lines.push("Gmail label: " + String(result.gmail_label || "Info Terbaru"));
  lines.push("Source query used: " + String(result.source_query_used || "-"));
  lines.push("Fallback enabled: " + String(!!result.source_query_fallback_enabled));
  lines.push("Max messages: " + String(result.max_messages || 5));
  lines.push("Allowed sender count: " + String(result.allowed_sender_count || 0));
  lines.push("");

  if (result.reason) {
    lines.push("Blocked / Reason:");
    lines.push(String(result.reason));
    lines.push("");
  }

  if (result.target_gmail_account || result.active_user_email || result.effective_user_email) {
    lines.push("Mailbox Identity:");
    lines.push("- Target: " + String(result.target_gmail_account || "-"));
    lines.push("- Active user: " + String(result.active_user_email || "-"));
    lines.push("- Effective user: " + String(result.effective_user_email || "-"));
    lines.push("- Active matches target: " + String(!!result.active_matches_target));
    lines.push("- Effective matches target: " + String(!!result.effective_matches_target));
    lines.push("");
  }

  lines.push("Counts:");
  lines.push("- Scanned threads: " + String(result.scanned_thread_count || 0));
  lines.push("- Scanned messages: " + String(result.scanned_message_count || 0));
  lines.push("- Candidates: " + String(result.candidate_count || 0));
  lines.push("- Candidates listed: " + String(candidates.length));
  lines.push("- Clarification needed: " + String(result.clarification_needed_count || 0));
  lines.push("- Sensitive skipped: " + String(result.skipped_sensitive_count || 0));
  lines.push("- Sender not allowed skipped: " + String(result.skipped_sender_not_allowed_count || 0));
  lines.push("- Missing label skipped: " + String(result.skipped_missing_label_count || 0));
  lines.push("- Dry-run routes: " + String(result.dry_run_route_count || 0));
  lines.push("");

  lines.push("Safety:");
  lines.push("- Gmail read performed: " + String(!!result.gmail_live_read_performed || !!result.gmail_read_performed));
  lines.push("- Mailbox read performed: " + String(!!result.mailbox_read_performed));
  lines.push("- Mail trigger created: " + String(!!result.mail_trigger_created));
  lines.push("- Email modified: " + String(!!result.email_modified));
  lines.push("- Full email body stored: " + String(!!result.full_email_body_stored));
  lines.push("- Sensitive content stored: " + String(!!result.sensitive_content_stored));
  lines.push("- Raw email forwarded to Telegram: " + String(!!result.raw_email_forwarded_to_telegram));
  lines.push("- Finance write performed: " + String(!!result.finance_write_performed));
  lines.push("- Account Ledger write performed: " + String(!!result.account_ledger_write_performed));
  lines.push("- Finance Events write performed: " + String(!!result.finance_events_write_performed));
  lines.push("- Review Queue write performed: " + String(!!result.review_queue_write_performed));
  lines.push("- Domain tab write performed: " + String(!!result.domain_tab_write_performed));

  if (candidates.length > 0) {
    lines.push("");
    lines.push("Candidates metadata:");
    for (var i = 0; i < candidates.length && i < 5; i++) {
      var c = candidates[i] || {};
      lines.push(String(i + 1) + ". " + String(c.provider || "Unknown") + " | " + String(c.sender || "-"));
      lines.push("   Subject: " + String(c.subject || "-"));
      lines.push("   Type: " + String(c.candidate_type || "-"));
      lines.push("   Clarification needed: " + String(!!c.clarification_needed));
      lines.push("   Write performed: false");
    }
  }

  return lines.join("\n");
}


function airoSprint7EOneShotReadOnlyPilotMaybeHandleRoute_(e) {
  var payload = {};
  try {
    payload = JSON.parse(e && e.postData && e.postData.contents ? e.postData.contents : "{}");
  } catch (err) {
    payload = {};
  }

  var message = payload.message || payload.edited_message || payload.channel_post || {};
  var rawText = String(message.text || message.caption || "").trim();
  var text = rawText.toLowerCase();

  if (text !== "admin email sprint7e one shot read only pilot") {
    return null;
  }

  var chatId = message.chat && message.chat.id;
  var result = airoSprint7ERunOneShotReadOnlyPilot_();
  var replyText = airoSprint7EOneShotPilotReplyText_(result);
  var telegramReplyAttempted = false;
  var telegramReplyDelivered = false;
  var telegramReplyError = "";

  if (chatId && typeof sendTelegram_ === "function") {
    telegramReplyAttempted = true;
    try {
      sendTelegram_(chatId, replyText);
      telegramReplyDelivered = true;
    } catch (sendErr) {
      telegramReplyError = String(sendErr && sendErr.message ? sendErr.message : sendErr);
    }
  }

  result.telegram_reply_attempted = telegramReplyAttempted;
  result.telegram_reply_delivered = telegramReplyDelivered;
  result.telegram_reply_error = telegramReplyError;

  return ContentService
    .createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}
