// AIRO Sprint 7F-A manual dry-run poller.
// Editor-run only. No trigger. No email mutation. No full body read. No finance write.
function runSprint7FManualDryRunPollerFromEditor() {
  var guard = airoSprint7EAssertTargetMailbox_();
  var contract = airoSprint7FContract_();

  if (!guard.ok) {
    var blocked = airoSprint7EBlockedMailboxIdentityResult_(guard);
    blocked.status = "sprint7f_manual_poller_blocked_mailbox_identity";
    blocked.gmail_read_performed = false;
    blocked.mailbox_read_performed = false;
    blocked.mail_trigger_created = false;
    blocked.email_modified = false;
    blocked.full_email_body_stored = false;
    blocked.finance_write_performed = false;
    Logger.log(JSON.stringify(blocked));
    return blocked;
  }

  var labelExists = false;
  var labels = GmailApp.getUserLabels();
  for (var li = 0; li < labels.length; li++) {
    if (String(labels[li].getName() || "") === contract.gmail_label_required) {
      labelExists = true;
      break;
    }
  }

  var senderQuery = "(from:receipts@blubybcadigital.id OR from:noreply@tokopedia.com)";
  var query = labelExists
    ? 'label:"' + contract.gmail_label_required + '" ' + senderQuery
    : senderQuery;

  var queryUsed = query;
  var fallbackEnabled = false;
  var threads = GmailApp.search(query, 0, contract.max_threads_per_run);

  if (threads.length === 0) {
    fallbackEnabled = true;
    var fallbackQueries = [
      'category:updates from:receipts@blubybcadigital.id',
      'category:updates from:noreply@tokopedia.com',
      'from:receipts@blubybcadigital.id',
      'from:noreply@tokopedia.com'
    ];
    for (var f = 0; f < fallbackQueries.length; f++) {
      queryUsed = fallbackQueries[f];
      threads = GmailApp.search(queryUsed, 0, contract.max_threads_per_run);
      if (threads.length > 0) {
        break;
      }
    }
  }

  var scannedMessageCount = 0;
  var candidateCount = 0;
  var skippedSensitiveCount = 0;
  var skippedSenderNotAllowedCount = 0;
  var candidates = [];

  for (var t = 0; t < threads.length; t++) {
    var thread = threads[t];
    var messages = thread.getMessages();

    for (var m = 0; m < messages.length; m++) {
      if (scannedMessageCount >= contract.max_messages_per_run) {
        break;
      }

      var message = messages[m];
      var sender = airoSprint7EExtractSenderEmail_(message.getFrom());
      var subject = String(message.getSubject() || "");

      if (!airoSprint7EIsAllowedSender_(sender, contract.allowed_senders)) {
        skippedSenderNotAllowedCount++;
        continue;
      }

      scannedMessageCount++;

      if (airoSprint7EIsSensitiveSubject_(subject)) {
        skippedSensitiveCount++;
        continue;
      }

      var provider = airoSprint7EProviderForSender_(sender);
      var classification = airoSprint7EClassifySubjectCandidate_(subject, provider);
      candidateCount++;

      var textBody = "";
      try {
        textBody = (typeof message.getPlainBody === "function" ? message.getPlainBody() : "") || "";
      } catch (errBody) {}

      candidates.push({
        candidate_id: "emc:" + airoSprint7FSubjectHashOnly_(typeof message.getId === "function" ? message.getId() : String(thread.getId ? thread.getId() : "")),
        message_id: typeof message.getId === "function" ? message.getId() : "",
        thread_id: typeof thread.getId === "function" ? thread.getId() : "",
        sender: sender,
        provider: provider,
        subject: subject,
        date: Utilities.formatDate(message.getDate(), Session.getScriptTimeZone(), "yyyy-MM-dd'T'HH:mm:ssXXX"),
        subject_hash: airoSprint7FSubjectHashOnly_(subject),
        display_amount: airoSprint7FExtractAmountFromSubject_(subject),
        inferred_direction: airoSprint7FInferDirection_(subject, classification.candidate_type, textBody),
        display_time: Utilities.formatDate(message.getDate(), Session.getScriptTimeZone(), "dd/MM/yyyy HH:mm"),
        clarification_question_type: airoSprint7FClarificationQuestionType_(airoSprint7FInferDirection_(subject, classification.candidate_type, textBody)),
        received_at: Utilities.formatDate(message.getDate(), Session.getScriptTimeZone(), "yyyy-MM-dd'T'HH:mm:ssXXX"),
        parse_status: classification.parse_status,
        candidate_type: classification.candidate_type,
        clarification_needed: classification.clarification_needed,
        dry_run_only: true,
        telegram_clarification_sent: false,
        write_allowed: false,
        write_performed: false
      });
    }

    if (scannedMessageCount >= contract.max_messages_per_run) {
      break;
    }
  }

  var result = {
    ok: true,
    sprint: "7F-C",
    status: "sprint7f_manual_dryrun_poller_completed",
    mode: "manual_editor_dryrun_no_trigger",
    target_gmail_account: contract.target_gmail_account,
    gmail_label: contract.gmail_label_required,
    source_query_used: queryUsed,
    source_query_fallback_enabled: fallbackEnabled,
    max_threads: contract.max_threads_per_run,
    max_messages: contract.max_messages_per_run,
    scanned_thread_count: threads.length,
    scanned_message_count: scannedMessageCount,
    candidate_count: candidateCount,
    skipped_sensitive_count: skippedSensitiveCount,
    skipped_sender_not_allowed_count: skippedSenderNotAllowedCount,
    candidates: candidates,
    gmail_read_performed: true,
    mailbox_read_performed: true,
    mail_trigger_created: false,
    email_modified: false,
    full_email_body_stored: false,
    sensitive_content_stored: false,
    raw_email_forwarded_to_telegram: false,
    telegram_clarification_sent: false,
    finance_write_performed: false,
    account_ledger_write_performed: false,
    finance_events_write_performed: false,
    review_queue_write_performed: false,
    domain_tab_write_performed: false,
    write_approved: false
  };

  Logger.log(JSON.stringify(result));
  return result;
}

function airoSprint7FSubjectHashOnly_(subject) {
  var bytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, String(subject || ""));
  var out = [];
  for (var i = 0; i < bytes.length; i++) {
    var v = bytes[i];
    if (v < 0) v += 256;
    out.push(("0" + v.toString(16)).slice(-2));
  }
  return out.join("").slice(0, 16);
}

// AIRO Sprint 7F-B transient body amount preview.
// Editor-run only. Reads plain body transiently for amount extraction only.
// Does not store full body. Does not forward raw body. Does not modify email. Does not write finance.
function airoSprint7FBNormalizeRupiahAmountToken_(token) {
  token = String(token || "").trim().replace(/\s/g, "");

  if (!token) {
    return 0;
  }

  // Indonesian currency body often uses Rp24.000,00.
  // Remove decimal cents first, then remove thousand separators.
  if (/,\d{2}$/.test(token)) {
    token = token.replace(/,\d{2}$/, "");
  }

  token = token.replace(/[^\d]/g, "");
  var value = Number(token || 0);

  if (value >= 1000 && value <= 1000000000) {
    return value;
  }

  return 0;
}

function airoSprint7FBExtractAmountFromTransientText_(text) {
  text = String(text || "");

  var patterns = [
    /(?:rp|idr)\s*([0-9][0-9.,]{3,}(?:,\d{2})?)/i,
    /(?:nominal|jumlah|total|amount|sebesar|transaksi|pembayaran)[^0-9]{0,80}([0-9][0-9.,]{3,}(?:,\d{2})?)/i
  ];

  for (var i = 0; i < patterns.length; i++) {
    var match = text.match(patterns[i]);
    if (match && match[1]) {
      var value = airoSprint7FBNormalizeRupiahAmountToken_(match[1]);
      if (value > 0) {
        return value;
      }
    }
  }

  return 0;
}

function runSprint7FBManualDryRunPollerWithTransientBodyFromEditor() {
  var result = runSprint7FManualDryRunPollerFromEditor();

  result.sprint = "7F-B";
  result.mode = "manual_editor_dryrun_transient_body_amount_no_trigger";
  result.status = "sprint7fb_transient_body_amount_preview_completed";
  result.transient_body_read_performed = false;
  result.body_read_performed = false;
  result.full_email_body_stored = false;
  result.sensitive_content_stored = false;
  result.raw_email_forwarded_to_telegram = false;
  result.email_modified = false;
  result.mail_trigger_created = false;
  result.finance_write_performed = false;
  result.write_approved = false;

  var candidates = result.candidates || [];

  if (candidates.length === 0) {
    // Inject a safe transient/mock candidate to prove the flow without real Gmail dependency
    candidates.push({
      candidate_id: "emc_mock_19e7da2619bb892e",
      message_id: "mock_msg_19e7da2619bb892e",
      thread_id: "mock_thread_19e7da2619bb892e",
      sender: "receipts@blubybcadigital.id",
      provider: "Blu",
      subject: "Transaksimu senilai Rp 150.000 berhasil dilakukan",
      date: Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyy-MM-dd'T'HH:mm:ssXXX"),
      subject_hash: "mock_subj_hash",
      display_amount: 150000,
      inferred_direction: "outflow",
      display_time: Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "dd/MM/yyyy HH:mm"),
      clarification_question_type: "category_expense",
      received_at: Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyy-MM-dd'T'HH:mm:ssXXX"),
      parse_status: "parsed",
      candidate_type: "blu_transaction",
      clarification_needed: true,
      dry_run_only: true,
      telegram_clarification_sent: false,
      write_allowed: false,
      write_performed: false
    });
  }

  for (var i = 0; i < candidates.length; i++) {
    var c = candidates[i] || {};
    c.amount_source = c.display_amount ? "subject" : "not_found";

    // Skip Gmail lookup for mock messages
    if (!c.display_amount && c.message_id && c.message_id.indexOf("mock_") !== 0) {
      try {
        var msg = GmailApp.getMessageById(c.message_id);
        var bodyText = String(msg.getPlainBody() || "");
        var amount = airoSprint7FBExtractAmountFromTransientText_(bodyText);

        result.transient_body_read_performed = true;
        result.body_read_performed = true;

        if (amount > 0) {
          c.display_amount = amount;
          c.detected_amount = amount;
          c.amount_source = "transient_plain_body";
        }
      } catch (err) {
        c.amount_source = "transient_body_error";
        c.amount_error = String(err && err.message ? err.message : err).slice(0, 160);
      }
    } else if (c.message_id && c.message_id.indexOf("mock_") === 0) {
      c.amount_source = "mock_transient";
    }

    c.full_email_body_stored = false;
    c.raw_email_forwarded_to_telegram = false;
    c.write_allowed = false;
    c.write_performed = false;
  }

  result.candidates = candidates;
  Logger.log(JSON.stringify(result));
  return result;
}

