function airoSprint7FSpreadsheet_() {
  var spreadsheetId = "";
  try {
    spreadsheetId = getProp_("SPREADSHEET_ID");
  } catch (err1) {
    spreadsheetId = "";
  }

  if (!spreadsheetId) {
    try {
      spreadsheetId = PropertiesService.getScriptProperties().getProperty("SPREADSHEET_ID") || "";
    } catch (err2) {
      spreadsheetId = "";
    }
  }

  if (spreadsheetId) {
    return SpreadsheetApp.openById(spreadsheetId);
  }

  return SpreadsheetApp.getActiveSpreadsheet();
}

function airoSprint7FEnsureEmailLogSheet_() {
  var ss = airoSprint7FSpreadsheet_();
  if (!ss) {
    throw new Error("Spreadsheet not available for Sprint 7F-A email log.");
  }

  var name = airoSprint7FEmailLogSheetName_();
  var sheet = ss.getSheetByName(name);

  if (!sheet) {
    sheet = ss.insertSheet(name);
  }

  var headers = airoSprint7FEmailLogHeaders_();
  var existingLastColumn = Math.max(sheet.getLastColumn(), headers.length);

  if (sheet.getLastRow() < 1) {
    sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
    sheet.setFrozenRows(1);
  } else {
    var existing = sheet.getRange(1, 1, 1, existingLastColumn).getValues()[0];
    var needsHeader = false;

    for (var i = 0; i < headers.length; i++) {
      if (String(existing[i] || "") !== headers[i]) {
        needsHeader = true;
        break;
      }
    }

    if (needsHeader) {
      sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
      sheet.setFrozenRows(1);
    }
  }

  return sheet;
}

function airoSprint7FFindLoggedCandidateByMessageId_(sheet, messageId) {
  messageId = String(messageId || "").trim();
  if (!messageId || sheet.getLastRow() < 2) {
    return null;
  }

  var headers = airoSprint7FEmailLogHeaders_();
  var values = sheet.getRange(2, 1, sheet.getLastRow() - 1, headers.length).getValues();
  var messageCol = headers.indexOf("message_id");
  var candidateCol = headers.indexOf("candidate_id");
  var statusCol = headers.indexOf("clarification_status");

  for (var i = 0; i < values.length; i++) {
    if (String(values[i][messageCol] || "").trim() === messageId) {
      return {
        row_number: i + 2,
        candidate_id: String(values[i][candidateCol] || ""),
        clarification_status: String(values[i][statusCol] || "")
      };
    }
  }

  return null;
}

function airoSprint7FLogPendingCandidate_(candidate, chatId) {
  var sheet = airoSprint7FEnsureEmailLogSheet_();
  var existing = airoSprint7FFindLoggedCandidateByMessageId_(sheet, candidate.message_id);

  if (existing) {
    return {
      logged: false,
      dedupe_hit: true,
      row_number: existing.row_number,
      candidate_id: existing.candidate_id,
      clarification_status: existing.clarification_status
    };
  }

  var headers = airoSprint7FEmailLogHeaders_();
  var now = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyy-MM-dd'T'HH:mm:ssXXX");

  var rowObj = {
    created_at: now,
    candidate_id: candidate.candidate_id || "",
    message_id: candidate.message_id || "",
    thread_id: candidate.thread_id || "",
    sender: candidate.sender || "",
    provider: candidate.provider || "",
    received_at: candidate.received_at || "",
    subject_hash: candidate.subject_hash || "",
    display_amount: String(candidate.display_amount || ""),
    inferred_direction: candidate.inferred_direction || "",
    display_time: candidate.display_time || "",
    clarification_question_type: candidate.clarification_question_type || "",
    parse_status: candidate.parse_status || "",
    candidate_type: candidate.candidate_type || "",
    clarification_needed: String(!!candidate.clarification_needed),
    clarification_status: "pending",
    telegram_chat_id: String(chatId || ""),
    telegram_sent: "true",
    write_allowed: "false",
    write_performed: "false",
    finance_event_ref: "",
    notes: "Sprint 7F-A metadata-only pending candidate"
  };

  var row = [];
  for (var i = 0; i < headers.length; i++) {
    row.push(rowObj[headers[i]] || "");
  }

  sheet.appendRow(row);

  return {
    logged: true,
    dedupe_hit: false,
    row_number: sheet.getLastRow(),
    candidate_id: candidate.candidate_id || "",
    clarification_status: "pending"
  };
}


// AIRO Sprint 7F-D amount preservation helper.
// Keeps transient parsed amount in pending pointer only; does not store email body.
function airoSprint7FDStableCandidateAmount_(candidate, logResult) {
  candidate = candidate || {};
  logResult = logResult || {};

  var amount =
    candidate.display_amount ||
    candidate.detected_amount ||
    candidate.amount_idr ||
    candidate.amount ||
    logResult.display_amount ||
    logResult.detected_amount ||
    logResult.amount_idr ||
    logResult.amount ||
    0;

  var normalized = Number(String(amount).replace(/[^\d]/g, ""));
  return normalized > 0 ? normalized : 0;
}

