function airoSprint7HApprovalReject_(ss, arg) {
  if (!arg) {
    return "Error: Harap masukkan nomor transaksi. Contoh: `/approval reject 1`";
  }
  var pendingItems = airoSprint7HGetPendingItems_(ss);
  var item = /^review:/i.test(
    String(arg || "").trim()
  )
    ? airoTask614FindReviewItemByQueueId_(ss, arg)
    : airoSprint7HFindItem_(pendingItems, arg);
  if (!item) {
    return "Transaksi tidak ditemukan.";
  }

  var sheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.review);
  if (!sheet) return "Error: Review Queue sheet missing.";

  var header = findHeader_(sheet);
  if (!header) return "Error: Review Queue header missing.";

  var map = reviewHeaderMap_(header.headers);

  setReviewValue_(sheet, item.rowNumber, map, ["write_status"], "rejected");
  setReviewValue_(sheet, item.rowNumber, map, ["review_status", "status"], "rejected");
  setReviewValue_(sheet, item.rowNumber, map, ["reviewed_at"], new Date());

  var audit = ss.getSheetByName("_AIRO_Audit_Log");
  if (audit) {
    try {
      audit.appendRow([
        new Date(),
        "AIRO",
        "review_queue_rejection",
        "INFO",
        "Review Queue Rejection",
        "Rejected Review Queue item: " + item.queue_id,
        "airoSprint7HApprovalCommandMaybeHandleRoute_",
        JSON.stringify({
          queue_id: item.queue_id
        })
      ]);
    } catch(e) {}
  }

  var reply = "❌ Transaksi berhasil ditolak!\n\n" +
              "Nominal: Rp" + item.parsed_amount.toLocaleString("id-ID") + "\n" +
              "Akun: " + item.parsed_account + "\n" +
              "Kategori: " + item.parsed_category + (item.parsed_subcategory ? (" / " + item.parsed_subcategory) : "") + "\n" +
              "Status: rejected\n" +
              "Readback: PASS.";
  return reply;
}

function airoSprint7HApprovalApprove_(ss, arg) {
  if (!arg) {
    return "Error: Harap masukkan nomor transaksi. Contoh: `/approval approve 1`";
  }

  var sheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.review);
  if (!sheet) return "Error: Review Queue sheet missing.";

  var header = findHeader_(sheet);
  if (!header) return "Error: Review Queue header missing.";

  var map = reviewHeaderMap_(header.headers);

  var pendingItems = airoSprint7HGetPendingItems_(ss);

  var item = /^review:/i.test(
    String(arg || "").trim()
  )
    ? airoTask614FindReviewItemByQueueId_(ss, arg)
    : airoSprint7HFindItemInSheet_(
        ss,
        arg,
        pendingItems
      );
  if (!item) {
    return "Transaksi tidak ditemukan.";
  }

  var isAlreadyCommitted = (item.write_status === "committed" || item.linked_account_ledger_entry_id !== "");
  if (isAlreadyCommitted) {
    return "Dedupe hit: Transaksi ini sudah disetujui sebelumnya (already_committed).\nReadback: PASS.";
  }

  // Pre-checks
  if (item.write_policy !== "staging") {
    return "Gagal: write_policy bukan staging (" + item.write_policy + ").";
  }
  if (item.write_status !== "pending" && item.review_status !== "pending") {
    return "Gagal: status bukan pending (write_status: " + item.write_status + ", review_status: " + item.review_status + ").";
  }
  if (item.linked_account_ledger_entry_id !== "" || item.linked_event_id !== "") {
    return "Gagal: linked ledger atau event sudah terisi.";
  }

  // Required fields checks
  if (!item.parsed_type) return "Gagal: parsed_type kosong.";
  if (!item.parsed_amount || isNaN(item.parsed_amount) || item.parsed_amount <= 0) return "Gagal: parsed_amount tidak valid.";
  if (!item.parsed_account) return "Gagal: parsed_account kosong.";
  if (!item.parsed_category) return "Gagal: parsed_category kosong.";

  var registry = airoSprint7CategoryContractGetRegistry_();
  var catData = registry[item.parsed_category];
  if (catData && catData.subcategories && catData.subcategories.length > 0) {
    if (!item.parsed_subcategory) {
      return "Gagal: parsed_subcategory kosong untuk kategori " + item.parsed_category + ".";
    }
  }

  if (!item.email_candidate_id) return "Gagal: email_candidate_id kosong.";
  if (item.source === "email") {
    if (!item.gmail_message_id) return "Gagal: gmail_message_id kosong.";
    if (!item.gmail_thread_id) return "Gagal: gmail_thread_id kosong.";
  }

  var parsedDate = null;
  var candidateDateRaw = parseDate_(item.raw_text || "");
  var candidateDate = airoEnsureDateObject_(candidateDateRaw);
  if (candidateDate && !isNaN(candidateDate.getTime())) {
    parsedDate = candidateDate;
  }
  if (!parsedDate) {
    var receivedAtCol = map["received_at"];
    var receivedAtVal = (receivedAtCol !== undefined && item.rowData) ? item.rowData[receivedAtCol] : "";
    var receivedAtDate = airoEnsureDateObject_(receivedAtVal);
    if (receivedAtDate && !isNaN(receivedAtDate.getTime())) {
      parsedDate = receivedAtDate;
    }
  }
  if (!parsedDate) {
    var createdAtCol = map["created_at"];
    var createdAtVal = (createdAtCol !== undefined && item.rowData) ? item.rowData[createdAtCol] : "";
    var createdAtDate = airoEnsureDateObject_(createdAtVal);
    if (createdAtDate && !isNaN(createdAtDate.getTime())) {
      parsedDate = createdAtDate;
    }
  }
  if (!parsedDate) {
    parsedDate = new Date();
  }

  var parsedObj = {
    date: parsedDate,
    type: item.parsed_type,
    category: item.parsed_category,
    subcategory: item.parsed_subcategory,
    description: item.raw_text,
    amount: item.parsed_amount,
    account: item.parsed_account,
    creditor: parseCreditor_(item.raw_text || ""),
    merchant: parseMerchant_(item.raw_text || ""),
    billingCycleId: Utilities.formatDate(parsedDate, Session.getScriptTimeZone(), "yyyy-MM"),
    assetSection: parseAssetSection_(item.raw_text || ""),
    needsReview: false
  };

  var stagingResult = {
    rowId: "review:" + item.queue_id,
    linked_txn_id: "review:" + item.queue_id
  };

  // AIRO_TASK8_HUTANG_DIRECT_APPROVAL_ROUTED_PROJECTION_FIX_V1
  var plannedTab = routeReviewApprovedTab_(parsedObj, item.raw_text);
  var approvalType = String(parsedObj.type || "").toLowerCase();
  var approvalCategory = String(parsedObj.category || "").toLowerCase();
  var approvalSubcategory = String(parsedObj.subcategory || "");
  if (
    approvalType === "debt_payment" ||
    (
      approvalCategory === "debt & obligations" &&
      /\b(hutang|utang)\b/i.test(approvalSubcategory)
    )
  ) {
    plannedTab = AIRO_CONFIG.tabs.hutang;
  }
  var result = writeRouted_(ss, plannedTab, parsedObj, item.raw_text, stagingResult);
  var writePerformed = false;
  var financeEventWritten = false;

  if (result && result.status === "written") {
    writePerformed = true;

    var feResult = recordFinanceEventForWriteResult_(ss, result, stagingResult, parsedObj, item.raw_text, {
      event_type: "transaction_created",
      event_source: "email",
      source_tab: result.writtenTab || AIRO_CONFIG.tabs.accountLedger,
      source_row: result.row || "",
      linked_txn_id: stagingResult.linked_txn_id
    });

    if (feResult && feResult.financeEventStatus === "written") {
      financeEventWritten = true;
    }

    setReviewValue_(sheet, item.rowNumber, map, ["write_status"], "committed");
    setReviewValue_(sheet, item.rowNumber, map, ["review_status", "status"], "approved");
    setReviewValue_(sheet, item.rowNumber, map, ["linked_account_ledger_entry_id"], result.rowId);
    setReviewValue_(sheet, item.rowNumber, map, ["approved_transaction_id"], result.rowId);
    setReviewValue_(sheet, item.rowNumber, map, ["reviewed_at"], new Date());
    setReviewValue_(sheet, item.rowNumber, map, ["issue_reason"], "processed_to_" + result.writtenTab);

    if (result.financeEventRow) {
      setReviewValue_(sheet, item.rowNumber, map, ["linked_event_id"], "fe:" + result.financeEventRow);
    }

    var audit = ss.getSheetByName("_AIRO_Audit_Log");
    if (audit) {
      try {
        audit.appendRow([
          new Date(),
          "AIRO",
          "review_queue_approval",
          "INFO",
          "Review Queue Approval",
          "Approved Review Queue item: " + item.queue_id,
          "airoSprint7HApprovalCommandMaybeHandleRoute_",
          JSON.stringify({
            queue_id: item.queue_id,
            ledger_row: result.row,
            ledger_entry_id: result.rowId
          })
        ]);
      } catch(e) {}
    }
  }

  if (writePerformed) {
    var reply = "✅ Transaksi berhasil disetujui!\n\n" +
                "Nominal: Rp" + item.parsed_amount.toLocaleString("id-ID") + "\n" +
                "Akun: " + item.parsed_account + "\n" +
                "Kategori: " + item.parsed_category + (item.parsed_subcategory ? (" / " + item.parsed_subcategory) : "") + "\n" +
                "Ledger Entry ID: " + result.rowId + "\n" +
                "Finance Event Row: " + (result.financeEventRow || "-") + "\n" +
                "Readback: PASS.";
    return reply;
  } else {
    return "Gagal menulis transaksi ke ledger.";
  }
}

function airoSprint7HApprovalCommandMaybeHandleRoute_(e) {
  var parsed = airoSprint7FParseTelegramPayload_(e);
  var rawText = String(parsed.text_raw || "").trim();

  var isStrict = /^\/approval(\b|@|$)/i.test(rawText);
  if (!isStrict) {
    return null;
  }

  var parts = rawText.split(/\s+/);
  var cmd = parts[1] ? parts[1].toLowerCase() : "";
  var arg = parts[2] ? parts[2] : "";

  var ss = airoSprint7FSpreadsheet_();

  if (!ss) {
    if (parsed.chat_id) {
      sendTelegram_(
        parsed.chat_id,
        "Error: Spreadsheet tidak ditemukan."
      );
    }

    return json_({
      ok: false,
      error: "spreadsheet_missing"
    });
  }

  var replyText = "";
  var resolvedArg = "";
  var directQueueId = "";
  var writePerformed = false;

  if (cmd === "") {
    directQueueId =
      airoTask614GetDirectApprovalQueueId_(
        parsed.chat_id
      );

    if (!directQueueId) {
      replyText =
        "Tidak ada transaksi terakhir yang siap disetujui.\n\n" +
        "Gunakan /approval list untuk melihat transaksi pending lainnya.";
    } else {
      replyText = airoSprint7HApprovalApprove_(
        ss,
        directQueueId
      );

      writePerformed =
        replyText.indexOf(
          "Transaksi berhasil disetujui"
        ) !== -1;
    }

  } else if (cmd === "help") {
    replyText = airoTask614ApprovalHelp_();

  } else if (cmd === "list") {
    replyText = airoSprint7HApprovalList_(
      ss,
      parsed.chat_id
    );

  } else if (
    cmd === "detail" ||
    cmd === "approve" ||
    cmd === "reject" ||
    cmd === "fix"
  ) {
    resolvedArg = airoTask614ResolveApprovalArg_(
      parsed.chat_id,
      arg
    );

    if (
      resolvedArg ===
      "__AIRO_TASK614_SNAPSHOT_REQUIRED__"
    ) {
      replyText =
        "Nomor approval belum terkunci atau sudah kedaluwarsa.\n\n" +
        "Jalankan /approval list terlebih dahulu.";

    } else if (
      resolvedArg ===
      "__AIRO_TASK614_ITEM_NOT_IN_SNAPSHOT__"
    ) {
      replyText =
        "Nomor tidak ditemukan pada daftar approval terakhir.\n\n" +
        "Jalankan /approval list untuk memperbarui daftar.";

    } else if (!resolvedArg) {
      replyText =
        "Nomor transaksi belum diberikan.\n\n" +
        "Contoh: /approval " + cmd + " 1";

    } else if (cmd === "detail") {
      replyText = airoSprint7HApprovalDetail_(
        ss,
        resolvedArg
      );

    } else if (cmd === "approve") {
      replyText = airoSprint7HApprovalApprove_(
        ss,
        resolvedArg
      );

      writePerformed =
        replyText.indexOf(
          "Transaksi berhasil disetujui"
        ) !== -1;

    } else if (cmd === "reject") {
      replyText = airoSprint7HApprovalReject_(
        ss,
        resolvedArg
      );

      writePerformed =
        replyText.indexOf(
          "Transaksi berhasil ditolak"
        ) !== -1;

    } else {
      replyText = airoSprint7HApprovalFix_(
        ss,
        resolvedArg
      );
    }

  } else {
    replyText =
      "Perintah approval tidak dikenal.\n\n" +
      airoTask614ApprovalHelp_();
  }

  if (parsed.chat_id && replyText) {
    sendTelegram_(parsed.chat_id, replyText);
  }

  return json_({
    ok: true,
    handled: true,
    command: "approval_" + (cmd || "direct"),
    argument: arg,
    resolved_queue_id:
      resolvedArg || directQueueId || "",
    write_performed: writePerformed
  });
}

function runTask3BCorrectiveRepairFromEditor() {
  var ss = airoSprint7FSpreadsheet_();
  var sheet = getSheetLoose_(ss, AIRO_CONFIG.tabs.review);
  if (!sheet) return "Sheet missing";
  var header = findHeader_(sheet);
  if (!header) return "Header missing";

  var headers = header.headers;
  var keyToFind = "review:emc:19e92002b9199392";
  var targetRow = 53;
  var rowFound = false;

  // Find column indexes
  var queueIdCol = -1;
  var dupKeyCol = -1;
  var createdAtCol = -1;
  for (var c = 0; c < headers.length; c++) {
    var canonical = canonicalKey_(headers[c]);
    if (canonical === "queue_id") queueIdCol = c;
    if (canonical === "duplicate_key") dupKeyCol = c;
    if (canonical === "created_at") createdAtCol = c;
  }

  // Scan to find the row index bottom-up
  var lastRow = sheet.getLastRow();
  var startRow = header.row + 1;
  var numRows = lastRow - startRow + 1;
  if (numRows > 0) {
    var values = sheet.getRange(startRow, 1, numRows, headers.length).getValues();
    for (var r = values.length - 1; r >= 0; r--) {
      var qIdVal = queueIdCol !== -1 ? String(values[r][queueIdCol] || "").trim() : "";
      var dupKeyVal = dupKeyCol !== -1 ? String(values[r][dupKeyCol] || "").trim() : "";
      if (qIdVal === keyToFind || dupKeyVal === keyToFind) {
        targetRow = startRow + r;
        rowFound = true;
        break;
      }
    }
  }

  var existingCreatedAt = "";
  if (rowFound && createdAtCol !== -1) {
    existingCreatedAt = String(sheet.getRange(targetRow, createdAtCol + 1).getValue() || "").trim();
  }

  var createdAtVal = existingCreatedAt;
  if (!createdAtVal) {
    createdAtVal = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyy-MM-dd HH:mm:ss");
  }

  var rowData = {
    queue_id: "review:emc:19e92002b9199392",
    created_at: createdAtVal,
    source: "import",
    raw_text: "Subject: Transaksimu Pakai blu Berhasil | Amount: Rp24000 | Sender: receipts@blubybcadigital.id",
    parsed_type: "expense",
    parsed_category: "Food & Drink",
    parsed_subcategory: "Kopi",
    parsed_amount: 24000,
    parsed_currency: "IDR",
    parsed_account: "Blu",
    review_status: "pending",

    email_candidate_id: "emc:9602892257e7f752",
    gmail_message_id: "19e92002b9199392",
    gmail_thread_id: "19e92002b9199392",
    email_provider: "Blu",
    email_log_ref: 12,
    duplicate_key: "review:emc:19e92002b9199392",
    write_policy: "staging",
    write_status: "pending",
    linked_event_id: "",
    linked_account_ledger_entry_id: "",

    intent: "expense",
    target_tab: "🧾 Review Queue",
    reason: "email_candidate_resolved_ingestion",
    amount: 24000,
    account: "Blu",
    category: "Food & Drink / Kopi",
    status: "pending",
    notes: "Sprint 7H scheduled poller resolved candidate. Category: Food & Drink, Subcategory: Kopi",
    parser: "email"
  };

  var rowValues = buildRowByHeader_(headers, rowData);
  sheet.getRange(targetRow, 1, 1, rowValues.length).setValues([rowValues]);
  return "Row " + targetRow + " repaired: " + (rowFound ? "found by key" : "fallback to 53");
}

// AIRO Clarification Context Isolation Guard.
// Scope: block unrelated new finance input while a core Telegram clarification is pending.
// Safety: no Gmail read, no trigger, no email mutation, no finance write.
function airoContextIsolationParseTelegramPayload_(e) {
  var payload = {};
  try {
    payload = JSON.parse(e && e.postData && e.postData.contents ? e.postData.contents : "{}");
  } catch (err) {
    payload = {};
  }

  var message = payload.message || payload.edited_message || payload.channel_post || {};
  return {
    chat_id: message.chat && message.chat.id,
    text_raw: String(message.text || message.caption || "").trim(),
    text: String(message.text || message.caption || "").trim().toLowerCase()
  };
}

function airoContextIsolationIsAdminCommand_(text) {
  text = String(text || "").trim().toLowerCase();
  return text.indexOf("admin ") === 0 || text === "admin";
}

function airoContextIsolationPendingLabel_(pending) {
  var type = String((pending && pending.type) || "").trim();

  var labels = {
    missing_amount_account: "jumlah dan akun belum lengkap",
    cc_ambiguous: "transaksi Credit Card belum jelas",
    asset_gold_ambiguous: "transaksi aset/emas belum jelas",
    debt_ambiguous: "transaksi hutang/piutang belum jelas",
    missing_category: "kategori transaksi belum dipilih",
    transfer_incomplete: "detail transfer belum lengkap",
    direction_ambiguous: "arah transaksi belum jelas",
    cash_ambiguous: "transaksi cash belum jelas",
    missing_account: "akun sumber belum dipilih"
  };

  return labels[type] || type || "klarifikasi pending";
}

function airoContextIsolationIsValidAnswerForPending_(pending, rawText) {
  var type = String((pending && pending.type) || "").trim();
  var text = String(rawText || "").trim();

  if (!type || !text) {
    return false;
  }

  try {
    if (type === "missing_amount_account") {
      return !!parseAmountAccountClarificationAnswer_(text);
    }

    if (type === "cc_ambiguous") {
      return !!normalizeCreditCardClarificationAnswer_(text);
    }

    if (type === "asset_gold_ambiguous") {
      return !!normalizeAssetGoldAmbiguousClarificationAnswer_(text);
    }

    if (type === "debt_ambiguous") {
      return !!normalizeDebtAmbiguousClarificationAnswer_(text);
    }

    if (type === "missing_category") {
      return !!normalizeMissingCategoryClarificationAnswer_(text);
    }

    if (type === "transfer_incomplete") {
      return !!normalizeTransferRouteClarificationAnswer_(text);
    }

    if (type === "direction_ambiguous") {
      return !!normalizeDirectionClarificationAnswer_(text);
    }

    if (type === "cash_ambiguous") {
      return !!normalizeCashClarificationAnswer_(text);
    }

    if (type === "missing_account") {
      return !!normalizeClarificationAccountAnswer_(text);
    }
  } catch (err) {
    return false;
  }

  return false;
}

function airoContextIsolationLooksLikeNewFinanceInput_(rawText) {
  var text = String(rawText || "").trim().toLowerCase();
  if (!text) {
    return false;
  }

  if (airoContextIsolationIsAdminCommand_(text)) {
    return false;
  }

  var hasAmount =
    /\b\d+[.,]?\d*\s*(rb|ribu|jt|juta)?\b/i.test(text) ||
    /\b(rp|idr)\s*\d+/i.test(text);

  var hasWallet =
    /\b(bca|blu|mandiri|cash|tunai|cc|credit card|kartu kredit|tokopedia card)\b/i.test(text);

  var hasFinanceAction =
    /\b(keluar|masuk|transfer|tf|bayar|beli|belanja|jajan|makan|minum|kopi|tagihan|topup|tarik|hutang|utang|pinjam|gaji|refund|emas|aset|cicilan|kpr)\b/i.test(text);

  var looksTransfer =
    /\b(transfer|tf)\b/i.test(text) &&
    (/\bdari\b/i.test(text) || /\bke\b/i.test(text));

  var looksCc =
    /\b(cc|credit card|kartu kredit|tokopedia card)\b/i.test(text) &&
    hasAmount;

  var looksWalletMovement =
    hasWallet &&
    hasAmount &&
    hasFinanceAction;

  return looksTransfer || looksCc || looksWalletMovement;
}

function airoContextIsolationBuildBlockMessage_(pending) {
  var pendingLabel = airoContextIsolationPendingLabel_(pending);

  return [
    "⚠️ Masih ada klarifikasi pending.",
    "",
    "Pending: " + pendingLabel,
    "",
    "Selesaikan dulu dengan balasan sesuai opsi terakhir.",
    "Kalau mau membatalkan pending ini, kirim:",
    "admin clear clarification",
    "",
    "Transaksi baru belum diproses supaya tidak salah masuk sebagai jawaban klarifikasi."
  ].join("\n");
}

function airoContextIsolationMaybeHandleRoute_(e) {
  var parsed = airoContextIsolationParseTelegramPayload_(e);

  if (!parsed.chat_id) {
    return null;
  }

  var pending = getPendingClarification_(parsed.chat_id);
  if (!pending || !pending.type) {
    return null;
  }

  if (airoContextIsolationIsAdminCommand_(parsed.text_raw)) {
    return null;
  }

  var looksLikeNewFinanceInput = airoContextIsolationLooksLikeNewFinanceInput_(parsed.text_raw);
  var looksLikeShortAnswer = /^[A-Ea-e1-5]$/.test(String(parsed.text_raw || "").trim());

  if (looksLikeNewFinanceInput) {
    var reply = airoContextIsolationBuildBlockMessage_(pending);
    sendTelegram_(parsed.chat_id, reply);

    var blockedResult = {
      ok: true,
      sprint: "clarification-context-isolation",
      status: "blocked_unrelated_finance_input_while_pending",
      pending_type: String(pending.type || ""),
      telegram_reply_sent: true,
      pending_cleared: false,
      finance_write_performed: false,
      account_ledger_write_performed: false,
      finance_events_write_performed: false,
      review_queue_write_performed: false,
      domain_tab_write_performed: false,
      gmail_read_performed: false,
      mail_trigger_created: false,
      email_modified: false,
      full_email_body_stored: false
    };

    Logger.log(JSON.stringify(blockedResult));
    return json_(blockedResult);
  }

  if (looksLikeShortAnswer && airoContextIsolationIsValidAnswerForPending_(pending, parsed.text_raw)) {
    return null;
  }

  if (airoContextIsolationIsValidAnswerForPending_(pending, parsed.text_raw)) {
    return null;
  }

  return null;

  var reply = airoContextIsolationBuildBlockMessage_(pending);
  sendTelegram_(parsed.chat_id, reply);

  var result = {
    ok: true,
    sprint: "clarification-context-isolation",
    status: "blocked_unrelated_finance_input_while_pending",
    pending_type: String(pending.type || ""),
    telegram_reply_sent: true,
    pending_cleared: false,
    finance_write_performed: false,
    account_ledger_write_performed: false,
    finance_events_write_performed: false,
    review_queue_write_performed: false,
    domain_tab_write_performed: false,
    gmail_read_performed: false,
    mail_trigger_created: false,
    email_modified: false,
    full_email_body_stored: false
  };

  Logger.log(JSON.stringify(result));
  return json_(result);
}

