  const maskedChat = adminChatId ? airoSprint6BMaskChatId_(adminChatId) : '';
  const timezone = Session.getScriptTimeZone ? Session.getScriptTimeZone() : 'Asia/Jakarta';
  const stamp = Utilities.formatDate(new Date(), timezone, 'yyyyMMdd_HHmmss');

  const ccStats = airoGetCcBillingStats_(ss);

  const opsRows = [
    ['AIRO Technical Ops Center', ''],
    ['Timestamp', stamp],
    ['Deployment ID', getProp_('SPREADSHEET_ID') ? 'SPREADSHEET_BOUND' : 'UNKNOWN'],
    ['Apps Script Runtime', '@203'],
    ['Live Switch Status', alertStatus.live_enabled ? 'LIVE' : 'SAFE'],
    ['ADMIN_CHAT_ID', adminChatId ? 'Registered (' + maskedChat + ')' : 'Missing'],
    ['Live Trigger Count', String(alertStatus.live_trigger_count)],
    ['Safe Trigger Count', String(alertStatus.safe_trigger_count)],
    ['Last Live Heartbeat', alertStatus.last_live_summary ? alertStatus.last_live_summary : '-'],
    ['Last Safe Heartbeat', alertStatus.last_safe_summary ? alertStatus.last_safe_summary : '-'],
    ['Total Aset Likuid', '=IFERROR(((SUMIFS(\'📒 Account Ledger\'!D:D;\'📒 Account Ledger\'!C:C;"Cash")+SUMIFS(\'📒 Account Ledger\'!D:D;\'📒 Account Ledger\'!C:C;"Cash Umum")+SUMIFS(\'📒 Account Ledger\'!D:D;\'📒 Account Ledger\'!C:C;"Cash Bensin"))-(SUMIFS(\'📒 Account Ledger\'!E:E;\'📒 Account Ledger\'!C:C;"Cash")+SUMIFS(\'📒 Account Ledger\'!E:E;\'📒 Account Ledger\'!C:C;"Cash Umum")+SUMIFS(\'📒 Account Ledger\'!E:E;\'📒 Account Ledger\'!C:C;"Cash Bensin")))+\'🥇 Aset\'!B17+\'🥇 Aset\'!B18;0)'],
    ['Hutang Non-Rumah', '=IFERROR(\'🥇 Aset\'!F18;0)'],
    ['Net Worth Likuid', '=IFERROR(B11-B12;0)'],
    ['Ekuitas Rumah', '=IFERROR(\'🥇 Aset\'!AB21;0)'],
    ['Net Worth Total', '=IFERROR(B13+B14;0)'],
    ['Credit Card Total', String(ccStats.payable_total)],
    ['Credit Card Unbilled', String(ccStats.unbilled_total)]
  ];

  opsSheet.getRange(1, 1, opsRows.length, 2).setValues(opsRows);
  opsSheet.getRange('A1:B1').setFontWeight('bold');
