function airoSprint7HScheduledGmailPoller_() {
  var disabled = false;
  try {
    disabled = (PropertiesService.getScriptProperties().getProperty("EMAIL_INGESTION_DISABLED") === "true");
  } catch (e) {
    disabled = false;
  }
  if (disabled) {
    var exitStatus = {
      ok: true,
      sprint: "7H",
      status: "fast_exit_kill_switch_active",
      write_performed: false,
      gmail_read_performed: false,
      gmail_modified: false,
      mail_trigger_created: false,
      account_ledger_write_performed: false,
      finance_events_write_performed: false,
      review_queue_write_performed: false,
      domain_tab_write_performed: false
    };
    Logger.log(JSON.stringify(exitStatus));
    return exitStatus;
  }

  var now = new Date();
  var tz = "Asia/Jakarta";
  var hourString = Utilities.formatDate(now, tz, "H");
  var hour = parseInt(hourString, 10);
  if (hour < 7 || hour >= 22) {
    var exitWindowStatus = {
      ok: true,
      sprint: "7H",
      status: "fast_exit_outside_active_window",
      hour_wib: hour,
      write_performed: false,
      gmail_read_performed: false,
      gmail_modified: false,
      mail_trigger_created: false,
      account_ledger_write_performed: false,
      finance_events_write_performed: false,
      review_queue_write_performed: false,
      domain_tab_write_performed: false
    };
    Logger.log(JSON.stringify(exitWindowStatus));
    return exitWindowStatus;
  }

  var allowedSenders = ["receipts@blubybcadigital.id", "noreply@tokopedia.com"];
  var baseQuery = 'label:"Info Terbaru" (from:receipts@blubybcadigital.id OR from:noreply@tokopedia.com)';
  var queryUsed = baseQuery;
  var fallbackEnabled = false;
  var maxThreads = 5;
  var maxMessages = 5;

  var threads = [];
  try {
    threads = GmailApp.search(baseQuery, 0, maxThreads);
  } catch (e) {
    threads = [];
  }

  if (threads.length === 0) {
    fallbackEnabled = true;
    var fallbackQueries = [
      'category:updates from:receipts@blubybcadigital.id',
      'category:updates from:noreply@tokopedia.com',
      'from:receipts@blubybcadigital.id',
      'from:noreply@tokopedia.com'
    ];
    for (var f = 0; f < fallbackQueries.length; f++) {
      queryUsed = fallbackQueries[f];
      try {
        threads = GmailApp.search(queryUsed, 0, maxThreads);
      } catch (err) {
        threads = [];
      }
      if (threads.length > 0) {
        break;
      }
    }
  }

  var scannedMessageCount = 0;
  var candidateCount = 0;
  var skippedSensitiveCount = 0;
  var skippedSenderNotAllowedCount = 0;
  var skippedMissingLabelCount = 0;
  var skippedDedupeCount = 0;
  var promptsSentCount = 0;

  var processedCandidates = [];

  for (var t = 0; t < threads.length; t++) {
    var thread = threads[t];
    var hasLabel = fallbackEnabled || airoSprint7EHasRequiredLabel_(thread, "Info Terbaru");
    var messages = [];
    try {
      messages = thread.getMessages();
    } catch (e) {
      messages = [];
    }

    for (var m = 0; m < messages.length; m++) {
      if (scannedMessageCount >= maxMessages) {
        break;
      }

      var message = messages[m];
      var sender = airoSprint7EExtractSenderEmail_(message.getFrom());
      var subject = String(message.getSubject() || "");
      var provider = airoSprint7EProviderForSender_(sender);

      if (!hasLabel) {
        skippedMissingLabelCount++;
        continue;
      }

      if (!airoSprint7EIsAllowedSender_(sender, allowedSenders)) {
        skippedSenderNotAllowedCount++;
        continue;
      }

      scannedMessageCount++;

      if (airoSprint7EIsSensitiveSubject_(subject)) {
        skippedSensitiveCount++;
        continue;
      }

      var msgId = "";
      var threadId = "";
      try {
        msgId = message.getId();
        threadId = thread.getId();
      } catch (errId) {
        msgId = "";
        threadId = "";
      }

      if (!msgId) continue;

      var dedupeKey = "review:emc:" + msgId;
      var isDup = false;
      try {
        var checkDup = PropertiesService.getScriptProperties().getProperty(dedupeKey);
        if (checkDup) {
          isDup = true;
        } else {
          var ss = airoSprint7FSpreadsheet_();
          var logSheet = ss.getSheetByName("_AIRO_Email_Ingestion_Log");
          if (logSheet) {
            var logResult = airoSprint7FFindLoggedCandidateByMessageId_(logSheet, msgId);
            if (logResult) {
              isDup = true;
            }
          }
        }
      } catch (errDup) {
        isDup = false;
      }

      if (isDup) {
        skippedDedupeCount++;
        continue;
      }

      var candidate = {
        candidate_id: "emc:" + msgId,
        message_id: msgId,
        thread_id: threadId,
        sender: sender,
        provider: provider,
        subject: subject,
        received_at: Utilities.formatDate(message.getDate(), Session.getScriptTimeZone(), "yyyy-MM-dd'T'HH:mm:ssXXX"),
        display_amount: 0,
        detected_amount: 0,
        amount_idr: 0,
        inferred_direction: "pengeluaran",
        display_time: Utilities.formatDate(message.getDate(), Session.getScriptTimeZone(), "yyyy-MM-dd HH:mm:ss"),
        clarification_question_type: "category_expense",
        candidate_type: "blu_transaction",
        parse_status: "metadata_only_candidate",
        clarification_needed: true
      };

      var textBody = "";
      try {
        textBody = message.getPlainBody() || "";
      } catch (errBody) {
        textBody = "";
      }

      var extractedAmt = 0;
      if (textBody) {
        extractedAmt = airoSprint7FExtractAmountFromSubject_(textBody);
        if (!extractedAmt) {
          extractedAmt = airoSprint7FExtractAmountFromSubject_(subject);
        }
      } else {
        extractedAmt = airoSprint7FExtractAmountFromSubject_(subject);
      }

      candidate.display_amount = extractedAmt;
      candidate.detected_amount = extractedAmt;
      candidate.amount_idr = extractedAmt;

      var direction = airoSprint7FInferDirection_(subject, candidate.candidate_type, textBody);
      candidate.inferred_direction = direction;
      candidate.clarification_question_type = airoSprint7FClarificationQuestionType_(direction);

      candidateCount++;

      if (promptsSentCount < 1) {
        var chatId = 8482041086;
        var logResult = airoSprint7FLogPendingCandidate_(candidate, chatId);

        if (logResult && logResult.dedupe_hit) {
          skippedDedupeCount++;
          processedCandidates.push({
            message_id: msgId,
            thread_id: threadId,
            prompt_sent: false,
            reason: "dedupe_hit"
          });
        } else {
          var pointerResult = airoSprint7FSavePendingPointer_(chatId, candidate, logResult);
          var messageText = airoSprint7FBuildFriendlyClarificationMessage_(logResult.candidate_id || candidate.candidate_id, candidate);
          sendTelegram_(chatId, messageText);

          promptsSentCount++;

          processedCandidates.push({
            message_id: msgId,
            thread_id: threadId,
            prompt_sent: true,
            log_row: logResult.row_number
          });
        }
      } else {
        processedCandidates.push({
          message_id: msgId,
          thread_id: threadId,
          prompt_sent: false,
          reason: "cap_exceeded"
        });
      }
    }

    if (scannedMessageCount >= maxMessages) {
      break;
    }
  }

  var finalResult = {
    ok: true,
    sprint: "7H",
    mode: "scheduled_polling_run",
    status: "success",
    scanned_thread_count: threads.length,
    scanned_message_count: scannedMessageCount,
    candidate_count: candidateCount,
    skipped_sensitive_count: skippedSensitiveCount,
    skipped_sender_not_allowed_count: skippedSenderNotAllowedCount,
    skipped_missing_label_count: skippedMissingLabelCount,
    skipped_due_to_dedupe: skippedDedupeCount,
    prompts_sent: promptsSentCount,
    processed_candidates: processedCandidates,
    write_performed: false,
    gmail_read_performed: scannedMessageCount > 0,
    gmail_modified: false,
    mail_trigger_created: false,
    account_ledger_write_performed: false,
    finance_events_write_performed: false,
    review_queue_write_performed: false,
    domain_tab_write_performed: false
  };

  Logger.log(JSON.stringify(finalResult));

  var ss = airoSprint7FSpreadsheet_();
  var audit = ss.getSheetByName("_AIRO_Audit_Log");
  if (audit) {
    audit.appendRow([
      new Date(),
      "AIRO",
      "sprint7h_poller_heartbeat",
      "INFO",
      "Sprint 7H Poller Engine",
      "Scheduled poll completed. Candidates found: " + candidateCount + ", prompts sent: " + promptsSentCount + ", skipped dupes: " + skippedDedupeCount,
      "airoSprint7HScheduledGmailPoller_",
      JSON.stringify(finalResult)
    ]);
  }

  return finalResult;
}

