// =============================================================================
// TASK 6.11 — Smoke/Test Data Cleanup — DRY RUN SCANNER
// =============================================================================
// READ-ONLY block.  Writes findings into "Smoke Archive (DRY RUN)" sheet.
// No operational row is modified or deleted.
// =============================================================================

/**
 * Editor runner — select this function in the Apps Script editor and click Run.
 * Calls airoTask611SmokeTestDryRunScan_() and logs a summary.
 */
function aaRun611DryRun() {
  var result = airoTask611SmokeTestDryRunScan_();
  Logger.log(JSON.stringify(result, null, 2));
  return result;
}

/**
 * Core dry-run scanner for Task 6.11.
 *
 * Scans every configured operational tab for rows that contain any of the
 * smoke/test identifiers (SMK_, QA_, TEST_).  Found rows are copied into
 * the ARCHIVE sheet with source metadata.  Nothing is deleted or modified.
 *
 * @return {Object}  { ok, totalFound, byTab, archiveSheetUrl, errors }
 */
function airoTask611SmokeTestDryRunScan_() {
  // TASK_6_11_PATCH_V2
  var SMOKE_TAGS = ['SMK_', 'QA_', 'TEST_'];

  // Configured tab labels — the configured label is used for reporting;
  // the resolver below finds the actual sheet using exact or canonical match.
  var SCAN_CONFIG = [
    { label: 'Account Ledger',  emoji: '\uD83D\uDCD2', configured: '\uD83D\uDCD2 Account Ledger' },
    { label: 'Finance Events',  emoji: '\uD83D\uDCCC', configured: '\uD83D\uDCCC Finance Events' },
    { label: 'Credit Card',     emoji: '\uD83D\uDCB3', configured: '\uD83D\uDCB3 Credit Card' },
    { label: 'Hutang',          emoji: '\uD83E\uDD1D', configured: '\uD83E\uDD1D Hutang' },
    { label: 'Aset',            emoji: '\uD83E\uDD47', configured: '\uD83E\uDD47 Aset' },
    { label: 'Cicilan Rumah',   emoji: '\uD83C\uDFE0', configured: '\uD83C\uDFE0 Cicilan Rumah' },
    { label: 'Review Queue',    emoji: '\uD83E\uDDFE', configured: '\uD83E\uDDFE Review Queue' },
    { label: '_AIRO_Audit_Log', emoji: '',             configured: '_AIRO_Audit_Log' }
  ];

  var ARCHIVE_SHEET_NAME = 'Smoke Archive DRY RUN';
  var ARCHIVE_HEADER = [
    'source_tab_label',
    'resolved_sheet_name',
    'source_row',
    'matched_tag',
    'matched_cell_col',
    'row_data_json',
    'scan_timestamp'
  ];

  var errors = [];
  var byTab = {};
  var totalFound = 0;
  var archiveSheetUrl = '';
  var allTabsNotFound = true;

  try {
    var ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
    var scanTs = new Date().toISOString();

    // Build map of actual sheet names for resolver
    var allSheets = ss.getSheets();
    var sheetNameMap = {};  // lower-canonical → actual name
    for (var si = 0; si < allSheets.length; si++) {
      var sn = allSheets[si].getName();
      // Skip the archive output sheet — never scan it as a source
      if (sn === ARCHIVE_SHEET_NAME || sn === '\uD83E\uDDEB Smoke Archive') continue;
      var canonical = sn.replace(/[^\x20-\x7E]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
      sheetNameMap[canonical] = sn;
    }

    /**
     * Resolve configured tab name to actual sheet name.
     * Strategy: exact match → canonical match → not found.
     */
    function resolveSheetName_(configured) {
      // 1. Exact match
      var exactSheet = ss.getSheetByName(configured);
      if (exactSheet && exactSheet.getName() !== ARCHIVE_SHEET_NAME) {
        return configured;
      }
      // 2. Canonical match: strip non-ASCII, normalize whitespace, lowercase
      var configCanonical = configured.replace(/[^\x20-\x7E]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
      if (sheetNameMap[configCanonical]) {
        return sheetNameMap[configCanonical];
      }
      // 3. Partial canonical match (label only, e.g. "account ledger")
      for (var cn in sheetNameMap) {
        if (cn.indexOf(configCanonical) !== -1 || configCanonical.indexOf(cn) !== -1) {
          return sheetNameMap[cn];
        }
      }
      return null;
    }

    // Prepare / reset the archive sheet (clear and rebuild header)
    var archiveSheet = ss.getSheetByName(ARCHIVE_SHEET_NAME);
    if (archiveSheet) {
      archiveSheet.clearContents();
      archiveSheet.clearFormats();
    } else {
      archiveSheet = ss.insertSheet(ARCHIVE_SHEET_NAME);
    }
    archiveSheet.appendRow(ARCHIVE_HEADER);
    archiveSheet.getRange(1, 1, 1, ARCHIVE_HEADER.length)
      .setFontWeight('bold')
      .setBackground('#2d4a7a')
      .setFontColor('#ffffff');

    // Scan each configured tab
    for (var ti = 0; ti < SCAN_CONFIG.length; ti++) {
      var cfg = SCAN_CONFIG[ti];
      var label = cfg.label;

      var tabResult = {
        label: label,
        configured: cfg.configured,
        resolved: null,
        exists: false,
        skipped: false,
        found: 0,
        rows: []
      };
      byTab[label] = tabResult;

      var resolvedName = resolveSheetName_(cfg.configured);
      if (!resolvedName) {
        tabResult.skipped = true;
        tabResult.exists = false;
        continue;
      }

      tabResult.resolved = resolvedName;
      tabResult.exists = true;
      allTabsNotFound = false;

      var sheet = ss.getSheetByName(resolvedName);
      if (!sheet) {
        // Should not happen after resolveSheetName_ succeeded, but guard anyway
        tabResult.skipped = true;
        tabResult.exists = false;
        continue;
      }

      var lastRow = sheet.getLastRow();
      var lastCol = sheet.getLastColumn();
      if (lastRow < 2 || lastCol < 1) {
        // Header-only or empty — tab exists but clean
        continue;
      }

      var data = sheet.getRange(2, 1, lastRow - 1, lastCol).getValues();

      for (var ri = 0; ri < data.length; ri++) {
        var row = data[ri];
        var sourceRowNum = ri + 2;  // 1-indexed

        var rowStr = row.map(function(cell) { return String(cell); }).join('|');

        var matchedTag = '';
        var matchedCellIdx = -1;

        for (var tsi = 0; tsi < SMOKE_TAGS.length && !matchedTag; tsi++) {
          var tag = SMOKE_TAGS[tsi];
          if (rowStr.indexOf(tag) !== -1) {
            matchedTag = tag;
            for (var ci = 0; ci < row.length; ci++) {
              if (String(row[ci]).indexOf(tag) !== -1) {
                matchedCellIdx = ci + 1;
                break;
              }
            }
          }
        }

        if (!matchedTag) continue;

        totalFound++;
        tabResult.found++;
        tabResult.rows.push(sourceRowNum);

        var rowDataJson = JSON.stringify(row.map(function(cell) {
          return cell instanceof Date ? cell.toISOString() : cell;
        }));

        archiveSheet.appendRow([
          label,
          resolvedName,
          sourceRowNum,
          matchedTag,
          'col ' + matchedCellIdx,
          rowDataJson,
          scanTs
        ]);
      }
    }

    // Defensive check: if every tab was not found → fatal
    if (allTabsNotFound) {
      errors.push('FATAL: all configured tabs returned not-found. Spreadsheet ID may be wrong or tab names changed. Scan aborted.');
    }

    // Alternating row colours
    var archiveLastRow = archiveSheet.getLastRow();
    if (archiveLastRow > 1) {
      for (var ar = 2; ar <= archiveLastRow; ar++) {
        var bg = ar % 2 === 0 ? '#f0f4fb' : '#ffffff';
        archiveSheet.getRange(ar, 1, 1, ARCHIVE_HEADER.length).setBackground(bg);
      }
    }

    // Auto-resize columns
    for (var col = 1; col <= ARCHIVE_HEADER.length; col++) {
      archiveSheet.autoResizeColumn(col);
    }

    // Build summary note
    var summaryLines = [
      'TASK 6.11 DRY-RUN SCAN v2 — ' + scanTs,
      'TOTAL SMOKE ROWS FOUND: ' + totalFound,
      allTabsNotFound ? 'WARNING: ALL TABS NOT FOUND — scan result is invalid' : '',
      ''
    ];
    for (var tk in byTab) {
      var tri = byTab[tk];
      if (!tri.exists) {
        summaryLines.push(tk + ': NOT FOUND (configured: ' + tri.configured + ')');
      } else {
        summaryLines.push(tk + ' (resolved: ' + tri.resolved + '): ' + tri.found + ' smoke row(s)' +
          (tri.rows.length ? ' [rows: ' + tri.rows.join(', ') + ']' : ' — CLEAN'));
      }
    }
    archiveSheet.getRange(1, 1).setNote(summaryLines.join('\n'));

    archiveSheetUrl = ss.getUrl() + '#gid=' + archiveSheet.getSheetId();

  } catch (err) {
    errors.push(String(err && err.message ? err.message : err));
  }

  var scanOk = errors.length === 0 && !allTabsNotFound;

  return {
    ok: scanOk,
    task: '6.11',
    phase: scanOk ? 'DRY_RUN_READY' : 'FAIL',
    totalFound: totalFound,
    byTab: byTab,
    allTabsNotFound: allTabsNotFound,
    archiveSheetUrl: archiveSheetUrl,
    scanTimestamp: new Date().toISOString(),
    errors: errors,
    write_performed: false,
    gmail_read_performed: false,
    gmail_modified: false,
    mail_trigger_created: false,
    account_ledger_write_performed: false,
    finance_events_write_performed: false,
    any_row_deleted: false,
    any_row_modified: false
  };
}



// =============================================================================
// TASK 6.11 — Smoke/Test Data Cleanup — EXECUTION RUNNER
// =============================================================================
// TASK_6_11_CLEANUP_V1
// Destructive block: Deletes approved smoke/test rows bottom-up.
// Writes permanent archive into "🧪 Smoke Archive" sheet.
// =============================================================================
function airoTask611SmokeCleanupExecute_() {
  var SMOKE_TAGS = ['SMK_', 'QA_', 'TEST_'];

  var SCAN_CONFIG = [
    { label: 'Account Ledger',  emoji: '\uD83D\uDCD2', configured: '\uD83D\uDCD2 Account Ledger' },
    { label: 'Finance Events',  emoji: '\uD83D\uDCCC', configured: '\uD83D\uDCCC Finance Events' },
    { label: 'Credit Card',     emoji: '\uD83D\uDCB3', configured: '\uD83D\uDCB3 Credit Card' },
    { label: 'Hutang',          emoji: '\uD83E\uDD1D', configured: '\uD83E\uDD1D Hutang' },
    { label: 'Aset',            emoji: '\uD83E\uDD47', configured: '\uD83E\uDD47 Aset' },
    { label: 'Cicilan Rumah',   emoji: '\uD83C\uDFE0', configured: '\uD83C\uDFE0 Cicilan Rumah' },
    { label: 'Review Queue',    emoji: '\uD83E\uDDFE', configured: '\uD83E\uDDFE Review Queue' },
    { label: '_AIRO_Audit_Log', emoji: '',             configured: '_AIRO_Audit_Log' }
  ];

  var manifest = {
    'Account Ledger': [46, 63, 70, 71, 72, 73, 74, 75, 81, 82, 83, 84, 85, 86, 87, 88, 89, 90, 94, 95, 98, 99, 100, 101, 102, 103, 104, 105, 106],
    'Finance Events': [16, 17, 24, 25, 26, 27, 28, 30, 31, 32, 33, 34, 35, 45, 46, 47, 48, 49, 50],
    'Credit Card': [26, 27, 28],
    'Hutang': [15, 16],
    'Aset': [4, 32, 33, 34, 35, 36],
    'Cicilan Rumah': [],
    'Review Queue': [61],
    '_AIRO_Audit_Log': []
  };

  var PERM_ARCHIVE_SHEET_NAME = '\uD83E\uDDEB Smoke Archive'; // 🧪 Smoke Archive
  var ARCHIVE_HEADER = [
    'source_tab_label',
    'resolved_sheet_name',
    'source_row',
    'matched_tag',
    'matched_cell_col',
    'row_data_json',
    'cleanup_timestamp'
  ];

  var errors = [];
  var deletedCountMap = {};
  var skippedCountMap = {};
  var suspiciousRows = [];
  var totalDeleted = 0;

  for (var k in manifest) {
    deletedCountMap[k] = 0;
    skippedCountMap[k] = 0;
  }

  try {
    var ss = SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
    var ts = new Date().toISOString();

    var allSheets = ss.getSheets();
    var sheetNameMap = {};
    for (var si = 0; si < allSheets.length; si++) {
      var sn = allSheets[si].getName();
      if (sn === PERM_ARCHIVE_SHEET_NAME) continue;
      var canonical = sn.replace(/[^\x20-\x7E]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
      sheetNameMap[canonical] = sn;
    }

    function resolveSheetName_(configured) {
      var exactSheet = ss.getSheetByName(configured);
      if (exactSheet && exactSheet.getName() !== PERM_ARCHIVE_SHEET_NAME) {
        return configured;
      }
      var configCanonical = configured.replace(/[^\x20-\x7E]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
      if (sheetNameMap[configCanonical]) {
        return sheetNameMap[configCanonical];
      }
      for (var cn in sheetNameMap) {
        if (cn.indexOf(configCanonical) !== -1 || configCanonical.indexOf(cn) !== -1) {
          return sheetNameMap[cn];
        }
      }
      return null;
    }

    var permArchiveSheet = ss.getSheetByName(PERM_ARCHIVE_SHEET_NAME);
    if (!permArchiveSheet) {
      permArchiveSheet = ss.insertSheet(PERM_ARCHIVE_SHEET_NAME);
      permArchiveSheet.appendRow(ARCHIVE_HEADER);
      permArchiveSheet.getRange(1, 1, 1, ARCHIVE_HEADER.length)
        .setFontWeight('bold')
        .setBackground('#1e7e34')
        .setFontColor('#ffffff');
    }

    for (var ti = 0; ti < SCAN_CONFIG.length; ti++) {
      var cfg = SCAN_CONFIG[ti];
      var label = cfg.label;
      var targetRows = manifest[label] || [];
      if (targetRows.length === 0) continue;

      var resolvedName = resolveSheetName_(cfg.configured);
      if (!resolvedName) {
        errors.push('Sheet not found for configured tab: ' + cfg.configured);
        skippedCountMap[label] += targetRows.length;
        continue;
      }

      var sheet = ss.getSheetByName(resolvedName);
      if (!sheet) {
        errors.push('Sheet failed to load: ' + resolvedName);
        skippedCountMap[label] += targetRows.length;
        continue;
      }

      var sortedRows = targetRows.slice().sort(function(a, b) { return b - a; });

      for (var ri = 0; ri < sortedRows.length; ri++) {
        var rowNum = sortedRows[ri];
        var lastRow = sheet.getLastRow();

        if (rowNum > lastRow) {
          errors.push(label + ' row ' + rowNum + ' is out of bounds (max ' + lastRow + '). Skipped.');
          skippedCountMap[label]++;
          continue;
        }

        var rowValues = sheet.getRange(rowNum, 1, 1, sheet.getLastColumn()).getValues()[0];
        var rowStr = rowValues.map(function(cell) { return String(cell); }).join('|');

        var matchedTag = '';
        var matchedCol = -1;

        for (var tsi = 0; tsi < SMOKE_TAGS.length && !matchedTag; tsi++) {
          var tag = SMOKE_TAGS[tsi];
          if (rowStr.indexOf(tag) !== -1) {
            matchedTag = tag;
            for (var ci = 0; ci < rowValues.length; ci++) {
              if (String(rowValues[ci]).indexOf(tag) !== -1) {
                matchedCol = ci + 1;
                break;
              }
            }
          }
        }

        if (label === 'Aset' && rowNum === 4) {
          if (!matchedTag) {
            suspiciousRows.push('Aset row 4: no explicit smoke/test tag found. Row skipped as suspicious. Content: ' + rowStr);
            skippedCountMap[label]++;
            continue;
          }
        }

        if (!matchedTag) {
          errors.push(label + ' row ' + rowNum + ' does not contain explicit smoke/test tag. Skipped. Content: ' + rowStr);
          skippedCountMap[label]++;
          continue;
        }

        var rowDataJson = JSON.stringify(rowValues.map(function(cell) {
          return cell instanceof Date ? cell.toISOString() : cell;
        }));

        permArchiveSheet.appendRow([
          label,
          resolvedName,
          rowNum,
          matchedTag,
          'col ' + matchedCol,
          rowDataJson,
          ts
        ]);

        sheet.deleteRow(rowNum);
        deletedCountMap[label]++;
        totalDeleted++;
      }
    }

    var ledgerResolvedName = resolveSheetName_('\uD83D\uDCD2 Account Ledger');
    var balanceVerification = 'OK';
    var repairedFormulaCount = 0;
    if (ledgerResolvedName) {
      var ledgerSheet = ss.getSheetByName(ledgerResolvedName);
      if (ledgerSheet) {
        var lastRow = ledgerSheet.getLastRow();
        if (lastRow >= 2) {
          for (var r = 2; r <= lastRow; r++) {
            var cell = ledgerSheet.getRange(r, 6);
            var formula = cell.getFormula();
            var expectedFormula = '=IF(C' + r + '="";"";SUMIFS($D$2:D' + r + ';$C$2:C' + r + ';C' + r + ')-SUMIFS($E$2:E' + r + ';$C$2:C' + r + ';C' + r + '))';
            if (!formula || formula.indexOf('#REF') !== -1) {
              cell.setFormula(expectedFormula);
              repairedFormulaCount++;
            }
          }
        }
      }
    }
    if (repairedFormulaCount > 0) {
      balanceVerification = 'REPAIRED (' + repairedFormulaCount + ' formulas fixed)';
    }

    var scanResult = airoTask611SmokeTestDryRunScan_();
    var smokeVerification = 'CLEAN';
    if (scanResult.totalFound > 0) {
      smokeVerification = 'WARNING: ' + scanResult.totalFound + ' smoke/test rows still remain!';
    }

    var audit = ss.getSheetByName("_AIRO_Audit_Log");
    if (audit) {
      audit.appendRow([
        new Date(),
        "AIRO",
        "task_611_smoke_cleanup",
        "INFO",
        "Task 6.11 Smoke Data Cleanup",
        "Executed destructive cleanup. Deleted " + totalDeleted + " rows. Balance status: " + balanceVerification + ". Smoke check: " + smokeVerification,
        "airoTask611SmokeCleanupExecute_",
        JSON.stringify({
          deleted: deletedCountMap,
          skipped: skippedCountMap,
          totalDeleted: totalDeleted,
          suspicious: suspiciousRows,
          errors: errors
        })
      ]);
    }

    return {
      ok: errors.length === 0 && smokeVerification === 'CLEAN',
      totalDeleted: totalDeleted,
      deleted: deletedCountMap,
      skipped: skippedCountMap,
      suspicious: suspiciousRows,
      balanceVerification: balanceVerification,
      smokeVerification: smokeVerification,
      archiveSheetName: PERM_ARCHIVE_SHEET_NAME,
      errors: errors
    };

  } catch (err) {
    var errStr = String(err && err.message ? err.message : err);
    return {
      ok: false,
      totalDeleted: totalDeleted,
      deleted: deletedCountMap,
      skipped: skippedCountMap,
      suspicious: suspiciousRows,
      balanceVerification: 'ERROR',
      smokeVerification: 'ERROR',
      archiveSheetName: PERM_ARCHIVE_SHEET_NAME,
      errors: [errStr]
    };
  }
}


