function airoSprint7ParseCategoryAndSubcategoryFromText_(text) {
  var t = String(text || '').toLowerCase();

  var registry = airoSprint7CategoryContractGetRegistry_();
  var categories = Object.keys(registry);

  for (var i = 0; i < categories.length; i++) {
    var cat = categories[i];
    var catLower = cat.toLowerCase();
    var catData = registry[cat];
    var subs = catData.subcategories;
    var subinfo = catData.subinfo || {};

    for (var j = 0; j < subs.length; j++) {
      var sub = subs[j];
      var subLower = sub.toLowerCase();
      var info = subinfo[sub] || {};
      var aliases = info.aliases || [];

      for (var k = 0; k < aliases.length; k++) {
        var alias = aliases[k].toLowerCase();
        var re = new RegExp("\\b" + escapeRegex_(alias) + "\\b", "i");
        if (re.test(t)) {
          return { category: cat, subcategory: sub };
        }
      }

      var subWordRe = new RegExp("\\b" + escapeRegex_(subLower) + "\\b", "i");
      if (subWordRe.test(t)) {
        return { category: cat, subcategory: sub };
      }
    }
  }

  for (var i = 0; i < categories.length; i++) {
    var cat = categories[i];
    var catLower = cat.toLowerCase();

    var catWordRe = new RegExp("\\b" + escapeRegex_(catLower) + "\\b", "i");
    if (catWordRe.test(t)) {
      var defaultSub = registry[cat].subcategories[0] || 'Lainnya';
      return { category: cat, subcategory: defaultSub };
    }
  }

  if (/\b(makan|minum|kopi|es teh|resto|warung|sarapan|lunch|dinner)\b/i.test(t)) {
    var sub = 'Makan di Luar';
    if (/\\b(kopi|coffee|starbucks)\\b/i.test(t)) sub = 'Kopi';
    else if (/\\b(jajan|snack|cemilan)\\b/i.test(t)) sub = 'Jajan';
    return { category: 'Food & Drink', subcategory: sub };
  }
  if (/\b(pdam|pln|listrik|air|wifi|internet|tagihan)\b/i.test(t)) {
    var sub = 'Listrik';
    if (/\\b(wifi|internet|indihome)\\b/i.test(t)) sub = 'Internet';
    return { category: 'Utilities', subcategory: sub };
  }
  if (/\b(bensin|bbm|pertalite|pertamax|solar|shell|spbu|parkir|tol|grab|gojek|transport|ojek|taxi)\b/i.test(t)) {
    var sub = 'Ride Hailing';
    if (/\\b(parkir)\\b/i.test(t)) sub = 'Parkir';
    return { category: 'Transport', subcategory: sub };
  }
  if (/\b(gaji|salary|gajian)\b/i.test(t)) {
    return { category: 'Income', subcategory: 'Salary' };
  }
  if (/\b(refund|refund tokopedia|kembalian)\b/i.test(t)) {
    return { category: 'Income', subcategory: 'Refund' };
  }
  if (/\b(tokopedia|shopee|belanja|beli)\b/i.test(t)) {
    return { category: 'Groceries', subcategory: 'Belanja Harian' };
  }
  if (/\b(obat|medicine|vet|grooming|kucing|anjing)\b/i.test(t)) {
    if (/\\b(obat|medicine)\\b/i.test(t)) return { category: 'Health', subcategory: 'Medicine' };
    return { category: 'Pets', subcategory: 'Pet Food' };
  }

  return { category: 'Other / Review', subcategory: 'Review' };
}

function escapeRegex_(string) {
  return string.replace(/[-\\/\\^$*+?.()|[\\]{}]/g, '\\$&');
}

function airoTask613BackfillDryRun_() {
  var ss = airoSprint7FSpreadsheet_();
  var result = {
    ledgerBlank: 0,
    ledgerInferred: 0,
    feBlank: 0,
    feInferred: 0,
    errors: []
  };

  try {
    var ledgerSheet = getSheetLoose_(ss, "📒 Account Ledger");
    if (ledgerSheet) {
      var lastRow = ledgerSheet.getLastRow();
      if (lastRow >= 2) {
        var headers = ledgerSheet.getRange(1, 1, 1, ledgerSheet.getLastColumn()).getValues()[0]
          .map(function(h) { return String(h || "").trim().toLowerCase(); });
        var subCol = headers.indexOf("subcategory") + 1;
        var rawTextCol = headers.indexOf("raw_text") + 1;

        if (subCol > 0 && rawTextCol > 0) {
          var vals = ledgerSheet.getRange(2, 1, lastRow - 1, ledgerSheet.getLastColumn()).getValues();
          for (var i = 0; i < vals.length; i++) {
            var sub = String(vals[i][subCol - 1] || "").trim();
            var rawText = String(vals[i][rawTextCol - 1] || "").trim();
            if (!sub) {
              result.ledgerBlank++;
              var inferred = airoSprint7ParseCategoryAndSubcategoryFromText_(rawText).subcategory;
              if (inferred && inferred !== 'Review') {
                result.ledgerInferred++;
              }
            }
          }
        }
      }
    }

    var feSheet = getSheetLoose_(ss, "📌 Finance Events");
    if (feSheet) {
      var lastRow = feSheet.getLastRow();
      if (lastRow >= 2) {
        var headers = feSheet.getRange(1, 1, 1, feSheet.getLastColumn()).getValues()[0]
          .map(function(h) { return String(h || "").trim().toLowerCase(); });
        var subCol = headers.indexOf("subcategory") + 1;
        var notesCol = headers.indexOf("notes") + 1;
        var payloadCol = headers.indexOf("payload_json") + 1;

        if (subCol > 0) {
          var vals = feSheet.getRange(2, 1, lastRow - 1, feSheet.getLastColumn()).getValues();
          for (var i = 0; i < vals.length; i++) {
            var sub = String(vals[i][subCol - 1] || "").trim();
            var notes = notesCol > 0 ? String(vals[i][notesCol - 1] || "").trim() : "";
            var payload = payloadCol > 0 ? String(vals[i][payloadCol - 1] || "").trim() : "";
            if (!sub) {
              result.feBlank++;

              var inferred = "";
              if (payload) {
                try {
                  var p = JSON.parse(payload);
                  if (p.raw_text) {
                    inferred = airoSprint7ParseCategoryAndSubcategoryFromText_(p.raw_text).subcategory;
                  }
                } catch (e) {}
              }
              if (!inferred && notes) {
                inferred = airoSprint7ParseCategoryAndSubcategoryFromText_(notes).subcategory;
              }

              if (inferred && inferred !== 'Review') {
                result.feInferred++;
              }
            }
          }
        }
      }
    }
  } catch (e) {
    result.errors.push(e.toString());
  }

  return result;
}

function airoTask613AdminCommandMaybeHandleRoute_(e) {
  try {
    var body = JSON.parse(e && e.postData && e.postData.contents ? e.postData.contents : '{}');
    var msg = body.message || body.edited_message || {};
    var chatId = (msg.chat || {}).id;
    var rawText = ((msg.text || '').replace(/\s+/g, ' ')).trim();

    if (/^admin\s+backfill\s+dryrun\s*$/i.test(rawText)) {
      sendTelegram_(chatId, 'Task 6.13 — Backfill dry-run starting...');
      var res = airoTask613BackfillDryRun_();
      var reply = [
        '📊 Backfill Dry-Run Result:',
        '',
        '- Account Ledger blank subcategories: ' + res.ledgerBlank + ' (can infer: ' + res.ledgerInferred + ')',
        '- Finance Events blank subcategories: ' + res.feBlank + ' (can infer: ' + res.feInferred + ')',
        '',
        'No writes performed. Owner approval required to commit backfill.'
      ].join('\n');

      sendTelegram_(chatId, reply);
      return json_({
        ok: true,
        handled: true,
        command: 'backfill_dryrun',
        result: res
      });
    }

    if (/^admin\s+import\s+registries\s*$/i.test(rawText)) {
      sendTelegram_(chatId, 'Task 6.13B — Importing Category and Account Registries...');
      var res = airoTask613BImportRegistries_(body);
      var reply = [
        '✅ Registry Import Complete!',
        '',
        '- Category backup sheet: ' + res.categoryBackupSheet,
        '- Category rows before: ' + res.categoryRowsBefore + ', added: ' + res.categoryRowsAdded + ', updated: ' + res.categoryRowsUpdated + ', duplicates: ' + res.categoryDuplicates,
        '- Account Registry created: ' + res.accountRegistryCreated,
        '- Account rows imported: ' + res.accountRowsImported + ', duplicates: ' + res.accountDuplicates
      ].join('\n');

      sendTelegram_(chatId, reply);
      return json_({
        ok: true,
        handled: true,
        command: 'import_registries',
        result: res
      });
    }

    if (/^admin\s+apply\s+account\s+styles\s*$/i.test(rawText)) {
      sendTelegram_(chatId, 'Task 6.13B — Applying account color styling to Account Ledger...');
      var res = runTask613ApplyAccountRegistryStyleFromEditor();
      var reply = '🎨 Applied account styles to ' + res.formattedRowsCount + ' ledger rows successfully.';
      sendTelegram_(chatId, reply);
      return json_({
        ok: true,
        handled: true,
        command: 'apply_account_styles',
        result: res
      });
    }

    return null;
  } catch (outerErr) {
    return null;
  }
}



function applySheetFormatting_(sheet, numHeaders) {
  var lastRow = sheet.getLastRow();
  var lastCol = sheet.getLastColumn();
  if (lastRow > 0 && lastCol > 0) {
    var range = sheet.getRange(1, 1, lastRow, lastCol);
    if (sheet.getFilter()) {
      sheet.getFilter().remove();
    }
    range.createFilter();

    var headerRange = sheet.getRange(1, 1, 1, lastCol);
    headerRange.setFontWeight('bold')
               .setBackground('#203a43')
               .setFontColor('#ffffff')
               .setHorizontalAlignment('center');

    for (var r = 2; r <= lastRow; r++) {
      var rowRange = sheet.getRange(r, 1, 1, lastCol);
      if (r % 2 === 0) {
        rowRange.setBackground('#ffffff');
      } else {
        rowRange.setBackground('#f9fbfd');
      }
    }

    for (var col = 1; col <= lastCol; col++) {
      sheet.autoResizeColumn(col);
    }
  }
}

function airoTask613BImportRegistries_(payload) {
  var ss = airoSprint7FSpreadsheet_();
  var timestamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyyMMdd_HHmmss");

  var catTabName = "📚 Category Registry";
  var origSheet = ss.getSheetByName(catTabName);
  var backupName = "📚 Category Registry BACKUP " + timestamp;
  var backupSheetName = "";
  var rowsBefore = 0;

  var existingRowsMap = {};
  var targetHeaders = ['active', 'category', 'subcategory', 'aliases', 'transaction_scope', 'display_order', 'dashboard_group', 'requires_review', 'domain', 'event_type', 'notes'];

  if (origSheet) {
    var backupSheet = origSheet.copyTo(ss).setName(backupName);
    backupSheetName = backupSheet.getName();
    var lastRow = origSheet.getLastRow();
    if (lastRow >= 1) {
      rowsBefore = lastRow - 1;
      var lastCol = origSheet.getLastColumn();
      var existingHeaders = origSheet.getRange(1, 1, 1, lastCol).getValues()[0].map(function(h) { return String(h || "").trim(); });
      var existingValues = lastRow > 1 ? origSheet.getRange(2, 1, lastRow - 1, lastCol).getValues() : [];
      for (var i = 0; i < existingValues.length; i++) {
        var rowVals = existingValues[i];
        var rowObj = {};
        for (var j = 0; j < existingHeaders.length; j++) {
          rowObj[existingHeaders[j]] = rowVals[j];
        }
        var cat = String(rowObj.category || "").trim();
        var sub = String(rowObj.subcategory || "").trim();
        var dom = String(rowObj.domain || "").trim();
        var evt = String(rowObj.event_type || "").trim();
        var key = (cat + "|" + sub + "|" + dom + "|" + evt).toLowerCase();
        existingRowsMap[key] = rowObj;
      }
    }
  }

  var designCategories = payload.categories || [];
  var mergedRows = [];
  var rowsAdded = 0;
  var rowsUpdated = 0;
  var catDuplicates = 0;
  var seenKeys = {};

  for (var idx = 0; idx < designCategories.length; idx++) {
    var designRow = designCategories[idx];
    var cat = String(designRow.category || "").trim();
    var sub = String(designRow.subcategory || "").trim();
    var dom = String(designRow.domain || "").trim();
    var evt = String(designRow.event_type || "").trim();
    var key = (cat + "|" + sub + "|" + dom + "|" + evt).toLowerCase();

    if (seenKeys[key]) {
      catDuplicates++;
      continue;
    }
    seenKeys[key] = true;

    if (existingRowsMap[key]) {
      var mergedRow = {};
      for (var colIdx = 0; colIdx < targetHeaders.length; colIdx++) {
        var h = targetHeaders[colIdx];
        var existingVal = existingRowsMap[key][h];
        if (existingVal !== undefined && existingVal !== null && String(existingVal).trim() !== "") {
          mergedRow[h] = existingVal;
        } else {
          mergedRow[h] = designRow[h];
        }
      }
      mergedRows.push(mergedRow);
      rowsUpdated++;
      delete existingRowsMap[key];
    } else {
      var mergedRow = {};
      for (var colIdx = 0; colIdx < targetHeaders.length; colIdx++) {
        var h = targetHeaders[colIdx];
        mergedRow[h] = designRow[h] !== undefined ? designRow[h] : "";
      }
      mergedRows.push(mergedRow);
      rowsAdded++;
    }
  }

  for (var key in existingRowsMap) {
    var existingRow = existingRowsMap[key];
    var mergedRow = {};
    for (var colIdx = 0; colIdx < targetHeaders.length; colIdx++) {
      var h = targetHeaders[colIdx];
      mergedRow[h] = existingRow[h] !== undefined ? existingRow[h] : "";
    }
    mergedRows.push(mergedRow);
  }

  if (!origSheet) {
    origSheet = ss.insertSheet(catTabName);
  } else {
    origSheet.clear();
  }

  origSheet.getRange(1, 1, 1, targetHeaders.length).setValues([targetHeaders]);
  origSheet.setFrozenRows(1);

  if (mergedRows.length > 0) {
    var outputValues = mergedRows.map(function(row) {
      return targetHeaders.map(function(h) {
        var val = row[h];
        if (typeof val === 'boolean') {
          return val ? 'TRUE' : 'FALSE';
        }
        return val === undefined || val === null ? "" : val;
      });
    });
    origSheet.getRange(2, 1, outputValues.length, targetHeaders.length).setValues(outputValues);
  }

  var activeColIdx = targetHeaders.indexOf('active') + 1;
  var reviewColIdx = targetHeaders.indexOf('requires_review') + 1;
  var lastCatRow = origSheet.getLastRow();
  applySheetFormatting_(origSheet, targetHeaders.length);
  if (lastCatRow > 1) {
    var rule = SpreadsheetApp.newDataValidation().requireValueInList(['TRUE', 'FALSE'], true).build();
    if (activeColIdx > 0) origSheet.getRange(2, activeColIdx, lastCatRow - 1, 1).setDataValidation(rule);
    if (reviewColIdx > 0) origSheet.getRange(2, reviewColIdx, lastCatRow - 1, 1).setDataValidation(rule);
  }

  var accTabName = "🏦 Account Registry";
  var accSheet = ss.getSheetByName(accTabName);
  var accountRegistryCreated = false;
  if (!accSheet) {
    accSheet = ss.insertSheet(accTabName);
    accountRegistryCreated = true;
  } else {
    accSheet.clear();
  }

  var accHeaders = ['active', 'account_id', 'account_name', 'aliases', 'parent_account', 'pocket_name', 'account_type', 'dashboard_group', 'font_color_hex', 'fill_color_hex', 'display_order', 'provider', 'is_cash', 'is_bank', 'is_credit', 'notes'];
  accSheet.getRange(1, 1, 1, accHeaders.length).setValues([accHeaders]);
  accSheet.setFrozenRows(1);

  var designAccounts = payload.accounts || [];
  var accOutputValues = [];
  var accDuplicates = 0;
  var seenAccIds = {};

  var initialColors = {
    "Blu": { font: "#0284C7", fill: "#E0F2FE" },
    "Blu Pocket": { font: "#0891B2", fill: "#CFFAFE" },
    "BCA": { font: "#1E3A8A", fill: "#DBEAFE" },
    "BCA Pocket": { font: "#4338CA", fill: "#E0E7FF" },
    "Cash Umum": { font: "#15803D", fill: "#DCFCE7" },
    "Cash Bensin": { font: "#7A7C00", fill: "#FEF3C7" },
    "Credit Card": { font: "#7E22CE", fill: "#F3E8FF" },
    "Unknown": { font: "#B45309", fill: "#FFEDD5" }
  };

  for (var idx = 0; idx < designAccounts.length; idx++) {
    var accRow = designAccounts[idx];
    var accId = String(accRow.account_id || "").trim();
    if (!accId) continue;

    if (seenAccIds[accId]) {
      accDuplicates++;
      continue;
    }
    seenAccIds[accId] = true;

    var name = accRow.account_name;
    if (initialColors[name]) {
      accRow.font_color_hex = accRow.font_color_hex || initialColors[name].font;
      accRow.fill_color_hex = accRow.fill_color_hex || initialColors[name].fill;
    }

    accOutputValues.push(accHeaders.map(function(h) {
      var val = accRow[h];
      if (typeof val === 'boolean') {
        return val ? 'TRUE' : 'FALSE';
      }
      return val === undefined || val === null ? "" : val;
    }));
  }

  if (accOutputValues.length > 0) {
    accSheet.getRange(2, 1, accOutputValues.length, accHeaders.length).setValues(accOutputValues);
  }

  applySheetFormatting_(accSheet, accHeaders.length);
  var activeAccColIdx = accHeaders.indexOf('active') + 1;
  var isCashColIdx = accHeaders.indexOf('is_cash') + 1;
  var isBankColIdx = accHeaders.indexOf('is_bank') + 1;
  var isCreditColIdx = accHeaders.indexOf('is_credit') + 1;
  var lastAccRow = accSheet.getLastRow();

  if (lastAccRow > 1) {
    var rule = SpreadsheetApp.newDataValidation().requireValueInList(['TRUE', 'FALSE'], true).build();
    if (activeAccColIdx > 0) accSheet.getRange(2, activeAccColIdx, lastAccRow - 1, 1).setDataValidation(rule);
    if (isCashColIdx > 0) accSheet.getRange(2, isCashColIdx, lastAccRow - 1, 1).setDataValidation(rule);
    if (isBankColIdx > 0) accSheet.getRange(2, isBankColIdx, lastAccRow - 1, 1).setDataValidation(rule);
    if (isCreditColIdx > 0) accSheet.getRange(2, isCreditColIdx, lastAccRow - 1, 1).setDataValidation(rule);
  }

  return {
    categoryBackupSheet: backupSheetName,
    categoryRowsBefore: rowsBefore,
    categoryRowsAdded: rowsAdded,
    categoryRowsUpdated: rowsUpdated,
    categoryDuplicates: catDuplicates,
    accountRegistryCreated: accountRegistryCreated,
    accountRowsImported: accOutputValues.length,
    accountDuplicates: accDuplicates
  };
}

function runTask613ApplyAccountRegistryStyleFromEditor() {
  var ss = airoSprint7FSpreadsheet_();
  var registry = airoSprint7AccountContractGetRegistry_();

  var styleMap = {};
  for (var i = 0; i < registry.length; i++) {
    var acc = registry[i];
    styleMap[acc.account_name.toLowerCase()] = {
      font: acc.font_color_hex || '#000000',
      fill: acc.fill_color_hex || '#ffffff'
    };
  }

  var warningStyle = {
    font: '#B45309',
    fill: '#FFEDD5'
  };

  var sheet = getSheetLoose_(ss, "📒 Account Ledger");
  if (!sheet) {
    return { formattedRowsCount: 0, error: "Account Ledger sheet not found" };
  }

  var lastRow = sheet.getLastRow();
  if (lastRow < 2) {
    return { formattedRowsCount: 0 };
  }

  var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0]
    .map(function(h) { return String(h || "").trim().toLowerCase(); });
  var accColIdx = headers.indexOf("account") + 1;
  if (accColIdx === 0) {
    return { formattedRowsCount: 0, error: "Account column not found in Ledger" };
  }

  var accValues = sheet.getRange(2, accColIdx, lastRow - 1, 1).getValues();
  var fontColors = [];
  var fillColors = [];

  for (var r = 0; r < accValues.length; r++) {
    var accName = String(accValues[r][0] || "").trim();
    var style = styleMap[accName.toLowerCase()] || warningStyle;
    fontColors.push([style.font]);
    fillColors.push([style.fill]);
  }

  var targetRange = sheet.getRange(2, accColIdx, lastRow - 1, 1);
  targetRange.setFontColors(fontColors);
  targetRange.setBackgrounds(fillColors);

  // AIRO_TASK615D_OWNER_STYLE_V1
  function task615DHeaderMap_(targetSheet) {
    var values = targetSheet
      .getRange(1, 1, 1, targetSheet.getLastColumn())
      .getValues()[0];

    var result = {};

    for (var c = 0; c < values.length; c++) {
      var header = String(values[c] || "").trim().toLowerCase();
      if (header) result[header] = c + 1;
    }

    return result;
  }

  function task615DPrepareSheet_(targetSheet, hiddenHeaders, widths) {
    var headerMap = task615DHeaderMap_(targetSheet);
    var targetLastRow = Math.max(targetSheet.getLastRow(), 1);
    var targetLastColumn = targetSheet.getLastColumn();

    targetSheet.showColumns(1, targetLastColumn);

    hiddenHeaders.forEach(function(header) {
      if (headerMap[header]) {
        targetSheet.hideColumns(headerMap[header]);
      }
    });

    Object.keys(widths).forEach(function(header) {
      if (headerMap[header]) {
        targetSheet.setColumnWidth(
          headerMap[header],
          widths[header]
        );
      }
    });

    targetSheet
      .getRange(1, 1, 1, targetLastColumn)
      .setBackground("#0F172A")
      .setFontColor("#FFFFFF")
      .setFontWeight("bold")
      .setHorizontalAlignment("center")
      .setVerticalAlignment("middle")
      .setWrap(true);

    targetSheet.setRowHeight(1, 36);
    targetSheet.setFrozenRows(1);

    if (targetSheet.getFilter()) {
      targetSheet.getFilter().remove();
    }

    targetSheet
      .getRange(1, 1, targetLastRow, targetLastColumn)
      .createFilter();

    if (targetLastRow > 1) {
      targetSheet
        .getRange(2, 1, targetLastRow - 1, targetLastColumn)
        .setFontFamily("Arial")
        .setFontSize(10)
        .setVerticalAlignment("middle")
        .setWrap(false);

      targetSheet.setRowHeights(
        2,
        targetLastRow - 1,
        28
      );
    }

    return {
      headerMap: headerMap,
      lastRow: targetLastRow,
      lastColumn: targetLastColumn
    };
  }

  function task615DStyleAccountColumn_(
    targetSheet,
    accountColumn,
    targetLastRow
  ) {
    if (!accountColumn || targetLastRow < 2) {
      return {
        formatted: 0,
        registry: 0,
        transfer: 0,
        warning: 0
      };
    }

    var values = targetSheet
      .getRange(2, accountColumn, targetLastRow - 1, 1)
      .getValues();

    var fonts = [];
    var fills = [];

    var counts = {
      formatted: values.length,
      registry: 0,
      transfer: 0,
      warning: 0
    };

    for (var rowIndex = 0; rowIndex < values.length; rowIndex++) {
      var rawAccount = String(values[rowIndex][0] || "").trim();
      var isTransfer = rawAccount.indexOf("->") >= 0;

      var lookupName = isTransfer
        ? rawAccount.split("->")[0].trim()
        : rawAccount;

      if (lookupName.toLowerCase() === "cash") {
        lookupName = "Cash Umum";
      }

      var resolvedStyle =
        styleMap[lookupName.toLowerCase()] ||
        warningStyle;

      if (isTransfer) {
        fonts.push([resolvedStyle.font]);
        fills.push(["#F1F5F9"]);
        counts.transfer++;
      } else {
        fonts.push([resolvedStyle.font]);
        fills.push([resolvedStyle.fill]);

        if (styleMap[lookupName.toLowerCase()]) {
          counts.registry++;
        } else {
          counts.warning++;
        }
      }
    }

    targetSheet
      .getRange(2, accountColumn, targetLastRow - 1, 1)
      .setFontColors(fonts)
      .setBackgrounds(fills)
      .setFontWeight("bold")
      .setHorizontalAlignment("center");

    return counts;
  }

  var ledgerSetup = task615DPrepareSheet_(
    sheet,
    [
      "entry_id",
      "raw_text",
      "source_tab",
      "linked_txn_id",
      "notes"
    ],
    {
      date: 115,
      account: 165,
      amount_in: 125,
      amount_out: 125,
      balance: 130,
      type: 155,
      category: 180,
      subcategory: 180,
      description: 280
    }
  );

  var ledgerHeaders = ledgerSetup.headerMap;

  if (ledgerSetup.lastRow > 1) {
    if (ledgerHeaders.date) {
      sheet
        .getRange(
          2,
          ledgerHeaders.date,
          ledgerSetup.lastRow - 1,
          1
        )
        .setNumberFormat("dd/mm/yyyy")
        .setHorizontalAlignment("center");
    }

    ["amount_in", "amount_out", "balance"].forEach(function(header) {
      if (ledgerHeaders[header]) {
        sheet
          .getRange(
            2,
            ledgerHeaders[header],
            ledgerSetup.lastRow - 1,
            1
          )
          .setNumberFormat('"Rp" #,##0;[Red]-"Rp" #,##0')
          .setHorizontalAlignment("right");
      }
    });

    if (ledgerHeaders.balance) {
      sheet
        .getRange(
          2,
          ledgerHeaders.balance,
          ledgerSetup.lastRow - 1,
          1
        )
        .setFontWeight("bold");
    }

    if (ledgerHeaders.type) {
      sheet
        .getRange(
          2,
          ledgerHeaders.type,
          ledgerSetup.lastRow - 1,
          1
        )
        .setHorizontalAlignment("center");
    }

    if (ledgerHeaders.description) {
      sheet
        .getRange(
          2,
          ledgerHeaders.description,
          ledgerSetup.lastRow - 1,
          1
        )
        .setWrap(true);
    }
  }

  var ledgerStyleResult = task615DStyleAccountColumn_(
    sheet,
    ledgerHeaders.account,
    ledgerSetup.lastRow
  );

  var financeSheet = getSheetLoose_(
    ss,
    AIRO_CONFIG.tabs.financeEvents
  );

  if (!financeSheet) {
    return {
      ok: false,
      status: "TASK_615D_FINANCE_EVENTS_NOT_FOUND"
    };
  }

  var financeSetup = task615DPrepareSheet_(
    financeSheet,
    [
      "event_id",
      "event_source",
      "source_tab",
      "source_row",
      "linked_txn_id",
      "reason",
      "payload_json",
      "notes"
    ],
    {
      event_ts: 115,
      event_type: 155,
      account: 195,
      category: 180,
      subcategory: 180,
      amount: 125,
      direction: 100,
      status: 120
    }
  );

  var financeHeaders = financeSetup.headerMap;

  if (financeSetup.lastRow > 1) {
    if (financeHeaders.event_ts) {
      financeSheet
        .getRange(
          2,
          financeHeaders.event_ts,
          financeSetup.lastRow - 1,
          1
        )
        .setNumberFormat("dd/mm/yyyy")
        .setHorizontalAlignment("center");
    }

    if (financeHeaders.amount) {
      financeSheet
        .getRange(
          2,
          financeHeaders.amount,
          financeSetup.lastRow - 1,
          1
        )
        .setNumberFormat('"Rp" #,##0;[Red]-"Rp" #,##0')
        .setHorizontalAlignment("right")
        .setFontWeight("bold");
    }

    ["event_type", "direction", "status"].forEach(function(header) {
      if (financeHeaders[header]) {
        financeSheet
          .getRange(
            2,
            financeHeaders[header],
            financeSetup.lastRow - 1,
            1
          )
          .setHorizontalAlignment("center");
      }
    });
  }

  var financeStyleResult = task615DStyleAccountColumn_(
    financeSheet,
    financeHeaders.account,
    financeSetup.lastRow
  );

  if (financeHeaders.status && financeSetup.lastRow > 1) {
    var statusRange = financeSheet.getRange(
      2,
      financeHeaders.status,
      financeSetup.lastRow - 1,
      1
    );

    var statusValues = statusRange.getValues();
    var statusFonts = [];
    var statusFills = [];

    statusValues.forEach(function(statusRow) {
      var status = String(statusRow[0] || "").trim().toLowerCase();
      var font = "#475569";
      var fill = "#F1F5F9";

      if (status === "ok") {
        font = "#166534";
        fill = "#DCFCE7";
      } else if (status === "needs_review") {
        font = "#92400E";
        fill = "#FEF3C7";
      } else if (status === "failed") {
        font = "#991B1B";
        fill = "#FEE2E2";
      } else if (status === "ignored") {
        font = "#475569";
        fill = "#E2E8F0";
      }

      statusFonts.push([font]);
      statusFills.push([fill]);
    });

    statusRange
      .setFontColors(statusFonts)
      .setBackgrounds(statusFills)
      .setFontWeight("bold");
  }

  var result = {
    ok: true,
    status: "TASK_615D_STYLING_COMPLETE",
    account_ledger: {
      formattedRowsCount: ledgerStyleResult.formatted,
      accountStyle: ledgerStyleResult,
      filterPresent: !!sheet.getFilter(),
      frozenRows: sheet.getFrozenRows()
    },
    finance_events: {
      formattedRowsCount: financeStyleResult.formatted,
      accountStyle: financeStyleResult,
      filterPresent: !!financeSheet.getFilter(),
      frozenRows: financeSheet.getFrozenRows()
    },
    valuesModified: false,
    formattingModified: true,
    gmailModified: false,
    triggerChanged: false,
    deploymentChanged: false,
    dashboardChanged: false
  };

  Logger.log(JSON.stringify(result));
  return result;
}

// === RECOVERY INVENTORY CODE ===
function runTask613CRecoveryInventoryFromEditor() {
  var result = {
    ok: true,
    mode: "task_613c_recovery_inventory",
    write_performed: false,
    sheet_rename_performed: false,
    sheet_delete_performed: false,
    registry_merge_performed: false,
    gmail_modified: false,
    trigger_changed: false,
    sheets: [],
    canonical_category_registry: {},
    imported_category_registry: {},
    canonical_account_registry: {},
    imported_account_registry: {},
    finance_events_ux_spec: {},
    conflicts: []
  };

  try {
    var ss = airoSprint7FSpreadsheet_();
    if (!ss) {
      throw new Error("Spreadsheet resolver returned null/undefined");
    }

    var sheets = ss.getSheets();
    for (var i = 0; i < sheets.length; i++) {
      var sheet = sheets[i];
      var name = sheet.getName();

      var lastCol = sheet.getLastColumn();
      var lastRow = sheet.getLastRow();
      var headers = [];
      if (lastCol > 0) {
        try {
          headers = sheet.getRange(1, 1, 1, lastCol).getValues()[0].map(function(h) {
            return String(h || "").trim();
          });
        } catch (e) {
          headers = [];
        }
      }

      var info = {
        name: name,
        sheetId: sheet.getSheetId(),
        lastRow: lastRow,
        lastColumn: lastCol,
        headers: headers,
        isHidden: sheet.isSheetHidden(),
        frozenRows: sheet.getFrozenRows(),
        filterPresent: sheet.getFilter() !== null
      };

      result.sheets.push(info);

      // Categorize and analyze category registry sheets (canonical, imported (1), backups)
      var isCatCanonical = (name === "📚 Category Registry");
      var isCatImported = (name === "📚 Category Registry (1)");
      var isCatBackup = (name.indexOf("Category Registry") !== -1 && !isCatCanonical && !isCatImported);

      if (isCatCanonical || isCatImported || isCatBackup) {
        var catInfo = analyzeCategoryRegistrySheet_(sheet, headers);
        if (isCatCanonical) {
          result.canonical_category_registry = catInfo;
        } else if (isCatImported) {
          result.imported_category_registry = catInfo;
        }
        if (catInfo.duplicates.length > 0) {
          result.conflicts.push("Sheet [" + name + "] has duplicate keys: " + JSON.stringify(catInfo.duplicates));
        }
      }

      // Categorize and analyze account registry sheets (canonical, imported (1), backups)
      var isAccCanonical = (name === "🏦 Account Registry");
      var isAccImported = (name === "🏦 Account Registry (1)");
      var isAccBackup = (name.indexOf("Account Registry") !== -1 && !isAccCanonical && !isAccImported);

      if (isAccCanonical || isAccImported || isAccBackup) {
        var accInfo = analyzeAccountRegistrySheet_(sheet, headers);
        if (isAccCanonical) {
          result.canonical_account_registry = accInfo;
        } else if (isAccImported) {
          result.imported_account_registry = accInfo;
        }
        if (accInfo.duplicates.length > 0) {
          result.conflicts.push("Sheet [" + name + "] has duplicate account IDs: " + JSON.stringify(accInfo.duplicates));
        }
      }

      // Specifically identify 📌 Finance Events UX Spec
      if (name === "📌 Finance Events UX Spec") {
        result.finance_events_ux_spec = {
          name: name,
          sheetId: sheet.getSheetId(),
          lastRow: lastRow,
          lastColumn: lastCol,
          headers: headers,
          isHidden: sheet.isSheetHidden(),
          frozenRows: sheet.getFrozenRows(),
          filterPresent: sheet.getFilter() !== null
        };
      }
    }

    // Compare Category Registry canonical vs imported
    var catCanon = result.canonical_category_registry;
    var catImport = result.imported_category_registry;
    if (catCanon.name && catImport.name) {
      if (catCanon.rowCount !== catImport.rowCount) {
        result.conflicts.push("Category Registry row count mismatch: canonical=" + catCanon.rowCount + ", imported=" + catImport.rowCount);
      }

      var canonHeadersStr = JSON.stringify(catCanon.headers.map(function(h) { return h.toLowerCase(); }));
      var importHeadersStr = JSON.stringify(catImport.headers.map(function(h) { return h.toLowerCase(); }));
      if (canonHeadersStr !== importHeadersStr) {
        result.conflicts.push("Category Registry headers mismatch: canonical=" + JSON.stringify(catCanon.headers) + ", imported=" + JSON.stringify(catImport.headers));
      }

      // Key differences
      var canonKeys = catCanon.keys || [];
      var importKeys = catImport.keys || [];

      var missingInImport = [];
      for (var k = 0; k < canonKeys.length; k++) {
        if (importKeys.indexOf(canonKeys[k]) === -1) {
          missingInImport.push(canonKeys[k]);
        }
      }
      if (missingInImport.length > 0) {
        result.conflicts.push("Category keys present in canonical but missing in imported: " + JSON.stringify(missingInImport));
      }

      var extraInImport = [];
      for (var k = 0; k < importKeys.length; k++) {
        if (canonKeys.indexOf(importKeys[k]) === -1) {
          extraInImport.push(importKeys[k]);
        }
      }
      if (extraInImport.length > 0) {
        result.conflicts.push("Category keys present in imported but missing in canonical: " + JSON.stringify(extraInImport));
      }
    } else {
      if (!catCanon.name) {
        result.conflicts.push("Canonical sheet [📚 Category Registry] is missing.");
      }
      if (!catImport.name) {
        result.conflicts.push("Imported sheet [📚 Category Registry (1)] is missing.");
      }
    }

    // Compare Account Registry canonical vs imported
    var accCanon = result.canonical_account_registry;
    var accImport = result.imported_account_registry;
    if (accCanon.name && accImport.name) {
      if (accCanon.rowCount !== accImport.rowCount) {
        result.conflicts.push("Account Registry row count mismatch: canonical=" + accCanon.rowCount + ", imported=" + accImport.rowCount);
      }

      var canonHeadersStr = JSON.stringify(accCanon.headers.map(function(h) { return h.toLowerCase(); }));
      var importHeadersStr = JSON.stringify(accImport.headers.map(function(h) { return h.toLowerCase(); }));
      if (canonHeadersStr !== importHeadersStr) {
        result.conflicts.push("Account Registry headers mismatch: canonical=" + JSON.stringify(accCanon.headers) + ", imported=" + JSON.stringify(accImport.headers));
      }

      // Key differences
      var canonIds = accCanon.accountIds || [];
      var importIds = accImport.accountIds || [];

      var missingInImport = [];
      for (var k = 0; k < canonIds.length; k++) {
        if (importIds.indexOf(canonIds[k]) === -1) {
          missingInImport.push(canonIds[k]);
        }
      }
      if (missingInImport.length > 0) {
        result.conflicts.push("Account IDs present in canonical but missing in imported: " + JSON.stringify(missingInImport));
      }

      var extraInImport = [];
      for (var k = 0; k < importIds.length; k++) {
        if (canonIds.indexOf(importIds[k]) === -1) {
          extraInImport.push(importIds[k]);
        }
      }
      if (extraInImport.length > 0) {
        result.conflicts.push("Account IDs present in imported but missing in canonical: " + JSON.stringify(extraInImport));
      }
    } else {
      if (!accCanon.name) {
        result.conflicts.push("Canonical sheet [🏦 Account Registry] is missing.");
      }
      if (!accImport.name) {
        result.conflicts.push("Imported sheet [🏦 Account Registry (1)] is missing.");
      }
    }

  } catch (err) {
    result.ok = false;
    result.error = err.toString();
    result.conflicts.push("Execution error: " + err.toString());
  }

  var jsonStr = JSON.stringify(result, null, 2);
  Logger.log(jsonStr);
  return result;
}

function analyzeCategoryRegistrySheet_(sheet, headers) {
  var lastRow = sheet.getLastRow();
  var lastCol = sheet.getLastColumn();

  var headersLower = headers.map(function(h) { return String(h || "").trim().toLowerCase(); });
  var catCol = headersLower.indexOf("category");
  var subCol = headersLower.indexOf("subcategory");

  var duplicates = [];
  var seenKeys = {};
  var keysList = [];
  var totalRows = 0;

  if (lastRow > 1 && catCol !== -1) {
    var vals = sheet.getRange(2, 1, lastRow - 1, lastCol).getValues();
    for (var i = 0; i < vals.length; i++) {
      var row = vals[i];
      var cat = String(row[catCol] || "").trim();
      var sub = subCol !== -1 ? String(row[subCol] || "").trim() : "";

      if (!cat) continue; // skip notes or empty rows
      totalRows++;

      var key = (cat + "|" + sub).toLowerCase();
      if (seenKeys[key]) {
        duplicates.push({
          row: i + 2,
          category: cat,
          subcategory: sub,
          key: key
        });
      } else {
        seenKeys[key] = i + 2;
      }
      if (keysList.indexOf(key) === -1) {
        keysList.push(key);
      }
    }
  }

  return {
    name: sheet.getName(),
    sheetId: sheet.getSheetId(),
    rowCount: lastRow,
    dataRowCount: totalRows,
    headers: headers,
    keys: keysList,
    duplicates: duplicates
  };
}

function analyzeAccountRegistrySheet_(sheet, headers) {
  var lastRow = sheet.getLastRow();
  var lastCol = sheet.getLastColumn();

  var headersLower = headers.map(function(h) { return String(h || "").trim().toLowerCase(); });
  var accIdCol = headersLower.indexOf("account_id");

  var duplicates = [];
  var seenIds = {};
  var idsList = [];
  var totalRows = 0;

  if (lastRow > 1 && accIdCol !== -1) {
    var vals = sheet.getRange(2, 1, lastRow - 1, lastCol).getValues();
    for (var i = 0; i < vals.length; i++) {
      var row = vals[i];
      var accId = String(row[accIdCol] || "").trim();

      if (!accId) continue; // skip notes or empty rows
      totalRows++;

      var key = accId.toLowerCase();
      if (seenIds[key]) {
        duplicates.push({
          row: i + 2,
          accountId: accId
        });
      } else {
        seenIds[key] = i + 2;
      }
      if (idsList.indexOf(key) === -1) {
        idsList.push(key);
      }
    }
  }

  return {
    name: sheet.getName(),
    sheetId: sheet.getSheetId(),
    rowCount: lastRow,
    dataRowCount: totalRows,
    headers: headers,
    accountIds: idsList,
    duplicates: duplicates
  };
}

// AIRO_TASK614_WSL_ARM_WRAPPER_V1
function runTask614ArmDirectApprovalFromWsl(
  chatId,
  queueId,
  targetRow
) {
  var stored = airoTask614StoreDirectApproval_(
    String(chatId || ""),
    String(queueId || ""),
    Number(targetRow || 0)
  );

  var result = {
    ok: stored === true,
    mode: "task_614_arm_direct_approval_from_wsl",
    chat_id: String(chatId || ""),
    queue_id: String(queueId || ""),
    target_row: Number(targetRow || 0),
    property_stored: stored === true,
    workbook_write_performed: false,
    gmail_modified: false,
    trigger_changed: false
  };

  Logger.log(JSON.stringify(result));
  return result;
}

// AIRO_TASK614_WSL_CLEAR_STATE_V1
function runTask614ClearApprovalStateFromWsl(chatId) {
  chatId = String(chatId || "").trim();

  if (!chatId) {
    return {
      ok: false,
      mode: "task_614_clear_approval_state",
      error: "chat_id_missing",
      property_delete_performed: false
    };
  }

  var properties = PropertiesService.getScriptProperties();

  var directKey =
    airoTask614DirectApprovalPropertyKey_(chatId);

  var snapshotKey =
    airoTask614SnapshotPropertyKey_(chatId);

  var directBefore =
    properties.getProperty(directKey);

  var snapshotBefore =
    properties.getProperty(snapshotKey);

  properties.deleteProperty(directKey);
  properties.deleteProperty(snapshotKey);

  var result = {
    ok:
      properties.getProperty(directKey) === null &&
      properties.getProperty(snapshotKey) === null,

    mode: "task_614_clear_approval_state",
    chat_id: chatId,

    direct_property_existed:
      directBefore !== null,

    snapshot_property_existed:
      snapshotBefore !== null,

    direct_property_cleared:
      properties.getProperty(directKey) === null,

    snapshot_property_cleared:
      properties.getProperty(snapshotKey) === null,

    property_delete_performed: true,
    workbook_write_performed: false,
    gmail_modified: false,
    trigger_changed: false
  };

  Logger.log(JSON.stringify(result));
  return result;
}

// AIRO_TASK7_READ_ONLY_WRAPPER_V1
function runTask7BaselineReadOnlyFromEditor(mode) {
  var ss = typeof airoSprint7FSpreadsheet_ === "function"
    ? airoSprint7FSpreadsheet_()
    : SpreadsheetApp.getActiveSpreadsheet();

  mode = String(mode || "dashboard_v2").trim();
  var result;

  if (mode === "layout") {
    result = dashboardLayoutReadOnlyAudit_(ss);
  } else if (mode === "dashboard_final") {
    result = airoSprint6DashboardFinalReadback_(ss);
  } else if (mode === "reconciliation") {
    result = airoSprint5ReconciliationReadOnly_(
      ss,
      { sampleLimit: 8 }
    );
  } else if (mode === "dashboard_v2") {
    result = airoSprint6DashboardV2Readback_(ss);
  } else {
    throw new Error("Unsupported Task 7 mode: " + mode);
  }

  return {
    ok: true,
    task: "7",
    mode: mode,
    result: result,
    write_performed: false,
    workbook_modified: false,
    gmail_modified: false,
    trigger_changed: false
  };
}

function runTask8TransferRegistrySelfTestFromEditor() {
  var results = [];
  var passed = true;

  // Case 1: transfer 25rb dr pocket blu ke blu
  var text1 = "transfer 25rb dr pocket blu ke blu";
  var parsed1 = { amount: parseAmount_(text1) };
  var res1 = detectInternalTransfer_(parsed1, text1);
  var tc1 = (parsed1.amount === 25000 && res1 && res1.sourceAccount === "Blu Pocket" && res1.targetAccount === "Blu");
  results.push({ test: 'transfer 25rb dr pocket blu ke blu', passed: tc1, result: { amount: parsed1.amount, route: res1 } });
  if (!tc1) passed = false;

  // Case 2: transfer 25rb dari blu pocket ke blu
  var text2 = "transfer 25rb dari blu pocket ke blu";
  var parsed2 = { amount: parseAmount_(text2) };
  var res2 = detectInternalTransfer_(parsed2, text2);
  var tc2 = (parsed2.amount === 25000 && res2 && res2.sourceAccount === "Blu Pocket" && res2.targetAccount === "Blu");
  results.push({ test: 'transfer 25rb dari blu pocket ke blu', passed: tc2, result: { amount: parsed2.amount, route: res2 } });
  if (!tc2) passed = false;

  // Case 3: transfer 10rb dari pocket bca ke bca
  var text3 = "transfer 10rb dari pocket bca ke bca";
  var parsed3 = { amount: parseAmount_(text3) };
  var res3 = detectInternalTransfer_(parsed3, text3);
  var tc3 = (parsed3.amount === 10000 && res3 && res3.sourceAccount === "BCA Pocket" && res3.targetAccount === "BCA");
  results.push({ test: 'transfer 10rb dari pocket bca ke bca', passed: tc3, result: { amount: parsed3.amount, route: res3 } });
  if (!tc3) passed = false;

  // Case 4: transfer 50rb dari cash ke bca
  var text4 = "transfer 50rb dari cash ke bca";
  var parsed4 = { amount: parseAmount_(text4) };
  var res4 = detectInternalTransfer_(parsed4, text4);
  var tc4 = (parsed4.amount === 50000 && res4 === null);
  results.push({ test: 'transfer 50rb dari cash ke bca (ambiguous)', passed: tc4, result: { amount: parsed4.amount, route: res4 } });
  if (!tc4) passed = false;

  // Case 5: old hardcoded route menu is not primary
  var msg = buildTransferIncompleteClarificationMessage_({ amount: 10000 });
  var tc5 = (msg.indexOf("A. BCA → Blu") === -1 && msg.indexOf("BCA → Blu") !== -1);
  results.push({ test: 'old hardcoded route menu is not primary', passed: tc5, result: msg });
  if (!tc5) passed = false;

  // Case 6: Finance Events remains no-op
  var feResult = null;
  var tc6 = false;
  try {
    feResult = writeFinanceEvent_(null, {});
    tc6 = (feResult && feResult.ok === true && feResult.finance_events_write_performed === false && feResult.deprecated === true);
  } catch(e) {
    feResult = e.toString();
  }
  results.push({ test: 'writeFinanceEvent_ is no-op/deprecated', passed: tc6, result: feResult });
  if (!tc6) passed = false;

  return {
    ok: passed,
    results: results,
    telegram_send_performed: false,
    gmail_modified: false,
    workbook_write_performed: false,
    deploy_performed: false
  };
}

// AIRO_TASK10_DASHBOARD_GOVERNANCE_REPAIR_START
function airoTask10GetSs_() {
  return SpreadsheetApp.openById(getProp_('SPREADSHEET_ID'));
}

function airoTask10Norm_(v) {
  return String(v || '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function airoTask10FindSheet_(ss, base, opts) {
  opts = opts || {};
  var b = airoTask10Norm_(base);
  var sheets = ss.getSheets();
  var found = [];
  for (var i = 0; i < sheets.length; i++) {
    var sh = sheets[i];
    var n = sh.getName();
    var nn = airoTask10Norm_(n);
    if (nn.indexOf(b) === -1) continue;
    if (opts.visibleOnly && sh.isSheetHidden()) continue;
    if (opts.excludeV2 && nn.indexOf('v2') >= 0) continue;
    if (opts.excludeBackup && (nn.indexOf('backup') >= 0 || nn.indexOf('pre promote') >= 0 || nn.indexOf('template') >= 0 || nn.indexOf('copy of') >= 0)) continue;
    found.push(sh);
  }
  return found.length ? found[found.length - 1] : null;
}

function airoTask10SheetRef_(sh) {
  return "'" + sh.getName().replace(/'/g, "''") + "'";
}

function airoTask10HeaderMap_(sh) {
  var lastCol = Math.max(1, sh.getLastColumn());
  var headers = sh.getRange(1, 1, 1, lastCol).getDisplayValues()[0];
  var map = {};
  for (var i = 0; i < headers.length; i++) {
    var key = String(headers[i] || '').toLowerCase().trim().replace(/\s+/g, '_');
    if (key) map[key] = i + 1;
  }
  return map;
}

function airoTask10ReadLedger_(ledger) {
  var h = airoTask10HeaderMap_(ledger);
  var lastRow = ledger.getLastRow();
  if (lastRow < 2) return { rows: [], headers: h };
  var values = ledger.getRange(2, 1, lastRow - 1, ledger.getLastColumn()).getValues();
  var rows = [];
  for (var i = 0; i < values.length; i++) {
    var r = values[i];
    var entry = h.entry_id ? r[h.entry_id - 1] : '';
    var date = h.date ? r[h.date - 1] : '';
    var account = h.account ? r[h.account - 1] : '';
    var typ = h.type ? r[h.type - 1] : '';
    if (!entry && !date && !account && !typ) continue;
    rows.push({
      row_index: i + 2,
      entry_id: entry,
      date: date,
      account: String(account || '').trim(),
      amount_in: Number(h.amount_in ? r[h.amount_in - 1] || 0 : 0),
      amount_out: Number(h.amount_out ? r[h.amount_out - 1] || 0 : 0),
      balance: Number(h.balance ? r[h.balance - 1] || 0 : 0),
      type: String(typ || '').trim(),
      category: String(h.category ? r[h.category - 1] || '' : '').trim(),
      subcategory: String(h.subcategory ? r[h.subcategory - 1] || '' : '').trim()
    });
  }
  return { rows: rows, headers: h };
}

function airoTask10DateOnly_(d) {
  if (Object.prototype.toString.call(d) === '[object Date]' && !isNaN(d.getTime())) {
    return new Date(d.getFullYear(), d.getMonth(), d.getDate());
  }
  var parsed = new Date(d);
  if (!isNaN(parsed.getTime())) return new Date(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
  return null;
}

function airoTask10LatestLedgerDate_(rows) {
  var latest = null;
  rows.forEach(function(r) {
    var d = airoTask10DateOnly_(r.date);
    if (d && (!latest || d.getTime() > latest.getTime())) latest = d;
  });
  return latest;
}

function airoTask10PeriodFromDashboard_(dashboard, latest) {
  var m3 = airoTask10DateOnly_(dashboard.getRange('M3').getValue());
  var m4 = airoTask10DateOnly_(dashboard.getRange('M4').getValue());
  if (m3 && m4) return { start: m3, end: m4 };
  var base = latest || new Date();
  return {
    start: new Date(base.getFullYear(), base.getMonth(), 1),
    end: new Date(base.getFullYear(), base.getMonth() + 1, 0)
  };
}

function airoTask10Bar_(share) {
  var n = Math.max(0, Math.min(10, Math.round(Number(share || 0) * 10)));
  return Array(n + 1).join('█') + Array(10 - n + 1).join('░');
}

function airoTask10BuildSpending_(rows, period) {
  var byCat = {};
  var total = 0;
  rows.forEach(function(r) {
    var d = airoTask10DateOnly_(r.date);
    if (!d || d < period.start || d > period.end) return;
    if (String(r.type).toLowerCase() !== 'expense') return;
    var cat = r.category || 'Others';
    var amt = Math.abs(Number(r.amount_out || 0));
    byCat[cat] = (byCat[cat] || 0) + amt;
    total += amt;
  });
  var sorted = Object.keys(byCat).map(function(k) { return [k, byCat[k]]; })
    .sort(function(a, b) { return b[1] - a[1]; });
  var top = sorted.slice(0, 5);
  var others = sorted.slice(5).reduce(function(s, x) { return s + x[1]; }, 0);
  if (others > 0) top.push(['Others', others]);
  return { total: total, rows: top };
}

function airoTask10RegistryRows_(registry) {
  if (!registry) return [];
  var h = airoTask10HeaderMap_(registry);
  var lastRow = registry.getLastRow();
  if (lastRow < 2) return [];
  var values = registry.getRange(2, 1, lastRow - 1, registry.getLastColumn()).getValues();
  var out = [];
  for (var i = 0; i < values.length; i++) {
    var r = values[i];
    var joined = r.join(' ');
    if (!joined || /CARA MENAMBAH/i.test(joined)) continue;
    var activeRaw = h.active ? r[h.active - 1] : '';
    var name = h.account_name ? String(r[h.account_name - 1] || '').trim() : '';
    var active = activeRaw === true || String(activeRaw).toLowerCase() === 'true' || String(activeRaw) === '1';
    var display = h.display_order ? Number(r[h.display_order - 1] || 999) : 999;
    var malformed = !name || isNaN(display);
    out.push({ name: name, active: active, display_order: display, malformed: malformed });
  }
  return out.sort(function(a, b) { return a.display_order - b.display_order || a.name.localeCompare(b.name); });
}

function airoTask10AccountPanel_(rows, registryRows) {
  var latestByAccount = {};
  rows.forEach(function(r) {
    if (!r.account) return;
    latestByAccount[r.account] = r;
  });
  var known = {};
  var out = [];
  registryRows.forEach(function(a) {
    if (!a.name) return;
    known[a.name] = true;
    var lr = latestByAccount[a.name];
    var bal = lr ? Number(lr.balance || 0) : 0;
    var status = a.malformed ? 'UNKNOWN / registry malformed' :
      (!a.active ? 'HIDDEN' : (lr || bal !== 0 ? 'ACTIVE' : 'DORMANT'));
    out.push([a.name, bal, status === 'ACTIVE' ? 'aktif' : status.toLowerCase(), status]);
  });
  Object.keys(latestByAccount).sort().forEach(function(name) {
    if (!known[name]) {
      out.push([name, Number(latestByAccount[name].balance || 0), 'unknown', 'UNKNOWN / missing registry']);
    }
  });
  return out;
}

function airoTask10FormulaRefCount_(ss, sheetName) {
  var count = 0;
  ss.getSheets().forEach(function(sh) {
    var formulas = sh.getDataRange().getFormulas();
    for (var r = 0; r < formulas.length; r++) {
      for (var c = 0; c < formulas[r].length; c++) {
        if (formulas[r][c] && formulas[r][c].indexOf(sheetName) >= 0) count++;
      }
    }
  });
  return count;
}

function airoTask10CleanupTabs_(ss, backupCreated) {
  var logs = [];
  var deleted = [];
  var hidden = [];

  var primaryBases = [
    'Dashboard', 'Account Ledger', 'Review Queue', 'Credit Card', 'Hutang',
    'Cicilan Rumah', 'Aset', 'Monthly Review', 'Account Registry',
    'Category Registry', 'Settings'
  ];

  primaryBases.forEach(function(base, idx) {
    var sh = airoTask10FindSheet_(ss, base, { visibleOnly: false, excludeV2: base === 'Dashboard', excludeBackup: true });
    if (sh) {
      try { sh.showSheet(); } catch (e) {}
      try { ss.setActiveSheet(sh); ss.moveActiveSheet(idx + 1); } catch (e) {}
      logs.push('visible_order:' + base + ':' + sh.getName());
    }
  });

  ss.getSheets().forEach(function(sh) {
    var n = sh.getName();
    var nn = airoTask10Norm_(n);
    var isMainDash = nn.indexOf('dashboard') >= 0 && nn.indexOf('v2') < 0 && nn.indexOf('backup') < 0 && nn.indexOf('pre promote') < 0 && nn.indexOf('copy of') < 0;
    var mustKeepVisible = primaryBases.some(function(base) {
      var b = airoTask10Norm_(base);
      if (base === 'Dashboard') return isMainDash;
      return nn.indexOf(b) >= 0 && nn.indexOf('backup') < 0 && nn.indexOf('legacy') < 0 && nn.indexOf('spec') < 0;
    });
    var shouldHide =
      nn.indexOf('finance events') >= 0 ||
      nn.indexOf('dashboard v2') >= 0 ||
      nn.indexOf('legacy') >= 0 ||
      nn.indexOf('smoke archive') >= 0 ||
      nn.indexOf('dry run') >= 0 ||
      nn.indexOf('pack2 audit temp') >= 0 ||
      nn.indexOf('backup') >= 0 ||
      nn === 'readme' ||
      nn.indexOf('ux spec') >= 0;

    if (shouldHide && !mustKeepVisible) {
      try { sh.hideSheet(); hidden.push(n); } catch (e) { logs.push('hide_failed:' + n + ':' + e.message); }
    }
  });

  var deleteAllow = [
    /^_AIRO_Dashboard_Backup_20260526$/,
    /^_AIRO_Dashboard_Backup_20260530$/,
    /^_AIRO_Dashboard_Backup_20260531$/,
    /^Sheet[3-9]$/,
    /Category Registry LEGACY BAC/,
    /^Copy of .*Dashboard v2 1$/,
    /^_AIRO_Dashboard_v2_Approved_202/
  ];

  if (backupCreated) {
    ss.getSheets().slice().forEach(function(sh) {
      var n = sh.getName();
      if (!sh.isSheetHidden()) return;
      var allowed = deleteAllow.some(function(re) { return re.test(n); });
      if (!allowed) return;
      if (airoTask10FormulaRefCount_(ss, n) > 0) {
        logs.push('delete_blocked_formula_ref:' + n);
        return;
      }
      try {
        ss.deleteSheet(sh);
        deleted.push(n);
      } catch (e) {
        logs.push('delete_failed:' + n + ':' + e.message);
      }
    });
  }

  return { logs: logs, hidden: hidden, deleted: deleted };
}

function airoTask10RepairDashboard_(ss) {
  var dashboard = airoTask10FindSheet_(ss, 'Dashboard', { visibleOnly: false, excludeV2: true, excludeBackup: true });
  var ledger = airoTask10FindSheet_(ss, 'Account Ledger', {});
  var registry = airoTask10FindSheet_(ss, 'Account Registry', { excludeBackup: true });
  var review = airoTask10FindSheet_(ss, 'Review Queue', {});
  var financeEvents = airoTask10FindSheet_(ss, 'Finance Events', {});
  if (!dashboard || !ledger) throw new Error('missing dashboard or account ledger');

  dashboard.showSheet();
  ss.setActiveSheet(dashboard);
  ss.moveActiveSheet(1);

  var ledgerData = airoTask10ReadLedger_(ledger);
  var rows = ledgerData.rows;
  var latest = airoTask10LatestLedgerDate_(rows);
  var period = airoTask10PeriodFromDashboard_(dashboard, latest);
  var spending = airoTask10BuildSpending_(rows, period);
  var accounts = airoTask10AccountPanel_(rows, airoTask10RegistryRows_(registry));

  var ledgerRef = airoTask10SheetRef_(ledger);
  var latestStr = 'NO DATA';
  if (latest) {
    try {
      latestStr = Utilities.formatDate(latest, Session.getScriptTimeZone(), 'd MMMM yyyy');
    } catch (eDate) {
      latestStr = String(latest);
    }
  }
  var refreshedStr = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'd MMMM yyyy, HH:mm');
  var b2Value = 'Last ledger update: ' + latestStr + ' | Dashboard refreshed: ' + refreshedStr + ' | Source: Account Ledger | Rows: ' + rows.length;
  dashboard.getRange('B2').setValue(b2Value);

  // Clear and unmerge Wallet & Cashflow range
  dashboard.getRange('B15:E24').clearContent();
  try {
    dashboard.getRange('B15:E24').breakApart();
  } catch (eBreak) {}
  dashboard.getRange('B15:E15').merge().setValue('💳 WALLET & CASHFLOW — dynamic from Account Registry + Account Ledger');
  dashboard.getRange('B16:E16').setValues([['Akun', 'Saldo', 'Group', 'Status']]);

  var accountRows = accounts.slice(0, 8);
  while (accountRows.length < 8) accountRows.push(['', '', '', '']);
  dashboard.getRange(17, 2, accountRows.length, 4).setValues(accountRows);

  var startRow = 27;
  // Clear and unmerge Spending range
  dashboard.getRange('B27:E33').clearContent();
  try {
    dashboard.getRange('B27:E33').breakApart();
  } catch (eBreak) {}
  dashboard.getRange(startRow, 2, 1, 4).setValues([['Kategori', 'Nominal', 'Share', 'Bar']]);
  var spendRows = [];
  spending.rows.forEach(function(x) {
    var share = spending.total ? x[1] / spending.total : 0;
    spendRows.push([x[0], x[1], share, airoTask10Bar_(share)]);
  });
  while (spendRows.length < 6) spendRows.push(['', '', '', '']);
  dashboard.getRange(startRow + 1, 2, 6, 4).setValues(spendRows);

  dashboard.getRange('C17:C24').setNumberFormat('"Rp" #,##0');
  dashboard.getRange('C28:C33').setNumberFormat('"Rp" #,##0');
  dashboard.getRange('D28:D33').setNumberFormat('0.00%');

  // Clear and unmerge Data Quality range
  dashboard.getRange('G24:J33').clearContent();
  try {
    dashboard.getRange('G24:J33').breakApart();
  } catch (eBreak) {}
  dashboard.getRange('G24:J24').merge().setValue('🔍 DATA QUALITY CENTER');
  var pending = 0;
  if (review) {
    var h = airoTask10HeaderMap_(review);
    if (h.review_status && review.getLastRow() > 1) {
      var vals = review.getRange(2, h.review_status, review.getLastRow() - 1, 1).getDisplayValues();
      vals.forEach(function(v) { if (String(v[0]).toLowerCase() === 'pending') pending++; });
    }
  }

  var unknownAccounts = accounts.filter(function(a) { return String(a[3]).indexOf('UNKNOWN') >= 0; }).length;
  var malformed = accounts.filter(function(a) { return String(a[3]).indexOf('malformed') >= 0; }).length;
  var missingCat = rows.filter(function(r) { return String(r.type).toLowerCase() === 'expense' && !r.category; }).length;
  var missingAmt = rows.filter(function(r) { return String(r.type).toLowerCase() === 'expense' && !r.amount_out; }).length;

  var feLast = '';
  if (financeEvents) {
    try {
      var feVals = financeEvents.getDataRange().getValues();
      var feDate = null;
      for (var f = 1; f < feVals.length; f++) {
        var fd = airoTask10DateOnly_(feVals[f][1]);
        if (fd && (!feDate || fd > feDate)) feDate = fd;
      }
      feLast = feDate || '';
    } catch (e) { feLast = 'unknown'; }
  }

  var dq = [
    ['Metric', 'Value', 'Status', 'Notes'],
    ['Ledger rows', rows.length, 'OK', 'real rows only'],
    ['Latest ledger date', latest || '', latest ? 'OK' : 'NO DATA', 'Account Ledger'],
    ['Expense rows missing category', missingCat, missingCat ? 'WARN' : 'OK', 'expense only'],
    ['Expense rows missing amount', missingAmt, missingAmt ? 'WARN' : 'OK', 'expense only'],
    ['Unknown accounts', unknownAccounts, unknownAccounts ? 'WARN' : 'OK', 'ledger/registry mismatch'],
    ['Malformed registry rows', malformed, malformed ? 'WARN' : 'OK', 'registry validation'],
    ['Review Queue pending', pending, pending ? 'WARN' : 'OK', 'manual review'],
    ['Finance Events status', feLast, 'DEPRECATED', 'hidden/no-op historical source']
  ];
  dashboard.getRange(25, 7, dq.length, 4).setValues(dq);

  var findings = [];
  if (latest) findings.push('Top spending: ' + (spending.rows[0] ? spending.rows[0][0] + ' Rp' + Math.round(spending.rows[0][1]).toLocaleString('id-ID') : '-'));
  if (unknownAccounts) findings.push('Unknown account exists: fix Account Registry.');
  if (malformed) findings.push('Malformed Account Registry row exists.');
  if (pending) findings.push('Review Queue pending: ' + pending + ' item.');
  if (!findings.length) findings.push('No actionable insight.');

  // Clear and unmerge Smart Insight range
  dashboard.getRange('G35:J40').clearContent();
  try {
    dashboard.getRange('G35:J40').breakApart();
  } catch (eBreak) {}
  dashboard.getRange('G35:J35').merge().setValue('🧠 SMART INSIGHT — deterministic rules');
  dashboard.getRange('G36:J36').merge().setValue('Engine: deterministic | Window: current dashboard period | Findings: ' + findings.length);
  for (var i = 0; i < Math.min(4, findings.length); i++) {
    dashboard.getRange(37 + i, 7, 1, 4).merge().setValue((i + 1) + '. ' + findings[i]);
  }

  dashboard.getRange('B15:E16').setBackground('#2d2d2d').setFontColor('#ffffff').setFontWeight('bold');
  dashboard.getRange('B27:E27').setBackground('#2d2d2d').setFontColor('#ffffff').setFontWeight('bold');
  dashboard.getRange('G24:J25').setBackground('#2d2d2d').setFontColor('#ffffff').setFontWeight('bold');
  dashboard.getRange('G35:J36').setBackground('#2d2d2d').setFontColor('#ffffff').setFontWeight('bold');
  dashboard.getRange('B17:E24').setBorder(true, true, true, true, true, true);
  dashboard.getRange('B28:E33').setBorder(true, true, true, true, true, true);
  dashboard.getRange('G25:J33').setBorder(true, true, true, true, true, true);
  dashboard.autoResizeColumns(2, 9);

  return {
    dashboard: dashboard.getName(),
    ledger_rows: rows.length,
    latest_ledger_date: latest,
    spending_total: spending.total,
    spending_rows: spending.rows,
    account_rows: accountRows.filter(function(r) { return r[0]; }),
    unknown_accounts: unknownAccounts,
    malformed_registry_rows: malformed,
    pending_review: pending
  };
}

function airoTask10InstallRefreshTrigger_() {
  var handler = 'airoTask10ScheduledDashboardRefresh_';
  var triggers = ScriptApp.getProjectTriggers();
  var exists = false;
  for (var i = 0; i < triggers.length; i++) {
    if (String(triggers[i].getHandlerFunction()) === handler) exists = true;
  }
  if (!exists) {
    ScriptApp.newTrigger(handler).timeBased().everyMinutes(15).create();
  }
  return { handler: handler, exists_or_created: true };
}

