  dashboard.getRange("B5").setFormula('=IF(COUNTIF($C$17:$C$21,"<0")>0,"⊗ Saldo negatif: "&INDEX($B$17:$B$21,MATCH(MIN($C$17:$C$21),$C$17:$C$21,0)),"✓ Clean / No Action Required")');
