function airoGate11bFormulaToSheetLocale_(formula) {
  formula = String(formula || '');
  var out = '';
  var inString = false;
  var arrayDepth = 0;

  for (var i = 0; i < formula.length; i++) {
    var ch = formula.charAt(i);

    if (ch === '"') {
      out += ch;
      if (inString && formula.charAt(i + 1) === '"') {
        out += formula.charAt(i + 1);
        i++;
      } else {
        inString = !inString;
      }
      continue;
    }

    if (!inString) {
      if (ch === '{') {
        arrayDepth++;
      } else if (ch === '}') {
        arrayDepth = Math.max(0, arrayDepth - 1);
      }

      if (ch === ',') {
        out += arrayDepth > 0 ? '\\' : ';';
        continue;
      }
    }

    out += ch;
  }

  return out;
}

function airoGate11bRepairDashboardFormulaLocale_(dashboard) {
  var range = dashboard.getRange('A1:Z41');
  var formulas = range.getFormulas();
  var changed = [];

  for (var r = 0; r < formulas.length; r++) {
    for (var c = 0; c < formulas[r].length; c++) {
      var original = formulas[r][c];
      if (!original) continue;

      var converted = airoGate11bFormulaToSheetLocale_(original);
      if (converted !== original) {
        dashboard.getRange(r + 1, c + 1).setFormula(converted);
        changed.push(dashboard.getRange(r + 1, c + 1).getA1Notation());
      }
    }
  }

  SpreadsheetApp.flush();

  return {
    converted_count: changed.length,
    sample_changed: changed.slice(0, 25)
  };
}


// AIRO_GATE11B_PERMANENT_RENDERER_START
function airoTask11bPermanentDashboardRefresh_(opts) {
  opts = opts || {};
  var dryRun = opts.dryRun !== false;
  var reason = String(opts.reason || 'manual');
  var ss = opts.ss || airoTask101GetSs_();
  var dashboard = airoTask102GetActiveDashboard_(ss);

  var result = {
    ok: false,
    task: 'AIRO_GATE11B_PERMANENT_DASHBOARD_REFRESH',
    dry_run: dryRun,
    reason: reason,
    dashboard_render_performed: false,
    workbook_write_performed: false,
    ledger_domain_mutated: false,
    onedit_connected: false,
    scheduled_refresh_connected: false,
    old_renderer_used: false,
    target_tab: '',
    selected_month: '',
    selected_year: '',
    marker: '',
    final_verdict: 'BLOCKED_UNINITIALIZED'
  };

  if (!dashboard) {
    result.final_verdict = 'BLOCKED_ACTIVE_DASHBOARD_NOT_FOUND';
    result.error = 'active Dashboard missing';
    return result;
  }

  result.target_tab = dashboard.getName();
  result.marker = String(dashboard.getRange('Z1').getDisplayValue()).trim();

  var month = String(dashboard.getRange('G2').getDisplayValue()).trim();
  var year = String(dashboard.getRange('I2').getDisplayValue()).trim();
  var months = airoTask103Months_();

  result.selected_month = month;
  result.selected_year = year;

  if (months.indexOf(month) < 0) {
    result.final_verdict = 'BLOCKED_INVALID_MONTH_FILTER';
    result.error = 'invalid G2 month';
    return result;
  }

  if (!/^(?:19|20)\d{2}$/.test(year)) {
    result.final_verdict = 'BLOCKED_INVALID_YEAR_FILTER';
    result.error = 'invalid I2 year';
    return result;
  }

  result.preflight = {
    z1: result.marker,
    g2: month,
    i2: year,
    has_install_filters: typeof airoTask102InstallFilters_ === 'function',
    has_install_native_formulas: typeof airoTask102InstallNativeFormulas_ === 'function',
    has_refresh_domain_health: typeof airoTask102RefreshDomainHealth_ === 'function'
  };

  if (dryRun) {
    result.ok = true;
    result.final_verdict = 'PASS_GATE11B_PERMANENT_RENDERER_DRYRUN';
    result.note = 'Dry-run only. No workbook write.';
    return result;
  }

  var lock = LockService.getScriptLock();
  if (!lock.tryLock(30000)) {
    result.final_verdict = 'BLOCKED_RENDER_LOCK_BUSY';
    result.error = 'render lock busy';
    return result;
  }

  try {
    airoTask102InstallFilters_(dashboard);
    result.dashboard_lite_render = airoDashboardLiteRender_(ss, dashboard, {
      month: month,
      year: year,
      reason: reason
    });
    result.dashboard_render_performed = !!(result.dashboard_lite_render && result.dashboard_lite_render.ok);
    result.formula_locale_repair = { skipped: true, reason: 'Dashboard Lite renderer does not use legacy native formulas' };
    result.domain_health_refresh = { skipped: true, reason: 'Dashboard Lite reads domain summaries without Domain Health panel' };

    dashboard.getRange('Z2').setValue(new Date());
    dashboard.getRange('Z3').setValue('DASHBOARD_LITE_REFRESH_PASS');
    dashboard.getRange('Z4').setValue(new Date());
    result.b2_topbar = airoGate11bWriteVisibleTopbarB2_(dashboard, reason);
    result.visible_wallet_status_repair = { skipped: true, reason: 'Dashboard Lite anti-scope: no wallet LEVEL/STATUS repair' };

    SpreadsheetApp.flush();

    result.readback = {
      b2: dashboard.getRange('B2').getDisplayValue() || dashboard.getRange('A2').getDisplayValue(),
      g2: dashboard.getRange('G2').getDisplayValue(),
      i2: dashboard.getRange('I2').getDisplayValue(),
      m2: dashboard.getRange('M2').getDisplayValue(),
      m3: dashboard.getRange('M3').getDisplayValue(),
      m4: dashboard.getRange('M4').getDisplayValue(),
      b25: dashboard.getRange('B25').getDisplayValue(),
      c25: dashboard.getRange('C25').getDisplayValue(),
      d25: dashboard.getRange('D25').getDisplayValue(),
      e25: dashboard.getRange('E25').getDisplayValue(),
      g25: dashboard.getRange('G25').getDisplayValue(),
      b34: dashboard.getRange('B34').getDisplayValue()
    };

    result.ok = true;
    result.dashboard_render_performed = true;
    result.workbook_write_performed = true;
    result.final_verdict = 'PASS_GATE11B_PERMANENT_RENDERER_MANUAL_REFRESH';
    return result;
  } catch (error) {
    result.ok = false;
    result.final_verdict = 'FAIL_GATE11B_PERMANENT_RENDERER_EXCEPTION';
    result.error = String(error && error.message ? error.message : error);
    return result;
  } finally {
    lock.releaseLock();
  }
}

function runGate11bPermanentRendererDryRunFromEditor() {
  return airoTask11bPermanentDashboardRefresh_({
    dryRun: true,
    reason: 'editor_dry_run'
  });
}

function runGate11bPermanentRendererManualRefreshFromEditor() {
  return airoTask11bPermanentDashboardRefresh_({
    dryRun: false,
    reason: 'editor_manual_refresh'
  });
}

// AIRO_DASHBOARD_LITE_RENDERER_START
// Owner-approved Dashboard Lite renderer.
// Scope: Dashboard sheet only. No scheduler. No triggers. No domain writes.
function airoDashboardLiteNumber_(value) {
  if (value === null || value === undefined || value === '') return 0;
  if (typeof value === 'number') return isFinite(value) ? value : 0;
  var s = String(value)
    .replace(/[^\d,\.\-]/g, '')
    .replace(/\./g, '')
    .replace(',', '.');
  var n = Number(s);
  return isFinite(n) ? n : 0;
}

function airoDashboardLiteText_(value) {
  return String(value === null || value === undefined ? '' : value).trim();
}

function airoDashboardLiteKey_(value) {
  return airoDashboardLiteText_(value).toLowerCase().replace(/[^a-z0-9]+/g, '');
}

function airoDashboardLiteMonthMap_() {
  return {
    januari: 0, february: 1, februari: 1, maret: 2, march: 2,
    april: 3, mei: 4, may: 4, juni: 5, june: 5,
    juli: 6, july: 6, agustus: 7, august: 7,
    september: 8, oktober: 9, october: 9,
    november: 10, desember: 11, december: 11
  };
}

function airoDashboardLitePeriod_(monthText, yearText) {
  var monthKey = airoDashboardLiteText_(monthText).toLowerCase();
  var monthMap = airoDashboardLiteMonthMap_();
  var monthIndex = Object.prototype.hasOwnProperty.call(monthMap, monthKey) ? monthMap[monthKey] : (new Date()).getMonth();
  var year = Number(yearText) || (new Date()).getFullYear();
  var start = new Date(year, monthIndex, 1);
  var end = new Date(year, monthIndex + 1, 0);
  var prevStart = new Date(year, monthIndex - 1, 1);
  var prevEnd = new Date(year, monthIndex, 0);
  return {
    month_text: monthText,
    month_index: monthIndex,
    year: year,
    start: start,
    end: end,
    prev_start: prevStart,
    prev_end: prevEnd,
    label: monthText + ' ' + year
  };
}

function airoDashboardLiteHeaderMap_(headers) {
  var map = {};
  for (var i = 0; i < headers.length; i++) {
    var key = airoDashboardLiteKey_(headers[i]);
    if (key && map[key] === undefined) map[key] = i;
  }
  return map;
}

function airoDashboardLiteFindCol_(map, aliases) {
  for (var i = 0; i < aliases.length; i++) {
    var key = airoDashboardLiteKey_(aliases[i]);
    if (map[key] !== undefined) return map[key];
  }
  return -1;
}

function airoDashboardLiteReadTable_(sheet) {
  if (!sheet || sheet.getLastRow() < 1 || sheet.getLastColumn() < 1) {
    return { headers: [], rows: [], map: {} };
  }
  var values = sheet.getRange(1, 1, sheet.getLastRow(), sheet.getLastColumn()).getValues();
  var display = sheet.getRange(1, 1, sheet.getLastRow(), sheet.getLastColumn()).getDisplayValues();
  var headers = display[0] || values[0] || [];
  return {
    headers: headers,
    rows: values.slice(1),
    displayRows: display.slice(1),
    map: airoDashboardLiteHeaderMap_(headers)
  };
}

function airoDashboardLiteDateOnly_(value) {
  if (value instanceof Date && !isNaN(value.getTime())) return new Date(value.getFullYear(), value.getMonth(), value.getDate());
  var s = airoDashboardLiteText_(value);
  if (!s) return null;
  var d = new Date(s);
  return isNaN(d.getTime()) ? null : new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

function airoDashboardLiteInPeriod_(dateValue, start, end) {
  var d = airoDashboardLiteDateOnly_(dateValue);
  return !!(d && d >= start && d <= end);
}

function airoDashboardLiteGetSheet_(ss, tabKey, fallbackName) {
  if (!ss) return null;
  var cfgName = '';
  try {
    cfgName = AIRO_CONFIG && AIRO_CONFIG.tabs && AIRO_CONFIG.tabs[tabKey] ? AIRO_CONFIG.tabs[tabKey] : '';
  } catch (e) {}
  if (cfgName && typeof getSheetLoose_ === 'function') {
    var byCfgLoose = getSheetLoose_(ss, cfgName);
    if (byCfgLoose) return byCfgLoose;
  }
  if (cfgName && ss.getSheetByName(cfgName)) return ss.getSheetByName(cfgName);
  if (fallbackName && typeof getSheetLoose_ === 'function') {
    var byFallbackLoose = getSheetLoose_(ss, fallbackName);
    if (byFallbackLoose) return byFallbackLoose;
  }
  return fallbackName ? ss.getSheetByName(fallbackName) : null;
}

function airoDashboardLiteReadLedgerRows_(ss) {
  var sheet = airoDashboardLiteGetSheet_(ss, 'accountLedger', 'Account Ledger');
  var table = airoDashboardLiteReadTable_(sheet);
  var m = table.map;
  return {
    sheet: sheet,
    rows: table.rows,
    displayRows: table.displayRows,
    headers: table.headers,
    dateCol: airoDashboardLiteFindCol_(m, ['date', 'tanggal', 'timestamp', 'created_at']),
    typeCol: airoDashboardLiteFindCol_(m, ['type', 'jenis', 'transaction_type']),
    outCol: airoDashboardLiteFindCol_(m, ['out', 'amount_out', 'keluar', 'debit', 'debit/out']),
    categoryCol: airoDashboardLiteFindCol_(m, ['category', 'kategori']),
    subcategoryCol: airoDashboardLiteFindCol_(m, ['subcategory', 'sub_category', 'subkategori', 'sub kategori']),
    accountCol: airoDashboardLiteFindCol_(m, ['account', 'akun']),
    balanceCol: airoDashboardLiteFindCol_(m, ['balance', 'saldo'])
  };
}

function airoDashboardLiteSpendingRows_(ledger, period, groupCol) {
  var result = [];
  if (!ledger || !ledger.rows || ledger.dateCol < 0 || ledger.typeCol < 0 || ledger.outCol < 0 || groupCol < 0) return result;
  var excludedTypes = {
    transfer_in: true, transfer_out: true, cc_payment: true, debt_payment: true,
    asset_purchase: true, income: true, cash_in: true, cash_out: true
  };
  for (var i = 0; i < ledger.rows.length; i++) {
    var row = ledger.rows[i];
    var type = airoDashboardLiteText_(row[ledger.typeCol]).toLowerCase();
    var category = ledger.categoryCol >= 0 ? airoDashboardLiteText_(row[ledger.categoryCol]) : '';
    var amountOut = airoDashboardLiteNumber_(row[ledger.outCol]);
    if (type !== 'expense') continue;
    if (excludedTypes[type]) continue;
    if (category.toLowerCase() === 'transfer') continue;
    if (amountOut <= 0) continue;
    if (!airoDashboardLiteInPeriod_(row[ledger.dateCol], period.start, period.end)) continue;
    result.push({
      group: airoDashboardLiteText_(row[groupCol]) || 'Lainnya',
      amount: amountOut
    });
  }
  return result;
}

function airoDashboardLiteSpendingRowsPrev_(ledger, period, groupCol) {
  var copy = {
    start: period.prev_start,
    end: period.prev_end
  };
  return airoDashboardLiteSpendingRows_(ledger, copy, groupCol);
}

function airoDashboardLiteTopGroups_(currentRows, prevRows, limit) {
  var curr = {};
  var prev = {};
  var total = 0;
  currentRows.forEach(function(r) {
    curr[r.group] = (curr[r.group] || 0) + r.amount;
    total += r.amount;
  });
  prevRows.forEach(function(r) {
    prev[r.group] = (prev[r.group] || 0) + r.amount;
  });

  var sorted = Object.keys(curr).map(function(k) {
    return { name: k, amount: curr[k], prev: prev[k] || 0 };
  }).sort(function(a, b) { return b.amount - a.amount; });

  var top = sorted.slice(0, limit);
  var others = sorted.slice(limit);
  var otherAmount = others.reduce(function(sum, r) { return sum + r.amount; }, 0);
  var otherPrev = others.reduce(function(sum, r) { return sum + r.prev; }, 0);
  if (otherAmount > 0 || otherPrev > 0) top.push({ name: 'Lainnya', amount: otherAmount, prev: otherPrev });

  return top.map(function(r) {
    return [
      r.name,
      r.amount,
      r.amount - r.prev,
      total ? r.amount / total : 0
    ];
  });
}

function airoDashboardLiteWalletRows_(ledger) {
  if (!ledger || !ledger.rows || ledger.accountCol < 0 || ledger.balanceCol < 0) return [];
  var latest = {};
  for (var i = 0; i < ledger.rows.length; i++) {
    var row = ledger.rows[i];
    var account = airoDashboardLiteText_(row[ledger.accountCol]);
    if (!account) continue;
    latest[account] = airoDashboardLiteNumber_(row[ledger.balanceCol]);
  }
  return Object.keys(latest).sort().map(function(k) {
    return [k, latest[k]];
  });
}

function airoDashboardLiteFindAdjacentValue_(sheet, labels) {
  if (!sheet) return '';
  var maxRows = Math.min(sheet.getLastRow(), 120);
  var maxCols = Math.min(sheet.getLastColumn(), 20);
  if (maxRows < 1 || maxCols < 1) return '';
  var display = sheet.getRange(1, 1, maxRows, maxCols).getDisplayValues();
  var keys = labels.map(function(x) { return airoDashboardLiteKey_(x); });
  for (var r = 0; r < display.length; r++) {
    for (var c = 0; c < display[r].length; c++) {
      var cellKey = airoDashboardLiteKey_(display[r][c]);
      if (!cellKey) continue;
      for (var i = 0; i < keys.length; i++) {
        if (cellKey.indexOf(keys[i]) !== -1) {
          return display[r][Math.min(c + 1, maxCols - 1)] || display[r][c] || '';
        }
      }
    }
  }
  return '';
}

function airoDashboardLiteDomainSummary_(ss) {
  var cc = airoDashboardLiteGetSheet_(ss, 'creditCard', 'Credit Card');
  var aset = airoDashboardLiteGetSheet_(ss, 'aset', 'Aset');
  var cicilan = airoDashboardLiteGetSheet_(ss, 'cicilanRumah', 'Cicilan Rumah');
  return {
    ccDue: airoDashboardLiteFindAdjacentValue_(cc, ['tagihan jatuh tempo', 'due bill', 'payable']),
    ccCurrent: airoDashboardLiteFindAdjacentValue_(cc, ['periode berjalan', 'current period', 'unbilled']),
    ccPocket: airoDashboardLiteFindAdjacentValue_(cc, ['blu pocket cc', 'pocket cc', 'setoran']),
    goldGram: airoDashboardLiteFindAdjacentValue_(aset, ['total gram', 'gram emas', 'emas gram']),
    goldValue: airoDashboardLiteFindAdjacentValue_(aset, ['total nilai emas', 'nilai emas', 'market value']),
    houseCount: airoDashboardLiteFindAdjacentValue_(cicilan, ['x/120', 'cicilan ke', 'installment']),
    houseProgress: airoDashboardLiteFindAdjacentValue_(cicilan, ['progress', 'progress %'])
  };
}

function airoDashboardLiteBreakApartMergedRanges_(sheet, targetRange) {
  if (!sheet || !targetRange) return 0;
  var tr1 = targetRange.getRow();
  var tc1 = targetRange.getColumn();
  var tr2 = tr1 + targetRange.getNumRows() - 1;
  var tc2 = tc1 + targetRange.getNumColumns() - 1;
  var merged = sheet.getDataRange().getMergedRanges();
  var cleared = 0;
  for (var i = 0; i < merged.length; i++) {
    var r = merged[i];
    var rr1 = r.getRow();
    var cc1 = r.getColumn();
    var rr2 = rr1 + r.getNumRows() - 1;
    var cc2 = cc1 + r.getNumColumns() - 1;
    var overlaps = !(rr2 < tr1 || rr1 > tr2 || cc2 < tc1 || cc1 > tc2);
    if (overlaps) {
      r.breakApart();
      cleared++;
    }
  }
  return cleared;
}

function airoDashboardLiteRender_(ss, dashboard, opts) {
  opts = opts || {};
  if (!ss || !dashboard) return { ok: false, error: 'missing ss/dashboard' };

  var month = airoDashboardLiteText_(opts.month || dashboard.getRange('G2').getDisplayValue());
  var year = airoDashboardLiteText_(opts.year || dashboard.getRange('I2').getDisplayValue());
  var period = airoDashboardLitePeriod_(month, year);
  var ledger = airoDashboardLiteReadLedgerRows_(ss);
  var domains = airoDashboardLiteDomainSummary_(ss);

  var categoryCurrent = airoDashboardLiteSpendingRows_(ledger, period, ledger.categoryCol);
  var categoryPrev = airoDashboardLiteSpendingRowsPrev_(ledger, period, ledger.categoryCol);
  var subCurrent = airoDashboardLiteSpendingRows_(ledger, period, ledger.subcategoryCol);
  var subPrev = airoDashboardLiteSpendingRowsPrev_(ledger, period, ledger.subcategoryCol);

  var categoryRows = airoDashboardLiteTopGroups_(categoryCurrent, categoryPrev, 5);
  var subRows = airoDashboardLiteTopGroups_(subCurrent, subPrev, 10);
  var walletRows = airoDashboardLiteWalletRows_(ledger);
  var walletTotal = walletRows.reduce(function(sum, r) { return sum + airoDashboardLiteNumber_(r[1]); }, 0);

  var liteClearRange = dashboard.getRange('B1:K45');
  var liteMergedRangeCount = airoDashboardLiteBreakApartMergedRanges_(dashboard, liteClearRange);
  liteClearRange.clear({ contentsOnly: false });
  dashboard.getRange('B1:K1').merge().setValue('AIRO Finance Dashboard Lite');
  dashboard.getRange('B2:E2').merge().setValue('Synced: ' + new Date() + ' | Period: ' + period.label + ' | Source: Account Ledger');
  dashboard.getRange('F2').setValue('Bulan');
  dashboard.getRange('G2').setValue(month);
  dashboard.getRange('H2').setValue('Tahun');
  dashboard.getRange('I2').setValue(String(period.year));
  dashboard.getRange('M2').setValue(period.label);
  dashboard.getRange('M3').setValue(period.start);
  dashboard.getRange('M4').setValue(period.end);
  dashboard.getRange('Z1').setValue('AIRO_DASHBOARD_LITE_RENDERED');
  dashboard.getRange('Z2').setValue(new Date());

  dashboard.getRange('B4:E4').setValues([['TOP KATEGORI', 'BULAN INI', 'VS BULAN LALU', 'CONTR. %']]);
  if (categoryRows.length) dashboard.getRange(5, 2, categoryRows.length, 4).setValues(categoryRows);

  dashboard.getRange('G4:J4').setValues([['TOP SUBKATEGORI', 'BULAN INI', 'VS BULAN LALU', 'CONTR. %']]);
  if (subRows.length) dashboard.getRange(5, 7, Math.min(subRows.length, 11), 4).setValues(subRows.slice(0, 11));

  dashboard.getRange('B17:C17').setValues([['WALLET AKTIF', 'SALDO']]);
  if (walletRows.length) dashboard.getRange(18, 2, Math.min(walletRows.length, 12), 2).setValues(walletRows.slice(0, 12));
  dashboard.getRange('B31:C31').setValues([['TOTAL SALDO', walletTotal]]);

  dashboard.getRange('G17:J17').setValues([['DOMAIN', 'METRIC 1', 'METRIC 2', 'METRIC 3']]);
  dashboard.getRange('G18:J20').setValues([
    ['Credit Card', domains.ccDue || '-', domains.ccCurrent || '-', domains.ccPocket || '-'],
    ['Emas', domains.goldGram || '-', domains.goldValue || '-', '-'],
    ['Cicilan Rumah', domains.houseCount || '-', domains.houseProgress || '-', '-']
  ]);

  dashboard.getRange('C5:C15').setNumberFormat('"Rp" #,##0');
  dashboard.getRange('D5:D15').setNumberFormat('"Rp" #,##0');
  dashboard.getRange('E5:E15').setNumberFormat('0.0%');
  dashboard.getRange('H5:H15').setNumberFormat('"Rp" #,##0');
  dashboard.getRange('I5:I15').setNumberFormat('"Rp" #,##0');
  dashboard.getRange('J5:J15').setNumberFormat('0.0%');
  dashboard.getRange('C18:C31').setNumberFormat('"Rp" #,##0');
  dashboard.getRange('M3:M4').setNumberFormat('yyyy-mm-dd');

  SpreadsheetApp.flush();

  return {
    ok: true,
    renderer: 'AIRO_DASHBOARD_LITE',
    target_tab: dashboard.getName(),
    period: period.label,
    ledger_rows: ledger.rows.length,
    category_rows: categoryRows.length,
    subcategory_rows: subRows.length,
    wallet_rows: walletRows.length,
    wallet_total: walletTotal,
    merged_ranges_cleared: liteMergedRangeCount
  };
}

function airoDashboardLiteStaticSelfTest_() {
  var period = airoDashboardLitePeriod_('Juli', '2026');
  var current = [
    { group: 'Food', amount: 100 },
    { group: 'Food', amount: 50 },
    { group: 'Transport', amount: 25 }
  ];
  var prev = [
    { group: 'Food', amount: 80 },
    { group: 'Transport', amount: 40 }
  ];
  var groups = airoDashboardLiteTopGroups_(current, prev, 5);
  return {
    ok: groups.length === 2 && groups[0][0] === 'Food' && groups[0][1] === 150 && period.year === 2026,
    groups: groups,
    period: period.label
  };
}

function runDashboardLiteSpendingDiagnosticFromEditor() {
  var ss = airoTask101GetSs_();
  var dashboard = airoTask102GetActiveDashboard_(ss);
  var month = dashboard ? airoDashboardLiteText_(dashboard.getRange('G2').getDisplayValue()) : '';
  var year = dashboard ? airoDashboardLiteText_(dashboard.getRange('I2').getDisplayValue()) : '';
  var period = airoDashboardLitePeriod_(month, year);
  var ledger = airoDashboardLiteReadLedgerRows_(ss);

  var typeCounts = {};
  var currentExpense = 0;
  var prevExpense = 0;
  var dateReadable = 0;
  var outPositive = 0;

  for (var i = 0; i < ledger.rows.length; i++) {
    var row = ledger.rows[i];
    var type = ledger.typeCol >= 0 ? airoDashboardLiteText_(row[ledger.typeCol]).toLowerCase() : '';
    typeCounts[type || '(blank)'] = (typeCounts[type || '(blank)'] || 0) + 1;
    if (ledger.dateCol >= 0 && airoDashboardLiteDateOnly_(row[ledger.dateCol])) dateReadable++;
    if (ledger.outCol >= 0 && airoDashboardLiteNumber_(row[ledger.outCol]) > 0) outPositive++;
    if (type === 'expense' && ledger.outCol >= 0 && airoDashboardLiteNumber_(row[ledger.outCol]) > 0) {
      if (airoDashboardLiteInPeriod_(row[ledger.dateCol], period.start, period.end)) currentExpense++;
      if (airoDashboardLiteInPeriod_(row[ledger.dateCol], period.prev_start, period.prev_end)) prevExpense++;
    }
  }

  return {
    ok: true,
    task: 'AIRO_DASHBOARD_LITE_SPENDING_DIAGNOSTIC',
    period: period.label,
    ledger_rows: ledger.rows.length,
    headers: ledger.headers,
    cols: {
      dateCol: ledger.dateCol,
      typeCol: ledger.typeCol,
      outCol: ledger.outCol,
      categoryCol: ledger.categoryCol,
      subcategoryCol: ledger.subcategoryCol,
      accountCol: ledger.accountCol,
      balanceCol: ledger.balanceCol
    },
    type_counts: typeCounts,
    date_readable_rows: dateReadable,
    out_positive_rows: outPositive,
    current_expense_rows: currentExpense,
    prev_expense_rows: prevExpense
  };
}


// AIRO_DASHBOARD_LITE_RENDERER_END


// AIRO_GATE11B_PERMANENT_RENDERER_END

function airoTask101OnEdit_(event) {
  if (!event || !event.range) return false;

  var range = event.range;
  var sheet = range.getSheet();

  if (sheet.getName() !== '🏠 Dashboard') {
    return false;
  }

  var a1 = range.getA1Notation();

  if (a1 !== 'G2' && a1 !== 'I2') {
    return false;
  }

  var months = airoTask103Months_();
  var month =
    sheet.getRange('G2').getDisplayValue();
  var year =
    sheet.getRange('I2').getDisplayValue();

  if (months.indexOf(month) < 0) {
    throw new Error('invalid month filter');
  }

  if (!/^(?:19|20)\d{2}$/.test(year)) {
    throw new Error('invalid year filter');
  }

  sheet
    .getRange('Z4')
    .setValue(new Date());

  try {
    var refreshSs =
      event && event.source
        ? event.source
        : airoTask101GetSs_();

    airoTask102RefreshDomainHealth_(
      refreshSs,
      sheet
    );

    sheet
      .getRange('Z5')
      .setValue(new Date());

    sheet
      .getRange('Z6')
      .setValue('ONEDIT_REFRESH_PASS');
  } catch (refreshError) {
    sheet
      .getRange('Z6')
      .setValue('ONEDIT_REFRESH_ERROR');

    try {
      Logger.log(
        'AIRO_TASK10_2_ONEDIT_REFRESH_ERROR=' +
        String(
          refreshError && refreshError.message
            ? refreshError.message
            : refreshError
        )
      );
    } catch (loggerError) {}
  }

  SpreadsheetApp.flush();

  return true;
}

function airoTask10MaybeRefreshOnEdit_(event) {
  return airoTask101OnEdit_(event);
}



// AIRO_GATE11B_WALLET_STATUS_SCRIPT_WRITTEN
function airoGate11bRepairVisibleWalletStatusAndTopbar_(dashboard, reason) {
  var ss = dashboard.getParent();
  var tz = ss.getSpreadsheetTimeZone() || Session.getScriptTimeZone() || 'Asia/Jakarta';
  var now = Utilities.formatDate(new Date(), tz, 'dd/MM/yyyy HH:mm:ss');
  var month = dashboard.getRange('G2').getDisplayValue();
  var year = dashboard.getRange('I2').getDisplayValue();
  var ledgerRows = dashboard.getRange('M11').getDisplayValue();

  var topbar = '● Synced: ' + now + ' | Period: ' + month + ' ' + year + ' | Ledger rows: ' + ledgerRows + ' | Source: Account Ledger';
  dashboard.getRange('B2').setValue(topbar);

  var statuses = [];
  for (var row = 17; row <= 21; row++) {
    var wallet = String(dashboard.getRange(row, 2).getDisplayValue() || '').trim();
    var balanceRaw = dashboard.getRange(row, 3).getValue();
    var balanceText = String(dashboard.getRange(row, 3).getDisplayValue() || '').replace(/[^\d,\.\-]/g, '').replace(/\./g, '').replace(',', '.');
    var balance = 0;

    if (typeof balanceRaw === 'number') {
      balance = balanceRaw;
    } else if (balanceText && !isNaN(Number(balanceText))) {
      balance = Number(balanceText);
    }

    var status = '';
    if (wallet) {
      if (balance < 0) {
        status = 'CRIT: saldo negatif';
      } else if (balance === 0) {
        status = 'OK';
      } else if (balance < 50000) {
        status = 'WARN: saldo rendah';
      } else {
        status = 'OK';
      }
    }

    dashboard.getRange(row, 5).setValue(status);
    statuses.push({ row: row, wallet: wallet, balance: balance, status: status });
  }

  SpreadsheetApp.flush();

  return {
    reason: reason || '',
    b2: dashboard.getRange('B2').getDisplayValue(),
    status_rows_written: statuses.length,
    statuses: statuses
  };
}


// AIRO_GATE11B_VISUAL_SANITY_FIX_HELPER_START
function runGate11bVisualSanityFixFromClasp() {
  var ss = airoTask101GetSs_();
  var dashboard = airoTask102GetActiveDashboard_(ss);
  var result = {
    task: 'AIRO_GATE11B_VISUAL_SANITY_FIX',
    manual_editor_required: false,
    scheduler_connected: false,
    trigger_created: false,
    ledger_domain_mutated: false,
    helper_columns_hidden: false,
    visible_error_count_a1k41: null,
    visible_error_cells_a1k41: [],
    final_verdict: 'FAIL_GATE11B_VISUAL_SANITY'
  };

  var renderResult = airoTask11bPermanentDashboardRefresh_({
    dryRun: false,
    reason: 'visual_sanity_fix',
    ss: ss
  });
  result.renderer_final_verdict = renderResult && renderResult.final_verdict ? renderResult.final_verdict : '';

  // Owner-facing cockpit is A:K. Hide helper/debug columns after the cockpit.
  dashboard.hideColumns(12, 15); // L:Z
  SpreadsheetApp.flush();
  result.helper_columns_hidden = dashboard.isColumnHiddenByUser(12) && dashboard.isColumnHiddenByUser(26);

  var range = dashboard.getRange('A1:K41');
  var display = range.getDisplayValues();
  var formulas = range.getFormulas();
  var errors = [];
  for (var r = 0; r < display.length; r++) {
    for (var c = 0; c < display[r].length; c++) {
      var v = String(display[r][c] || '');
      if (v.indexOf('#ERROR!') !== -1 || v.indexOf('#N/A') !== -1 || v.indexOf('#REF!') !== -1 || v.indexOf('#VALUE!') !== -1 || v.indexOf('#DIV/0!') !== -1) {
        errors.push({
          cell: dashboard.getRange(r + 1, c + 1).getA1Notation(),
          display: v,
          has_formula: !!formulas[r][c],
          formula: formulas[r][c] ? String(formulas[r][c]).slice(0, 180) : ''
        });
      }
    }
  }

  result.visible_error_count_a1k41 = errors.length;
  result.visible_error_cells_a1k41 = errors.slice(0, 25);

  result.readback = {
    g2: dashboard.getRange('G2').getDisplayValue(),
    i2: dashboard.getRange('I2').getDisplayValue(),
    b2: dashboard.getRange('B2').getDisplayValue(),
    b17: dashboard.getRange('B17').getDisplayValue(),
    e17: dashboard.getRange('E17').getDisplayValue(),
    b25: dashboard.getRange('B25').getDisplayValue(),
    c25: dashboard.getRange('C25').getDisplayValue(),
    d25: dashboard.getRange('D25').getDisplayValue(),
    e25: dashboard.getRange('E25').getDisplayValue(),
    g25: dashboard.getRange('G25').getDisplayValue(),
    b34: dashboard.getRange('B34').getDisplayValue(),
    col_l_hidden: dashboard.isColumnHiddenByUser(12),
    col_n_hidden: dashboard.isColumnHiddenByUser(14),
    col_z_hidden: dashboard.isColumnHiddenByUser(26)
  };

  if (result.helper_columns_hidden && result.visible_error_count_a1k41 === 0) {
    result.final_verdict = 'PASS_GATE11B_VISUAL_SANITY_FIX';
    result.ok = true;
  } else {
    result.ok = false;
  }

  return result;
}
// AIRO_GATE11B_VISUAL_SANITY_FIX_HELPER_END


function onEdit(event) {
  try {
    // AIRO_GATE11B_ONEDIT_CONNECTED_AFTER_FILTER_SWITCH_PASS
    if (!event || !event.range) return false;
    var range = event.range;
    var sheet = range.getSheet();
    if (sheet.getName() !== "🏠 Dashboard") return false;
    var a1 = range.getA1Notation();
    if (a1 !== "G2" && a1 !== "I2") return false;
    var ss = event.source || airoTask101GetSs_();
    var refreshRes = airoTask11bPermanentDashboardRefresh_({dryRun:false, reason:"onedit_filter_refresh", ss:ss});
    return refreshRes.ok;
    return airoTask101OnEdit_(event);
  } catch (error) {
    Logger.log(
      'AIRO_TASK10_1_NATIVE_ONEDIT_ERROR=' +
      String(
        error && error.message
          ? error.message
          : error
      )
    );

    return false;
  }
}

function airoTask102ScheduledNativeRefresh_() {
  var lock = LockService.getScriptLock();

  if (!lock.tryLock(30000)) {
    return {
      ok: false,
      status: "skipped",
      reason: "lock_busy",
      handler: "airoTask102ScheduledNativeRefresh_",
      financial_write_performed: false,
      gmail_read_performed: false,
      telegram_send_performed: false,
      trigger_created: false
    };
  }

  try {
    var ss = airoTask101GetSs_();
    var dashboard = airoTask102GetActiveDashboard_(ss);

    if (!dashboard) {
      return {
        ok: false,
        status: "skipped",
        reason: "active_dashboard_missing",
        handler: "airoTask102ScheduledNativeRefresh_",
        financial_write_performed: false,
        gmail_read_performed: false,
        telegram_send_performed: false,
        trigger_created: false
      };
    }

    var marker = String(dashboard.getRange("Z1").getDisplayValue() || "").trim();

    if (marker !== "AIRO_TASK10_1_NATIVE_V2_FINAL") {
      return {
        ok: false,
        status: "skipped",
        reason: "marker_incorrect",
        marker: marker,
        handler: "airoTask102ScheduledNativeRefresh_",
        financial_write_performed: false,
        gmail_read_performed: false,
        telegram_send_performed: false,
        trigger_created: false
      };
    }

    airoTask102RefreshDomainHealth_(ss, dashboard);

    dashboard.getRange("Z5").setValue(new Date());
    dashboard.getRange("Z6").setValue("SCHEDULED_REFRESH_PASS");

    SpreadsheetApp.flush();

    var readback = runTask103DashboardActiveReadbackFromEditor();

    return {
      ok: !!(readback && readback.ok),
      status: readback && readback.ok ? "success" : "readback_failed",
      handler: "airoTask102ScheduledNativeRefresh_",
      active_readback: readback,
      financial_write_performed: false,
      gmail_read_performed: false,
      telegram_send_performed: false,
      trigger_created: false
    };
  } catch (error) {
    return {
      ok: false,
      status: "error",
      handler: "airoTask102ScheduledNativeRefresh_",
      error: String(error && error.message ? error.message : error),
      financial_write_performed: false,
      gmail_read_performed: false,
      telegram_send_performed: false,
      trigger_created: false
    };
  } finally {
    lock.releaseLock();
  }
}

function runGate11bFilterSwitchProofFromClasp() {
  var ss = airoTask101GetSs_();
  var dashboard = airoTask102GetActiveDashboard_(ss);

  if (!dashboard) {
    return { ok: false, error: "exact active Dashboard missing" };
  }

  var originalMonth = String(dashboard.getRange("G2").getDisplayValue() || "").trim();
  var originalYear = String(dashboard.getRange("I2").getDisplayValue() || "").trim();

  var months = airoTask103Months_();
  if (months.indexOf("Mei") < 0 || months.indexOf("Juni") < 0) {
    return { ok: false, error: "months list validation failed" };
  }

  function readback(label) {
    return {
      label: label,
      g2: dashboard.getRange("G2").getDisplayValue(),
      i2: dashboard.getRange("I2").getDisplayValue(),
      b2: dashboard.getRange("B2").getDisplayValue() || dashboard.getRange("A2").getDisplayValue(),
      m2: dashboard.getRange("M2").getDisplayValue(),
      m3: dashboard.getRange("M3").getDisplayValue(),
      m4: dashboard.getRange("M4").getDisplayValue(),
      b25: dashboard.getRange("B25").getDisplayValue(),
      c25: dashboard.getRange("C25").getDisplayValue(),
      d25: dashboard.getRange("D25").getDisplayValue(),
      e25: dashboard.getRange("E25").getDisplayValue(),
      g25: dashboard.getRange("G25").getDisplayValue(),
      b34: dashboard.getRange("B34").getDisplayValue(),
      z2: dashboard.getRange("Z2").getDisplayValue(),
      z3: dashboard.getRange("Z3").getDisplayValue(),
      z4: dashboard.getRange("Z4").getDisplayValue()
    };
  }

  // 1. Set G2=Juni, I2=2026, flush
  dashboard.getRange("G2").setValue("Juni");
  dashboard.getRange("I2").setValue("2026");
  SpreadsheetApp.flush();

  var refreshJuni = airoTask11bPermanentDashboardRefresh_({dryRun:false, reason:"filter_switch_juni_proof", ss:ss});
  var juniRead = readback("juni");

  // 2. Set G2=Mei, I2=2026, flush
  dashboard.getRange("G2").setValue("Mei");
  dashboard.getRange("I2").setValue("2026");
  SpreadsheetApp.flush();

  var refreshMei = airoTask11bPermanentDashboardRefresh_({dryRun:false, reason:"filter_switch_mei_proof", ss:ss});
  var meiRead = readback("mei");

  // 3. Restore original G2/I2 if not Mei/2026
  if (originalMonth !== "Mei" || originalYear !== "2026") {
    dashboard.getRange("G2").setValue(originalMonth);
    dashboard.getRange("I2").setValue(originalYear);
    SpreadsheetApp.flush();
  }

  var periodChanged = (juniRead.m2 !== meiRead.m2 || juniRead.m3 !== meiRead.m3 || juniRead.m4 !== meiRead.m4);
  var spendingChanged = (juniRead.b25 !== meiRead.b25 || juniRead.c25 !== meiRead.c25);
  var b2NonemptyJuni = (juniRead.b2 !== "");
  var b2NonemptyMei = (meiRead.b2 !== "");

  var finalVerdict = "FAIL_GATE11B_FILTER_SWITCH_INCOMPLETE";
  if (periodChanged && refreshJuni.ok && refreshMei.ok) {
    finalVerdict = "PASS_GATE11B_FILTER_SWITCH_PROOF";
  }

  return {
    ok: (finalVerdict === "PASS_GATE11B_FILTER_SWITCH_PROOF"),
    original_month: originalMonth,
    original_year: originalYear,
    juni_verdict: refreshJuni.final_verdict,
    mei_verdict: refreshMei.final_verdict,
    juni_readback: juniRead,
    mei_readback: meiRead,
    period_changed: periodChanged,
    spending_changed: spendingChanged,
    b2_nonempty_juni: b2NonemptyJuni,
    b2_nonempty_mei: b2NonemptyMei,
    final_verdict: finalVerdict
  };
}

